window.__D("text/zohar/c027",{"p":[[9520012019,"<p>רִבִּי חִיָּיא וְרִבִּי יוֹסֵי הֲווֹ אָזְלֵי מֵאוּשָׁא לִטְבֶרְיָה, אָמַר רִבִּי חִיָּיא, כְּתִיב (תהילים קל״ב:י״ד) כִּי בָחַר יְיָ' בְּצִיּוֹן וְגוֹ'. זֹאת מְנוּחָתִי וְגוֹ', לְזִמְנִין קָרָאן לְהַאי חַבְרַיָּיא כֻּלְּהוּ דְּכוּרָא, בְּגִין דְּאִיהוּ (ס\"א דציון איהו) רַחֲמֵי. וְהָכָא קְרָא נוּקְבָּא קָרָא לֵיהּ.</p>\n<p>אָמַר רִבִּי יוֹסֵי, הָכִי שְׁמִיעַ לִי מִבּוּצִינָא קַדִּישָׁא, (אבל) בְּשַׁעֲתָא דְּזִוּוּגָא אִזְדְּוַוג כַּחֲדָא, לְאַחֲזָאָה דְּהָא נוּקְבָּא אִתְכְּלִילַת בֵּיהּ בִּכְלָלָא חֲדָא, אִתְקְרֵי נוּקְבָּא בִּשְׁמָא (דדכורא), דְּהָא כְּדֵין בִּרְכָאן דְּמַטְרוֹנִיתָא אִשְׁתְּכָחוּ, וְלָא הֲוִי בָּהּ פְּרִישׁוּתָא כְּלַל. וְעַל דָּא לְמוֹשָׁב לוֹ כְּתִיב. וּכְתִיב כִּי בָחַר יְיָ' בְּצִיּוֹן, בְּצִיּוֹן דַּיְיקָא, בְּהַהוּא דְּאִית בְּגַוִּיהּ דְּשַׁרְיָא בֵּיהּ, וְלָא כְּתִיב לְצִיּוֹן. וְכֹלָּא חַד, בֵּין דְּקָרָא לְהַאי בִּשְׁמָא דִּדְכוּרָא, וּבֵין דְּקָרָא לְהַאי בִּשְׁמָא דְּנוּקְבָּא כֹּלָּא חַד וּבְדַרְגָּא חַד קַיְימִין.</p>\n<p>(פתח רבי יוסי ואמר), וְעַל דָּא כְּתִיב, (תהילים פ״ז:ה׳) וּלְצִיּוֹן יֵאָמֵר אִישׁ וְאִישׁ יוּלַּד בָּהּ. חַד לְדִינָא, וְחַד לְרַחֲמֵי. כַּד מִזְדַּוְּוגֵי כַּחֲדָא בְּזִוּוּגָא חַד, כְּדֵין צִיּוֹן אִקְרֵי, וְצִיּוֹן וִירוּשָׁלַים אִשְׁתְּמוֹדַע, וְאִשְׁתְּכַח דְּדָא בְּדָא תַּלְיָיא.</p>\n<p>פָּתַח רִבִּי יוֹסֵי וְאָמַר, כְּתִיב (ויקרא כ׳:ז׳) וְהִתְקַדִּשְׁתֶּם <Nonei></i>וִהְיִיתֶם קְדוֹשִׁים. מַאן דִּמְקַדֵּשׁ גַּרְמֵיהּ מִלְּרַע, מְקַדְּשִׁין לֵיהּ מִלְעֵילָּא. מַאן דְּמַסְאִיב גַּרְמֵיהּ מִלְּרַע, מְסָאֲבִין לֵיהּ מִלְעֵילָּא. מְקַדְּשִׁין לֵיהּ מִלְעֵילָּא יָאוּת, דְּהָא קְדוּשָּׁה דְּמָארֵיהּ שַׁרְיָא עָלֵיהּ, אֲבָל מְסָאֲבִין לֵיהּ מֵאָן אֲתַר. וְאִי תֵּימָא מִלְּעֵילָּא, וְכִי מְסָאֲבוּתָא שַׁרְיָא לְעֵילָּא.</p>"],[9520012020,"<p>אָמַר רִבִּי חִיָיא, הַיְינוּ דְּתָנֵינָן, בְּעוֹבָדָא דִּלְתַּתָּא אִתְּעַר עוֹבָדָא לְעֵילָּא. אִי עוֹבָדָא דִּלְתַּתָּא הִיא בִּקְדוּשָּׁה, אִתְּעַר קְדוּשָּׁה לְעֵילָּא, וְאָתֵי וְשַׁרְיָא עָלֵיהּ, וְאִתְקַדָּשׁ בֵּיהּ. וְאִי אִיהוּ אִסְתְּאַב לְתַתָּא, אִתְּעַר רוּחַ מִסְאֲבוּתָא לְעֵילָּא, וְאָתֵי וְשַׁרְיָא עָלֵיהּ, וְאִסְתְּאַב בֵּיהּ. דְּהָא בְּעוֹבָדָא תַּלְיָא מִלְּתָא.</p>\n<p>דְּהָא לֵית לָךָ טַב וּבִישׁ, קְדוּשָּׁא וּמְסָאֲבוּתָא, דְּלֵית לֵיהּ עִקָרָא וְשָׁרְשָׁא לְעֵילָּא. וּבְעוֹבָדָא דִּלְתַּתָּא אִתְּעַר עוֹבָדָא דִּלְעֵילָּא, מַה דְּתָלֵי בְּעוֹבָדָא, בְּעוֹבָדָא אִתְּעַר לְעֵילָּא, וְאִתְעָבִיד עוֹבָדָא. וּמַה דְּתָלֵי בְּמִלִּין, בְּמִלִּין. כַּד אִתְגְּזַר בְּמִלָּה, אִתְּעַר הָכִי לְעֵילָּא.</p>\n<p>וְאִי תֵּימָא, מִלָּה מַה אִתְּעַר. אֶלָּא הָכִי כְּתִיב, (ישעיה נח) וְדַבֵּר דָּבָר. הַהוּא דָּבַר, אִתְּעַר מִלָּה אָחֳרָא לְעֵילָּא, דְּאִקְרֵי דָּבָר. (הושע א) דְּבַר יְיָ' אֲשֶׁר הָיָה. (שמואל א, ג) וּדְבַר יְיָ' הָיָה יָקָר. (תהילים ל״ג:ו׳) בִּדְבַר יְיָ' שָׁמַיִם נַעֲשׂוּ. דְּהָא תָּנֵינָן, הַהִיא מִלָּה סַלְּקָא, וּבָקַע רְקִיעִין, עַד דְּסַלְּקָא (ס\"א דאתיישבא) בְּדוּכְתֵּיהּ, וְאִתְּעַר מַה דְּאִתְּעַר, אִי טַב, טַב. אִי בִּישׁ, בִּישׁ. וְעַל דָּא כְּתִיב, (דברים כ״ג:י׳) וְנִשְׁמַרְתָּ מִכֹּל דָּבָר רָע.</p>"],[9520012021,"<p>ד' מִינִין בַּלוּלָב, וְאִינּוּן שִׁבְעָה. וְאִי תֵּימָא דְּז' מִינִין אִינּוּן. לָאו הָכֵי, אֶלָּא אַרְבְּעָה נִינְהוּ וְאִינּוּן מִתְפָּרְשִׁין לִתְלָתָא אוֹחֲרָנִין. וּבְעוֹבָדָא דִּלְהוֹן אִתְּעֲרוּ שִׁבְעָה אָחֳרָנִין לְעֵילָּא, לְאוֹטָבָא עָלְמָא בְּכַמָּה סִטְרִין.</p>\n<p>כְּנֶסֶת יִשְׂרָאֵל, אַף עַל גַּב דְּאִיהִי בִּכְלָלָא, מִתְבָּרְכָא מְכֻּלְּהוּ שִׁית, (ס\"א ולאתברכא מאינון שית) וּמִנַּחֲלָא דַּעֲמִיקָא דְּמַבּוּעָא, דְּנָגִיד וְלָא פָּסִיק לְעָלְמִין מֵימוֹי דְּנַגְדָא (ס\"א מלנגדא) עָלַיְיהוּ, וְיַנְקָא לְבַת. דְּהָא בְּגִין דְּאִיהִי בַּת לָהּ לְעָלְמָא עִלָּאָה וְתַתָּאָה, אִתְבָּרְכָא מִנַּיְיהוּ בְּאִתְעָרוּתָא דָּא. דְּהָא בְּשַׁעֲתָא דִּכְנֶסֶת יִשְׂרָאֵל אִתְבָּרְכָא מִנַּיְיהוּ, כֻּלְּהוּ עָלְמִין אִתְבָּרְכָן. עַל דָּא סוֹבְבִים אֶת הַמִּזְבֵּחַ כְּמָה (כ\"ד ע\"ב) דְּאִתְּמַר.</p>\n<p>וְעוֹד בְּאִתְּעָרוּתָא דָּא, שִׁיתָא כֻּלְּהוּ מִתְבָּרְכָא בְּמַיָּא, לְאִסְתַּפְּקָא בֵּיהּ, וְאִשְׁתַּאֲבִין כֻּלְּהוּ מִמַּבּוּעָא דְּיֵינָא (ס\"א דימא) (דמיא) (ס\"א דנחלא) עֲמִיקָא דְּכֹלָּא, לְנַחְתָּא לְעָלְמָא. וּבְגִין כָּךְ, בַּעְיָין כֻּלְּהוּ לַחִין וְלָא יְבֵשִׁין, לְאַמְשָׁכָא בִּרְכָאן לְעָלְמָא, בְּגִין דְּאִילָנֵי אִלֵּין, כֻּלְּהוּ לַחִין תְּדִירָא, וְטַרְפִּין דִּלְהוֹן מִשְׁתַּכְּחִין תְּדִירָא, וּזְמַן חֶדְוָותָא דִּלְהוֹן בְּהַאי זִמְנָא.</p>\n<p>וְתָנֵינָן בְּסִפְרָא דְּרַב הַמְנוּנָא סָבָא, דְּהָא הַהוּא חֵילָא דְּאִתְפָּקְּדָא עַל אִילָנִין אִלֵּין, כָּל חַד וְחַד מֵאִלֵּין, לָא נָטִיל בִּרְכָאן דְּחֶדְוְותָא לְעֵילָּא, אֶלָּא בְּזִמְנָא דָּא. וְחֶדְוָותָא דִּלְהוֹן כֻּלְּהוּ לְעֵילָּא, וְחֶדְוָותָא דְּאִילָנִין אִלֵּין לְתַתָּא, כֻּלְּהוּ בְּזִמְנָא דָּא הוּא. וְאִתְּעֲרוּתָא דִּלְהוֹן בְּאִינּוּן קַדִּישֵׁי מַלְכָּא תַּלְיָין. וְכַד יִשְׂרָאֵל נַטְלֵי לוֹן, כֹּלָּא אִתְּעַר בְּזִמְנָא דָּא, וְעָלְמָא מִתְבָּרְכָא, (ס\"א לכנסת ישראל מתברכא) לְאַרְקָא בִּרְכָאן לְעָלְמָא.</p>\n<p>כְּתִיב (תהילים כ״ט:ג׳) קוֹל יְיָ' עַל הַמָּיִם אֵל הַכָּבוֹד, אָמַר רִבִּי יוֹסֵי, דָּא אַבְרָהָם. קוֹל יְיָ' בַּכֹּחַ: דָּא יִצְחָק. קוֹל יְיָ' בֶּהָדָר: דָּא יַעֲקֹב. קוֹל יְיָ' שׁוֹבֵר אֲרָזִים: דָּא נֶצַח. קוֹל יְיָ' חוֹצֵב לַהֲבוֹת אֵשׁ: דָּא הוֹד. קוֹל יְיָ' יָחִיל מִדְבָּר: דָּא צַדִּיק. קוֹל יְיָ' יְחוֹלֵל אַיָּלוֹת: דָּא צֶדֶק. וְכֻלְּהוּ מִתְגַּדְּלֵי עַל יַמָּא (מיא) וְאִתְשַּׁקְיָין בְּמַיָּא, לְגַדְּלָא. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְכֻלְּהוּ הָנֵי מִתְעָרֵי בִּרְכָאן לְעָלְמָא, מֵהַהוּא שַׁקְיוּ, דְּאִתְּשַׁקְיָין כֻּלְּהוּ.</p>\n<p>תָּא חֲזֵי, הָנֵי שֶׁבַע קָלִין, תַּלְיָין בְּמִלָּה דְּפוּמָא בִּשְׁאָר יוֹמֵי שַׁתָּא, וְהַשְׁתָּא, לָא תַּלְיָין אֶלָּא בְּעוֹבָדָא, וַאֲנָן עוֹבָדָא קָא בָּעֵינָן, וְלָא מִלָּה. בְּגִין דִּבְזִמְנָא דָּא, מְבָרֵךְ לְכָל שַׁתָּא.</p>\n<p>בְּיוֹמָא שְׁבִיעָאָה דְּחָג, הוּא סִיּוּמָא דְּדִינָא דְּעָלְמָא, וּפִתְקִין נָפְקִין מִבֵּי מַלְכָּא, וּגְבוּרָן מִתְעָרֵי וּמִסְתַּיְּימָן בְּהַאי יוֹמָא, וְעַרְבֵי נַחַל (תליין) בְּהוּ. וּבָעֵינָן לְאִתְּעָרָא גְּבוּרָן לְמַיָּא. וּלְסַחֲרָא ז' זִמְנִין, לְרַוָואָה לְהַאי מִזְבֵּחַ, מִמַּיָּא דְּיִצְחָק, בְּגִין דְּאִתְמַלְיָא מַיָּא הַאי בֵּירָא דְּיִצְחָק, וְכַד הוּא אִתְמַלְּיָא, כָּל עָלְמָא אִתְבָּרְכָא בְּמַיָּא.</p>\n<p>וּבְהַאי יוֹמָא גְּבוּרוֹת בָּעֵינָן לְמַיָּא, וּלְסַיְימָא לוֹן לְבָתַר, דְּהָא <Nonei></i>בְּהַאי יוֹמָא מִסְתַּיְּימֵי דִּינָא. וּבְגִין כָּךְ בָּעֵינָן לְבַטְּשָׁא לוֹן בְּאַרְעָא, וּלְסַיְימָא לוֹן דְּלָא מִשְׁתַּכְחוּ, דְּהַאי יוֹמָא אִתְּעָרוּתָא וְסִיּוּמָא הוּא. וְעַל דָּא אִתְּעָרוּתָא וְסִיּוּמָא הוּא דְּעַבְדִינָן בְּעַרְבֵי נַחַל.</p>\n<p>אָמַר רִבִּי חִיָיא וַדַּאי הָכִי הוּא, וְשַׁפִּיר. וְעַרְבֵי נַחַל, מִסִּטְרָא דְּנַחַל, נַפְקֵי גְּבוּרָאן. וּבְהַאי יוֹמָא מִתְעָרֵי וּמְסַיְּימֵי. בְּהַאי יוֹמָא כְּתִיב, (בראשית כ״ו:י״ח) וַיָּשָׁב יִצְחָק וַיַחְפּוֹר אֶת בְּאֵרֹת הַמַּיִם. בְּאֵרֹת כְּתִיב חָסֵר. וַיָּשָׁב, מַהוּ וַיָּשָׁב. אֶלָּא יוֹמָא קַדְמָאָה דְּיַרְחָא, שֵׁירוּתָא דְּדִינָא הַוָה בְּכָל עָלְמָא, וְיִצְחָק קַיְּימָא לְכוּרְסְיָיא לְמֵידָן עָלְמָא. בְּהַאי יוֹמָא, וַיָּשָׁב יִצְחָק לְאִתְּעָרָא דִּינִין וּלְסַיְימָא דִּינִין. וַיַחְפּוֹר אֶת בְּאֵרֹת הַמַיִם, לְאַרְקָא גְּבוּרָן לִכְּנֶסֶת יִשְׂרָאֵל, לְאִתְּעָרָא לְמַיָּא, דְּהָא מַיָּא בִּגְבוּרָן נַחְתָּן לְעָלְמָא.</p>\n<p>וּבְגִין דְּאִלֵּין גְּבוּרָן, לָא נַחְתִּין אֶלָּא בְּעִיבָא, וְיוֹמָא דְּעִיבָא לָא נַיְיחָא רוּחֵיהוֹן דְּקַיְימֵי עָלְמָא, אֶלָּא בְּגִין דְּעָלְמָא אִצְטְרִיךְ לְהוּ. מַאי טַעֲמָא. בְּגִין דְּעָלְמָא בְּדִינָא אִתְבְּרֵי, וְכֹלָּא בַּעְיָא הָכִי. בְּגִין כָּךְ כֹּלָּא בְּעוֹבָדָא תַּלְיָא מִלְּתָא. וְעַל דָּא, כַּהֲנָא בְּעוֹבָדָא וְתִקּוּנָא דְּאִיהוּ עָבִיד לְתַתָּא, אִתְּעֲרוּ עִלָּאִין וְתַתָּאִין לְתַקְּנָא לוֹן, וּמִתְתַּקְנֵי עַל יְדוֹי.</p>\n<p>אָמַר רִבִּי יוֹסֵי הָא תָּנֵינָן, הַעֲרָבָה דְּדַמְיָא לְשִׂפְוָון בְּהַאי יוֹמָא, וּמַאי הִיא. אָמַר רִבִּי חִיָּיא, אַף עַל גַּב דְּלִדְרָשָׁא הוּא דְּאָתֵי, הָכִי הוּא וַדַּאי. דְּהָא בְּהַאי יוֹמָא בְּשִׂפְוָון תַּלְיָא, בְּהַאי יוֹמָא פָּקִיד מַלְכָּא לְמֵיהַב פִּתְקִין לְסַנְטִירָא, וּמִסְתַּיְּימֵי דִּינִין, וְאַסְתִּים לִישָׁנָא בִּישָׁא מֵעָלְמָא. בְּיוֹמָא קַדְמָאָה דְּיַרְחָא שֵׁירוּתָא דְּדִינָא הוּא, וְסִיּוּמָא הוּא בְּהַאי יוֹמָא. וְהָא אִתְּמַר.</p>\n<p>תָּא חֲזֵי, בְּיוֹמָא דָּא שְׁלֵמִין וּמְסַיְּימֵי עַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה בִּרְכָאן דִּלְהוֹן, וְשָׁרָאן בְּדִינָא. וְיִשְׂרָאֵל בְּיוֹמָא דָּא מְסַיְּימֵי דִּינִין דִּלְהוֹן וְשָׁרָאן בְּבִרְכָתָא. דְּהָא לְיוֹמָא אָחֳרָא זְמִינִין לְאִשְׁתַּעְשְׁעָא בְּמַלְכָּא, לְנַטְלָא מִינֵיהּ בִּרְכָאן לְכָל שַׁתָּא, וּבְהַהוּא חֶדְוָותָא לָא מִשְׁתַּכְּחֵי בְּמַלְכָּא אֶלָּא יִשְׂרָאֵל בִּלְחוֹדַיְיהוּ. וּמַאן דְּיָתִיב עִם מַלְכָּא, וְנָטַל לֵיהּ בִּלְחוֹדֵיהּ, כָּל מַה דְּבָעֵי שָׁאִיל, וְיָהִיב לֵיהּ. וְעַל דָּא יִשְׂרָאֵל שָׁרָאן, וְעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה מְסַיְּימֵי. וְעַל דָּא כְּתִיב, (מלאכי א׳:ב׳) אָהַבְתִּי אֶתְכֶם אָמַר יְיָ' וְגוֹ'.</p>\n<p>אָמַר לֵיהּ, הָא חֲמֵינָא לֵיהּ לְעֵשָׂו בְּשַׁלְוָה, בְּמַלְכוּ, בִּכְרִיכָן עִלָּאִין, וְשָׁלִיט עַל עָלְמָא, וְאַתְּ אָמַר וָאָשִׂים אֶת הָרָיו שְׁמָמָה. אָמַר לֵיהּ, בְּכָל אֲתַר הָכִי הוּא. כֵּיוָן דְּמַלְכָּא קַדִּישָׁא גָּזַר גְּזֵרָה, וְשַׁוִּי הַהִיא גְּזֵרָה בְּפִתְקֵיהּ, קְרָא אַסְהִיד כְּמָה דְּאִתְעָבִיד. וְעַל דָּא וָאָשִׂים אֶת הָרָיו שְׁמָמָה, הָא שִׁוִיתִי בְּפִתְקָא דִּילִי. וְכֵן כָּל אִינּוּן טָבָן דְּגָזַר עָלַיְיהוּ דְּיִשְׂרָאֵל, דִּכְתִּיב, (יחזקאל י״ז:כ״ד) אֲנִי יְיָ' דִּבַּרְתִּי וְעָשִׂיתִי.</p>\n<p>(ויקרא ז׳:י״א) וְזֹאת תּוֹרַת הָאָשָׁם וְזֹאת תּוֹרַת הַמִּנְחָה וְזֹאת תּוֹרַת זֶבַח הַשְּׁלָמִים זֹאת תּוֹרַת הַחַטָּאת. רִבִּי יִצְחָק אָמַר, הָא אוּקְמוּהָ אִי לְתַתָּא דָּא בְּכֹלָּא. אִי לְעֵילָּא דָּא בְּכֹלָּא. וּמַאן דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא, נָטְלָא לְחוּלָקֵיהּ בְּכֹלָּא, וְאִתְאֲחִיד בְּכָל סִטְרִין, וְלָא בָּעֵי לְקָרְבָא קָרְבְּנָא עַל נַפְשֵׁיהּ, וְהָא אִתְּמַר.</p>"],[9520012022,"<p>רִבִּי יִצְחָק פָּתַח, (ירמיהו ב׳:ח׳) הַכֹּהֲנִים לֹא אָמְרוּ אַיֵה יְיָ' וְתוֹפְשֵׂי הַתּוֹרָה לֹא יְדָעוּנִי וְהָרוֹעִים פָּשְׁעוּ בִי. הַכֹּהֲנִים, אִלֵּין כֹּהֲנִים דִּמְשַׁמְּשִׁין בִּכְהוּנָה גְּדוֹלָה, וּמְקָרְבִין מִלִּין קַדִּישִׁין לְאַתְרַיְיהוּ, וּמְיַיחֲדִין יִחוּדָא כָּל חַד וְחַד כַּדְקָא חֲזֵי. וְתוֹפְשֵׂי הַתּוֹרָה מַאן אִינּוּן תּוֹפְשֵׂי הַתּוֹרָה, וְכִי כַּהֲנֵי לָאו תּוֹפְשֵׂי הַתּוֹרָה נִינְהוּ. אֶלָּא, אִלֵּין אִינּוּן לֵיוָאֵי, דְּתַפְשֵׂי בְּכִנּוֹרוֹת, דְּאַתְיָין מִסִּטְרָא דְּאוֹרַיְיתָא. וְאִתְיְיהִיבַת מִסִּטְרָא דִּלְהוֹן אוֹרַיְיתָא. וְאִינּוּן מְמָנָן עַל שְׁבָחָא דְּתוּשְׁבַּחְתָּא דְּמַלְכָּא קַדִּישָׁא, לְיַחֲדָא לֵיהּ יִחוּדָא שְׁלִים כְּדְקָא יֵאוֹת. וְהָרוֹעִים פָּשְׁעוּ בִי. אִלֵּין אִינּוּן רַבְרְבֵי עַמָּא, דְּאִינּוּן רַעְיָין לְעַמָּא, כְּרַעְיָא דְּמַדְבַּר עָאנֵיהּ.</p>\n<p>וְאִלֵּין אִינּוּן ג' דַּרְגִּין, דְּבַעְיָא לְאִשְׁתַּכְּחָא תָּדִיר עַל קָרְבְּנָא, לְאַשְׁכְּחָא רַעֲוָא לְעֵילָּא וְתַתָּא, וּלְאִשְׁתַּכְּחָא בִּרְכָאן בְּכֻלְּהוּ עָלְמִין. כַּהֲנָא מְקָרֵב קָרְבְּנָא, וְאִתְכְּוָּון לְיַחֲדָא שְׁמָא קַדִּישָׁא כַּדְקָא חֲזֵי, וּלְאַתְעֲרָא סִטְרָא דִּילֵיהּ. וְלֵיוָאֵי אִתְכַּוְּונָן בְּשִׁיר, לְאִתְּעָרָא סִטְרָא דִּלְהוֹן, <Nonei></i>וּלְאִתְכַּלְּלָא בְּסִטְרָא דְּכַהֲנָא. וְיִשְׂרָאֵל אִתְכְּוָּון לִבָּא וּרְעוּתָא לְתִיוּבְתָּא שְׁלֵימָתָא, וְאִתְכְּנָּע קָמֵי מַלְכָּא קַדִּישָׁא, וְהַאי נָטִיל כֹּלָּא, וְאִתְכְּפַּר חוֹבֵיהּ, וְאִשְׁתְּכַח חֶדְוָותָא בְּעִלָּאֵי וְתַתָּאֵי.</p>"],[9520012023,"<p>רִבִּי יְהוּדָה פָּתַח, (תהילים ק״ד:ג׳) הַמְקָּרֶה בַמַּיִם עֲלִיּוֹתָיו וְגוֹ'. קוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא עָלְמָא, מִגּוֹ מַיָּא אַפִּיק לֵיהּ, וְסִדֵּר לֵיהּ עַל מַיָּא. מָה עֲבַד. פָּלַג מַיָּא לִתְרֵין. פַּלְגּוּתָא לְתַתָּא, וּפַלְגּוּתָא לְעֵילָּא. וְעָבִיד מִנַּיְיהוּ עוֹבָדִין, מִפַּלְגוּתָא תַּתָּאָה עָבֵד וְתִקֵּן עָלְמָא דָּא, וְסִדֵּר לֵיהּ עַל פַּלְגּוּתָא דָּא, וְאַתְקִין לֵיהּ לְעֵילָּא עָלַיְיהוּ. הֲדָא הוּא דִכְתִיב, (תהילים כ״ד:ב׳) כִּי הוּא עַל יַמִּים יְסָדָהּ. וּפַלְגּוּ אָחֳרָא סַלְקֵיהּ לְעֵילָּא, וְתָקַר בֵּיהּ תִּקְרָאִין עִלָּאִין, הֲדָא הוּא דִכְתִיב הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו וְגוֹ'.</p>\n<p>וַעֲבַד רָקִיעַ בֵּין תְּרֵין פַּלְגּוּתַיָּא אִלֵּין, הֲדָא הוּא דִכְתִיב (בראשית א׳:ו׳) יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וְגוֹ', וְעָלַיְיהוּ אַתְקִין וְסִדֵּר עִלָּאִין קַדִּישִׁין מִגּוֹ טִיפֵּי טִיפֵּי בְּרוּחָא דְאִתְגַזְרָא בְּבְּסִיטָא (ס\"א בבוצינא) (ס\"א וסדר מלאכי עלאי קדישי, מגו רוחא דאתגזר מפומיה.) דִּכְתִּיב, (תהילים ל״ג:ו׳) וּבְרוּחַ פִּיו כָּל צְבָאָם.</p>\n<p>וּבְאִלֵּין אַתְקִין וְסִדֵּר מְזַמְּרֵי תּוּשְׁבַּחְתֵּיהּ בְּיוֹמָא, וְאִתְעָרְבוּ בְּשַׁלְהוֹבֵי אֶשָּׁא. וְאִינּוּן גְדוּדֵי חַיָּילִין, אַמְרִין שִׁירָתָא בְּיוֹמָא, תּוּשְׁבְּחָן בְּצַפְרָא, וּזְמִירָן בְּרַמְשָׁא. כַּד מָטֵי לֵילְיָא, כֻּלְּהוּ פַּסְקֵי שִׁירָתָא. לְעֵילָּא מִנַּיְיהוּ, גְּדוּדִין דְּאֶשָּׁא, בְּשַׁלְהוֹבָא תַּקִּיף, קַיְימִין וּמְרִיחִין אֶשָּׁא דְּאָכְלָא, וְאָהַדְרֵי לְאַתְרַיְיהוּ.</p>\n<p>וְאִית בְּסִטְרָא אָחֳרָא, דִּתְהוֹמִין סַלְּקִין אִלֵּין עַל אִלֵּין. וְאִית תְּהוֹמָא עִלָּאָה, וּתְהוֹמָא תַּתָּאָה, וּבְכֻלְּהוּ שָׁארָן מָארֵיהוֹן דְּדִינִין מִסִּטְרָא דְּדִינָא קַשְׁיָא. וְאִית בְּגוֹ סִטְרָא דִּתְהוֹמָא תַּתָּאָה, שַׁלְהוֹבָן דְּאוֹקְדִין זִיקִין נוּרִין, מְמָנָן עַל דִּינִין דְּעָלְמָא, לְאוֹקְדָא לְחַיָּיבַיָּא בְּנוּרָא, דְּנַגְדֵּי מֵהַהוּא נָהָר דִּינוּר. וְכֻלְּהוּ אֶשָּׁא, וְחֵיזוּ דִּלְהוֹן אֶשָּׁא דְּלָהִיט, וְקַיְימִין בֵּין עִלָּאֵי וְתַתָּאֵי.</p>\n<p>וְכַד תְּנָנָא דְּמַדְבְּחָא סָלִיק, מִתְעַבְּרָן וְסַלְּקִין מֵהַהוּא דַּרְגָּא, דְּקַיְימִין לְשֵׁיצָאָה וּלְאוֹבָדָא, וְהַהוּא נְגִידוּ דְּאֶשָּׁא תַּקִּיפָא דְּנָהַר דִּינוּר, דְּאִיהוּ תַּקִּיף וְעִלָּאָה, אַהְדָּר לְאַתְרֵיהּ. וְכֻלְּהוּ, מִתְהַנְיָין מִתְּנָנָא דְּמַדְבְּחָא, בְּגִין דְּאִתְתָּקְנַת לָקֳבְלֵי (ס\"א מדבחא) מַלְכָּא עִלָּאָה, וּבְגִין כָּךְ מִתְהַנְיָין מִנֵּיהּ, וְאִינּוּן קְרֵבִין לְהָכָא. וּתְנָנָא אָחֳרָא סָלִיק, וְהָא אוֹקִימְנָא, לְכָל חַד וְחַד, רְעוּתָא דְּכֹלָּא דְּסַלְּקָא לְעֵילָּא, דְּאִיהוּ נַיְיחָא דְּרוּחָא, לְגַבֵּי מַלְכָּא קַדִּישָׁא.</p>"],[9520012024,"<p>הָא אִתְּמַר, דִּבְמַדְבְּחָא סַלְּקָא וְאִתְחַזֵּי אוּרִיאֵ\"ל, כְּחֵיזוּ דְּחַד אַרְיָא תַּקִּיפָא, רְבִיעַ עַל טַרְפֵיהּ. וַהֲווּ חָמָאן כַּהֲנֵי וְיִשְׂרָאֵל, וְחַדָּאן, דַּהֲווֹ יַדְעִין דְּאִתְקַבַּל בְּרַעֲוָא קָמֵי מַלְכָּא קַדִּישָׁא. וְאֶשָּׁא אָחֳרָא עִלָּאָה קַדִּישָׁא נָחִית, לְקַבְּלָא אֶשָּׁא תַּתָּאָה, כְּדֵין בַּר נָשׁ אָזִיל (נ\"א דחיל) וְאִזְדַּעְזָע קָמֵי מָארֵיהּ, וְתָב בְּתִיּוּבְתָּא שְׁלֵימָתָא.</p>\n<p>לְמַלְכָּא דְּשַׁדְּרוּ לֵיהּ דּוֹרוֹנָא, וְאִתְיְישָׁר קָמֵיהּ, אָמַר לְעַבְדֵיהּ, זִיל וְטוֹל דּוֹרוֹן דָּא, דְּאַיְיתִיאוּ לִי. כַּךְ אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְאוּרִיאֵ\"ל, זִיל וְקַבִּיל דּוֹרוֹנָא דִּבְנַי מַקְרִיבִין קָמַאי. כַּמָה חֶדְוָוה מִשְׁתַּכְּחֵי בְּכֹלָּא, כַּמָה בְּסִימוּתָא בְּכֹלָּא מִשְׁתְּכַח, כַּד כַּהֲנָא וְלֵיוָאָה, וְהַהוּא דְּמַקְרִיב קָרְבְּנָא, מְכַוְּונֵי לְקָרְבָא קָרְבְּנָא כְּדְקָא יֵאוֹת, בְּיִחוּדָא שְׁלִים.</p>\n<p>תָּא חֲזֵי, כְּתִיב, (ויקרא ט׳:כ״ד) וַתֵּצֵא אֵשׁ מִלִּפְנֵי יְיָ' וַתֹּאכַל עַל הַמִּזְבֵּחַ אֶת הָעוֹלָה וְגוֹ'. דָּא אוּרִיאֵ\"ל, דְּנָחִית בְּחֵיזוּ דְּאֶשָּׁא בְּשַׁלְהוֹבָא, עַד דְּנָחִית לְמַדְבְּחָא, לְקַבְּלָא דּוֹרוֹנָא וְאִתְחַזֵּי כְּאַרְיֵה רַבְרְבָא, רְבִיעַ עַל קָרְבְּנָא.</p>\n<p>וְכַד יִשְׂרָאֵל לָא אִשְׁתְּכָחוּ זַכָּאִין, אוֹ הַהוּא דְּמַקְרִיב קָרְבְּנָא לָא קָרִיב כַּדְקָא יָאוּת, וְלָא אִתְקַבָּל קָרְבָּנֵיהּ, הֲווֹ חָמָאן דְּלָא סָלִיק תְּנָנָא בְּאֹרַח מֵישָׁר, וַהֲוָה קָם חַד רוּחָא מִנוּקְבָּא דְּצָפוֹן, וְעָאל לְמַדְבְּחָא, וַהֲווּ חָמָאן דִּיּוּקְנָא דְּחַד כַּלְבָּא חֲצִיפָא, רְבִיעַ עַל קָרְבְּנָא. כְּדֵין הֲווֹ יַדְעֵי דְּלָא אִתְקַבָּל בְּרַעֲוָא הַהוּא קָרְבְּנָא.</p>\n<p>לְמַלְכָּא דְּשַׁדְּרוּ לֵיהּ דּוֹרוֹן, חָמָא לֵיהּ מַלְכָּא דְּלָאו אִיהוּ כְּדַאי לְקָרְבָא קַמֵּיהּ, אָמַר מַלְכָּא, אֲסִיקוּ הַהוּא דּוֹרוֹנָא, וְהָבוּ לֵיהּ לְכַלְבָּא, דְּלָאו אִיהוּ כְּדַאי לְאַעֲלָא קָמַאי. כַּךְ בְּשַׁעֲתָא דְּקָרְבְּנָא אִתְקְרִיב, וְלָא אִתְקַבָּל בְּרַעֲוָא, דּוֹרוֹנָא לְכַלְבָּא אִתְמְסַר. וּבְגִין כָּךְ הֲווֹ חָמָאן, דִּיּוּקְנָא דְּכַלְבָּא עַל גַּבֵּי מַדְבְּחָא.</p>\n<p>תָּא חֲזֵי כְּתִיב <Nonei></i>(ויקרא ט׳:כ״ד) וַתֵּצֵא אֵשׁ מִלִּפְנֵי יְיָ' וַתֹּאכַל עַל הַמִּזְבֵּחַ אֶת הָעוֹלָה. אָמַר רִבִּי יְהוּדָה, דָּא אוּרִיאֵ\"ל, דְּאִתְחֲזֵי בְּשַׁלְהוֹבִיתָא דְּאֶשָּׁא עַל מַדְבְּחָא, כְּמָה דְּאִתְּמַר רְבִיעַ עַל קָרְבְּנָא. וּכְדֵין חֶדְוָותָא הֲוָה בְּכֹלָּא, דְּהָא אִתְקַבָּל בְּרַעֲוָוא, כְּמָה דִּכְתִּיב, וַיֵּרָא כְבוֹד יְיָ' אֶל כָּל הָעָם. וְאִי לָא הֲוָה עִרְבּוּבְיָא דִּבְנֵי אַהֲרֹן, מִן יוֹמָא דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרָיִם, לָא אִשְׁתְּכַח רַעֲוָא הָכִי לְעֵילָּא וְתַתָּא.</p>"],[9520012025,"<p><Noneb>רעיא מהימנא</b> פִּקּוּדָא דָּא לִשְׂרוֹף קֳדָשִׁים בְּאֵשׁ. וַאֲבַתְרֵיהּ וְהַנּוֹתָר מִבְּשַׂר הַזָּבַח בַּיּוֹם הַשְּׁלִישִׁי בָּאֵשׁ יִשָּׂרֵף. תָּנָאִין וְאָמוֹרָאִין. בְּסִתְרֵי תּוֹרָה, אִית קֹדֶשׁ, וְאִית קֳדָשִׁים, וְאִית קֹדֶשׁ קֳדָשִׁים. מַה הֲנָאָה אִית לְּקוּדְשָׁא בְּרִיךְ הוּא בַּקֳדָשִׁים דְּאִתּוֹקָדוּ. אִי תֵּימָא בְּגִין יִצְּחָק, דִּבְשַׁעֲתָא דְּיִשְׂרָאֵל בְּעָקוּ, סָלִיק אֲפָרוֹ שֶׁל יִצְּחָק קַמֵּיהּ, דְּאִי חַיָּיבִין שְׂרֵיפָה אִשְׁתֵּזִיבוּ בְּגִינֵיהּ. הַאי לִדְּרָשָׁא אִיהוּ. וְאִי תֵּימְרוּן בְּגִין (צדיקייא) (נ\"א ואי בגין) בְּנֵי אַהֲרֹן דַּהֲווֹ שְׂרֵיפַת קֳדָשִׁים, דִּכְתִּיב בְּהוֹן וַתֵּצֵּא אֵשׁ מִלִּפְנֵי יְיָ' וַתֹּאכַל אוֹתָם וַיָמוּתוּ. וּמִיתַתְהוֹן כַּפָּרָה לְיִשְׂרָאֵל כְּמוֹ שְׂרֵיפַת קֳדָשִׁים, אוּף דָּא לִדְּרָשָׁא קָא אָתֵי.</p>\n<p>אֶלָּא, תְּלַת אֶשִּׁין בִּשְׁרָגָא: אֶשָּׁא חִוָּורָא, וְאֶשָּׁא אוּכָמָא, וְאֶשָּׁא תְּכֶלְתָּא. לָקֳבֵל: תּוֹרָה, נְבִיאִים, וּכְתוּבִים. לָקֳבֵל: כֹּהֵן, לֵוִי, וְיִשְׂרָאֵל. וּתְכֵלֶת אִיהִי שְׁכִינְתָּא, קְרִיבָא לָן, וְאִיהִי אֲחִידָא בְּאִינּוּן פְּתִילוֹת, בְּכַנְפֵי מִצְּוָה, דְּאִתְּמַר בְּהוֹן וְעָשׂוּ לָהֶם צִּיצִּית. וְהַאי תְּכֵלֶת דְּאִיהִי שְׁכִינְתָּא, אִיהִי דִּינָא, דַּאֲכִילַת קָרְבָּנִין וְעִלָּוָון.</p>\n<p>אִי אַשְׁכָּחַת בְּנֵי נָשָׁא, דְּאִינּוּן עֵצִּים יְבֵשִׁים, כְּגַוְונָא דְּאִינּוּן פְּתִילוֹת יְבֵשִׁין, בְּלָא מִשְׁחָא, דְּאִיהִי אוֹרַיְיתָא רַחֲמֵי, אִיהִי לוֹן (דלידונון) שְׂרֵיפָה, וְאוֹקִידַת לוֹן. וּבְגִין דְּעַמֵי הָאָרֶץ אִינּוּן בְּעִירָן, כְּמָה דְּאוּקְמוּהָ דְּאִינּוּן שֶׁקֶץ. תְּכֵלֶת, דְּאִיהִי אֲדֹנָי, אוֹקִידַת לוֹן, בְּגִין דְּקָרְבִין לְגַבָּהּ עִם שֶׁרֶץ, דְּאִיהוּ יֵצֶּר הָרָע, זָר, הֲדָא הוּא דִכְתִיב, (במדבר ג׳:י׳) וְהַזָּר הַקָּרֵב יוּמָת.</p>\n<p>וְאִי בְּמִיתָתְהוֹן חַזְרִין בְּתִיּוּבְתָּא, (נ\"א כד שחיט לון מלאך המות מיכאל) מַלְאָךְ מִיכָאֵל דְּאִיהוּ כַּהֲנָא רַבָּא, אַרְיֵה דְּאָכִיל קָרְבְּנִין, נָחִית עָלַיְיהוּ, לְקָרְבָא לוֹן קָרְבְּנָא קֳדָם יְיָ'.</p>\n<p>וְקֹדֶם דְּתִפּוּק נִשְׁמָתֵיהּ, מִתְוַודֶּה בְּכַמָּה וִדוּיִין, וְכַד נָפִיק נִשְׁמָתֵיהּ הוּא הֲוָה מִתְכַּוִון לִגְמוֹר אֶת הַשֵׁם, שְׁמַע יִשְׂרָאֵל וּבָרוּךְ שֵׁם, לְקָרְבָא נִשְׁמָתֵיהּ מָאנָא (נ\"א קרבנא) לְשֵׁם יְהוָֹ\"ה, וְצָּרִיךְ לְמִתְוַדֶּה לְקוּדְשָׁא בְּרִיךְ הוּא, לְקַבֵּלָא לְקָרְבָא ה' בִּשְׁמֵיהּ, דְּאָכִיל וְשֵׁצֵּי, וּלְאַחְזְרָה בְּתִיּוּבְתָּא לְגַבֵּי יה\"ו, אֶהְיֶ\"ה כְּחוּשְׁבָן מ\"ב. דַּאֲדֹנָי קָרֵינָא לֵיהּ דִּינָא דְּמַלְכוּתָא דִּינָא.</p>\n<p>וִיכַוִּון בִּשְׁמָא מְפֹרָשׁ, דְּאִיהוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, בְּלֵּב אֶחָד. וּבֵיהּ יִפּוֹק רוּחֵיהּ. בְּנֶפֶשׁ דִּילֵיהּ מְקַבֵּל עָלֵיהּ מִיתָה וְיִסוּרִין. וּבְנִשְׁמְתָא מוֹדֶה בְּכַמָּה וִדוּיִין וּמִתְחָרֵט.</p>\n<p>בְּנֶפֶשׁ מְקַבֵּל עָלֵיהּ מִיתָה שְׁחִיטָה שְׂרֵיפָה, וְאִי צָּרִיךְ ד' מִיתוֹת בֵּית דִּין, דְּאִינּוּן סְקִילָה שְׂרֵיפָה הֶרֶג וְחֶנֶק, מְקַבֵּל לֵיהּ מֵאֲדֹנָ\"י בְּנֶפֶשׁ דִּילֵיהּ. וּבְנִשְׁמָתֵיהּ מוֹדֶה בְּכַמָּה וִידוּיִין, וְחוֹזִר בְּתִיּוּבְתָּא לְגַבֵּי אֶהְיֶ\"ה, דְּאָחִיד בִּתְרֵין שְׁמָהָן, יְהוָֹ\"ה יְהוָֹ\"ה.</p>\n<p>בְּמַחֲשַׁבְתֵיהּ יְכַוִין לְאַפָּקָא ודּוּי, וְקַבָּלַת מִיתָה עָלֵיהּ, בְּלֵּב א', דְּאִיהוּ שְׁמָא מְפֹרָשׁ, כְּגַוְונָא דָּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. (כבוד) בֵּיהּ כֹּהֲנִים כּוֹרְעִים וּמִשְׁתַּחֲוִים עַל פְּנֵיהֶם, וְאוֹמְרִים בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. כָּבוֹד, אִיהוּ ל\"ב בְּחוּשְׁבָּן. וּבֵיהּ הָיָה מִתְכַּוִּין לִגְמוֹר אֶת הַשֵׁם. (וא\"ו איהו א' בלב).</p>\n<p>וְתַנָאִין וְאָמוֹרָאִין, אִי תֵּימְרוּן וְכִי עַם הָאָרֶץ מְנָא יָדַע דָּא. אֶלָּא וַדַּאי עַם הָאָרֶץ אִיהוּ כְּשׁוֹר, אוֹ שֶׂה, אוֹ עֵז, אוֹ (פר) תּוֹר, אוֹ יוֹנָה. מַה בְּעִירָן לָא יַדְעֵי אוֹרַיְיתָא, דְּאִיהִי שֵׁם יְדוָֹ\"ד. הָכִי עַם הָאָרֶץ, לָא יָדַע. אֶלָּא מִיכָאֵל כַּהֲנָא רַבָּא, אִיהוּ עָבִיד לֵיהּ עוֹלָה וְקָרְבְּנָא קֳדָם יְיָ', וְאִיהוּ מְכַוְּון בִּשְׁמָא מְפֹרָשׁ, בִּסְלִיקוּ דְּרוּחֵיהּ, דְּתִפוּק בְּלֵּב אֶחָד, כְּגַוְונָא דְּכַד נָפִיק רוּחָא דְּבַּר נָשׁ בְּכָל לֵילְיָא.</p>\n<p>וּבְגִין דָּא אוּקְמוּהָ רַבָּנָן, שׁוּב יוֹם א' לִפְנֵי מִיתָתָךְ, דִּבְכָל יוֹם וְיוֹם צָּרִיךְ בַּר נָשׁ לְאָהַדְרָא בְּתִיּוּבְתָא, וּלְמִמְסַר רוּחֵיהּ לְגַבֵּיהּ, דְּיִפוּק בְּאֶחָד, הֲדָא הוּא דִכְתִיב, (תהילים ל״א:ו׳) בְּיָדְךָ אַפְקִיד רוּחִי.</p>\n<p>וְאִם הוּא תַּלְמִיד חָכָם, עָלֵיהּ אִתְּמַר (משלי י״ב:י׳) יוֹדֵעַ צַּדִּיק נֶפֶשׁ בְּהֶמְתּוֹ דְּלֵית חָכָם, כְּמוֹ כַּהֲנָא. כְּמָה דְּאוּקְמוּהָ הָרוֹצֶּה לְהַחְכִּים יַדְרִים. וְאִם תַּלְמִיד חָכָם הוּא, צָּרִיךְ שֶׁיְּהֵא בֵּיהּ חֶסֶד, וְעִם י' דְּאִיהוּ חָכְמָה, חָסִיד. וּמַאן <Nonei></i>דְּלֵית בֵּיהּ חָכְמָה, לָאו אִיהוּ חָסִיד. וּבְגִין דָּא אוּקְמוּהָ, וְלֹא עַם הָאָרֶץ חָסִיד. וְאִי אִית בֵּיהּ ה', חַמְשָׁה חוּמָשֵׁי תּוֹרָה, דְּאִתְיְיהִיבוּ מִשְּׂמָאלָא, אִתְקְרֵי גִּבּוֹר בַּתּוֹרָה, וִירֵא חֵטְא. וְאִי אִיהוּ בּוּר, אִתְּמַר בֵּיהּ, אֵין בּוּר יְרֵא חֵטְא.</p>\n<p>וּמַאן דְּזָכֵי לְתִפְאֶרֶת, דְּאִיהוּ ו', וְאִיהוּ חָכָם מֵבִין בַּתּוֹרָה וִירֵא חֵטְא, יָרִית מַלְכוּתֵיהּ, דְּאִיהוּ הֵ\"א, מִצְּוַת הַמֶּלֶךְ, אִי עָבִיד פִּקּוּדֵי מַלְכָּא. כֵּיוָן דְּזָכֵי לְשֵׁם יְהוָֹ\"ה, זָכֵי לִשְׁמָא מְפֹרָשׁ דְּאִתְקְרֵי אָדָם, וְדָא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. בְּהַהוּא זִמְנָא שַׁלִּיט עַל גּוּפֵיהּ, דְּאִיהוּ שׁוּתָּפוּ דְּנֶפֶשׁ הַבְּהֵמִית. וְרוּחַ הַבְּהֵמִית דִּבְנֶפֶשׁ הַבְּהֵמִית עֲשִׂיַּית הַבְלֵי עָלְמָא, רוּחַ מְמַלְּלָא בְּהַבְלֵי עָלְמָא (נשמה דבה כל הרהורין ומחשבות דהבלי עלמא). וְתַּלְמִיד חָכָם שַׁלִּיט עָלַיְיהוּ.</p>\n<p>הֲדָא הוּא דִכְתִיב, (בראשית א׳:כ״ו) וְיִרְדּוּ בִדְגַת הַיָם וּבְעוֹף הַשָׁמַיִם וּבַבְּהֵמָה וּבְכָל הָאָרֶץ. מַאי וּבְכָל הָאָרֶץ. דָּא גּוּפָא, עוֹלָם קָטָן, וְדַחֲלִין מִנֵּיהּ, הֲדָא הוּא דִכְתִיב, (בראשית ט׳:ב׳) וּמוֹרַאֲכֶם וְחִתְּכֶם. מִסִּטְרָא דִּימִינָא, שַׁלִּיט עָלַיְיהוּ, בֵּיהּ וְיִרְדּוּ, כְּמָה דְאַתְּ אָמֵר, (תהילים ע״ב:ח׳) וְיִּרְדְּ מִיָּם עַד יָם. מִסִּטְרָא דִּשְׂמָאלָא, דַּחֲלִין מִנֵּיהּ, הֲדָא הוּא דִכְתִיב וּמוֹרַאֲכֶם וְחִתְּכֶם. וְעָלֵיהּ אִתְּמַר, יוֹדֵעַ צַּדִּיק נֶפֶשׁ בְּהֶמְתּוֹ.</p>\n<p>בָּתַר דְּאִיהוּ צַּדִיק, לָא יָהִיב לֵיהּ שְׂכַר מִצְּוֹת, לֵית לֵיהּ אַגְרָא בְּעָלְמָא דָּא, וְלָא מְזוֹנָא לִבְעִירָן דְּעָנִי חָשׁוּב כַּמֵּת. אִיהוּ עִם שְׁכִינְתָּא בִּקְבִיעוּ דִּילָהּ עִמָּהּ עַל כֹּלָּא.</p>\n<p>(דברים ד׳:כ״ד) כִּי יְיָ' אֱלֹהֶיךָ אֵשׁ אוֹכְלָה הוּא. הַאי אֵשׁ, צָּרִיךְ לֵיהּ תָּמִיד עִמָּהּ, דְּלֵית לֵיהּ כְּבִיָה, דְּאִיהוּ אָכִיל כָּל קָרְבָּנִין דִּצְּלוֹתִין, וּמִלִּין דְּאוֹרַיְיתָא. דְּאִיהִי שְׁכִינְתָּא אִיהוּ פַּרְנָסָה דִּילֵיהּ, וּבְמָּה. בִּצְּלוֹתִין, הֲדָא הוּא דִכְתִיב, (שיר השירים ה) פִּתְחִי לִי. פִּתְחִי לִי, בִּצְּלוֹתָא דְּאִתְּמַר בָּהּ (תהילים נ״א:י״ז) אֲדֹנָי שְׂפָתַי תִּפְתָּח, דְּאִיהִי אֲחוֹתִי רַעְיָתִי, וְלֵית רַעְיָתִי אֶלָּא פַּרְנָסָתִי, דְּבָהּ מְתַקְּנִין מַאֲכָלִין דְּקָרְבְּנִין דְּמַלְכָּא בְּנִין קַדִישִׁין, בְּכַמָּה מִינֵי מַאֲכָלִים, בְּנַהֲמָא דְּאוֹרַיְיתָא.</p>\n<p>דְּאִתְּמַר בָּהּ (משלי ט׳:ה׳) לְכוּ לַחֲמוּ בְלַחְמִי, מִימִינָא. וּבְחַמְרָא, דְּאִיהוּ יֵינָא דְּאוֹרַיְיתָא, מִשְּׂמָאלָא. בְּנִסוּךְ הַמַּיִם, וְיַיִן דְּאוֹרַיְיתָא דְּבִכְתָב וּבְּעַל פֶּה, מֵעַמוּדָא דְּאֶמְצָּעִיתָא, דְּכָלִיל תַּרְוַויְיהוּ. בְּבִשְׂרָא, דְּאִיהִי בְּשַׂר הַקֹּדֶשׁ, בְּכַמָּה קָרְבָּנִין, דְּעָלָהּ אוּקְמוּהָ מָארֵי מַתְנִיתִין בְּבָשָׂר הַיוֹרֵד מִן הַשָּׁמַיִם עַסְקִינָן. מַאי מִן הַשָּׁמַיִם. עַמּוּדָא דְּאֶמְצָּעִיתָא. דְּעָלָהּ אִתְּמַר, וּבָשָׂר מִבְּשָׂרִי.</p>\n<p>וְדָא בְּשַׂר הַקֹּדֶשׁ, דְּאַדְלִיקַת בְּכַמָּה שַׁלְהוֹבִין, מִסִּטְרָא דִּגְבוּרָה בִּרְחִימוּ דְּבַעְלָהּ, אִתּוֹקְדַת בִּרְחִימוּ דְּאַהֲבָה בְּקְרִיאַת שְׁמַע, בִּרְחִימוּ דְּיִחוּדָא, דְּלֵילְיָא וְיוֹמָם לָא תִכְבֶּה. וְחַבְרַיָּיא בְּחַיִּיכוֹן אַל תִּתְּנוּ דֳּמִי לוֹ לְּקוּדְשָׁא בְּרִיךְ הוּא, לְמֶהֱוִי אִיהוּ בְּשָׁלְהוֹבִין דִּרְחִימוּ דְּיִחוּדֵיהּ דִּקְרִיאַת שְׁמַע. לְקַיְּימָא בֵּיהּ, אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה. (ע\"כ רעיא מהימנא).</p>"],[9520012026,"<p>תָּא חֲזֵי, אַף עַל גַּב דִּבִנֵי אַהֲרֹן מִיתוּ בְּהַהִֹיא שַׁעֲתָא, יָאוּת הֲוָה בְּכַמָּה גַּוְונִין. חֲדָא, דְּלָא הֲוָה שַׁעֲתָא דִּקְטֹרֶת, דְּהָא קְטֹרֶת לָא סַלְּקָא, אֶלָּא בְּזִמְנִין יְדִיעָן, דִּכְתִיב (שמות ל׳:ז׳) וְהִקְטִיר עָלָיו אַהֲרֹן קְטֹרֶת סַמִּים בַּבֹּקֶר בַּבֹּקֶר. וְאֵימָתַי בְּהֵטִיבוֹ אֶת הַנֵּרוֹת וְגוֹ' לְאִשְׁתַּכְחָא שֶׁמֶן וּקְטֹרֶת כַּחֲדָא. וּכְתִיב וּבְהַעֲלוֹת אַהֲרֹן אֶת הַנֵּרוֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה וְגוֹ'.</p>\n<p>וּבְזִמְנִין אִלֵּין אִתְקְרִיב, וְלָא בְּזִמְנָא אָחֳרָא, בַּר בְּזִמְנָא דְּמוֹתָנָא שַׁרְיָא בְּעָלְמָא, כְּמָה דְּאִעְרַע דִּכְתִיב (במדבר י״ז:י״א) וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְתֵן עָלֶיהָ אֵשׁ וְגוֹ'. וּבְנֵי אַהֲרֹן לָא קְרִיבוּ בְּשַׁעֲתָא דְּשֶמֶן וּקְטֹרֶת מִשְׁתַּכְחֵי כַּחֲדָא.</p>\n<p>וְעוֹד דְּדָחֲקוּ שַׁעֲתָא בְּחַיֵּי דַּאֲבוּהוֹן. וְעוֹד דְּלָא אַנְסִיבוּ, וַהֲווּ פְּגִימִין, <Nonei></i>דְּמַאן דְּלָא אַנְסִיב, פָּגִים הוּא, וְלָאו הוּא כְּדַאי לְאִשְׁתַּכְחָא בִּרְכָאן בְּעָלְמָא עַל יְדוֹי, עֲלוֹי לָא שַׁרְיָין, כָּל שֶׁכֵּן עַל יְדוֹי לַאֲחֵרִים. וְעוֹד, דְּהָא תְּנָן רְוָּוי חַמְרָא הֲווֹ, וּבְגִין כַּךְ, וַתֵּצֵא אֵשׁ מִלִּפְנֵי יְיָ' וַתֹּאכַל אוֹתָם וְגוֹ'. דְּהָא קְטֹרֶת חָבִיב הוּא מִכֹּלָּא, וְחֶדְוָותָא דְּעִלָּאִין וְתַתָּאִין, וּכְתִיב (משלי כ״ז:ט׳) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב.</p>"],[9520012027,"<p><Nonei></i><Noneb>רעיא מהימנא</b> (פקודי ר\"ס) לֵית מְצּוֹרָע אֶלָּא הַהוּא דְּאִתְעָבִיד בְּזָבוּתָא. דְּחָמֵשׁ דָּמִים אִינּוּן דְּדָם נִדָּה מִסְאֲבִין, דְּאִינּוּן כֻּלְּהוּ דָּם טָמֵא. וְה' דָּמִין דַּכְיָין. וּמַאן דְּאַעְבָּר עָלַיְיהוּ, כְּאִלּוּ אַעְבָּר עַל עֶשֶׂר דִּבְּרוֹת, דְּאִינּוּן כְּלַל תרי\"ג פִּקוּדִין.</p>\n<p>וְשִׁפְחָה יִצֶּר הָרָע אִיהִי מַלְיָא מוּמִין. וּבְגִין דָּא, (ויקרא כ״א:י״ח) כָל אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב. וּבְגִין דָּא, כַּהֲנָא לָא הֲוָה צָּרִיךְ לְקָרְבָא לְגַבֵי מַאן דְּאִית בֵּיהּ מוּמָא, מִכָּל מוּמִין דְּעָלְמָא. בְּגִין דְּמַטְרוֹנִיתָא אִתְּמַר בָּהּ, (שיר השירים ד׳:ז׳) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. הָכִי לָא צָּרִיךְ לְקָרְבָא לְגַבָּהּ מַאן דְּאִית בֵּיהּ מוּם, וְאוּף הָכִי לָא צָּרִיךְ לְמִקְרַב לְגַבָּהּ זָר (במדבר ג׳:י׳) וְהַזָּר הַקָּרֵב יוּמָת וְהַיְינוּ מַמְזִ\"ר, מוּ\"ם זָר. מוּם נוּקְבָּא, זָר זָכָר. וּבְגִין דָּא מָנֵי. (ויקרא י״ח:י״ט) וְאֶל אִשָּׁה בְּנִדַּת טוּמְאָתָהּ לֹא תִקְרַב וְעַל אִינּוּן דִּקְרִיבִין לָהּ, כְּתִיב בְּהוֹן וַיַקְרִיבוּ לִפְנֵי יְיָ' אֵשׁ זָרָה אֲשֶׁר לֹא צִּוָּה אוֹתָם וַתֵּצֵּא אֵשׁ מִלִּפְנֵי יְיָ'. <Nonei></i>וַתֹּאכַל אוֹתָם וַיָמוּתוּ.</p>\n<p>וְקָרְבָּן דְּאַתְוָון אִינּוּן, י' בָּאִישׁ, ה' בָּאִשָּׁה, ו' בַּבֵּן חָתָן, ה' בַּכַּלָּה. זַכָּאָה אִיהוּ מַאן דְּאַקְרִיב אַתְוָון דִּיְדוָֹ\"ד, בֵּיהּ וּבְאִתְּתֵיהּ וּבִבְרֵיהּ וּבִבְרַתֵּיהּ, בִּקְדוּשָּׁה וּבִבְרָכָה בִּנְקִיוּ בַּעֲנָוָה וּבְבֹשֶׁת פָּנִים בְּכָל מִדוֹת טָבִין דִּכְתִיבִין עַל מָארֵי מַתְנִיתִין.</p>\n<p>וּמִתְחַמְּמִין בְּאֶשִׁין קַדִישִׁין, דְּאִישׁ וְאִשָּׁה דְּאִינּוּן אֵשׁ, עוֹלֶה וְיּוֹרֵד, אֵשׁ קֹדֶשׁ דַּעֲצֵּי הַמַעֲרָכָה, דְּאִינּוּן עֲצֵּי הַקֹּדֶשׁ אֵבָרִין קַדִישִׁין, וְאֵשׁ שֶׁל גָּבוֹהַּ נָחִית, דְּאִיהוּ קֹדֶשׁ הַקָּדָשִׁים, וּבְגִין תְּרֵין אֶשִּׁין אִלֵּין אָמַר נָבִיא, (ישעיהו כ״ד:ט״ו) בָּאוּרִים כַּבְּדוּ יְיָ'. דְּאִינּוּן אֶשִּׁין דִּשְׁכִינְתָא, דְּבָהּ כְּתִיב (דברים ד׳:כ״ד) כִּי יְיָ' אֱלֹהֶיךָ אֵשׁ אוֹכְלָה הוּא.</p>\n<p>וְאִינּוּן אֵשׁ עִלָּאָה כִּסֵּא רַחֲמִים. אֵשׁ תַּתָּאָה כִּסֵּא דִּין. וְאִינּוּן בִּינָה וּמַלְכוּת מַלְכוּת אֵשׁ עוֹלֶה. בִּינָה אֵשׁ יוֹרֵד. יְהוָֹ\"ה, עַמּוּדָא דְּאֶמְצָּעִיתָא, אָחִיד בְּתַרְוַויְיהוּ. בִּינָה יה\"ו ה' מַלְכוּת.</p>\n<p>תִּפְאֶרֶת כַּד אָחִיד לוֹן, שַׁרְיָא עָלֵיהּ חָכְמָה, דְּבֵיהּ כֹּ\"חַ מַ\"ה. מָ\"ה: אִיהוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. כֹּחַ דִּילֵיהּ, יוֹ\"ד וָא\"ו דָּלֶ\"ת. הֵ\"א אָלֶ\"ף. וָא\"ו אָלֶ\"ף וָא\"ו. הֵ\"א אָלֶ\"ף. וְכֻלְּהוּ מ\"ב אַתְוָון, מִשְׁתַּכְחִין בְּבַּר נָשׁ וּבְאִתְתֵיהּ וּבִבְנוֹי, וּבְגִין דָּא לֵית בַּר נָשׁ שְׁלִים, אֶלָּא בְּבֵן וּבַת.</p>\n<p>וּמַאן דְּלֵית לֵיהּ בֵּן דְּאִיהוּ ו', אִסְתַּלָּק י' מִינֵיהּ. וּמַאן דְּלֵית לֵיהּ בַּת, דְּאִיהִי ה', אִסְתָּלַק ה' עִלָּאָה, דְּאִיהִי אֵם, מִן בַּת זוּגֵיהּ. דְּאַתְוָון לָא שַׁרְיָין דָּא בְּלָא דָּא. וּבְגִין דָּא, בְּאִישׁ וְאִשָּׁה בֵּן וּבַת, דְּאִתְעָבֵידוּ כְּדְקָא יִאוֹת, שַׁרְיָא עָלַיְיהוּ יְהוָֹ\"ה, וְאִתְקְרִיאוּ (שם י\"ד) (ס\"א בנים לקודשא בריך הוא. הדא הוא דכתיב) (דברים י״ד:א׳) בָּנִים אַתֶם לַיְדוָֹ\"ד אֱלֹהֵיכֶם. (ע\"כ רעיא מהימנא).</p>"],[9520012028,"<p>(ויקרא ז׳:ל״ה) זֹאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו. רִבִּי יוֹסֵי אָמַר, זֹאת וַדַאי מְשִׁיחוּתָא דְּאַהֲרֹן. דְּהָא אַהֲרֹן אִתְמְשַׁח, וְאַיְיתֵי מִמְשַׁח רְבוּת עִלָּאָה מֵעֵילָּא, וְנָגִיד לֵיהּ לְתַתָּא. וְעַל יְדָא דְּאַהֲרֹן אִתְמְשַׁח, מִמְשִׁיחָתָא קַדִישָׁא לְאִתְבָּרְכָא, וְעַל דָּא זֹאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו וַדַּאי.</p>\n<p>רִבִּי יְהוּדָה פָּתַח, (מלכים ב ד׳:ב׳) וַיֹאמֶר אֵלֶיהָ אֱלִישָׁע מָה אֶעֱשֶׂה לָךְ הַגִידִי לִי מַה יֶּשׁ לָךְ בַּבָּיִת. מֵהָכָא אוֹלִיפְנָא, דְּלֵית בִּרְכָתָא שַׁרְיָא בְּפָתוֹרָא רֵיקַנְיָא, וְעַל מִלָּה רֵיקָנִית. וַתֹּאמֶר אֵין לְשִׁפְחָתְךָ כֹּל בַּבַּיִת כִּי אִם אָסוּךְ שָׁמֶן. אָמַר לָהּ, ודַּאי סִיּוּעָא דְּנִיסָּא הוּא, דְּהָא וַדַּאי בְּאַתְרֵיהּ הוּא, וּמִתַּמָּן בִּרְכָאן נָפְקִין וְשַׁרְיָין. מַה כְּתִיב הֵם מַגִּישִׁים אֵלֶיהָ וְהִיא מוֹצָקֶת. וְהִיא מוֹצָקֶת סְתָם.</p>\n<p>רִבִּי יוֹסֵי אָמַר, וַיַּעֲמוֹד הַשָּׁמֶן, כְּמָה דְּאוּקְמוּהָ, דִּכְתִּיב, (ישעיהו ה׳:א׳) בְּקֶרֶן בֶּן שָׁמֶן. וּכְתִיב (שיר השירים א׳:ג׳) שֶׁמֶן תּוּרַק שְׁמֶךָ, לְאַחֲזָאָה דְּהָא מֵהַאי שֶׁמֶן, נְגִּידִין בִּרְכָאן עַל יְדָא דְּכַהֲנָא, וְכַהֲנָא נָגִיד לְהוּ לְתַתָּא, וְאַמְשַׁח (ס\"א ואתמשך) לְהַאי זֹאת, הֲדָא הוּא דִכְתִיב זֹאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו, וּכְתִיב (תהילים קל״ג:ב׳) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ, וְהָא אִתְּמַר.</p>"],[9520012029,"<p>(ויקרא ח׳:ב׳) קַח אֶת אַהֲרֹן וְאֶת בָּנָיו אִתּוֹ וְאֶת הַבְּגָדִים. רִבִּי חִיָּיא פָּתַח (תהילים ל״ו:י׳) כִּי עִמְּךָ מְקוֹר חַיִּים בְּאוֹרְךָ נִרְאֶה אוֹר. כִּי עִמְּךָ מְקוֹר חַיִּים, דָּא שֶׁמֶן עִלָּאָה, דְּנָגִיד וְלָא פָּסִיק לְעָלְמִין, דְּשַׁרְיָא בְּגוֹ חָכְמָה עִלָּאָה דְּכֹלָּא, הֲדָא הוּא דִכְתִיב כִּי עִמְּךָ, עִמְּךָ שַׁרְיָא, וְלָא מִתְפָּרְשָׁא מִנָךְ לְעָלְמִין, בַּחֲבִיבוּתָא דְּכֹלָּא. מְקוֹר חַיִים, בְּגִין דְּהִיא מְקוֹרָא וּמַבּוּעָא דְּחַיִּים, לְאַפָּקָא חַיִּים לְאִילָנָא עִלָּאָה, וּלַאֲדְלָקָא בּוּצִינִין. וְעַל דָּא הַהוּא אִילָנָא אִקְרֵי עֵץ חַיִּים, אִילָנָא דְּנָטִיעַ וְאִשְׁתָּרְשָׁא בְּגִין הַהוּא מְקוֹרָא דְּחַיִּים.</p>\n<p>וְעַל דָּא בְּאוֹרְךָ נִרְאֶה אוֹר. בְּאוֹרְךָ: דָּא אוֹר דְּגָנִיז לְצַדִּיקַיָּיא לְזִמְנָא דְּאָתֵי, דִּכְתִּיב, (בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וּמֵהַהוּא נְהִירוּ זְמִינִין יִשְׂרָאֵל לְאַנְהָרָא <Nonei></i>לְעָלְמָא דְּאָתֵי.</p>\n<p>דָּבָר אַחֵר כִּי עִמְּךָ מְקוֹר חַיִּים וְגוֹ', דָּא קוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ אִילָנָא עִלָּאָה בִּמְצִיעוּת גִּנְתָּא, דְּאָחִיד לְכָל סִטְרִין. מַאי טַעְמָא. בְּגִין דְּאָחִיד בֵּיהּ הַהוּא (נ\"א בההוא) מְקוֹר חַיִּים, וְאַעְטַּר לֵיהּ בְּעִטְרִין עִלָּאִין סַחֲרָנֵיהּ דְּגִּנְתָּא. כְּאִימָּא דִּמְעַטְּרָא לִבְרָהּ עַל כֹּלָּא, הֲדָא הוּא דִּכְתִּיב, (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן וְגוֹ'. וּבְגִין כָּךְ כִּי עִמְּךָ מְקוֹר חַיִּים, וְעַל דָּא בְּאוֹרְךָ נִרְאֶה אוֹר.</p>\n<p>רִבִּי יִצְחָק אָמַר, כִּי עִמְּךָ מְקוֹר חַיִּים, דָּא כֹּהֵן גָּדוֹל לְעֵילָּא, לָקֳבְלֵיהּ כֹּהֵן גָּדוֹל לְתַתָּא. בְּגִין כַּךְ, אַנְגִּיד כַּהֲנָא מְשַׁח רְבוּת עִלָּאָה קַדִּישָׁא לְתַתָּא, וְאַדְלִיק בּוּצִינִין לְעֵילָּא. דְּכֹהֵן גָּדוֹל שְׁלִים בִּשְׁלִימוּ דְּז' יוֹמִין עִלָּאִין, וּלְאִתְעַטְּרָא עַל כֹּלָּא.</p>\n<p>לָקֳבֵל דָּא ז' יְמֵי מִלּוּאִים, לְכַהֲנָא דִּלְתַתָּא, לְאִשְׁתַּכְּחָא כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא. וְעַל דָּא יְמֵי מִלּוּאִים אִקְרוּן: יוֹמֵי אַשְׁלְמוּתָא. בְּגִין דְּיִשְׁתְּלִים כַּהֲנָא בִּשְׁאָר יוֹמִין אָחֳרָנִין, לְאַשְׁלְמָא ז' כַּחֲדָא. וְאִלֵּין יְמֵי מִלּוּאִים אִקְרוּן, בְּגִין דְּאִתְאַחֲדָן שְׁאָר אָחֳרָנִין בֵּיהּ. מַאי קָא מַיְירֵי. דְּכַד כַּהֲנָא אִתְּעַר, כָּל שְׁאָר אָחֳרָנִין מִתְעָרִין עִמֵּיהּ.</p>\n<p>וּבְגִין כָּךְ כְּתִיב וּמִפֶּתַח אֹהֶל מוֹעֵד וְגוֹ', עַד יוֹם מְלֹאת וְגוֹ'. ז' יוֹמִין וַדַּאי, כְּדֵין אִתְעֲטָּר כַּהֲנָא לְתַתָּא בְּכֹלָּא, כְּגַוְונָא דִּלְעֵילָּא. בְּגִין דִּבְשַׁעֲתָא דְּכַהֲנָא דִּלְתַתָּא אִתְּעַר, כֹּלָּא יִתְּעֲרוּן עַל יְדֵיהּ לְעֵילָּא, וְיִשְׁתַּכְחוּן בִּרְכָאן לְעֵילָּא וְתַתָּא.</p>\n<p>רִבִּי אַבָּא אָמַר, מַאי שְׁנָא דְּמַשַׁח מֹשֶׁה לְאַהֲרֹן. אֶלָּא, בְּגִין דְּאִיהוּ בְּרָא דְּהַהוּא (ס\"א אחיד בההוא) אֲתַר מְקוֹרָא דְּחַיֵּי. וּכְתִיב (ישעיהו ס״ג:י״ב) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ. וּמֹשֶׁה שִׁמֵּשׁ כָּל אִינּוּן ז' יְמֵי מִלּוּאִין, לְאַשְׁרָאָה כֹּלָּא עִמֵּיהּ דְּאַהֲרֹן.</p>\n<p>רִבִּי חִזְקִיָּה הֲוָה יָתִיב קָמֵי דְּרִבִּי אֶלְעָזָר, אָמַר לֵיהּ, כַּמָה נְהוֹרִין אִתְבְּרִיאוּ עַד לָא אִבְרֵי עָלְמָא. אָמַר לֵיהּ ז'. וְאִלֵּין אִינּוּן: אוֹר תּוֹרָה. אוֹר גֵּיהִנָּם. אוֹר גַּן עֵדֶן. אוֹר כִּסֵּא הַכָּבוֹד. אוֹר בֵּית הַמִּקְדָּשׁ. אוֹר תְּשׁוּבָה. אוֹרוֹ שֶׁל מָשִׁיחַ. וְאִלֵּין אִתְבְּרִיאוּ עַד לָא אִתְבְּרֵי עָלְמָא. ז' נְהוֹרִין בּוּצִינִין אִתְאֲחָדוּ בֵּיהּ בְּאַהֲרֹן, וְהוּא אַדְלִיק בּוּצִינִין מֵעֵילָּא לְתַתָּא.</p>"],[9520012030,"<p>רִבִּי אֶלְעָזָר פָּתַח (קהלת ג׳:כ׳) הַכֹּל הָיָה מִן הֶעָפָר וְהַכֹּל שָׁב אֶל הֶעָפָר. הָא תָּנֵינָן, הַכֹּל הָיָה מִן הֶעָפָר, אֲפִילּוּ גַּלְגַּל חַמָּה. מַאן הֶעָפָר. הַהוּא דְּשַׁרְיָא תְּחוֹת כּוּרְסֵי יְקָרָא קַדִּישָׁא.</p>\n<p>בְּסִפְרָא דְּבֵי רַב יֵיסָא סָבָא, הַכֹּל הָיָה מִן הֶעָפָר, אֲתַר דְּכָנִישׁ לְכֹלָּא, מְלַמֵּד, דְּנַפְקוּ שְׁבִילִין לְהַאי סִטְרָא וּלְהַאי סִטְרָא, וְאִתְכְּנָשׁוּ לְאַנְהָרָא, כְּעַפְרָא דָּא דְּזַרְקִין לָהּ לְכָל עִבָר. וְעַל דָּא הַכֹּל הָיָה מִן הֶעָפָר, וְהַכֹּל שָׁב אֶל הֶעָפָר וַדַּאי.</p>\n<p>אֶלָּא מִן הֶעָפָר, דְּבֵי מַקְדְּשָׁא קַדִּישָׁא. וְהַאי עָפָר מֵעַפְרָא עִלָּאָה, כְּמָה דְאַתְּ אָמֵר (איוב כ״ח:ו׳) וְעַפְרוֹת זָהָב לוֹ. כְּמָה דְּאִשְׁתְּכַח עוֹבָדָא לְתַתָּא, הָכִי נָמֵי הוּא לְעֵילָּא כְּגַוְונָא דָּא. וְאוֹקִימְנָא עָפָר, עָפָר דְּבֵי מַקְדְּשָׁא. דְּעָלְמָא דָּא בְּה' אִתְבְּרֵי. וְעַל דָּא, אֲפִילּוּ גַּלְגַּל חַמָּה. כְּמָה דְּאַתְּ אָמֵר, אֵלֶה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. וּבְגִּינֵי כַּךְ, הַכֹּל הָיָה מִן הֶעָפָר. מַאן עָפָר. הַהוּא דְּשָׁרִי תְּחוֹת כּוּרְסֵי יְקָרָא קַדִּישָׁא.</p>\n<p>כְּתִיב (שיר השירים ד׳:ז׳) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. כֻּלָּךְ יָפָה רַעְיָתִי, דָּא כְּנֶסֶת יִשְׂרָאֵל. וּמוּם אֵין בָּךְ, אֵלּוּ סַנְהֶדְרִין דְּאִינּוּן לָקֳבֵיל שִׁבְעִין וּתְרֵין שְׁמָהָן. ע' נֶפֶשׁ דְּנַחְתּוּ עִם יַעֲקֹב, וְקוּדְשָׁא בְּרִיךְ הוּא עַל כֹּלָּא. וְעַל דָּא אֵין בּוֹדְקִין מִן הַסַנְהֶדְרִין וּלְמַעְלָה תְּנָן.</p>\n<p>כְּתִיב (שמות י״ט:ו׳) וְאַתֶם תִּהְיוּ לִי מַמְלֶכֶת כֹּהֲנִים וְגוֹי קָדוֹשׁ. מַאן מַמְלֶכֶת כֹּהֲנִים. כְּמָה דְאַתְּ אָמֵר, זֹאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו, דְּכַד אִתְבָּרְכָא כְּנֶסֶת יִשְׂרָאֵל עַל יְדָא דְּכַהֲנֵי, כְּדֵין אִתְקְרֵי עַל שְׁמֵיהוֹן, הֲדָא הוּא דִכְתִיב מַמְלֶכֶת כֹּהֲנִים.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, תָּא חֲזֵי, מַלְכוּת כֹּהֲנִים לָא אִקְרֵי, אֶלָּא מַמְלֶכֶת, דְּאַמְלְכוּ לָהּ כַּהֲנֵי, וְעַבְדוּ לָהּ (גבירתא) גְּבוּרְתָּא עַל כֹּלָּא. אֲבָל מַלְכוּת כֹּהֲנִים לָא אִקְרֵי, דְּהָא מִן הַשָּׁמַיִם אִקְרֵי מַלְכוּת, מַלְכוּת שָׁמַיִם וַדַּאי. וְהָכָא מַמְלֶכֶת, כְּמָה דְאַתְּ אָמֵר דְּכַהֲנֵי אַמְלְכוּ לָהּ, וּמְחַבְּרָאן לָהּ בְּמַלְכָּא, וּכְדֵין הִיא מַמְלֶכֶת, עַל כָּל גִּנְזֵי מַלְכָּא. מַמְלֶכֶת עַל כָּל זַיְנֵי מַלְכָּא. <Nonei></i>מַמְלֶכֶת בְּעִלָּאֵי וְתַתָּאֵי. מַמְלֶכֶת עַל כָּל עָלְמָא.</p>"],[9520012031,"<p>רִבִּי יוֹסֵי אָמַר, כְּתִיב (עמוס ט׳:ו׳) וַאֲגֻדָּתוֹ עַל אֶרֶץ יְסָדָהּ. וַאֲגֻדָּתוֹ: כַּד אִזְדְּוַוג מַלְכָּא לָקֳבְלָהּ, בְּכָל אִינּוּן עִטְרִין קַדִישִׁין, בִּכְנוּפְיָא חַד, כְּדֵין וַאֲגֻדָּתוֹ כְּתִיב.</p>\n<p>רִבִּי יִצְחָק אָמַר, וַאֲגֻדָּתוֹ: כְּמָה דְאַתְּ אָמֵר, (שמות י״ב:כ״ב) וּלְקַחְתֶּם אֲגֻדַּת אֵזוֹב. מַאי קָא מַיְירֵי. דְּכַד מִתְחַבְּרָאן כַּחֲדָא, וְאִתְבָּרְכָא מִנַּיְיהוּ, כְּדֵין שַׁלְטָא עַל כֹּלָּא, וְנַהֲרָא לְעֵילָּא וְתַתָּא. וְכֹלָּא בְּשַׁעֲתָא דְּכַהֲנָא פָּלַח פּוּלְחָנָא, וְאַקְרִיב קָרְבְּנָא, וְאַקְטַר קְטֹרֶת, וּמְכַוִּון מִלִּין לְקָרְבָא כֹּלָּא כַּחֲדָא. כְּדֵין כְּתִיב, וַאֲגֻדָּתוֹ עַל אֶרֶץ יְסָדָהּ.</p>\n<p>רִבִּי יוֹסֵי אָמַר, כַּד נָטַל אַהֲרֹן כֹּלָּא נַטְלִין עִמֵּיהּ, עַד דְּאִתְבָּרְכָא כְּנֶסֶת יִשְׂרָאֵל, וְאִתְבָּרְכָאן עִלָּאֵי וְתַתָּאֵי. כְּדֵין כְּתִיב, (תהילים קל״ה:כ״א) בָּרוּךְ יְיָ' מִצִיּוֹן שׁוֹכֵן יְרוּשָׁלַם הַלְלוּיָהּ. (תהילים ע״ב:י״ט) וּבָרוּךְ שֵׁם כְּבוֹדוֹ לְעוֹלָם וְיִמָּלֵא כְבוֹדוֹ אֶת כָּל הָאָרֶץ אָמֵן וְאָמֵן.</p>"],[9520012032,"<p>רִבִּי אֶלְעָזָר הֲוָה אָזִיל מִקַּפּוֹטְקַיָּא לְלוּד, וַהֲווּ עִמֵּיהּ רִבִּי יֵיסָא וְרִבִּי חִזְקִיָּה. פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (ישעיהו נ״א:ט״ז) וָאָשִׂים דְּבָרַי בְּפִיךָ וּבְצֵל יָדִי כִּסִּיתִיךָ וְגוֹ'. תָּנֵינָן, כָּל בַּר נָשׁ דְּאִשְׁתָּדַּל בְּמִלֵּי דְּאוֹרַיְיתָא, וְשִׂפְוָותֵיהּ מְרַחְשָׁן אוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא חַפְּיָא עָלֵיהּ, וּשְׁכִינְתָּא פַּרְשָׂא עָלֵיהּ גַּדְפָהָא, הֲדָא הוּא דִכְתִיב וָאָשִׂים דְּבָרַי בְּפִיךָ וּבְצֵל יָדִי כִּסִּיתִיךָ. וְלֹא עוֹד, אֶלָּא דְּהוּא מְקַיֵּים עָלְמָא, וְקוּדְשָׁא בְּרִיךְ הוּא חַדֵּי עִמֵּיהּ, כְּאִלּוּ הַהוּא יוֹמָא נָטַע שְׁמַיָא וְאַרְעָא. הֲדָא הוּא דִכְתִיב, (ישעיהו נ״א:ט״ז) לִנְטוֹעַ שָׁמַיִם וְלִיסוֹד אָרֶץ וְלֵאמֹר לְצִיּוֹן עַמִּי אָתָּה.</p>\n<p>מִכָּאן אוֹלִיפְנָא, דְּיִשְׂרָאֵל אִקְרוּן בִּשְׁמָא דְּצִיּוֹן, דִּכְתִּיב וְלֵאמֹר לְצִיּוֹן עַמִּי אַתָּה, וַחֲמֵינָא דִּכְנֶסֶת יִשְׂרָאֵל אִקְרֵי בִּשְׁמָא דְּצִיּוֹן, דִּכְתִּיב, (ישעיהו א׳:כ״ז) צִיּוֹן בְּמִשְׁפָּט תִּפָּדֶה וְשָׁבֶיהָ בִּצְדָקָה.</p>\n<p>תּוּ פָּתַח וְאָמַר, (ישעיהו ח׳:ט״ז) צוֹר תְּעוּדָה חֲתוֹם תּוֹרָה בְּלִמּוּדָי. צוֹר תְּעוּדָה. דָּא סַהֲדוּתָא דְּדָוִד, דִּכְתִּיב, (תהילים קל״ב:י״ב) וְעֵדוֹתִי זוֹ אֲלַמְּדֵם. צוֹר: הִיא קִשּׁוּרָא, כְּמַאן דְּקָטַר קְטוּרָא בַּאֲתַר חַד. חֲתוֹם תּוֹרָה בְּלִמּוּדָי. חֲתוֹם תּוֹרָה: חַתִימָה דְּאוֹרַיְיתָא, וְכָל נְגִידוּ וּרְבוּ דְּנָגִיד מִלְּעֵילָּא, בְּאָן (נ\"א בין) חֲתִימָה דִּילֵיהּ. בְּלִמּוּדָי. בְּגִין דְּתַמָּן אִתְכְּנַשׁ רְבוּ וּמִשְׁחָא, בֵּין תְּרֵין קַיָימִין, דְּתַמָּן שַׁרְיָין, אֲתַר כְּנִישׁוּ דְּכָל רְבוּת וּמְשַׁח דְּנָגִיד מִלְּעֵילָּא, לְאַשְׁדָּאָה לֵיהּ בְּפוּמָא דְּאַמָּה, וּלְאַרְקָא לֵיהּ בְּהַאי תְּעוּדָה. וּכְדֵין אִתְקְשַׁר כֹּלָּא קִשְׁרָא חַד מְהֵימָנָא.</p>"],[9520012033,"<p>תָּא חֲזֵי, מַה בֵּין אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, לִנְבִיאֵי מְהֵימְנֵי. אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, עֲדִיפֵי מִנְּבִיאֵי בְּכָל זִמְנָא. מַאי טַעֲמָא. דְּאִינּוּן קַיְימֵי בְּדַרְגָּא עִלָּאָה, יַתִּיר מִנְּבִיאֵי, אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא קַיְימֵי לְעֵילָּא, בְּאַתְרָא דְּאִקְרֵי תּוֹרָה, (נ\"א תפארת) דְּהוּא קִיוּמָא דְּכָל מְהֵימְנוּתָא. וּנְבִיאֵי קַיְימֵי לְתַתָּא, בַּאֲתַר דְּאִקְרוּן נֶצַח וְהוֹד. וְעַל דָּא (אקרון), אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, עֲדִיפֵי מִנְּבִיאֵי, וְעִלָּאִין מִנְּהוֹן יַתִּיר. דְּאִלֵּין קַיְימִין לְעֵילָּא, וְאִלֵּין קַיְימִין לְתַתָּא. אִינּוּן דְּאַמְרֵי מִלִּין בְּרוּחַ הַקֹּדֶשׁ, קַיְימֵי לְתַתָּא מְכֻּלְּהוּ. (ועל דא)</p>\n<p>זַכָּאִין אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, דְּאִינּוּן בְּדַרְגָּא עִלָּאָה יַתִּיר עַל כֹּלָּא. (ועל דא) מַאן דְּלָעֵי בְּאוֹרַיְיתָא, לָא אִצְטְרִיךְ לָא לְקָרְבְּנִין, וְלָא לְעִלָּוָון. דְּהָא אוֹרַיְיתָא עָדִיף מִכֹּלָּא, וְקִשּׁוּרָא דִּמְהֵימְנוּתָא דְּכֹלָּא. וְעַל דָּא כְּתִיב, (משלי ג׳:י״ז) דְּרָכֶיהָּ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. וּכְתִיב, (תהילים קי״ט:קס״ה) שָׁלוֹם רָב לְאוֹהֲבֵי תוֹרָתֶךָ וְאֵין לָמוֹ מִכְשׁוֹל.</p>"],[9520012034,"<p>עַד דַּהֲווֹ אָזְלֵי, אַשְׁכָּחוּ חַד גַּבְרָא דְּהֲוָה אָתֵי, וְג' עַנְפֵּי הֲדַס בִּידֵיהּ, קְרִיבוּ גַּבֵּיהּ, אָמְרוּ לֵיהּ לָמָּה לָךְ הַאי. אָמַר לְרַוְוחָא אוֹבְדָא. אָמַר רִבִּי אֶלְעָזָר שַׁפִּיר קָאָמְרָת. אֲבָל ג' אִלֵּין לָמָּה. אָמַר לֵיהּ, חַד לְאַבְרָהָם. חַד לְיִצְחָק, וְחַד לְיַעֲקֹב. וְקַשִׁירְנָא לְהוּ כַּחֲדָא, וְאָרַחְנָא בְּהוּ. בְּגִין דִּכְתִּיב, (שיר השירים א׳:ג׳) לְרֵיחַ שְׁמָנֶיךָ טוֹבִים שֶׁמֶן תּוּרַק שְׁמֶךָ. בְּגִין דִּבְהַאי רֵיחָא, אִתְקְיַּים חוּלְשָׁא דְּנַפְשָׁא, וּבְהֵימְנוּתָא דָּא אִתְקַיְּימָא, וְאִתְנְגִידוּ בִּרְכָאן מֵעֵילָּא וְתַתָּא. אָמַר רִבִּי אֶלְעָזָר זַכָּאָה חוּלָקֵיהוֹן <Nonei></i>דְּיִשְׂרָאֵל בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.</p>\n<p>תָּא חֲזֵי, לֵית עָלְמָא (נ\"א נפשא) מִתְקַיְּימָא, אֶלָּא עַל רֵיחָא, וּמֵרֵיחָא דָּא אִשְׁתְּמוֹדְעָא רֵיחָא אָחֳרָא. דְּהָא בְּשַׁעֲתָא דְּנָפִיק שַׁבְּתָא, (נתפרדה החבילה) וְסַלְּקָא נַפְשָׁא יְתֵירָא, וְאִשְׁתָּאֲרוּן נַפְשָׁא וְרוּחָא מִתְפָּרְשָׁן עֲצִיבִין, אָתָא רֵיחָא דָּא, וּמִתְקָרְבָן דָּא בְּדָא וְחַדָּאן.</p>\n<p>וְעַל דָּא, בָּעֵי רוּחָא בָּתַר רוּחָא, לְקַבְּלָא רֵיחָא, כֵּיוָן דְּאִתְקָבַּל רֵיחָא מִתְקָרְבָן כַּחֲדָא וְחַדָּאן. כֵּי הַאי גַּוְונָא רֵיחָא דְּקוּרְבְּנָא, בְּרֵיחָא (דא) מִתְקָרְבִין כֹּלָּא כַּחֲדָא, וּמִתְלַהֲטָן בּוּצִינֵי וְחַדָּאן.</p>\n<p>תָּא חֲזֵי, תְּרֵי בּוּצִינֵי, חַד לְעֵילָּא וְחַד לְתַתָּא, אִי לָהִיט בַּר נָשׁ הַאי בּוּצִינָא דִּלְתַתָּא, וְכַבֵי לָהּ (ס\"א לההוא דלעילא), הַהוּא תְּנָנָא דְּסָלִיק (נ\"א מבוצינא תתאה), לָהִיט הַהוּא בּוּצִינָא עִלָּאָה. כַּךְ תְּנָנָא דְּקָרְבְּנִין, הַאי תְּנָנָא דְּסָלִיק, לָהִיט בּוּצִינֵי עִלָּאֵי, וּמִתְלַהֲטָן בְּחַד, וּמִתְקָרְבִין כֻּלְּהוּ כַּחֲדָא, בְּרֵיחָא דָּא. וּבְגִין כָּךְ, רֵיחַ נִיחֹחַ לַיְיָ', (אשה) וְהָא אוּקְמוּהָ.</p>\n<p>וְעַל דָּא, רֵיחָא דְּקָרְבְּנָא, קִיּוּמָא דְּכֹלָּא, וְקִיּוּמָא דְּעָלְמָא. וְקָרְבְּנָא עַל יְדָא דְּכַהֲנָא, דְּמִקְרַב כֹּלָּא. וּבְגִין כָּךְ, שִׁבְעָה יוֹמֵי אַשְׁלְמוּתָא, אִשְׁתְּלִימוּ בֵּיהּ, בְּגִין דְּיִתְבָּרְכוּן כֻּלְּהוּ בְּפוּלְחָנֵיהּ, וְיִשְׁתְּכָחוּ חֶדְוָואן וּבִרְכָּאן לְעֵילָּא וְתַתָּא.</p>"],[9520012035,"<p>כְּתִיב (ישעיהו כ״ה:א׳) יְיָ' אֱלֹהַי אַתָּה אֲרוֹמִמְךָ וְגוֹ', הַאי קְרָא אוּקְמוּהָ, יְיָ' אֱלֹהַי אַתָּה. דְּבָעֵי בַּר נָשׁ לְאוֹדָאָה לִשְׁמָא קַדִּישָׁא, וּלְשַׁבְּחָא לֵיהּ עַל כֹּלָּא. וּמַאן אֲתַר שְׁבָחָא דִּילֵיהּ, כְּמָה דְּאוּקְמוּהָ. וְהָכָא מֵעֲמִיקָא דְּכֹלָּא, דִּכְתִּיב כִּי עָשִׂיתָ פֶּלֶא. פֶּלֶא: כְּמָה דִּכְתִּיב, (ישעיהו ט׳:ה׳) וַיִּקְרָא שְׁמוֹ פֶּלֶא, וְהָא אִתְּמַר. עֵצוֹת מֵרָחוֹק, עֵצוֹת: כְּמָה דְאַתְּ אָמֵר, יוֹעֵץ. מֵרָחוֹק: דִּכְתִּיב, (ירמיהו ל״א:ג׳) מֵרָחוֹק יְיָ' נִרְאָה לִי. וּכְתִיב, (משלי ל״א:י״ד) מִמֶּרְחָק תָּבִיא לַחְמָהּ.</p>\n<p>אֱמוּנָה אֹמֶן, כְּמָה דְאַתְּ אָמֵר, (דברים ל״ב:ד׳) אֵל אֱמוּנָה וְאֵין עָוְל. וְאוּקְמוּהָ אֱמוּנָה בַּלַּיְלָה, כְּמָה דְאַתְּ אָמֵר (תהילים צ״ב:ג׳) וְאֱמוּנָתֶךָ בַּלֵּילוֹת. וּכְתִיב (איכה ג׳:כ״ג) חֲדָשִׁים לַבְּקָרִים רַבָּה אֱמוּנָתֶךָ, וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְדַכְּאָה לוֹן לְיִשְׂרָאֵל מֵחוֹבֵיהוֹן, כְּמָה דִּכְתִּיב, (יחזקאל ל״ו:כ״ה) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם מִכָּל טֻמְאוֹתֵיכֶם וּמִכָּל גִּלּוּלֵיכֶם אֲטַהֵר אֶתְכֶם. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן</p>"],[9520012036,"<p>(ויקרא ט׳:א׳) וַיְהִי בַּיוֹם הַשְּׁמִינִי וְגוֹ'. רִבִּי יִצְחָק פָּתַח, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹּקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לוֹן אוֹרַיְיתָא קַדִּישָׁא, חֶדְוָותָא דְּכֹלָּא, חֶדְוָותָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאַטְיָילוּתָא דִּילֵיהּ, דִּכְתִּיב, (משלי ח׳:ל׳) וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. וְאוֹרַיְיתָא כֹּלָּא, חַד שְׁמָא קַדִּישָׁא אִיהִי דְּקוּדְשָׁא בְּרִיךְ הוּא. וּבְאוֹרַיְיתָא אִתְבְּרֵי עָלְמָא דִּכְתִּיב, (משלי ח׳:ל׳) וָאֶהְיֶה אֶצְלוֹ אָמוֹן אַל תִּקְרֵי אָמוֹן אֶלָּא אוּמָן.</p>\n<p>וּבְאוֹרַיְיתָא אִתְבְּרֵי בַּר נָשׁ, הֲדָא הוּא דִכְתִיב, (בראשית א׳:כ״ו) וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם. אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְאוֹרַיְיתָא, בָּעֵינָא לְמִבְרֵי אָדָם. אָמְרָה קַמֵּיהּ, הַאי בַּר נָשׁ זַמִּין לְמֶחֱטֵי וּלְאַרְגְזָא קַמָּךְ, אִי לָא תַּאֲרִיךְ רוּגְזָךְ עָלֵיהּ, הֵיךְ יְקוּם בְּעָלְמָא. אָמַר לָהּ, אֲנָא וְאַתְּ נוֹקִים לֵיהּ בְּעָלְמָא, דְּהָא לָאו לְמַגָּנָא אִתְקָרֵינָא אֶרֶךְ אַפַּיִם. (ס\"א דהא כל זמנא דישתדלון באורייתא מתקיימי בעלמא)</p>\n<p>רִבִּי חִיָּיא אָמַר, תּוֹרָה שֶׁבִּכְתָּב וְתוֹרָה שֶׁבְּעַל פֶּה אוּקְמוּהָ לֵיהּ לְבַּר נָשׁ בְּעָלְמָא, הֲדָא הוּא דִכְתִיב נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵינוּ. רִבִּי יוֹסֵי אָמַר מֵהָכָא, (קהלת ב׳:י״ב) אֵת אֲשֶׁר כְּבָר עָשׂוּהוּ, עָשׂוּהוּ וַדַּאי. וְדָא הוּא צֶלֶם וּדְמוּת, צֶלֶם: בִּדְכוּרָא. דְּמוּת: בְּנוּקְבָּא וְעַל דָּא שֵׁירוּתָא דְּאוֹרַיְיתָא ב', וְאוֹקְמוּהָ.</p>\n<p>רִבִּי יִצְחָק אָמַר, מִפְּנֵי מַה ב' פְּתִיחָא וּסְתִימָא. אֶלָּא, בְּשַׁעֲתָא דְּבַּר נָשׁ אָתֵי <Nonei></i>לְאִתְחַבְּרָא בְּאוֹרַיְיתָא, הֲרֵי הִיא פְּתִיחָא לְקַבְּלָא לֵיהּ, וּלְאִשְׁתַּתְּפָא בַּהֲדֵיהּ. וּבְשַׁעֲתָא דְּבַּר נָשׁ, סָתִים עֵינוֹי מִנָּהּ, וְיֵהַךְ לְאָרְחָא אָחֳרָא, הֲרֵי הִיא סְתִימָא, מִסִּטְרָא אָחֳרָא. כְּמָה דְאַתְּ אָמֵר, אִם יוֹם תַּעַזְבֵנִי יוֹמַיִם אֱעֶזְבֶךָּ. וְלָא יִשְׁכַּח פִּתְחָא, עַד דְּיֵתוּב לְאִתְחַבָּר בָּהּ בְּאוֹרַיְיתָא אַנְפִּין בְּאַנְפִּין, וְלָא יִתְנְשֵׁי מִנָּהּ. וְעַל דָּא אוֹרַיְיתָא פַּתְחָת קָמֵי בְּנֵי נָשָׁא וְאַכְרְזָא וְקָרֵי לְהוֹן (משלי ח׳:ד׳) אֲלֵיכֶם אִישִׁים אֶקְרָא וְגוֹ' וּכְתִיב (משלי א׳:כ״א) בְּרֹאשׁ הוֹמִיּוֹת תִּקְרָא בְּפִתְחֵי שְׁעָרִים בָּעִיר אֲמָרֶיהָ תֹאמֵר.</p>\n<p>רִבִּי יְהוּדָה אָמַר, ב' תְּרֵין גַּגִין, וְחַד דְּאָחִיד לוֹן. מַאי קָא מַיְירֵי. אֶלָּא חַד לִשְּׁמַיָּא וְחַד לְאַרְעָא, וְקוּדְשָׁא בְּרִיךְ הוּא אָחִיד וְקַבִּיל לוֹן.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, ג' נְהוֹרִין (צדדים אלין) אִינּוּן עִלָּאִין קַדִּישִׁין, דַּאֲחִידָן כַּחֲדָא, וְאִינּוּן כְּלָלָא דְּאוֹרַיְיתָא, וְאִלֵּין פָּתְחִין פִּתְחָא לְכֹלָּא. פָּתְחִין פִּתְחָא לִמְהֵימְנוּתָא, וְאִלֵּין בֵּיתָא דְּכֹלָּא. וְעַל דָּא בַּיִת אִקְרוּ, דְּאִלֵּין אִינּוּן בֵּיתָא. וּבְגִין כָּךְ שֵׁירוּתָא דְּאוֹרַיְיתָא ב'. דְּהָא הִיא אוֹרַיְיתָא (ס\"א אביה הוי אסוותא) הֲוִי וְאַסְוָותָא דְּעָלְמָא.</p>\n<p>וּבְגִין כָּךְ, מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, כְּאִלּוּ אִשְׁתָּדַּל בֵּיהּ בִּשְׁמָא קַדִּישָׁא. וְהָא אִתְּמַר, דְּאוֹרַיְיתָא כֹּלָּא, חַד שְׁמָא קַדִּישָׁא עִלָּאָה אִיהִי. וּבְגִין דְּאִיהִי שְׁמָא קַדִּישָׁא, פַּתְחָא בְּבֵית, דְּאִיהִי כְּלָלָא דִּשְׁמָא קַדִּישָׁא, בִּתְלַת קִשְׁרֵי מְהֵימְנוּתָא.</p>\n<p>תָּא חֲזֵי, כָּל אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, מִתְדַּבְּקִין בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וּמִתְעַטְּרֵי בְּעִטְרֵי דְּאוֹרַיְיתָא, וְאִתְרְחִימוּ לְעֵילָּא וְתַתָּא, וְקוּדְשָׁא בְּרִיךְ הוּא אוֹשִׁיט לוֹן יְמִינֵיהּ (ס\"א וקודשא בריך הוא ארשים לון) כָּל שֶׁכֵּן אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא נָמֵי בְּלֵילְיָא. וְהָא אוּקְמוּהָ, דְּאִינּוּן מִשְׁתַּתְּפֵי בִּשְׁכִינְתָּא (נ\"א בכנסת ישראל) וְאִתְחַבָּרוּ כַּחֲדָא. וְכַד אָתֵי צַפְרָא, קוּדְשָׁא בְּרִיךְ הוּא מְעַטֵּר לְהוּ, בְּחַד חוּטָא דְּחֶסֶד, לְאִשְׁתְּמוֹדְעָא בֵּין עִלָּאִין וְתַתָּאִין.</p>\n<p>וְכָל אִינּוּן כֹּכְבֵי צַפְרָא, בְּשַׁעֲתָא דִּכְנֶסֶת יִשְׂרָאֵל, וְכָל אִינּוּן דְּלָעָאן בְּאוֹרַיְיתָא, אָתָאן לְאִתְחֲזָאָה קָמֵי מַלְכָּא, כֻּלְּהוּ מְזַמְּרֵי כַּחֲדָא, הֲדָא הוּא דִכְתִיב בְּרָן יַחַד כֹּכְבֵי בֹּקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. מַאי וַיָּרִיעוּ. כְּמָה דְאַתְּ אָמֵר, (ישעיהו כ״ד:י״ט) רוֹעָה הִתְרוֹעֲעָה הָאָרֶץ. דְּאִינּוּן דִּינִין מִתַּבְּרִין, וְאַתְּבָּרוּ כֻּלְּהוּ מִקַּמֵּי בֹּקֶר, כַּד אִתְּעַר בֹּקֶר בְּעָלְמָא, כְּמָה דְאַתְּ אָמֵר, (בראשית כד) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. וְעַל דָּא וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים.</p>"],[9520012037,"<p>רִבִּי אֶלְעָזָר הֲוָה אָזִיל בְּאוֹרְחָא, אַשְׁכָּחֵיהּ לְרִבִּי פִּנְחָס בֶּן יָאִיר דְּהֲוָה אָתֵי, גָּעָא חֲמָרֵיהּ. אָמַר רִבִּי פִּנְחָס, וַדַּאי בְּטַקוּלָא (נ\"א בקלא) דְּחֶדְוְותָא דַּחֲמָרָא, חֲמֵינָא (חמית) אַנְפִּין חַדְתִּין יִשְׁתַּכְּחוּן הָכָא, כֵּיוָן דְּנָפַק מִבָּתַר עַנְפּוֹי דְּטוּרָא, חָמָא לֵיהּ לְרִבִּי אֶלְעָזָר דְּהֲוָה אָתֵי, אָמַר וַדַּאי טַקוּלָא (נ\"א קלא) דְּחֶדְוְותָא אִשְׁתְּלִים. נָחַת רִבִּי אֶלְעָזָר לְגַבֵּיהּ, וְנָשִׁיק לֵיהּ, אָמַר לֵיהּ אִי טוּפְסָא דְּאָרְחָא, חַד לְגַבָּךְ, נֵזִיל וְנִתְחַבֵּר כַּחֲדָא. וְאִי לָאו טוֹל אָרְחָךְ וְזִיל. אָמַר לֵיהּ, וַדַּאי לָקֳבְלָךְ אֲזִילְנָא, כֵּיוָן דְּאַשְׁכַּחְנָא לָךְ, אֵיזִיל אֲבַתְרָךְ וְנִתְחַבָּר כַּחֲדָא.</p>\n<p>פָּתַח רִבִּי פִּנְחָס וְאָמַר, (תהילים קכ״ח:ה׳) יְבָרֶכְךָ יְיָ' מִצִּיּוֹן וּרְאֵה בְּטוּב וְגוֹ'. יְבָרֶכְךָ יְיָ' מִצִיּוֹן, מַאי טַעְמָא מִצִּיּוֹן. בְּגִין דְּהָא מִתַמָּן שָׁרָאן בִּרְכָאן לְאִשְׁתַּתְּפָא (ס\"א לאשתכחא). הֲדָא הוּא דִכְתִיב כִּי שָׁם צִוָּה יְיָ' אֶת הַבְּרָכָה חַיִּים עַד הָעוֹלָם. וּבְגִין כָּךְ יְבָרֶכְךָ יְיָ' מִצִיּוֹן דְּהָא מִתַּמָּן נַפְקֵי בִּרְכָאן לְכֹלָּא. וּרְאֵה בְּטוּב יְרוּשָׁלַם, דִּבְגִינֵי צִיּוֹן יְרוּשָׁלַם אִתְבָּרְכָא, דְּכֵיוָן דְּצִיּוֹן אִתְמְלֵי בִּרְכָאן, כְּדֵין יְרוּשָׁלַם אִתְבָּרְכָא, וְאִשְׁתְּכָחוּ בָּהּ רַחֲמִים. וְכַד יְרוּשָׁלַם אִתְבָּרְכָא, כָּל עַמָּא אִתְבָּרְכָא.</p>\n<p>כָּל יְמֵי חַיֶּיךָ, דְּלָא יִתְחֲזֵי קֶשֶׁת בְּיוֹמָךְ, כְּמָה לְאָבוּךְ. וְעַל דָּא וּרְאֵה בְּטוּב יְרוּשָׁלַם כֹּל יְמֵי חַיֶּיךָ. וּרְאֵה בָנִים לְבָנֶיךָ, דַּחֲלֵי חַטָּאָה, חֲסִידִין, קַדִּישִׁין, כְּדֵין שָׁלוֹם עַל יִשְׂרָאֵל. מַאי שָׁלוֹם עַל יִשְׂרָאֵל. אֶלָּא, כְּמַאן דְּאָמַר שְׁלָמָא עַל רֵישֵׁיהּ דְּמַלְכָּא, דְּלָא יֶחְסַר כֹּלָּא. כַּךְ שָׁלוֹם עַל יִשְׂרָאֵל, בְּזִמְנָא דְּצַדִּיקַיָּיא יִשְׁתַּכְּחוּן בְּעָלְמָא.</p>\n<p>פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (משלי י״ז:ו׳) עֲטֶרֶת זְקֵנִים בְּנֵי בָנִים וְתִפְאֶרֶת בָּנִים אֲבוֹתָם. בָּנִים הָא אוֹקִימְנָא. בְּנֵי בָנִים, אִלֵּין (ל\"ה ע\"א) שְׁאָר כִּתְרֵי מַלְכָּא, כְּמָה דְאַתְּ אָמֵר (ישעיהו נ״ד:י״ג) וְכָל בָּנַיִךְ לִמּוּדֵי יְיָ'. וּכְתִיב (איכה ד׳:ב׳) בְּנֵי צִיּוֹן הַיְקָרִים, כְּמָה דְאַתְּ אָמֵר וְתִפְאֶרֶת בָּנִים אֲבוֹתָם, לָא מִתְעַטְּרָן בְּנִין אֶלָּא בַּאֲבָהָן. מִכָּאן אוֹלִיפְנָא, דִּבְנִין לָא מִתְעַטְּרֵי, וְלָא מִשְׁתַּקְיָין מִשַּׁקְיוּ דְּנַחֲלָא, אֶלָּא בְּזִמְנָא דַּאֲבָהָן מִתְעַטְּרָאן וּמִתְבָּרְכָאן, הֲדָא הוּא דִּכְתִּיב <Nonei></i>וְתִפְאֶרֶת בָּנִים אֲבוֹתָם.</p>"],[9520012038,"<p>עַד דַּהֲווֹ אָזְלֵי, מָטָא עִדָּן צְלוֹתָא, נַחְתּוּ וְצַלּוּ. עַד דַּהֲווֹ מְצָלֵי, קַפְטָר חַד חִוְיָא בְּרַגְלוֹי דְּחֲמָרָא, דְּרִבִּי פִּנְחָס. קִסְטָא (ס\"א קפטא) וְגָעָא תְּרֵי זִמְנֵי. בָּתַר דְּסִיְּימוּ צְלוֹתָא, אָמַר רִבִּי פִּנְחָס, וַדַּאי צַעֲרָא הוּא לִבְעִירָא דִּילִי, דְּהָא יוֹמָא דָּא אַקְדִּימְנָא, וַהֲוִינָא מַרְחִישׁ בְּאוֹרַיְיתָא, וְאַעְבַּר לִי בַּאֲתַר דְּלִכְלוּכָא שַׁרְיָא, וְהַשְׁתָּא מְצַעֲרֵי לָהּ. קָמוּ וְחָמוּ חַד חִוְיָא קָטִיר אֲרַגְלֵיהּ, אָמַר רִבִּי פִּנְחָס, חִוְיָא חִוְיָא, זִיל וְאַתְחַר (ס\"א ואסטר) קוּטְרָךְ, בְּקִטְפוּרָא דְּחוּרָא. אַדְּהָכִי אִתְנְשַׁר חִוְיָא, וְנָפַל קַפְסִירֵי קַפְסִירֵי.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, וּמַה כָּל כַּךְ מְדַקְדֵק קוּדְשָׁא בְּרִיךְ הוּא בְּצַדִּיקַיָּיא. אָמַר לֵיהּ, וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא מְדַקְדֵק בְּהוּ בְּצַדִּיקַיָּיא, וְנָטִיר לוֹן, וּבָעָא לְאוֹסְפָא לוֹן קְדוּשָּׁה עַל קְדוּשָּׁתַיְיהוּ וְהַשְׁתָּא הַאי חֲמָרָא, עַל דְּלָא נָטַר קְדוּשָּׁתָא דִּילִי אִצְטָעַר. וְדָא חִוְיָא שְׁלִיחָא הַוְיָא, וְכַמָּה שְׁלוּחִין אִית לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא וּבְכֻלְּהוּ עָבִיד שְׁלִיחוּתֵיהּ, וַאֲפִילּוּ בְּחַיוֹת בָּרָא. הֲדָא הוּא דִכְתִיב, (ויקרא כ״ו:כ״ב) וְשָׁלַחְתִּי בָּכֶם אֶת חַיַּת הַשָּׂדֶה וְשִׁכְּלָה אֶתְכֶם. וַאֲפִילּוּ בְּיַד גּוֹי, הֲדָא הוּא דִכְתִיב, (דברים כ״ח:מ״ט) יִשָֹּׁא יְיָ' עָלֶיךָ גּוֹי מֵרָחוֹק מִקְצֵה הָאָרֶץ.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, וּבִידָא דְּיִשְׂרָאֵל עָבִיד שְׁלִיחוּתָא. אָמַר לֵיהּ, אִין. כְּגוֹן רָשָׁע בִּידָא דְּצַדִּיק. אֲבָל רָשָׁע בִּידָא דְּיִשְׂרָאֵל רָשָׁע אָחֳרָא, לָא עָבִיד בֵּיהּ שְׁלִיחוּתָא, אֶלָּא בְּזִמְנָא דְּאִיהוּ לָא מְכַוְּון בֵּיהּ. הֲדָא הוּא דִכְתִיב, (שמות כ״א:י״ג) וַאֲשֶׁר לֹא צָדָה וְהָאֱלֹהִים אִנָּה לְיָדוֹ. וַאֲשֶׁר לֹא צָדָה דַּיְיקָא, דְּלָא לְקַטָלָא לֵיהּ. דָּא, וְהָאֱלֹהִים אִנָּה לְיָדוֹ, בְּגִין לְאַעְנְשָׁא לְתַרְוַויְּיהוּ.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, הֵיכִי עָבִיד קוּדְשָׁא בְּרִיךְ הוּא שְׁלִיחוּתָא בִּידָא דְּהָנֵי, וּבִידָא דְּגוֹי. אָמַר לֵיהּ וְאָבוּךְ לָא קָאָמַר לָךְ. אָמַר לֵיהּ עַד לָא שָׁאִילְנָא.</p>\n<p>פָּתַח וְאָמַר, (איוב ל״ד:כ״ט) וְהוּא יַשְׁקִיט וּמִי יַרְשִׁיעַ וְגוֹ'. וְהוּא יַשְׁקִיט, בְּזִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָהִיב שְׁקִיטוּ וְשַׁלְוָה לְבַּר נָשׁ, מַאן הוּא רַשַּׁאי לְאַבְאָשָׁא לֵיהּ, וּלְמֶעְבַּד לֵיהּ קַטֵיגוֹרְיָא. וְיַסְתֵּר פָּנִים וּמִי יְשׁוּרֶנּוּ. וּבְזִמְנָא דְּאִיהוּ אַסְתִּיר עֵינֵיהּ מִלְּאַשְׁגְּחָא עָלֵיהּ, מַאן הוּא דְּיִשְׁגַּח עָלֵיהּ, לְנַטְרָא לֵיהּ, וּלְמֶעְבַּד לֵיהּ נְטִירוּ. וְאוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא בְּדָא, עַל גּוֹי, וְעַל אָדָם יַחַד. בֵּין לְעָלְמָא כֹּלָּא, בֵּין לְעַמָּא חַד, בֵּין לְחָד בִּלְחוֹדוֹי.</p>\n<p>תָּא חֲזֵי, בְּזִמְנָא דִּבְנֵי נָשָׁא מִתְכַּשְּׁרָן עוֹבָדִין לְתַתָּא, אִתְּעַר לְגַבַּיְיהוּ לְעֵילָּא יְמִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא. כְּדֵין מִתְעָרִין כַּמָה רְחִימִין, כַּמָה נְטוּרֵי עָלְמָא, כַּמָה נְטוּרֵי דְּבַר נָשׁ, מִימִינָא וּמִשְּׂמָאלָא. וּכְדֵין אִתְכַּפְיָא שְׂמָאלָא, וְלָא יַכְלָא לְשַׁלְּטָאָה. וּבְזִמְנָא דִּבְנֵי אֱנָשָׁא לָא מִתְכַּשְּׁרָן עוֹבָדִין לְתַתָּא, שְׂמָאלָא אִתְּעַר, וְכָל אִינּוּן דְּאָתוּ מִסִּטְרָא דִּשְׂמָאלָא, כֻּלְּהוּ אִתְּעֲרוּ, וְכֻלְּהוּ אִתְעָבִידוּ שְׁלוּחִין לְאַבְאָשָׁא לְגַבַּיְיהוּ דִּבְנֵי נָשָׁא. דְּהָא אִינּוּן דְּעָבְרוּ עַל פִּתְגָּמֵי אוֹרַיְיתָא, כֻּלְּהוּ רְשִׁימִין בְּאַנְפַּיְיהוּ, וְאִשְׁתְּמוֹדְעָן לְגַבֵּי אִינּוּן דְּמִתְּעֲרֵי מִסִּטְרָא דִּשְׂמָאלָא.</p>\n<p>וּבְגִין כָּךְ, חֵיוָותָא וְעוֹבְדֵי עֲבוֹדָה זָרָה, וְכָל אִינּוּן דְּאָתוּ מִסִּטְרָא דִּשְׂמָאלָא, כֻּלְּהוּ אִקְרוּן (נ\"א אינון) שְׁלוּחִין, לְגַבֵּי אִינּוּן רְשִׁימִין דְּמִתְּעֲרֵי לְהוּ. וְיִשְׂרָאֵל, אַף עַל גַּב דְּלָא מְכַשְׁרָן עוֹבָדִין, כֻּלְּהוּ מִן סִטְרָא דִּימִינָא קָא אַתְיָין. וּבְגִין דְּאִתְכַּפְיָיא יְמִינָא בְּעוֹבָדַיְיהוּ, שַׁלְטָא עָלַיְיהוּ שְׂמָאלָא, וְכָל אִינּוּן דְּאָתוּ מִסִּטְרָא דִּשְׂמָאלָא, וְעַל דָּא, שְׁלִיחוּתָא בִּידָא דְּחֵיוָותָא וְגוֹי, וְכָל דְּדָמֵי לוֹן, דְּאִינּוּן מִסִּטְרָא דִּשְׂמָאלָא, וְלָא בִּידָא דְּיִשְׂרָאֵל, דְּאַף עַל גַּב דְּחַיָּיבָא אִיהוּ, מִסִּטְרָא דִּימִינָא קָא אָתֵי.</p>\n<p>וְיִשְׂרָאֵל חַיָּיבָא, דְּנָפַל בִּידָא דְּיִשְׂרָאֵל חַיָּיבָא אָחֳרָא, בְּזִמְנָא דְּלָא אִתְכַּוָּון בֵּיהּ, בְּגִין דְּיִתְעֲנְשׁוּ תַּרְוַויְיהוּ, וִיקַבְּלוּן עוֹנְשָׁא לְדַכְּאָה לוֹן. אָמַר רִבִּי אֶלְעָזָר, מְנָלָן. אָמַר לֵיהּ אִינּוּן בִּימִינָא. וְלָא אִתְדְּבָקוּ בִּשְׂמָאלָא, וְלָא אִתְעָרְבוּ בַּהֲדָהּ לְעָלְמִין, וְעַל דָּא, לְזִמְנָא אָחֳרָא אִתְעָבְרוּ.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, מְנָא לָן. אָמַר לֵיהּ, תָּא חֲזֵי מִן (שופטים כ) פִּלֶּגֶשׁ בַּגִּבְעָה, דְּאַף עַל גַּב דְּחַיָּיבֵי נִינְהוּ, לָא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא דְּיִתְעָרוּן גַּבַּיְיהוּ חַיָּיבֵי יִשְׂרָאֵל אָחֳרָנִין. וְעַל דָּא מִיתוּ (מישראל) כָּל אִינּוּן זִמְנִין דְּמִיתוּ. עַד דְּכֻלְּהוּ חַיָּיבִין דְּאִתְעֲרוּ לְגַבַּיְיהוּ, מִיתוּ וְאִתְאֲבִידוּ, וְאִשְׁתָּאָרוּ אִינּוּן <Nonei></i>זַכָּאִין יַתִּיר, דְּיַעַבְדוּן מִלָּה בְּאֹרַח קְשׁוֹט. וְאַף עַל גַּב דְּזַכָּאִין אִינּוּן, לָא אִתְיְיהִיב מִלָּה, אֶלָּא לְאִינּוּן דְּאִתְיְיהִיב. כַּד שְׁקִילָן עָלְמִין כַּחֲדָא, עָלְמָא תַּתָּאָה כְּגַוְונָא דְּעָלְמָא עִלָּאָה, וְהַהוּא זִמְנָא, לָא אִשְׁתְּכָחוּ עָלְמִין שְׁקִילָן כַּחֲדָא.</p>\n<p>וְעַל דָּא, חַיָּיבִין דְּיִשְׂרָאֵל לְגַבַּיְיהוּ דְּחַיָּיבִין אָחֳרָנִין, לָאו אִינּוּן שְׁלוּחֵי מַלְכָּא, דְּהָא לָא אַתְיָין מִסִּטְרָא דִּשְׂמָאלָא. מְתַל לִבְנֵי נָשָׁא דְּחָבוּ לְמַלְכָּא, אִתְּעַר סַנְטִירָא לְגַבַּיְיהוּ, לְתַפְשָׂא לוֹן, וּלְאַעְנְשָׁא לוֹן, לְאִינּוּן דְּחָבוּ לְמַלְכָּא. קָם חַכִּים חַד מִנַּיְיהוּ, וְאִתְעֲרַב בַּהֲדֵי בְּנֵי סַנְטִירָא, זָקַף סַנְטִירָא עֵינוֹי וְחָמָא לֵיהּ. אָמַר לֵיהּ מַאן יָהֲבָךְ לְגַבָּן, וְלָאו אַנְתְּ מֵאִינּוּן דְּחָבוּ לְמַלְכָּא, הָא אַנְתְּ אִתְעַנָּשׁ בְּקַדְמִיתָא, שְׁקִילוּ לֵיהּ וְקַטְלוּהוּ.</p>\n<p>כַּךְ יִשְׂרָאֵל מִסִּטְרָא דִּימִינָא קָא אַתְיָין, וְלָא אִתְדָּבָקוּ בִּשְׂמָאלָא, וְלָא אִתְעָרְבוּ בַּהֲדָהּ לְעָלְמִין. וְכַד אִינּוּן גַּרְמִין בְּחוֹבַיְיהוּ, דְּאִתְכַּפְיָא יְמִינָא, וְאִתְּעַר שְׂמָאלָא וְכָל אִינּוּן דְּאָתוּ מִסִּטְרֵיהּ, אִי חַד מִיִשְׂרָאֵל קָם לְאִתְעָרְבָא בַּהֲדַיְיהוּ, אִשְׁתְּמוֹדְעָן בֵּיהּ, אַמְרֵי לֵיהּ לָאו אַנְתְּ מֵאִינּוּן דְּקָא אַתְיָין מִסִּטְרָא דִּימִינָא, דְּאִתְכַּפְיָא מֵחוֹבַיְיהוּ, וְלָאו אַנְתְּ מֵאִינּוּן דְּחָבוּ לְמַלְכָּא מַאן יָהֲבָךְ לְגַבָּן. אִשְׁתְּכַח דְּאִיהוּ אִתְעַנָּשׁ בְּקַדְמִיתָא. וּשְׁלֹמֹה מַלְכָּא צָוַוח לָקֳבְלַיְיהוּ, וְאָמַר (קהלת ח׳:ט׳) עֵת אֲשֶׁר שָׁלַט הָאָדָם בְּאָדָם לְרַע לוֹ. לְרַע לוֹ וַדַּאי, בְּגִין דְּלָאו שְׁלִיחָא דְּמַלְכָּא אִיהוּ, וְלָא אָתֵי מֵהַהוּא סִטְרָא.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר ודַּאי הָכִי הוּא, דְּהָא תָּנֵינָן, דְּאִית יְמִינָא וְאִית שְׂמָאלָא, רַחֲמֵי וְדִינָא, יִשְׂרָאֵל (לימינא), וְעוֹבְדֵי עֲבוֹדַה זָרָה לִשְׂמָאלָא. יִשְׂרָאֵל אַף עַל גַּב דְּחַיָּיבֵי נִינְהוּ, וְאִתְכַּפְיָין, אִינּוּן בִּימִינָא, וְלָא אִתְדַּבְּקָן בִּשְׂמָאלָא, וְלָא אִתְעָרְבוּן בַּהֲדָהּ לְעָלְמִין. וּבְגִין כָּךְ כְּתִיב, (תהילים ס׳:ז׳) הוֹשִׁיעָה יְמִינְךָ וַעֲנֵנִי. דְּכַד אִסְתַּלָּק יְמִינָא יִשְׂרָאֵל דְּאִתְדַבְּקוּן בַּהֲדֵיהּ, יִסְתַּלְּקוּן וְיִתְעַטְּרוּן בֵּיהּ. כְּדֵין אִתְכַּפְיָא שְׂמָאלָא, וְכָל אִינּוּן דְּאָתוּ מִסִּטְרֵיהּ, הֲדָא הוּא דִכְתִיב, (שמות ט״ו:ו׳) יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב.</p>"],[9520012039,"<p>פָּתַח רִבִּי אֶלְעָזָר וְאָמַר וַיְהִי בַּיוֹם הַשְּׁמִינִי קָרָא וְגוֹ'. וַיְהִי בַּיוֹם הַשְּׁמִינִי, מַאי יוֹם הַשְּׁמִינִי. אֶלָּא כְּתִיב וּמִפֶּתַח אֹהֶל מוֹעֵד וְגוֹ', כִּי שִׁבְעַת יָמִים יְמַלֵּא אֶת יֶדְכֶם. כִּי שִׁבְעַת, בְּשִׁבְעַת יָמִים מִבָּעֵי לֵיהּ, אוֹ שִׁבְעָה יָמִים יְמַלֵּא אֶת יֶדְכֶם, מַאי כִּי שִׁבְעַת יָמִים יְמַלֵּא.</p>\n<p>אֶלָּא, זַכָּאִין אִינּוּן כַּהֲנֵי, דְּמִתְעַטְּרֵי בְּעִטְרוֹי דְּמַלְכָּא קַדִּישָׁא, וּמְשִׁיחִין בִּמְשַׁח רְבוּת קַדִּישָׁא, בְּגִין דְּאִתְּעַר מִשְׁחָא (אחרא) עִלָּאָה, דְּמַשְׁקֵי לְכָל שִׁבְעָה, וְאִתְמַשְּׁחָן מֵהַהוּא רְבוּת קַדִּישָׁא, וְאִתְדְּלָקוּ מִנֵּיהּ כָּל אִינּוּן שִׁבְעָה בּוּצִינִין, וְהַאי מְשַׁח רְבוּת הוּא כְּלָלָא דְּכָל שִׁבְעָה, וְכֻלְּהוּ בֵּיהּ אִתְכְּלִילוּ.</p>\n<p>וְתָנֵינָן שִׁיתָא אִינּוּן, וְכֻלְּהוּ אִתְכְּלִילָן בְּהַאי, וְדָא הוּא כְּלָלָא דְּכֻלְּהוּ, וּבְגִין כַּךְ שִׁבְעַת יָמִים יְמַלֵּא, דְּהָא בְּהַאי תַּלְיָין. וְעַל דָּא, אִקְרֵי כְּנֶסֶת יִשְׂרָאֵל, בַּת שֶׁבַע. מַאי אִיהִי בַּת שֶׁבַע. דְּאִיהִי כְּלִילָא מִשִּׁיתָא אָחֳרָנִין.</p>\n<p>כֵּיוָן דְּהַאי שִׁבְעָה, אַשְׁלִים לְהוּ לְכַהֲנֵי, וְאַעְטַּר לוֹן, וּמָשַׁח לוֹן בְּכֹלָּא, כַּד מָטוּ לִכְּנֶסֶת יִשְׂרָאֵל דְּאִיהִי תְּמִינָאָה, אִתְפְּקַד אַהֲרֹן לְקָרְבָא עֵגֶל, בְּגִין דְּאִיהוּ בְּרֵיהּ דְּפָרָה, לְכַפָּרָא עַל הַהוּא חוֹבָא דְּעֵגֶל אָחֳרָא דַּעֲבַד אַהֲרֹן, וְחָב לְגַבֵּי פָּרָה, דְּאִיהִי תְּמִינָאָה, שְׁלִימוּ דֶּמֱמוּנֵיה (ס\"א דאמוני) יִשְׂרָאֵל. וְאִשְׁתְּכַח כַּהֲנָא שְׁלִים בְּכֹלָּא, בִּתְמַנְיָא מִינֵי לְבוּשִׁין דִּיקָר, שְׁלִים בְּכָל כִּתְרִין, שְׁלִים לְעֵילָּא, שְׁלִים לְתַתָּא.</p>\n<p>וּבְכֹלָּא, בָּעֵי לְאַחֲזָאָה עוֹבָדָא. וְעַל דָּא אִתְעָבִיד בֵּיהּ בְּאַהֲרֹן עוֹבָדָא לְתַתָּא, בְּגִין דְּיִתְּעַר הָכִי לְעֵילָּא, וְיִשְׁתְּכַּח כֹּלָּא בְּגַוְונָא חַד, וּכְדֵין אִתְבָּרְכָאן עָלְמִין כֻּלְּהוּ, וּמִשְׁתַּכְחִין בִּרְכָאן עַל יְדָא דְּכַהֲנָא. וְהָכָא אִשְׁתְּלִים כַּהֲנָא בְּכֹלָּא כַּדְקָא חֲזֵי.</p>\n<p>עֵגֶל לָמָּה. דִּכְתִּיב עֵגֶל בֶּן בָּקָר לְחַטָּאת, בְּגִין הַהוּא חַטָּאת, דַּעֲבַד בְּקַדְמִיתָא. וְאַיִל לְעוֹלָה, מַאי טַעְמָא אַיִל. בְּגִין אַיִל דְּיִצְחָק, דַּהֲוָא עוֹלָה תְּמִימָה, וְהַאי אִתְחֲזֵי לְקָרְבָא, לְאַשְׁלְמָא כֹּלָּא. וְהַאי אֲתַר, מִסִּטְרָא דְּיִצְחָק אִשְׁתְּאַב. וְהַאי אַיִל בְּגִין אַיִל דְּיִצְחָק מִתְקָרְבָא עוֹלָה, (בגין דאיהי עולה) דְּהָא עוֹלָה לְעֵילָּא סַלְּקָא, וּבְגִין לְאַעְטְּרָא לָהּ בִּשְׁלֵימוּתָא. עֵגֶל וְאַיִל: עֵגֶל בְּגִינָהּ, כִּדְקָאַמְרָן. אַיִל, לְאַשְׁלְמָא <Nonei></i>לָהּ בִּשְׁלִימוּ דְּיִצְחָק כַּדְקָא חֲזֵי.</p>\n<p>וְיִשְׂרָאֵל דְּחָבוּ עִמֵּיהּ דְּכַהֲנָא בְּהַאי, מַקְרִיבִין כְּגַוְונָא דָּא, דִּכְתִּיב וְשׁוֹר וְאַיִל לִשְׁלָמִים לִזְבּוֹחַ לִפְנֵי יְיָ'. שׁוֹר, עַל מַה דְּחָבוּ. וְאַיִל לְאַשְׁלְמָא לְהַאי אֲתַר בִּשְׁלִימוּ דְּיִצְחָק.</p>\n<p>מַאי שְׁנָא בְּכַהֲנָא דִּכְתִּיב בֵּיהּ עֵגֶל לְחַטָּאת, וְלָא כְּתִיב בְּיִשְׂרָאֵל שׁוֹר לְחַטָּאת. אֶלָּא, יִשְׂרָאֵל הָא קַבִּילוּ עוֹנְשָׁא בְּקַדְמִיתָא, וּבְגִין דְּקַבִּילוּ עוֹנְשָׁא בְּכַמָה אֲתַר, עַל דָּא קוּדְשָׁא בְּרִיךְ הוּא לָא בָּעָא לְאַדְכְּרָא לוֹן חוֹבַיְיהוּ כִּדְקַדְמֵיתָא, וְעַל דָּא לָא כְּתִיב הָכָא לְחַטָּאת, אֶלָּא לִשְׁלָמִים, בְּגִין לְאַחֲזָאָה שְׁלָמָא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא בִּשְׁלָמָא בְּהוּ בְּיִשְׂרָאֵל עַל דָּא.</p>\n<p>אֲבָל אַהֲרֹן, דְּהָא לָא קַבִּיל עוֹנְשָׁא מִצְּלוֹתָא דְּמֹשֶׁה, דִּכְתִּיב, (דברים ט׳:כ׳) וּבְאַהֲרֹן הִתְאַנַּף יְיָ' וְגוֹ'. וּכְתִיב וָאֶתְפַּלֵּל גַּם בְּעַד אַהֲרֹן בָּעֵת הַהִיא, וְעַד כְּעַן חוֹבָא הֲוָה תָּלֵי, כְּתִיב וְעֵגֶל בֶּן בָּקָר לְחַטָּאת, לְחַטָּאת וַדַּאי, (ואיל לעולה) בְּגִין דִּיְכַפֵּר חוֹבֵיהּ, וְיִתְדַכֵּי וְיִשְׁתְּלִים בְּכֹלָּא.</p>\n<p>וּבְהַהוּא יוֹמָא אִשְׁתְּלִימוּ עִלָּאִין וְתַתָּאִין. וְאִשְׁתְּכַח שְׁלָמָא בְּכֹלָּא, בְּחֶדְוָותָא דִּלְעֵילָּא וְתַתָּא וְאִלְמָלֵא דְּאִשְׁתְּכַח עִרְבּוּבְיָא דִּבְנֵי אַהֲרֹן בְּהַהוּא יוֹמָא, מִן יוֹמָא דְּאִסְתָּלָקוּ יִשְׂרָאֵל מִן יַמָּא, לָא אִשְׁתְּכַח חֶדְוָותָא דְּעִלָאֵי וְתַתָּאֵי כְּהַהוּא יוֹמָא. בְּהַהוּא יוֹמָא אִתְעַבָּר הַהוּא חוֹבָא מִן עָלְמָא, וְאִשְׁתְּכָחוּ כַּהֲנָא וְיִשְׂרָאֵל מִתְדַּכְּאָן מִנֵּיהּ. (כל) הַהוּא יוֹמָא, אִתְעֲבָרוּ כָּל אִינּוּן מְקַטְרְגִין דִּלְעֵילָּא, וַהֲווּ אַזְלִין וְשָׁטָאן בְּסַחֲרָנַיְיהוּ דְּיִשְׂרָאֵל, וְלָא אִשְׁתְּכָחוּ בְּהַהוּא עִדָנָא.</p>\n<p>עַד דְּגָרִים שַׁעֲתָא, וְקָמוּ נָדָב וַאֲבִיהוּא וְעִכְּבוּ (ס\"א וערבבו) חֶדְוָותָא דְּכֹלָּא. וְאִשְׁתְּכַח רוּגְזָא בְּעָלְמָא, הֲדָא הוּא דִכְתִיב, וַיֵּרָא כְבוֹד יְיָ' אֶל כָּל הָעָם, מִיַד וַיִּקְחוּ שְׁנֵי בְנֵי אַהֲרֹן נָדָב וַאֲבִיהוּא אִישׁ מַחְתָּתוֹ וְגוֹ'.</p>\n<p>תְּנָן, בְּהַהוּא יוֹמָא חֶדְוָותָא דְּכְּנֶסֶת יִשְׂרָאֵל הֲוַות, לְאִתְקַטְּרָא בְּקִיטוּרָא דִּמְהֵימְנוּתָא בְּכֻלְּהוּ קִשְׁרִין קַדִּישִׁין. דְּהָא קְטֹרֶת קָשִׁיר כֹּלָּא כַּחֲדָא, וּבְגִין כָּךְ אִקְרֵי קְטֹרֶת. וְאִינּוּן אָתוּ, וּקְשִׁירוּ כָּל אִינּוּן אָחֳרָנִין כַּחֲדָא, וְשָׁרוּ לָהּ לְבַר, דְּלָא קָשְׁרוּ לָהּ בַּהֲדַיְיהוּ, וּקְשִׁירוּ מִלָּה אָחֳרָא. וּבְגִין כַּךְ, אַזְהַר לוֹן לְכַהֲנֵי לְבָתַר, דִּכְתִּיב, (ויקרא ט״ז:ג׳) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ.</p>\n<p>וּבְכַמָּה גַּוְונִין עִרְבְּבוּ חֶדְוָותָא דְּכְנֶסֶת יִשְׂרָאֵל. חַד דְּלָא אִתְנְסִיבוּ, וְלָא אִתְחַזְיָין לְקָרְבָא, וּלְאִתְבָּרְכָא עָלְמִין עַל יְדַיְיהוּ. וְחַד דְּלָא הֲוָה שַׁעֲתָא כְּדְקָא יֵאוֹת. וְחַד דְּדַּחֲקוּ שַׁעֲתָא. וְחַד, דְּהָא מִקַּדְמַת דְּנָא, נָפַק נִימוּסָא דִּלְהוֹן, וַיַּקְרִיבוּ לִפְנֵי יְיָ' אֵשׁ זָרָה וְגוֹ'. וַדַּאי מִלָּה אָחֳרָא אִתְקְשָּׁרוּ בְּקִשּׁוּרָא דָּא, וְשָׁרוּ לְכְנֶסֶת יִשְׂרָאֵל לְבַר. אָמַר לֵיהּ רִבִּי פִּנְחָס, לָא תֵּימָא דְּאִינּוּן שָׁארוּ לָהּ לְבַר, אֶלָּא כְּנֶסֶת יִשְׂרָאֵל לָא אִתְקַשְּׁרָא עַל יְדַיְיהוּ. דְּהָא בְּכָל אֲתַר דְּלָא אִשְׁתְּכַח דְּכַר וְנוּקְבָּא, כְּנֶסֶת יִשְׂרָאֵל לָא שַׁרְיָא בֵּינַיְיהוּ כְּלַל. בְּגִין כַּךְ אַזְהַר לְכַהֲנֵי, דִּכְתִּיב בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ, דְּיִשְׁתְּכַח דְּכַר וְנוּקְבָּא. וְעַל דָּא לָא יִיעוּל כַּהֲנָא לְקוּדְשָׁא, עַד דְּיִתְנְסִיב. בְּגִין דְּיִשְׁתָּתַּף בְּקִשּׁוּרָא דְּכְּנֶסֶת יִשְׂרָאֵל. דְּמַאן דְּלָא אִנְסִיב, שָׁארֵי לָהּ לִכְּנֶסֶת יִשְׂרָאֵל לְבַר, וְהִיא לָא אִשְׁתַּתְּפָא בַּהֲדֵיהּ, וְעַל דָּא אִשְׁתְּכַח עִרְבּוּבְיָא בְּהַהוּא יוֹמָא לְגַבַּיְיהוּ. (ויקרא ט׳:א׳) וַיְהִי בַּיוֹם הַשְּׁמִינִי, רִבִּי יוֹסֵי פָּתַח וְאָמַר, (שיר השירים ב׳:ב׳) כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים כֵּן רַעְיָתִי בֵּין הַבָּנוֹת. כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים, דָּא כְּנֶסֶת יִשְׂרָאֵל, וְהָא אוּקְמוּהָ דְּקוּדְשָׁא בְּרִיךְ הוּא מְשַׁבַּח לָהּ לִכְנֶסֶת יִשְׂרָאֵל, וַחֲבִיבוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא לָקֳבְלָהָא, לְאִתְדַּבְּקָא בָּהּ.</p>\n<p>וְעַל דָּא, מַאן דְּאִנְסִיב, בָּעֵי לְשַׁבְּחָא לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְשַׁבְּחָא לָהּ לְכְנֶסֶת יִשְׂרָאֵל, דְּהָא תָּנֵינָן בְּכֹלָּא בָּעֵי לְאַחֲזָאָה עוֹבָדָא, כְּמָה דְּאִיהוּ בַּר נָשׁ מִתְדְּבַק בְּבַת זוּגֵיהּ, וַחֲבִיבוּתָא דִּילֵיהּ לָקֳבְלָהּ, כַּד אָתֵי לְמִפְלַח קָמֵי מַלְכָּא קַדִּישָׁא, הוּא אִתְּעַר זִוּוּגָא אָחֳרָא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא חֲבִיבוּתָא דִּילֵיהּ לְאִתְדַּבְּקָא בִּכְּנֶסֶת יִשְׂרָאֵל, וּמַאן דְּאִתְעַר מִלָּה, קוּדְשָׁא בְּרִיךְ הוּא מְבָרֵךְ לֵיהּ, וּכְּנֶסֶת יִשְׂרָאֵל מְבָרְכָא לֵיהּ, וְהָא אִתְּמַר.</p>\n<p>וְעַל דָּא שְׁבָחָא דְּקוּדְשָׁא בְּרִיךְ הוּא דִּמְשַׁבַּח לָהּ לִכְּנֶסֶת יִשְׂרָאֵל, כְּשׁוֹשַׁנָּה דְּאִיהִי בֵּין הַחוֹחִים, דְּאִיהִי מְעַלְּיָא וְסַלְּקָא עַל כֹּלָּא. כַּךְ כְּנֶסֶת יִשְׂרָאֵל בֵּין שְׁאָר אוּכְלוּסִין, בְּגִין דְּהִיא סַלְּקָא <Nonei></i>וּמִתְעַטְּרָא עַל כֹּלָּא. וְדָא שׁוֹשַׁנָה בֵּין הַחוֹחִים, וְאֶתְרוֹג בֵּין הַחוֹחִים, לְאַחֲזָאָה שְׁבָחָא דְּכְּנֶסֶת יִשְׂרָאֵל, עַל כֹּלָּא.</p>\n<p>תָּא חֲזֵי, כְּנֶסֶת יִשְׂרָאֵל מִתְבָּרְכָא עַל יְדֵי דְּכַהֲנָא, וְיִשְׂרָאֵל מִתְבָּרְכָאן עַל יְדֵי דְּכַהֲנָא. וְכַהֲנָא מִתְבָּרְכָא עַל יְדֵי דְּכַהֲנָא עִלָּאָה, הֲדָא הוּא דִכְתִיב, (במדבר ו׳:כ״ז) וְשָׂמוּ אֶת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל וַאֲנִי אֲבָרַכֵם.</p>\n<p>כְּתִיב (תהילים כ״ה:ו׳) זְכֹר רַחֲמֶיךָ יְיָ' וַחֲסָדֶיךָ כִּי מֵעוֹלָם הֵמָּה. זְכֹר רַחֲמֶיךָ, דָּא יַעֲקֹב. וַחֲסָדֶיךָ, דָּא אַבְרָהָם. כִּי מֵעוֹלָם הֵמָּה, וּמֵעוֹלָם נָטַל לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְסָלִיק לוֹן לְעֵילָּא, וַעֲבַד מִנַּיְיהוּ רְתִיכָא קַדִּישָׁא, לְאַגָּנָא עַל עָלְמָא. וּבְגִין דַּהֲווֹ מֵעוֹלָם, הוּא דְּכִיר לְהוֹן לְאַגָּנָא וּלְרַחֲמָא עַל עָלְמָא. כְּגַוְונָא דָּא. נָטִיל קוּדְשָׁא בְּרִיךְ הוּא לְצַדִּיקַיָּיא מִן עָלְמָא, וְסָלִיק לוֹן לְעֵילָּא, לְאַגָּנָא עַל עָלְמָא.</p>\n<p>וְאִי תֵּימָא יִצְחָק אֲמַאי לָא אַדְכַּר הָכָא. אֶלָּא אִשְׁתְּאַר לְאִתְפָּרְעָא מֵאִינּוּן דְּעָאקִין לִבְנוֹי, הֲדָא הוּא דִכְתִיב (תהלים פט) עוֹרְרָה אֶת גְּבוּרָתֶּךָ. וּכְתִיב, (ישעיהו מ״ב:י״ג) יְיָ' כַּגִבּוֹר יֵצֵא כְּאִישׁ מִלְחָמוֹת יָעִיר קִנְאָה וְגוֹ', וְדָא הוּא יִצְחָק, דְּאִסְתַּלָּק מֵהָכָא. רִבִּי חִיָּיא אָמַר, זְכֹר רַחֲמֶיךָ יְיָ' וַחֲסָדֶיךָ, אִלֵּין אִינּוּן יַעֲקֹב וְאַבְרָהָם, דְּבָעֵינָן לְהוֹן לְאַגָּנָא עֲלָן. אֲבָל יִצְחָק, לְמֶעְבַּד קְרָבִין קַיְּימָא, וּבְגִּינֵי כַּךְ לָא בָּעֵינָן לֵיהּ לְגַבַּיְיהוּ.</p>\n<p>דָּבָר אַחֵר כִּי מֵעוֹלָם הֵמָּה, דְּכַד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, נָטַל יִצְחָק וּבָרָא בֵּיהּ עָלְמָא. חָמָא דְּלָא יָכִיל לְמֵיקָם בִּלְחוֹדוֹי, נָטַל אַבְרָהָם וְקִיֵּים בֵּיהּ עָלְמָא. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, אַל תִּקְרֵי בְּהִבָּרְאָם, אֶלָּא בְּאַבְרָהָם. חָמָא דְּבַעְיָין קִיּוּמָא יַתִּיר, נָטַל לְיַעֲקֹב, וְשָׁתַף לֵיהּ בְּיִצְחָק, וְקִיֵּים עָלְמָא. הֲדָא הוּא דִכְתִיב בְּיוֹם עֲשׂוֹת יְיָ' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. וְעַל דָּא, בְּאַבְרָהָם וְיַעֲקֹב אִתְקַיָּים עָלְמָא. וּבְגִין כָּךְ כִּי מֵעוֹלָם הֵמָּה.</p>\n<p>רִבִּי יְהוּדָה פָּתַח, וַיְהִי בַּיּוֹם הַשְּׁמִינִי, לְבָתַר דְּאִשְׁתְּלִים אַהֲרֹן, בְּאִינּוּן ז' יוֹמִין, וְאִתְעַטָּר בְּהוּ, (בההוא משח רבות קדישא עלאה) יוֹמָא תְּמִינָאָה בַּעְיָא לְאִשְׁתַּלְּמָא מִן שִׁבְעָה, דְּאַשְׁלָמוּתָא עַל יְדֵי דְּכַהֲנָא, וְעַל דָּא פּוּלְחָנָא בִּתְמִינָאָה, לְאִתְעַטְּרָא מִן שִׁבְעָה. וּלְאִתְתַּקְּנָא כַּהֲנָא עַל הַהוּא (חובה) דְּחָב (ס\"א דקביל) בְּקַדְמִיתָא.</p>\n<p>הֲדָא הוּא דִכְתִיב, וַיֹּאמֶר אֶל אַהֲרֹן קַח לְךָ עֵגֶל, הָא אוּקְמוּהָ עֵגֶל ודַּאי, לְכַפְּרָא עַל הַהוּא עֵגֶל, דִּכְתִּיב (שמות ל״ב:ד׳) וַיַּעֲשֵׂהוּ עֵגֶל מַסֵּכָה. בֶּן בָּקָר, מַאי טַעְמָא בֶּן בָּקָר, וְלָא בֶּן פָּרָה. אֶלָּא אִיהוּ בָּעֵי לְאִתְתַּקְנָא לְגַבֵּי פָּרָה, לָא אִתְחֲזֵי לְקָרְבָא מִינָּהּ לְגַבָּהּ. מַאן דְּשָׁדַר דּוֹרוֹן לְמַלְכָּא, חֲמִיתוּן דְּנָסִיב מִבֵּי מַלְכָּא, וְיָהִיב לְמַלְכָּא, אֶלָּא דּוֹרֹנָא לְשַׁדְּרָא לְמַלְכָּא, מִבֵּי אָחֳרָא אִצְטְרִיךְ, וְלָא מִבֵּי מַלְכָּא. רִבִּי יוֹסֵי אָמַר, מִדִּידֵיהּ לְדִידֵיהּ לָא אִתְחֲזֵי. אָמַר רִבִּי יְהוּדָה בְּגִין כָּךְ בֶּן בָּקָר וַדַּאי וְלָא בֶּן פָּרָה.</p>\n<p>לְחַטָּאת: לְדַכְּאָה עַל הַהוּא חוֹבָה דְּחָב בֵּיהּ. וְאַיִל לְעוֹלָה תְּמִימִים. תְּמִימִים, תָּמִים מִבָּעֵי לֵיהּ. אִי תֵּימָא דְּעַל אַיִל וְעֵגֶל קָאָמַר, לָאו הָכֵי. דְּהָא תַּרְוַויְיהוּ לָא סַלְּקִין לְעוֹלָה, דְּהָא כְּתִיב לְעוֹלָה תְּמִימִים, וְעֵגֶּל לְחַטָּאת סַלְּקָא, מַהוּ תְּמִימִים, וּכְתִיב אַיִל.</p>\n<p>אֶלָּא אֵילוֹ דְּיִצְחָק, לְקָרְבָא לְגַבֵּי פָּרָה, דְּאִדְכַּר תְּרֵי זִמְנֵי בִּקְרָא, חַד דִּכְתִּיב, (בראשית כ״ב:י״ג) וַיִּשָּׂא אַבְרָהָם אֶת עֵינָיו וַיַּרְא וְהִנֵּה אַיִל, הָא חַד, וְחַד וַיֵּלֶךְ אַבְרָהָם וַיִּקַּח אֶת הָאַיִל, הָא תְּרֵי, וַיַּעֲלֵהוּ לְעוֹלָה. וְעַל דָּא אַיִל לְעוֹלָה תְּמִימִים, תְּרֵי אַיִל, דְּאִיהוּ תְּרֵי. וְעַל דָּא (ויחי רמ\"א ע\"א) גְּבוּרוֹת תָּנֵינָן, וּמִנַּיְיהוּ מִתְפָּרְשִׁין לְכַמָּה אָחֳרָנִין.</p>\n<p>(ויקרא ט׳:ג׳) וְאֶל בְּנֵי יִשְׂרָאֵל תְּדַבֵּר לֵאמֹר קְחוּ שְׂעִיר עִזִּים לְחַטָּאת, עֵגֶל לְחַטָּאת מִבָּעֵי לֵיהּ, כְּגַוְונָא דְּכַהֲנָא. אֶלָּא יִשְׂרָאֵל הָא קַבִּילוּ עוֹנְשָׁא, וְעַל דָּא לָא כְּתִיב בְּהוּ עֵגֶל לְחַטָּאת, אֶלָּא עֵגֶל לְעוֹלָה. מַאי טַעְמָא. דְּכָל אִינּוּן דְּחָבוּ בֵּיהּ, קַבִּילוּ עוֹנְשָׁא, בֵּין בְּמִלּוּלָא, בֵּין בְּעוֹבָדָא, בֵּין בְּפוּלְחָנָא, וַאֲפִילּוּ אִינּוּן דְּלָא עַבְדוּ מִדִי, אֶלָּא דִּסְלִיקוּ לֵיהּ בִּרְעוּתָא דְּלִבַּיְיהוּ לְמִפְלַח לֵיהּ, אִתְעֲנָשׁוּ, כְּמָה דִּכְתִּיב, (שמות לב) וַיַּשְׁק אֶת בְּנֵי יִשְׂרָאֵל. אֲבָל כָּל אִינּוּן דִּסְלִיקוּ לֵיהּ בִּרְעוּתָא דְּלָא לְמִפְלַח לֵיהּ, אֶלָּא דִּסְלִיקוּ גַּוְונָא דִּרְעוּתָא מִנֵיהּ, הָכָא אִתְדַּכָּן, וּמְקָרְבִין לֵיהּ <Nonei></i>לְעוֹלָה וְלֹא לְחַטָאת.</p>\n<p>אֲבָל קְחוּ שְׂעִיר עִזִּים לְחַטָּאת, אֲמַאי. אֶלָּא בְּגִין דַּהֲווֹ מְקָרְבִין בְּקַדְמִיתָא לַשְּׂעִירִים, דְּשַׁלְטִין עַל טוּרֵי רָמָאֵי. וְדָא הוּא לְחַטָּאת, וּבַעְיָין לְאִתְדַכְּאָה מֵהַהוּא חוֹבָא, וְלֹא עוֹד אֶלָּא לְחַדְתּוּתֵי דְּסִיהֲרָא אִצְטְרִיךְ.</p>\n<p>(ויקרא ט׳:ד׳) וְשׁוֹר וְאַיִל לִשְׁלָמִים. שׁוֹר וְלָא פַּר, בְּגִין דְּשׁוֹר שְׁלִים אִיהוּ, לְאַחֲזָאָה שְׁלָמָא, הֲדָא הוּא דִכְתִיב לִשְׁלָמִים. רִבִּי יוֹסֵי אָמַר, שׁוֹר וְאַיִל מִסִּטְרָא דִּשְׂמָאלָא קָא אַתְיָין. שׁוֹר מִסִּטְרָא דִּשְׂמָאלָא, דִּכְתִּיב, (יחזקאל א׳:י׳) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. אַיִל, בְּגִין אֵילוֹ דְּיִצְחָק. וְסַלְּקִין לִשְׁלָמִים, לְאַשְׁלְמָא לוֹן לִכְּנֶסֶת יִשְׂרָאֵל וְעַל דָּא שׁוֹר וָאַיִל לִשְׁלָמִים.</p>\n<p>אָמַר רִבִּי יְהוּדָה, כֹּלָּא בְּגִין דְּכְנֶסֶת יִשְׂרָאֵל מִתְעַטְּרָא וּמִתְבָּרְכָא עַל יְדָא דְּכַהֲנָא, בְּאַשְׁלְמוּתָא. וְהַאי יוֹמָא חֶדְוָותָא דְּכֹלָּא הֲוָה, חֶדְוָותָא דְּכְנֶסֶת יִשְׂרָאֵל בְּקוּדְשָׁא בְּרִיךְ הוּא, חֶדְוָותָא דְּעִלָּאִין וְתַתָּאִין. וּכְמָּה דְּאִשְׁתְּלִים כַּהֲנָא לְתַתָּא, כִּבְיָכוֹ\"ל אִשְׁתְּלִים כַּהֲנָא לְעֵילָּא, בַּר נָדָב וַאֲבִיהוּא דְּאִתְעֲרוּ עִרְבּוּבְיָא בֵּין מַטְרוֹנִיתָא וּמַלְכָּא. וּבְגִין כָּךְ וַתֵּצֵא אֵשׁ מִלִּפְנֵי יְיָ' וַתֹּאכַל אוֹתָם וְגוֹ'.</p>\n<p>(חסר) (ויקרא י׳:י״ב) וַיֹּאמֶר מֹשֶׁה אֶל אֶלְעָזָר וְאֶל אִיתָמָר רָאשֵׁיכֶם אַל תִּפְרָעוּ וְגוֹ', כִּי שֶׁמֶן מִשְׁחַת יְיָ' עֲלֵיכֶם. רִבִּי אַבָּא אָמַר, הָא תָּנֵינָן בְּעוֹבָדִין דִּלְתַתָּא, אִתְּעָרוּן עוֹבָדִין לְעֵילָּא, וְעוֹבָדָא דִּלְתַתָּא בָּעֵי לְאִתְחֲזָאָה כְּגַוְונָא דְּעוֹבָדָא דִּלְעֵילָּא.</p>\n<p>תָּא חֲזֵי, כָּל חֶדְוָותָא דִּלְעֵילָּא, תַּלְיָא בְּהַהוּא שַׁמְנָא קַדִּישָׁא, דְּמִתַּמָּן נָפִיק חֶדְוָה וּבִרְכָּאן לְכֻלְּהוּ בּוּצִינִין, וְכַהֲנָא עִלָּאָה (מיניה) אִתְעֲטָּר בִּנְגִּידוּ דְּמִשְׁחָא, וּבְגִין כָּךְ כַּהֲנָא, דִּרְבוּ מִשְׁחָא אִתְנְגִיד עָלֵיהּ כְּגַוְונָא דִּלְעֵילָּא, בָּעֵי לְאַחֲזָאָה חֵידוּ, וּנְהִירוּ דְּאַנְפִּין (יתיר מכלא), וְלָא יִתְחֲזֵי גִּרְעוֹנָא בְּרֵישֵׁיהּ, וְלָא בִּלְבוּשֵׁיהּ, אֶלָּא לְמֶהֱוִי כֹּלָּא שְׁלִים כְּגַוְונָא דִּלְעֵילָּא, וְלָא יִתְחֲזֵי בֵּיהּ פְּגִימוּ כְּלָל, בְּגִין דְּלָא יַעֲבִיד פְּגִימוּ בַּאֲתַר אָחֳרָא.</p>\n<p>תָּא חֲזֵי, אִלְמָלֵא אֶלְעָזָר וְאִיתָמָר אִתְחָזוּן פְּגִימוּ בְּהַהִיא שַׁעֲתָא בִּלְבוּשֵׁיהוֹן אוֹ בְּרָאשֵׁיהוֹן, לָא אִשְׁתְּזִיבוּ בְּהַהִיא שַׁעֲתָא, דְּהָא שַׁעֲתָא קַיְּימָא לְמֶעְבַּד דִּינָא. וְעַל דָּא תָּנֵינָן, בְּשַׁעֲתָא דְּמוֹתָנָא אִעְרַע בְּעָלְמָא, לָא יִתְּעַר אִינַשׁ גַּרְמֵיהּ לְמִלָּה בְּעָלְמָא, בְּגִין דְּלָא יִתְּעֲרוּן עָלֵיהּ. בַּר אִי אִתְּעַר גַּרְמֵיהּ לְטָב, וְיָכִיל לְדַחְיָיא (לדחקא) שַׁעֲתָא, דְּהָא בְּזִמְנָא וְשַׁעֲתָא דְּדִינָא קַיְּימָא בְּעָלְמָא, מַאן דְּיִעְרַע בֵּיהּ, לַקְטֵי לֵיהּ וְיִסְתָּלַק מֵעָלְמָא. וּבְגִין כָּךְ וְלֹא תָמוּתוּ. כְּתִיב וַאֲחֵיכֶם כָּל בֵּית יִשְׂרָאֵל יִבְכּוּ אֶת הַשְּׂרֵיפָה, בְּגִין דְּאִינּוּן לָא אַתְיָין מִסִּטְרָא דְּכַהֲנֵי, וְלָא מִתְזָקֵי.</p>"],[9520012040,"<p>רִבִּי אֶלְעָזָר פָּתַח, (שמות ו׳:כ״ג) וַיִּקַּח אַהֲרֹן אֶת אֱלִישֶׁבַע בַּת עַמִּינָדָב אֲחוֹת נַחְשׁוֹן לוֹ לְאִשָּׁה. וַיִּקַח אַהֲרֹן. כֹּלָּא כְּמָה דְּאִצְטְרִיךְ, כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא. תָּא חֲזֵי, רְאוּיָה הָיְתָה בַּת שֶׁבַע לְדָוִד, מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא. רְאוּיָה הָיְתָה אֱלִישֶׁבַע לְאַהֲרֹן מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא.</p>\n<p>מַה בֵּין הַאי לְהַאי. אֶלָּא כֹּלָּא חַד. אֲבָל הָתָם לְדִינָא, הָכָא לְרַחֲמֵי. כַּד אִתְחַבְּרָא בְּדָוִד, לְדִינָא, לְאַגָּחָא קְרָבִין, לְאוֹשָׁדָא דָּמִין. הָכָא בְּאַהֲרֹן, לִשְׁלָמָא, לְחֶדְוָה, לִנְהִירוּ דְּאַנְפִּין, לְאִתְבָּרְכָא. וְעַל דָּא אִתְקְרֵי (הכי) הָתָם בַּת שֶׁבַע, הָכָא אֱלִישֶׁבַע. אֱלִישֶׁבַע: דְּאִתְחַבְּרָא בְּחֶסֶד, (תא חזי) בַּת שֶׁבַע לְדִינָא, לְיָרְתָא מַלְכוּתָא וּלְאִתָּקְפָא.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, הָא דְּתָנֵינָן דִּכְתִּיב, (שמות י״ט:י״ט) קוֹל הַשּׁוֹפָר, שַׁפִּיר הוּא, וְדָא הוּא יַעֲקֹב, דְּאִסְתַּלָּק בְּמַחֲשָׁבָה דַּאֲבָהָן, וְנַפְקוּ כַּחֲדָא מִגּוֹ שׁוֹפָר, דְּהָא שׁוֹפָר אַפִּיק מַיָּא וְאֶשָּׁא וְרוּחָא כַּחֲדָא, וְאִתְעָבִיד מִנַּיְיהוּ קָלָא. כַּךְ אִמָּא עִלָּאָה, אַפִּיק לַאֲבָהָן, בְּקָל חַד. וּמִגּוֹ מַחֲשָׁבָה אִסְתְּלָקוּ כַּחֲדָא בְּחַד קוֹל, וְהַהוּא קוֹל אִקְרֵי קוֹל הַשּׁוֹפָר, וְדָא יַעֲקֹב דְּכָלִיל לַאֲבָהָן כַּחֲדָא, וְאִקְּרֵי קוֹל.</p>\n<p>וּתְרֵי קַלֵי נִינְהוּ, דְּהָא מִגּוֹ קָלָא, נָפִיק קָלָא. אֲבָל קוֹל חַד דְּאִקְרֵי קוֹל הַשּׁוֹפָר, וּמֵהָכָא נָפְקוּ שְׁאָר קוֹלוֹת, מִגּוֹ הַהוּא שׁוֹפָר בְּזִוּוּגָא <Nonei></i>דְּמַחֲשָׁבָה. וְשִׁבְעָה קוֹלוֹת נִינְהוּ, דְּנָפְקִין בְּזִוּוּגָא דְּמַחֲשָׁבָה בְּשּׁוֹפָר, וְדָא שׁוֹפָר דְּאַשְׁקֵי לוֹן וְרַוִּי לוֹן לַאֲבָהָן בְּקַדְמִיתָא, וּלְבָתַר לִבְנִין, וְהָא אוּקְמוּהָ מִלָּה.</p>\n<p>תָּא חֲזֵי, וַיִּקַּח אַהֲרֹן אֶת אֱלִישֶׁבַע, לְבַסְּמָא לָהּ, לְמֵחֱדֵי לָהּ, לְחַבְּרָא לָה בְּמַלְכָּא, בְּזִוּוּגָא שְׁלִים, לְאִשְׁתַּכְּחָא בִּרְכָאן לְעָלְמִין כֻּלְּהוּ, עַל יְדֵי דְּאַהֲרֹן. בְּגִין כָּךְ, בָּעֵי כַּהֲנָא לְאִשְׁתַּכְּחָא בִּנְהִירוּ דְּאַנְפִּין, בְּחֵידוּ, כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא, דְּהָא עַל יְדוֹי בִּרְכָאן וְחֶדְוָון מִשְׁתַּכְּחֵי. וְעַל דָּא אִתְרַחֲקָא מִנֵּיהּ דִּינָא וְרוּגְזָא וְעָצִיבוּ, בְּגִין דְּלָא יִתְפְּגָם מֵהַהוּא אֲתַר דְּאִתְקְטַר בֵּיהּ. וְעַל דָּא וַאֲחֵיכֶם כָּל בֵּית יִשְׂרָאֵל יִבְכּוּ אֶת הַשְּׂרֵפָה, וְלָאו כַּהֲנָא. עָלַיְיהוּ כְּתִיב (דברים ל״ג:י״א) בָּרֵךְ יְיָ' חֵילוֹ וּפֹעַל יָדָיו תִּרְצֶה וְגוֹ'.</p>"],[9520012041,"<p>(ויקרא י׳:ט׳) יַיִן וְשֵׁכָר אַל תֵּשְׁתְּ אַתָּה וּבָנֶיךָ אִתָּךְ וְגוֹ'. אָמַר רִבִּי יְהוּדָה, מִגּוֹ פַּרְשְׁתָּא דָּא שַׁמְעֵינָן, דְּנָדָב וַאֲבִיהוּא רְוִי חַמְרָא הֲווֹ, מִדְּאַזְהַר לְכַהֲנֵי בְּהָא. רִבִּי חִיָּיא פָּתַח, (תהילים ק״ד:ט״ו) וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ וְגוֹ', אִי בָּעֵי כַּהֲנָא לְמֶחְדֵּי וּלְאִשְׁתַּכְּחָא בִּנְהִירוּ דְּאַנְפִּין יַתִּיר מִכֹּלָּא, אֲמַאי אָסִיר לֵיהּ חַמְרָא, דְּהָא חֵידוּ בֵּיהּ אִשְׁתְּכַח, נְהִירוּ דְּאַנְפִּין בֵּיהּ אִשְׁתְּכַח.</p>\n<p>אֶלָּא שֵׁירוּתָא דְּחַמְרָא חֶדְוָותָא. סוֹפֵיהּ עֲצִיבוּ. וְעוֹד דְּיַּיִן מִסִּטְרָא דְּלֵיוָאֵי אָתֵי, מֵאֲתַר דְּחַמְרָא שָׁרֵי, דְּהָא אוֹרַיְיתָא וְחַמְרָא דְּאוֹרַיְיתָא, מִסִּטְרָא דִּגְבוּרָה הוּא. (ס\"א סיפיה עציבו, וכהנא שירותא וסיומא בעי חדותא ונהירו דאנפין, יין אתי מסטרא דליואי) וְסִטְרָא דְּכַהֲנָא מַיִין צְלִילִין נְהִירִין.</p>\n<p>רִבִּי יוֹסֵי אָמַר כָּל חַד אוֹזִיף לְחַבְרֵיהּ, וְכָלִיל כֹּלָּא דָּא בְּדָא, וּבְגִין כָּךְ, חַמְרָא שָׁרֵי חֶדְוָותָא, בְּגִין דְּכָלִיל מִגּוֹ מַיָּא, וּלְבָתַר אַהְדָּר לְאַתְרֵיהּ, וְעָצִיב וְרָגִיז וְדָאִין דִּינָא. (וכהנא שירותא וסיומא בעי חדותא ונהירו דאנפין)</p>\n<p>רִבִּי אַבָּא אָמַר, מֵאֲתַר חַד נָפְקוּ, יַיִן וְשֶׁמֶן וּמַיִם. מַיִם וְשֶׁמֶן לִימִינָא, נַטְלֵי כַּהֲנֵי וְיַרְתֵּי לוֹן, וְשֶׁמֶן יַתִּיר מִכֹּלָּא. דְּאִיהוּ חֶדְוָותָא שֵׁירוּתָא וְסִיּוּמָא, דִּכְתִּיב, (תהילים קל״ג:ב׳) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ יוֹרֵד עַל הַזָּקָן זְקַן אַהֲרֹן. וְיַיִן לִשְׂמָאלָא, יַרְתֵּי לֵיוָאֵי, לְאַרְמָא קָלָא וּלְזַמְּרָא, וְלָא לִשְׁתּוּק, דְּהָא חַמְרָא לָא שָׁתִיק לְעָלְמִין, וְשֶׁמֶן בַּחֲשַׁאי הוּא תָּדִיר.</p>\n<p>מַה בֵּין הַאי לְהַאי. אֶלָּא, שֶׁמֶן דְּאִיהוּ בַּחֲשַׁאי בִּלְחִישׁוּ תָּדִיר, אָתֵי מִסִּטְרָא דְּמַחֲשָׁבָה, דְּאִיהוּ בִּלְחִישׁוּ תָּדִיר וְלָא אִשְׁתְּמַע, וְהוּא בַּחֲשַׁאי, וְעַל דָּא הוּא מִימִינָא. וְיַיִן דְּאִיהוּ (קרח קע\"ו) לְאַרְמָא קָלָא, וְלָא שָׁתִיק לְעָלְמִין, אָתֵי מִסִּטְרָא דְּאִימָּא, וְיָרְתִין לֵיוָאֵי לִסְטַר שְׂמָאלָא, וְקַיְימֵי לְזַמְּרָא לְאַרְמָא קָלָא, וְקַיְימֵי בְּדִינָא. וּבְגִין כָּךְ כְּתִיב, (דברים כ״א:ה׳) וְעַל פִּיהֶם יִהְיֶה כָּל רִיב וְכָל נָגַע.</p>\n<p>בְּגִין כַּךְ, כַּהֲנָא כַּד יִיעוּל לְמַקְדְּשָׁא לְמִפְלַח פּוּלְחָנָא, אָסִיר לֵיהּ לְמִשְׁתֵּי חַמְרָא, דְּהָא עוֹבָדוֹי בַּחֲשַׁאי אִינּוּן, וּבַחַשַׁאי (ס\"א אתחזי) אָתָאן וְאִתְכְּוָּון, (ס\"א ובחשאי אתכוון במה דאתכוון) וְזִוִּוג לְמַאן דְּזִוִּוג, וְנָגִיד בִּרְכָאן לְעָלְמִין כֻּלְּהוּ, וְכֹלָּא בַּחֲשַׁאי, (ועוד) דְעוֹבָדוֹי כֻּלְּהוּ בְּרָזָא. וְחַמְרָא מְגַלֶּה רָזִין הוּא, דְּהָא כָּל עוֹבָדוֹי לְאַרְמָא קָלָא קָאִים.</p>\n<p>רִבִּי יְהוּדָה וְרִבִּי יִצְחָק הֲווֹ אַזְלֵי בְּאָרְחָא, מִבֵּי מִרוֹנְיָא לְצִפּוֹרִי, וַהֲוָה רַבְיָיא חַד שְׁכִיחַ בְּגַוָּון (ס\"א לגבייהו), בְּחַמְרָא בְּקִינְטָא דְּדוּבְשָׁא אָמַר רִבִּי יְהוּדָה נֵימָא מִלָּה דְּאוֹרַיְיתָא וְנֵזִיל.</p>\n<p>פָּתַח רִבִּי יִצְחָק וְאָמַר, (שיר השירים ז׳:י׳) וְחִכֵּךְ כְּיֵין הַטּוֹב הוֹלֵךְ לְדוֹדִי לְמֵישָׁרִים וְגוֹ'. וְחִכֵּךְ כְּיֵין הַטּוֹב, דָּא יֵינָא דְּאוֹרַיְיתָא, דְּאִיהוּ טָב. דְּהָא יֵינָא אָחֳרָא לָאו אִיהוּ טָב, וְיֵינָא דְּאוֹרַיְיתָא, טָב לְכֹלָּא. טָב לְעָלְמָא דָּא, וְטָב לְעָלְמָא דְּאָתֵי. וְדָא הוּא יֵינָא דְּנִיחָא לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא יַתִּיר מִכֹּלָּא, וּבִזְכוּ דָּא, מַאן דִּמְרַוִּי מִיֵינָא דְּאוֹרַיְיתָא, יִתְּעַר לְעָלְמָא דְּאָתֵי, וְיִזְכֵּי לְאַחֲיָיא, כַּד יוֹקִים קוּדְשָׁא בְּרִיךְ הוּא לְצַדִּיקַיָּיא. אָמַר רִבִּי יְהוּדָה, דּוֹבֵב שִׂפְתֵי יְשֵׁנִים, הָא תָּנֵינָן דְּאֲפִילּוּ בְּהַהוּא עָלְמָא, יִזְכֵּי לְמִלְעֵי בְּאוֹרַיְיתָא, הֲדָא הוּא דִכְתִיב דּוֹבֵב שִׂפְתֵי יְשֵׁנִים.</p>\n<p>אָמַר הַהוּא רַבְיָא, אִי כְּתִיב וְחִכֵּךְ מִיֵּין הַטּוֹב, הֲוִינָא אַמְרֵי הָכֵי. אֲבָל כְּיֵין הַטּוֹב כְּתִיב, וְלָא מִיֵּין. אַשְׁגְּחוּ בֵּיהּ, אָמַר רִבִּי יְהוּדָה, בְּרִי אֵימָא מִילָּךְ, דְּשַׁפִּיר קָא אַמְרַת.</p>\n<p>אָמַר, אֲנָא שְׁמַעְנָא, דְּמַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, וְדָבִיק בָּה, וְהַהִיא מִלָּה דְּאוֹרַיְיתָא אִשְׁתְּמַע בְּפוּמֵיהּ, וְלָא לָחִישׁ לָהּ <Nonei></i>בִּלְחִישׁוּ, אֶלָּא אָרִים קָלֵיהּ בָּה. דְּאוֹרַיְיתָא הָכִי בַּעְיָא לְאַרְמָא קָלָא, דִּכְתִּיב, (משלי א׳:כ״א) בְּרֹאשׁ הוֹמִיּוֹת תִּקְרָא, לְאָרָמָא רִנָּה דְּאוֹרַיְיתָא, וְלָא בִּלְחִישׁוּ. כְּיֵין הַטּוֹב, כַּחֲמַר טָב דְּלָא שָׁתִיק. וְהוּא עָתִיד לְאָרָמָא קָלָא, כַּד יִפּוּק מֵהַאי עָלְמָא. הוֹלֵךְ לְדוֹדִי לְמֵשָׁרִים, דְּלָא יִסְטֵי לִימִינָא וְלִשְׂמָאלָא, לָא יִשְׁתְּכַּח דְּיִמְחֵי בִּידוֹי. דּוֹבֵב שִׂפְתֵי יְשֵׁנִים, אֲפִילּוּ בְּהַהוּא עָלְמָא שִׁפְוָותֵיהּ מְרַחְשָׁן אוֹרַיְיתָא.</p>\n<p>תּוּ שְׁמַעְנָא וְחִכֵּךְ כְּיֵין הַטּוֹב, הַאי קְרָא לִכְּנֶסֶת יִשְׂרָאֵל אִתְּמַר, וּבְתוּשְׁבַּחְתָּא אִתְּמַר. אִי הָכִי, מַאן הוּא דִּמְשַׁבַּח לָהּ בְּהַאי. אִי קוּדְשָׁא בְּרִיךְ הוּא, מַהוּ הוֹלֵךְ לְדוֹדִי, הוֹלֵךְ אֵלַי מִבָּעֵי לֵיהּ.</p>\n<p>אֶלָּא וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא קָא מְשַׁבַּח לָהּ לִכְּנֶסֶת יִשְׂרָאֵל, כְּמָה דְּהִיא קָא מְשָׁבַּחַת לֵיהּ, דִּכְתִּיב חִכּוֹ מַמְתַּקִּים, כַּךְ קוּדְשָׁא בְּרִיךְ הוּא מְשַׁבַּח לֵהּ לִכְּנֶסֶת יִשְׂרָאֵל. (דכתיב) וְחִכֵּךְ כְּיֵין הַטּוֹב, יֵין הַטּוֹב: דְּהוּא חַמְרָא דְּמִנְטְרָא. הוֹלֵךְ לְדוֹדִי: דָּא יִצְחָק, דְּאִקְרֵי יְדִיד מִבֶּטֶן. לְמֵישָׁרִים: כְּמָה דְאַתְּ אָמֵר, (תהילים צ״ט:ד׳) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים, לְאִתְכַּלְּלָא שְׂמָאלָא בִּימִינָא. וְדָא הוּא מֵישָׁרִים, דִּבְגִין חֶדְוָותָא דְּהַהוּא חֲמָר טַב, אִתְכְּלִיל שְׂמָאלָא בִּימִינָא, וְחַדָּאן כֹּלָּא. (דובב שפתי ישנים) דְּהָא כֹּלָּא מִתְעֲרֵי בְּחֶדְוָואן וּבִרְכָּאן, וְעָלְמִין כֻּלְּהוּ מִשְׁתַּכְּחֵי בְּחֵדוּ, וּמִתְעָרֵי לְאַרְקָא בִּרְכָאן לְתַתָּא.</p>\n<p>אָתוּ רִבִּי יְהוּדָה וְרִבִּי יִצְחָק וְנַשְּׁקוּ לֵיהּ רֵישֵׁיהּ, וְחַדּוּ עִמֵּיהּ, אָמְרוּ לֵיהּ מַה שְׁמָךְ. אָמַר לְּהוֹ יֵיסָא. אָמְרוּ רִבִּי יֵיסָא תְּהֵא. יַתִּיר תְּהֵא שְׁכִיחַ בְּעָלְמָא מֵרַבִּי יֵיסָא חַבְרָנָא, דְּאִסְתַּלָּק מִבֵּינָנָא. אָמְרוּ לֵיהּ וּמַאן אָבוּךְ. אָמַר לְּהוֹ, אַפְטַר מֵעָלְמָא, וַהֲוָה אוֹלִיף לִי כָּל יוֹמָא ג' מִלִּין דְּאוֹרַיְיתָא, וּבְלֵילְיָא ג' מִילִּין דְּחָכְמְתָא דְּאַגַּדְתָּא. וְהָנֵי מִילֵי אוֹלִיפְנָא מֵאַבָּא, וְהַשְׁתָּא דִּיוּרִי בְּחַד בַּר נָשׁ, וְסָלִיק לִי מֵאוֹרַיְיתָא. וַאֲנָא אָזִיל כָּל יוֹמָא לַעֲבִידְתָּא, וּבְכָל יוֹמָא אַהֲדַרְנָא אִינּוּן מִלִּין דְּאוֹלִיפְנָא מֵאַבָּא.</p>\n<p>אָמְרוּ לֵיהּ הַהוּא בַּר נָשׁ יָדַע בְּאוֹרַיְיתָא. אָמַר לוֹן לָאו. סָבָא הוּא, וְלָא יָדַע לְבָרְכָא לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִית לֵיהּ בְּנִין, וְלָא שַׁוִּי לוֹן בְּבֵי רַב. אָמַר רִבִּי יְהוּדָה (נ\"א אי לאו הכי הוה) אִי לָא הֲוָה הָכִי, הֲוָה אֲעִילְנָא לְגַבֵּי הַאי כְּפַר לְמַלְּלָא עֲלָךְ, הַשְׁתָּא אָסִיר לָן לְמֵחֱזֵי אַנְפּוֹי. שְׁדֵי חֲמָרָא מִנָךְ, וְאַתְּ זִיל לְגַבָּן. אָמְרוּ לֵיהּ מַאן הוּא אָבוּךְ. אָמַר רִבִּי זְעֵירָא דִּכְפַר רָאמִין.</p>\n<p>שָׁמַע רִבִּי יְהוּדָה וּבָכָה, אָמַר אֲנָא הֲוִינָא בְּבֵיתֵיהּ, וְאוֹלִיפְנָא מִנֵּיהּ ג' מִלִּין בְּכַסָּא דִּבְרָכָה, וְאוֹלִיפְנָא מִנֵּיהּ בְּמַעֲשֵׂה בְּרֵאשִׁית תְּרֵי. אָמַר רִבִּי יִצְחָק, וּמַה מֵהַאי רַבְיָא בְּרֵיהּ אוֹלִיפְנָא, מִנֵּיהּ לָא כָּל שֶׁכֵּן. אַזְלוּ וְאָחִידוּ בִּידֵיהּ. חָמוּ חַד חֲקַל וְיָתְבוּ תַּמָּן. אָמְרוּ לֵיהּ אֵימָא חַד מִלָּה, מֵאִינּוּן דְּאוֹלִיף לָךְ אָבוּךְ בְּמַעֲשֵׂה בְּרֵאשִׁית.</p>"],[9520012042,"<p>פָּתַח וְאָמַר, (בראשית א׳:כ״א) וַיִבְרָא אֱלֹהִים אֶת הַתַּנִּינִים הַגְּדוֹלִים וְגוֹ'. וַיִבְרָא אֱלֹהִים, כָּל אֲתַר דְּדִינָא אֱלֹהִים אִקְרֵי. וְהַהוּא אֲתַר עִלָּאָה אֲתַר דְּנָפְקוּ מִנֵּיהּ, הָכִי קָרֵי לֵיהּ הָכָא. וְאַף עַל גַּב דְּרַחֲמֵי הוּא, מִנֵיהּ נָפְקוּ דִּינִין, וּבֵיהּ תַּלְיָין.</p>\n<p>אֶת הַתַּנִּינִים הַגְּדוֹלִים, אִלֵּין אֲבָהָן. דְּאִינּוּן מִתְשַׁקְיָין בְּקַדְמִיתָא, וּמִשְׁתָּרְשִׁין עַל כֹּלָּא. וְאֵת כָּל נֶפֶשׁ הַחַיָּה הָרוֹמֶשֶׂת, וְאֵת כָּל נֶפֶשׁ הַחַיָּה, דָּא נֶפֶשׁ, דְּהַהִיא אֶרֶץ עִלָּאָה אַפִּיקַת מֵהַהִיא חַיָּה עִלָּאָה עַל כֹּלָּא, דִּכְתִּיב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה. וְדָא אִיהִי נֶפֶשׁ דְּאָדָם קַדְמָאָה, דְּמָשִׁיךְ בְּגַוִיהּ. הָרוֹמֶשֶׂת: דָּא הִיא חַיָּה דְּרַחֲשָׁא בְּכָל טוּרִין (ס\"א סטרין), לְעֵילָּא וְתַתָּא. אֲשֶׁר שָׁרְצוּ הַמַּיִם, דְּהַהוּא נָהָר עִלָּאָה נָגִיד וְנָפִיק מֵעֵדֶן, וְאַשְׁקֵי לְהַאי אִילָנָא, לְאִשְׁתָּרְשָׁא בְּשָׁרְשׁוֹי עַל כֹּלָּא, וּלְאִשְׁתַּכְּחָא בֵּיהּ מְזוֹנָא לְכֹלָּא.</p>\n<p>דָּבָר אַחֵר הַחַיָּה הָרוֹמֶשֶׂת, דָּא הוּא דָּוִד מַלְכָּא, דִּכְתִּיב בֵּיהּ (תהילים קי״ח:י״ז) לֹא אָמוּת כִּי אֶחְיֶה וְגוֹ'. וְאֵת כָּל עוֹף כָּנָף לְמִינֵהוּ, אִלֵּין כָּל אִינּוּן מַלְאֲכִין קַדִּישִׁין, דְּמִשְׁתַּכְּחֵי לְקַדְּשָׁא שְׁמָא דְּמָארֵיהוֹן בְּכָל יוֹמָא וְיוֹמָא, דִּכְתִּיב בְּהוּ (ישעיהו ו׳:ב׳) שֵׁשׁ כְּנָפַיִם שֵׁשׁ כְּנָפַיִם לְאֶחָד. וּמִנְּהוֹן טָאסִין בְּעָלְמָא לְמֶעְבַּד רְעוּתָא דְּמָארֵיהוֹן, כָּל חַד וְחַד כַּדְקָא חֲזֵי. אָמַר רִבִּי יְהוּדָה, ודַּאי כָּל כַּךְ לְהַאי רַבְיָא לָא אִתְחֲזֵי, אֲבָל אֲנָא חָמֵי בֵּיהּ דְּלַאֲתַר עִלָּאָה יִסְתְּלַק.</p>\n<p>אָמַר רִבִּי יִצְחָק, <Nonei></i>וַדַּאי. הַחַיָּה (הרומשת) דָּא הִיא חַיָּה עִלָּאָה עַל כֹּלָּא, דְּהָא אָחֳרָא אֶרֶץ קַרְיֵיהּ קְרָא. הָכָא דִּכְתִּיב וְהָעוֹף יִרֶב בָּאָרֶץ, בָּאָרֶץ ודַּאי, וְלָא בַּמַיִם. דְּהָא הַהוּא נָהָר, נָגִיד וְנָפִיק וְאַשְׁקֵי, בְּלָא פֵּירוּדָא, עַד הַהוּא אֲתַר דְּאִקְרֵי אֶרֶץ, וּמִתַּמָּן כְּתִיב וּמִשָּׁם יִפָּרֵד וְגוֹ'. וְהָעוֹף, וְהַהוּא עוֹף בְּהַאי אֶרֶץ תַּלְיָין וְאִתְשַּׁקְיָין, וְדָא הוּא דִּכְתִּיב וְהָעוֹף יִרֶב בָּאָרֶץ. קָמוּ וְאָזְלוּ. אָמַר רִבִּי יְהוּדָה, נִשְׁתַּתֵּף לְהַאי רַבְיָא עִמָּנָא, וְכָל חַד וְחַד לֵימָא מִלָּה דְּאוֹרַיְיתָא.</p>"],[9520012043,"<p>פָּתַח רִבִּי יְהוּדָה וְאָמַר, (שיר השירים ב׳:ה׳) סַמְּכוּנִי בָּאֲשִׁישׁוֹת רַפְּדוּנִי בַּתַּפּוּחִים וְגוֹ'. הַאי קְרָא הָא אִתְּמַר וְשַׁפִּיר. אֲבָל כְּנֶסֶת יִשְׂרָאֵל קָאָמַר דָּא בְּגָלוּתָא. סַמְּכוּנִי, מַהוּ סַמְּכוּנִי. אֶלָּא מַאן דְּנָפִיל בָּעֵי לְאַסְמְכָא לֵיהּ, הֲדָא הוּא דִכְתִיב, (תהילים קמ״ה:י״ד) סוֹמֵךְ יְיָ' לְכָל הַנּוֹפְלִים וְגוֹ'. וּבְגִין כָּךְ, כְּנֶסֶת יִשְׂרָאֵל דְּנָפְלָה, דִּכְתִּיב, (עמוס ה׳:ב׳) נָפְלָה לֹא תוֹסִיף קוּם, בַּעְיָא לְאַסְמְכָא, וְהִיא אָמְרָה סַמְּכוּנִי. לְמַאן אָמְרָה. לְיִשְׂרָאֵל בְּנָהָא דְּאִינּוּן בְּגָלוּתָא עִמָּהּ.</p>\n<p>וּבְמָּה בָּאֲשִׁישׁוֹת. אִלֵּין אִינּוּן אֲבָהָן, דְּאִינּוּן אִתְמַלְיָין בְּקַדְמִיתָא, מֵהַהוּא חֲמָר טַב דְּמִנְטְרָא. וְכַד אִינּוּן אִתְמַלְיָין, הָא בִּרְכָאָן מִשְׁתַּכְּחֵי לְגַבָּהּ, עַל יְדָא דְּחַד דַּרְגָּא דְּאִיהוּ צַדִּיק. וּמַאן דְּיָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא, אַף עַל גַּב דְּבִרְכָּאן לָא מִשְׁתַּכְּחֵי בְּעָלְמָא, אִיהוּ סָמִיךְ וְסָעִיד לָהּ לִכְּנֶסֶת יִשְׂרָאֵל בְּגָלוּתָא.</p>\n<p>רַפְּדוּנִי בַּתַּפּוּחִים, כֹּלָּא חַד כְּמָה דְּאַמָרָן, אֲבָל רָזָא דָּא, אֲשִׁישָׁא: עָיֵיל חַמְרָא. תַּפּוּחַ: אַפִּיק חַמְרָא, וּמְכַוִּון רְעוּתָא. וְעַל דָּא אֲשִׁישׁוֹת וְתַפּוּחִים. אֲשִׁישׁוֹת, לְרַוָואָה מֵחַמְרָא. תַּפּוּחִים, לְכַוְּונָא רְעוּתָא דְּלָא יָזִיק חַמְרָא. וְכָל דָּא לָמָּה. כִּי חוֹלַת אַהֲבָה אָנִי, בְּגָלוּתָא. וּמַאן דִּמְיַיחֵד שְׁמָא קַדִּישָׁא, בָּעֵי לְיַחֲדָא דִּינָא בְּרַחֲמֵי, וּלְאַכְלְלָא לוֹן כַּדְקָא חֲזֵי, לְאִתְבַּסְּמָא וּלְאִתְתַּקְנָא כֹּלָּא כְּדְקָא יֵאוֹת, וְדָא סָמִיךְ לָהּ לִכְּנֶסֶת יִשְׂרָאֵל בְּגָלוּתָא.</p>"],[9520012044,"<p>רִבִּי יִצְחָק פָּתַח, (דברים ל״ב:ל״ח) אֲשֶׁר חֵלֶב זְבָחֵימוֹ יֹאכֵלוּ יִשְׁתּוּ יֵין נְסִיכָם. זַכָּאִין אִינּוּן יִשְׂרָאֵל דְּאִינּוּן קַדִּישִׁין, וְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְקַדְּשָׁא לוֹן. תָּא חֲזֵי יִשְׂרָאֵל קַדִּישִׁין, כָּל חַיֵּי עָלְמָא דְּיַרְתִין, כֹּלָּא תַּלְיָין בְּהַהוּא עָלְמָא דְּאָתֵי, בְּגִין דְּאִיהוּ חַיִּין דְּכֹלָּא, לְעֵילָּא וְתַתָּא, וְהוּא אֲתַר, דְּיַיִן דְּמִנְטְרָא שָׁארֵי (ואקרי יין) וּמִתַּמָּן נָפְקִין חַיִּין וּקְדוּשָׁא לְכֹלָּא. וְיַיִן דְּיִשְׂרָאֵל בְּגִין יַיִן דְּיִשְׂרָאֵל אָחֳרָא, וְדָא בְּדָא תַּלְיָא. דְּהָא יִשְׂרָאֵל לְעֵילָּא, בֵּיהּ נָטִיל חַיִּין, וּבְגִין כָּךְ אִקְרֵי עֵץ חַיִים, עֵץ מֵהַהוּא אֲתַר דְּאִקְרֵי חַיִּים, וְנַפְקֵי מִתַּמָּן חַיִּין, וְעַל דָּא מְבָרְכִין לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא בְּיַיִן. וְיַיִן דְּיִשְׂרָאֵל לְתַתָּא כְּהַאי גַּוְונָא.</p>\n<p>עוֹבֵד עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, דְּאִיהוּ מְסָאָב, וּמַאן דְּקָרִיב בַּהֲדֵיהּ יִסְתְּאָב, כַּד יִקְרַב בְּיַיִן דְּיִשְׂרָאֵל, הָא אִסְתְּאַב וְאָסִיר, כָּל שֶׁכֵּן הַהוּא יַיִן דְּאִיהוּ עָבִיד. וְעַל דָּא לָא תֵּימָא דְּדָא הוּא בִּלְחוֹדוֹי, אֶלָּא כָּל מַה דְּעָבְדֵי יִשְׂרָאֵל לְתַתָּא, כֹּלָּא הוּא כְּעֵין דּוּגְמָא דִּלְעֵילָּא, כָּל שֶׁכֵּן יַיִן, דְּקָאֵי בַּאֲתַר עִלָּאָה, דּוּגְמָא דְּיַיִן דְּמִנְטְרָא.</p>\n<p>בְּגִין כַּךְ יִשְׂרָאֵל שַׁתְיָין יַיִן דְּיִשְׂרָאֵל, דְּאִתְעָבִיד כַּדְקָא חֲזֵי בִּקְדוּשָּׁה, כְּגַוְונָא דְּיִשְׂרָאֵל לְעֵילָּא, דְּשָׁתֵי וְאִשְׁתָּרְשָׁא וְאִתְבָּרְכָא בְּהַהוּא יַיִן עִלָּאָה קַדִּישָׁא, וְלָא שָׁתָאן יַיִן דְּאִתְעָבִיד בִּמְסָאֲבוּתָא, וּמִסִּטְרָא דִּמְסָאֲבוּתָא, דְּהָא בֵּיהּ שַׁרְיָא רוּחָא דִּמְסָאֲבוּתָא. (ולאו הוא מסטרא דישראל) וּמַאן דְּשָׁתֵי לֵיהּ (בהדייהו), אִסְתְּאַב רוּחֵיהּ, וְאִסְתְּאַב אִיהוּ, וְלָאו הוּא מִסִּטְרָא דְּיִשְׂרָאֵל, וְלֵית לֵיהּ חוּלָקָא בְּעָלְמָא דְּאָתֵי. דְּהָא הַהוּא עָלְמָא דְּאָתֵי, יַיִן דְּמִנְטְרָא אִיהוּ.</p>\n<p>וְעַל דָּא יִשְׂרָאֵל קַדִּישִׁין, בַּעְיָין לְנַטְרָא דָּא עַל כֹּלָּא, בְּגִין דְּאִתְקְשַׁר בַּאֲתַר דְּעָלְמָא דְּאָתֵי. וּבְגִין כָּךְ, בְּיַיִן אִתְבְּרִיךְ קוּדְשָׁא בְּרִיךְ הוּא יַתִּיר מִכֹּלָּא, בְּגִין דְּאִיהוּ חַדֵּי לְסִטְרָא שְׂמָאלָא, וּבְגוֹ חֶדְוָותָא דִּילֵיהּ אִתְכְּלִיל בִּימִינָא. וְכַד אִתְעָבִיד כֹּלָּא יְמִינָא, כְּדֵין שְׁמָא קַדִּישָׁא בְּחֵידוּ, וּבִרְכָּאן מִשְׁתַּכְּחֵי בְּכֻלְּהוּ עָלְמִין. וּבְעוֹבָדָא דִּלְתַתָּא יִתְּעַר עוֹבָדָא דִּלְעֵילָּא, וְעַל דָּא מְזַמְּנֵי יַיִן לָקֳבֵיל יַיִן.</p>\n<p>וּבְגִין דְּאִיהוּ מְנַטְרָא לְעֵילָּא, בָּעֵי לְנַטְרָא לֵיהּ לְתַתָּא, וְכָל נְטִירוּ דִּילֵיהּ קְדוּשָּׁה הוּא לְיִשְׂרָאֵל, וּמַאן דְּפָגִים לֵיהּ לְתַתָּא בְּסִטְרָא דִּמְסָאֲבוּתָא, יִסְתְּאָב אִיהוּ בְּהַאי עָלְמָא, וְלֵית לֵיהּ חוּלָקָא בְּעָלְמָא דְּאָתֵי, אֲתַר דְּהַהוּא יַיִן דְּמִנְטְרָא שַׁרְיָא. הוּא לָא נָטִיר לֵיהּ, לָא יִתְנְטַר הוּא לְעָלְמָא דְּאָתֵי. <Nonei></i>הוּא סָאִיב לֵיהּ, יִסְאֲבוּן לֵיהּ בְּהַהוּא עָלְמָא, לָא יְהֵא לֵיהּ חוּלָקָא בְּהַהוּא יַיִן דְּעָלְמָא דְּאָתֵי. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דִּמְקַדְּשֵׁי נַפְשַׁיְיהוּ בִּקְדוּשָּׁה עִלָּאָה, וְנַטְרֵי מַה דְּאִצְטְרִיךְ לְאִתְנַטְרָא, וּמְקַדְּשֵׁי לְמַלְכָּא בִּנְטִירוּ עִלָּאָה דָּא. זַכָּאִין אִינּוּן בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.</p>"],[9520012045,"<p>פָּתַח הַהוּא רַבְיָא וְאָמַר, (משלי כ״ט:ד׳) מֶלֶךְ בְמִשְׁפָּט יַעֲמִיד אָרֶץ וְגוֹ'. מַאן מֶלֶךְ. דָּא קוּדְשָׁא בְּרִיךְ הוּא. בְּמִשְׁפָּט דָּא יַעֲקֹב, דְּאִיהוּ כְּלָלָא דַּאֲבָהָן. וְאִישׁ תְּרוּמוֹת, תְּרוּמַת כְּתִיב, כְּמָה דְאַתְּ אָמֵר (שמות כ״ה:ג׳) וְזֹאת הַתְּרוּמָה. וְאִישׁ תְּרוּמוֹת, דָּא עֵשָׂו, דְּבָעֵי עַל תְּרוּמוֹת וְעַל מַעֲשְׂרוֹת כָּל יוֹמָא, וְלָא עָבִיד מִדִי. וְאִישׁ תְּרוּמוֹת דְּלָאו אִיהוּ מִשְׁפָּט. דְּהָא תְּרוּמָה אִסְתַּלְקוּתָא דְּרַחֲמֵי, בְּגִין דָּא לָא אַתְיָא בְּמִּשְׁפָּט, כְּמָה דְאַתְּ אָמֵר (משלי י״ג:כ״ג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט, וְעַל דָּא, וְאִישׁ תְּרוּמֹת יֶהֶרְסֶנָּה.</p>\n<p>וְאִי תֵּימָא, הָא דָּוִד מַלְכָּא אִישׁ תְּרוּמָה הֲוָה, אֶלָּא בְּרַחֲמֵי. וְלֹא עוֹד אֶלָּא (ס\"א דוד מלכא איש תרומה הוה וארעא אתקיימא בגיניה הכי הוא ודאי. אבל כלא ברחמי הוה) דְּהָא כְּתִיב (ישעיהו נ״ה:ג׳) חַסְדֵי דָּוִד הַנֶּאֱמָנִים, כְּמָה דְּאִתְדְּבַק בְּהַאי, אִתְדְּבַק בְּהַאי.</p>\n<p>תָּא חֲזֵי, כָּל יוֹמוֹי דְּדָוִד מַלְכָּא, הֲוָה מִשְׁתָּדַּל (בגין) דְּהַאי תְּרוּמָה, יִתְקְשַׁר בְּמִּשְׁפָּט, וְיִזְדַּוְוגוּן כַּחֲדָא. (בגין דיתקיים בארעא) אָתָא שְׁלֹמֹה וְזִוִּוג לוֹן כַּחֲדָא, וְקַיְּימָא סִיהֲרָא בְּאַשְׁלְמוּתָא, וְקַיְּימָא אַרְעָא בְּקִיּוּמָא. אָתָא צִדְקִיָּהוּ וְאַפְרִישׁ לוֹן, וְאִשְׁתְּאָרַת אַרְעָא בְּלָא מִשְׁפָּט, וְאִתְפְּגִימַת סִיהֲרָא, וְאִתְחֲרִיבַת אַרְעָא, כְּדֵין וְאִישׁ תְּרוּמַת יֶהֶרְסֶנָּה.</p>"],[9520012046,"<p>וְתָא חֲזֵי, שֶׁמֶן לְכַהֲנֵי, וְיַיִן לְלֵיוָאֵי. לָא בְּגִין דְּבַעְיָין יַיִן, אֶלָּא מִיַּיִן דְּמִנְטְרָא אָתֵי לְסִטְרָא דִּלְהוֹן, לְחַבְּרָא כֹּלָּא כַּחֲדָא, וּלְמֵחֱדֵי עָלְמִין כֻּלְּהוּ, לְאִשְׁתַּכְּחָא בְּהוּ כֹּלָּא, יְמִינָא וּשְׂמָאלָא כָּלִיל דָּא בְּדָא. לְאִשְׁתַּכְּחָא בְּהוּ חֲבִיבוּתָא דְּכֹלָּא, וּרְחִימוּתָא דִּבְנֵי מְהֵימְנוּתָא.</p>\n<p>מַאן דְּאִתְדְּבַק רְעוּתֵיהּ בְּהַאי, הוּא שְׁלִים בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי, וְיִשְׁתְּכַּח כָּל יוֹמוֹי דְּאִתְדְּבַק בִּתְשׁוּבָה, אֲתַר דְּיַיִן וְשֶׁמֶן מִשְׁתַּכְּחֵי. כְּדֵין לָא יִתְדְּבָק בָּתַר עָלְמָא דָּא, לָא לְעֻתְרָא, וְלָא לְכִסּוּפָא דִּילֵיהּ. וּשְׁלֹמֹה מַלְכָּא צָוַוח עַל דָּא וְאָמַר, (משלי כ״א:י״ז) אוֹהֵב יַיִן וָשֶׁמֶן, לֹא יַעֲשִׁיר, דְּהָא עוּתְרָא אָחֳרָא יִזְדָּמַן לֵיהּ, לְמֶהֱוִי לֵיהּ חוּלָקָא בֵּיהּ, וּלְמֶהֱוִי בֵּיהּ חוּלָקָא בְּעָלְמָא דְּאָתֵי, אֲתַר דְּיַיִן וְשֶׁמֶן שַׁרְיָין בְּעָלְמָא דָּא וּבְעָלְמָא דְּאָתֵי. וּמַאן דְּרָחִים לֵיהּ לְהַאי אֲתַר, לָא בָּעֵי עוּתְרָא וְלָא רָדִיף אֲבַתְרֵיהּ. זַכָּאִין אִינּוּן צַדִּיקַיָּיא דְּמִשְׁתַּדְּלֵי בְּעוּתְרָא עִלָּאָה כָּל יוֹמָא, דִּכְתִּיב, (איוב כ״ח:י״ז) לֹא יַעֲרְכֶנָה זָהָב וּזְכוּכִית וּתְמוּרָתָהּ כְּלִי פָז. הַאי בְּהַאי עָלְמָא. לְבָתַר, (משלי ח׳:כ״א) לְהַנְחִיל אֹהֲבַי יֵשׁ וְאוֹצְרוֹתֵיהֶם אֲמַלֵּא.</p>"],[9520012047,"<p>תּוּ פָּתַח וְאָמַר, (שמות כ״ד:י״ב) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה עֲלֵה אֵלַי הָהָרָה וְגוֹ'. וְהַתּוֹרָה, דָּא תּוֹרָה שֶׁבִּכְתָּב. וְהַמִּצְוָה, דָּא תּוֹרָה שֶׁבְּעַל פֶּה. לְהֹרֹתָם כְּתִיב חָסֵר, כְּמָה דְאַתְּ אָמֵר (שיר השירים ג׳:ד׳) וְאֶל חֶדֶר הוֹרָתִי. הָכָא אִית לְאִסְתַּכְּלָא, לְהוֹרֹתָם דְּמִי, אִי תֵּימָא הוֹרֹתָם דְּיִשְׂרָאֵל, לָאו הָכֵי, דְּהָא יִשְׂרָאֵל לָא אַדְכָּרוּ בְּהַאי קְרָא. אֶלָּא הוֹרֹתָם דְּתוֹרָה וּמִצְוָה. וּמַאי הִיא. דָּא (אתר) יַיִן דְּמִנְטְרָא. בְּגִין דְּכָל כְּתִיבָה דְּסֵפֶר עִלָּאָה תַּמָּן שַׁרְיָא, וּמִתַּמָּן נָפְקָא תּוֹרָה, וְעַל דָּא קָרֵינָן תּוֹרָה שֶׁבִּכְתָּב. וְדָא הוּא אֲשֶׁר כָּתַבְתִּי לְהֹרֹתָם, לְהֹרֹתָם וַדַּאי. (כמה דאת אמר ואל חדר הורתי)</p>\n<p>תּוֹרָה שֶׁבְּעַל פֶּה, תּוֹרָה אָחֳרָא, (ויקהל ר\"א) דְּקַיְּימָא עַל פֶּה. מַאן אִיהוּ פֶּה. דָּא הוּא דַּעַת, דְּאִיהוּ פֶּה דְּסֵפֶר וּכְתִיבָה. וְתוֹרָה דָּא, הִיא תּוֹרָה אָחֳרָא, דְּאִקְרֵי תּוֹרָה שֶׁבְּעַל פֶּה, דְּאִיהִי קַיְּימָא עַל הַהוּא פֶּה דְּאִיהִי תּוֹרָה שֶׁבִּכְתָּב, בְּגִין כַּךְ אִסְתָּלִיק מֹשֶׁה בְּכֹלָּא, עַל כָּל שְׁאָר נְבִיאֵי מְהֵימְנֵי, דִּכְתִּיב וְאֶתְּנָה לְךָ, לְךָ דַּיְיקָא.</p>"],[9520012048,"<p>כְּתִיב (משלי כ״ה:ד׳-ה׳) הָגוֹ סִיגִים מִכָּסֶף וַיֵּצֵא לַצּוֹרֵף כֶּלִי הָגוֹ רָשָׁע לִפְנֵי מֶלֶךְ וְיִכּוֹן בַּחֶסֶד כִּסְאוֹ. תָּא חֲזֵי, בְּשַׁעֲתָא דְּאַסְגִּיאוּ חַיָּיבִין בְּעָלְמָא, כּוּרְסְיָיא דְּמַלְכָּא קַדִישָׁא אִתְתַּקְּנַת בְּדִינָא, לְאִסְתְּאָבָת (ס\"א ואשתאבת) (ס\"א וקיימא) בְּדִינָא, וְשַׁלְהוֹבוֹי אוֹקְדִין עָלְמָא. וּבְשַׁעֲתָא דְּאִתְעֲבָר חַיָּיבַיָא מֵעָלְמָא, כְּדֵין וְיִכּוֹן בַּחֶסֶד כִּסְאוֹ. בַּחֶסֶד, וְלָא בְּדִינָא מַאי מַשְׁמַע.</p>\n<p>מַשְׁמַע דְּעָלְמָא תַּתָּאָה תַּלְיָא בְּעָלְמָא עִלָּאָה, וְעָלְמָא עִלָּאָה לְפוּם אָרְחֵי דְּעָלְמָא תַּתָּאָה. וְיִכּוֹן בַּחֶסֶד <Nonei></i>כִּסְאוֹ. מַאן דְּבָעֵי לְבָרְכָא לֵיהּ, וּלְאַתְקְנָא כּוּרְסְיֵיהּ, בְּחֶסֶד וְלָא בְּדִינָא. מַאי מַשְׁמַע. דְּכַד עָיֵיל כַּהֲנָא לְבֵי מַקְדְּשָׁא, דְּיֵעוּל בְּחֶסֶד דְּאִיהוּ מַיָּא, וְלָא יֵיעוּל בְּיַיִן דְּשָׁתֵי דְּאִיהוּ גְּבוּרָה. יֵיעוּל (בהאי מלה) בְּמַיָּא, וְלָא יֵיעוּל בְּחַמְרָא.</p>\n<p>אָתוּ רִבִּי יְהוּדָה וְרִבִּי יִצְחָק, וְנַשְּׁקוּ רֵישֵׁיהּ, וּמֵהַהוּא יוֹמָא לָא אִתְפְּרַשׁ מִבֵּי רִבִּי יְהוּדָה, וְכַד הֲוָה עָיֵיל לְבֵי מִדְרָשָׁא, הֲוָה קָם רִבִּי יְהוּדָה קַמֵּיהּ, אָמַר מִלָּה אוֹלִיפְנָא מִנֵּיהּ, וְיָאוּת לְאַנְהָגָא בֵּיהּ יְקָר. לְבָתַר אִסְתְּלַּק בֵּין חַבְרַיָּיא, וַהֲווּ קָארָן לֵיהּ רִבִּי יֵיסָא, רֵישָׁא דְּפַטִּישָׁא דְּמַתְבָּר טִנָרִין, וְאַפִּיק שַׁלְהוֹבִין לְכָל סְטָר. וַהֲוָה קָרֵי עָלֵיהּ רִבִּי אֶלְעָזָר, (ירמיהו א׳:ה׳) בְּטֶרֶם אֶצָּרְךָ בַּבֶּטֶן יְדַעְתִּיךָ.</p>"],[9520012049,"<p>(ויקרא י״א:א׳) וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה וְאֶל אַהֲרֹן לֵאמֹר אֲלֵיהֶם זֹאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ וְגוֹ', מַאי שְׁנָא הָכָא אַהֲרֹן. אֶלָּא בְּגִין דְּאִיהוּ קַיְּימָא תָּדִיר לְאַפְרְשָׁא בֵּין מִסְאֲבָא וּבֵין דַּכְיָא. דִּכְתִּיב לְהַבְדִּיל בֵּין הַטָּמֵא וּבֵין הַטָּהוֹר.</p>\n<p>רִבִּי אַבָּא פָּתַח וְאָמַר, (תהילים ל״ד:י״ג) מִי הָאִישׁ הֶחָפֵץ חַיִּים וְגוֹ'. נְצוֹר לְשׁוֹנְךָ מֵרָע וְגוֹ'. סוּר מֵרָע וְגוֹ'. וּכְתִיב (משלי כ״א:כ״ג) שׁוֹמֵר פִּיו וּלְשׁוֹנוֹ וְגוֹ'. מִי הָאִישׁ הֶחָפֵץ חַיִּים. מַאן חַיִּים. אֶלָּא אִלֵּין חַיִּים דְּאִקְרוּן עָלְמָא דְּאָתֵי, וְחַיִּים תַּמָּן שַׁרְיָין. וְעַל דָּא תָּנֵינָן, עֵץ חַיִּים, הִיא אִילָנָא מֵאִינּוּן חַיִּים, אִילָנָא דְּאִתְנְטַע בְּאִינּוּן חַיִּין. וְעַל דָּא מִי הָאִישׁ הֶחָפֵץ חַיִּים כְּתִיב.</p>\n<p>אוֹהֵב יָמִים לִרְאוֹת טוֹב, מַאן יָמִים. אֶלָּא דָּא הוּא שְׁמָא דְּמַלְכָּא קַדִּישָׁא, דַּאֲחִידָא בְּאִינּוּן יוֹמִין עִלָּאִין, דְּאִקְרוּן יְמֵי הַשָּׁמַיִם עַל הָאָרֶץ, יְמֵי הַשָּׁמַיִם וַדַּאי, עַל הָאָרֶץ וַדַּאי. מַאן דְּבָעֵי חַיִּים דִּלְעֵילָּא, לְמֶהֱוִי לֵיהּ חוּלָקָא בְּהוּ. וּמַאן דְּבָעֵי יוֹמִין עִלָּאִין לְאִתְדַּבְּקָא בְּהוּ וּלְרַחֲמָא לְהוּ. יִנְטַר פּוּמֵיהּ מִכֹּלָּא, יִנְטַר פּוּמֵיהּ וְלִישָׁנֵיהּ, יִנְטַר פּוּמֵיהּ מִמֵּיכְלָא וּמִמִּשְׁתְּיָא, דִּמְסָאֵב לְנַפְשָׁא, וּמְרַחָקָא לְבַּר נָשׁ מֵאִינּוּן חַיִּין וּמֵאִינּוּן יוֹמִין, וְיִנְטַר (ס\"א פומיה ולישניה) לִישָׁנֵיהּ מִמִּלִּין בִּישִׁין, דְּלָא יִסְתְּאַב בְּהוּ, וְיִתְרְחַק מִנַּיְיהוּ, וְלָא יְהֵא לֵיהּ חוּלָקָא בְּהוּ.</p>\n<p>תָּא חֲזֵי, פּוּמָא וְלִישָׁן, אֲתַר (אחרא) עִלָּאָה הָכִי אִקְרֵי, וּבְגִין כָּךְ לָא יַפְגִּים אִינִישׁ פּוּמֵיהּ וְלִישָׁנֵיהּ, וְכָּל שֶׁכֵּן לְאִסְתַּאֲבָא נַפְשֵׁיהּ וְגַרְמֵיהּ, בְּגִין דְּאִסְתְּאַב הוּא בְּעָלְמָא אָחֳרָא, וְהָא אוֹקִימְנָא.</p>\n<p>(ויקרא י״א:ב׳) זֹאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ מִכָּל הַבְּהֵמָה וְגוֹ', הַאי קְרָא לָאו רֵישֵׁיהּ סֵיפֵיהּ, וְלָאו סֵיפֵיהּ רֵישֵׁיהּ. זֹאת הַחַיָּה בְּקַדְמִיתָא, וּלְבָתַר מִכָּל הַבְּהֵמָה. אֶלָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא, בְּכָל זִמְנָא דְּיִשְׂרָאֵל מְנַטְרֵי נַפְשַׁיְיהוּ, וְגַרְמַיְיהוּ, דְּלָא לְסָאֲבָא לוֹן, וַדַּאי זֹאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ, יֵהוֹן שְׁכִיחִין בִּקְדוּשָּׁה עִלָּאָה, לְאִתְדַּבְּקָא בִּשְׁמִי, בִּבְרִירוּ דְּהַהִיא בְּהֵמָה דְּבָרִירְנָא לְכוּ לְמֵיכַל, לָא תִּסְתַּאֲבוּ בְּהוּ, וְתֶהווֹן דְּבֵקִין בִּשְׁמִי.</p>\n<p>וְכָל זִמְנָא דְּלָאו אִינּוּן נַטְרִין נַפְשַׁיְיהוּ וְגַרְמַיְיהוּ מִמֵּיכְלָא וּמִשְׁתְּיָּא, יִתְדַבְּקוּן בַּאֲתַר אָחֳרָא מִסְאֲבָא, לְאִסְתַּאֲבָא בְּהוּ. וּבְגִין כַּךְ כְּתִיב, זֹאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ מִכָּל, מִכָּל ודַּאי, דְּאִיהוּ רָזָא דִּשְׁמָא קַדִּישָׁא, לְאִתְדַּבְּקָא בֵּיהּ. מִכָּל הַבְּהֵמָה אֲשֶׁר עַל הָאָרֶץ, בְּגִין דְּהַאי מֵיכְלָא דְּהַאי בְּהֵמָה אִשְׁתְּכַח דַּכְיָא, וְלָא יְסָאַב לְכוּ, יְהֵא לְכוּ חוּלָקָא בִּשְׁמִי, לְאִתְדַּבְּקָא בֵּיהּ.</p>\n<p>תּוּ, זֹאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ. בְּפַרְעֹה כְּתִיב, (שמות ו׳:ז׳) בְּזֹאת תֵּדַע כִּי אֲנִי יְיָ'. הָא זֹאת לָקֳבְלָךְ, לְאִתְפָּרְעָא מִנָךְ. אוּף הָכָא זֹאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ מִכָּל הַבְּהֵמָה, הָא זֹאת לָקֳבְלֵיכוֹן, לְאִתְפָּרְעָא מִנַּיְיכוּ, אִי תְּסָאֲבוּן נַפְשֵׁכוֹן. מַאי טַעֲמָא. בְּגִין דְּנַפְשָׁתָא מִנָּהּ הֲווֹ, וְאִי אַתּוּן תְּסָאֲבוּן לְהַהוּא דִּילָהּ, הָא זֹאת לָקֳבְלַיְיכוּ, אִי לְטָב הִיא קַיְּימָא לְגַבַּיְיכוּ, אִי לְבִישׁ הִיא קַיְּימָא לְגַבַּיְיכוּ.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, זֹאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ מִכָּל הַבְּהֵמָה, מִכָּל אִינּוּן דַּאֲחִידָן מִן סְטָר דָּא, שָׁארֵי לְכוּ לְמֵיכַל, וְכָל אִינּוּן דְּלָא אַתְיָין <Nonei></i>מִסִּטְרָא דָּא, אָסִיר לְכוּ לְמֵיכַל. בְּגִין דְּאִית בְּעִירָן דְּאַתְיָין מִסִּטְרָא דָּא, וְאִית דְּאַתְיָין מִסִּטְרָא אָחֳרָא מִסְאֲבָא. וְסִימָנָא דִּלְהוֹן דִּכְתִּיב, כֹּל מַפְרֶסֶת פַּרְסָה. וְגַמְרִינָן כֻּלְּהוּ רְשִׁימָן, וְכֻלְּהוּ אַרְשִׁים לְהוּ קְרָא. וּבְגִין כַּךְ, כָּל מַאן דְּאָכִיל מֵאִינּוּן דְּאַתְיָין מִסִּטְרָא דָּא מִסְאֲבָא, אִסְתְּאַב בְּהוּ, וְסָאִיב לְנַפְשֵׁיהּ דְּאַתְיָא מִסִּטְרָא דַּכְיָא.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר כְּלַל כֹּלָּא, כְּמָה דְּאִית עֶשֶׂר כִּתְרִין דִּמְהֵימְנוּתָא לְעֵילָּא. כַּךְ אִית עֶשֶׂר כִּתְרֵי דְּחָרָשֵׁי מֵסָאֲבֵי לְתַתָּא. וְכָל מַה דִּי בְּאַרְעָא, מִנַּיְיהוּ אֲחִידָן בְּסִטְרָא דָּא, וּמִנַּיְיהוּ אֲחִידָן בְּסִטְרָא אָחֳרָא.</p>\n<p>וְאִי תֵּימָא, הַאי עֵז, דְּשַׁרְיָא עָלֵיהּ רוּחַ מִסְאֲבָא. לָאו הָכֵי. דְּאִי רוּחַ מִסְאֲבָא שַׁרְיָא בֵּיהּ, אָסִיר לָן לְמֵיכַל. אֶלָּא אַעְבְּרָן בְּגַוַויְיהוּ, וְיִתְחֲזוּן לָקֳבְלֵיהוֹן, וְלָא שַׁרְיָא לְדַיְּירָא בְּהוּ, דְּכַד אִינּוּן שַׁרְיָין, רוּחַ אָחֳרָא אַעְבָּר עָלַיְיהוּ, וּפְרִישָׁן מִגַּרְמַיְיהוּ. וּבְגִין כַּךְ אִתְחָזוּן לָקֳבְלַיְיהוּ, וּמְקַטְרְגֵי בְּגַוַויְיהוּ, וְלָא שַׁלְטֵי בְּהוּ בְּגַרְמַיְיהוּ, וְעַל דָּא שָׁרִי לָן לְמֵיכַל.</p>\n<p>תָּא חֲזֵי, כֵּיוָן דְּאַתְיָין לְשַׁלְּטָאָה בְּהוּ, אַעֲבַר רוּחָא חֲדָא, זַקְפָן עַיְינִין וְחָמָאן רְשִׁימִין דִּלְהוֹן, וְאִתְפָּרְשָׁן מִנַּיְיהוּ, אֲבָל אִתְחֲזוֹ לָקֳבְלֵיהוֹן, וְלָא אֲסִירֵי לָן לְמֵיכַל.</p>\n<p>בֵּין בִּבְעִירֵי, בֵּין בְּחֵיוָותָא, בֵּין בְּעוֹפֵי, בֵּין בְּנוּנֵי יַמָּא, בְּכֻלְּהוּ אִתְחָזוּן יְמִינָא וּשְׂמָאלָא (רחמי ודינא), וְכָל מַאן דְּאָתֵי מִסִּטְרָא דִּימִינָא, (מסטרא דרחמי) שָׁארֵי לָן לְמֵיכַל. וְכָל אִינּוּן דְּאַתְיָין מִסִּטְרָא דִּשְׂמָאלָא (מסטרא דדינא), כֻּלְּהוּ אָסִיר לָן לְמֵיכַל. בְּגִין דְּדַרְגָּא (ס\"א דגרמא) דְּכֻלְּהוּ מִסְאֲבָא, וְכֻלְּהוּ מִסְאֲבִין, וְרוּחַ מִסְאֲבָא שַׁרְיָא בְּגַוַויְיהוּ, וְדָרֵי בְּהוּ. וְעַל דָּא רוּחָא קַדִּישָׁא דְּיִשְׂרָאֵל, לָא יִתְעָרַב בְּהוּ, וְלָא יִסְתְּאָב בְּהוּ, בְּגִין דְּיִשְׁתַּכְּחוּן קַדִּישִׁין, וְיִשְׁתְּמוֹדְעוּן לְעֵילָּא וְתַתָּא. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּמַלְכָּא קַדִּישָׁא אִתְרְעֵי בְּהוּ, וּבָעֵי לְדַכְּאָה לְהוּ, וּלְקַדְּשָׁא לְהוּ עַל כֹּלָּא, בְּגִין דַּאֲחִידָן בֵּיהּ.</p>\n<p>תָּא חֲזֵי, כְּתִיב (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר, אִי קוּדְשָׁא בְּרִיךְ הוּא מִתְפָּאַר בְּהוּ בְּיִשְׂרָאֵל, הֵיךְ אַתְיָין לְאִסְתַּאֲבָא וּלְאִתְדַּבְּקָא בְּסִטְרָא מִסְאֲבָא. וְעַל דָּא כְּתִיב, וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים כִּי קָדוֹשׁ אָנִי וְלֹא תְשַׁקְּצוּ אֶת נַפְשׁוֹתֵיכֶם וְגוֹ', מַאן דְּאִיהוּ בְּדִיּוּקְנָא דְּמַלְכָּא, לָא לִבְעֵי לֵיהּ לְאַפְרְשָׁא מֵאוֹרְחוֹי דְּמַלְכָּא. וּבְגִין כַּךְ רָשִׁים לְהוּ קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, כָּל אִינּוּן דְּאַתְיָין מִסִּטְרָא דָּא, וְכָל אִינּוּן דְּאַתְיָין מִסִּטְרָא אָחֳרָא. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דִּכְתִּיב בְּהוּ, (ישעיהו ס״א:ט׳) כָּל רוֹאֵיהֶם יַכִּירוּם (נח ע\"א, פ') כִּי הֵם זֶרַע בֵּרַךְ יְיָ', בֵּרַךְ יְיָ' מַמָּשׁ, בֵּרַךְ יְיָ' בְּכֹלָּא.</p>"],[9520012050,"<p>וְתָּא חֲזֵי, כָּל מַאן דְּאָכִיל מֵאִינּוּן מַאֲכָלֵי דַּאֲסִירֵי, אִתְדְּבַק בְּסִטְרָא אָחֳרָא, וְגָעִיל נַפְשֵׁיהּ וְגַרְמֵיהּ, וְרוּחַ מְסָאָב שַׁרְיָא עָלֵיהּ, וְאַחְזֵי גַּרְמֵיהּ דְּלֵית לֵיהּ חוּלָקָא בֶּאֱלָהָא עִלָּאָה, וְלָא אָתֵי מִסִּטְרֵיהּ, וְלָא אִתְדְּבַק בֵּיהּ. וְאִי יִפּוּק הָכִי מֵהַאי עָלְמָא, אֲחִידָן בֵּיהּ כָּל אִינּוּן דַּאֲחִידָן בִּסְטָר (ס\"א דאתיין מסטר) דִּמְסָאֲבָא, וּמְסָאֲבִין לֵיהּ וְדַיְינִין לֵיהּ כְּבַּר נָשׁ דְּאִיהוּ גַּעֲלָא דְּמָארֵיהּ, גַּעֲלָא בְּהַאי עָלְמָא, וְגַעֲלָא בְּעָלְמָא דְּאָתֵי.</p>\n<p>וְעַל דָּא כְּתִיב, וְנִטְמֵתֶם בָּם בְּלָא א', דְּלָא אִשְׁתְּכַח אַסוּותָא לְגִעוּלֵיהּ, וְלָא נָפִיק מִמְּסָאֲבוּתֵיהּ לְעָלְמִין. וַוי לוֹן, וַוי לְנַפְשַׁיְיהוּ, דְּלָא יִתְדַבְּקוּן בִּצְרוֹרָא דְּחַיֵּי לְעָלְמִין, דְּהָא אִסְתְּאָבוּ. וַוי לְגַרְמַיְיהוּ, עָלַיְיהוּ כְּתִיב (ישעיהו ס״ו:כ״ד) כִּי תוֹלַעְתָּם לֹא תָמוּת וְגוֹ', וְהָיוּ דֵרָאוֹן לְכָל בָּשָׂר. מַאי דֵּרָאוֹן. סִרְחוֹנָא. מַאן גָּרִים לֵיהּ, הַהוּא סְטָר דְּאִתְדַּבָּק בֵּיהּ.</p>\n<p>יִשְׂרָאֵל אַתְיָין מִסִּטְרָא דִּימִינָא, אִי אִתְדַּבְּקָן בִּסְטָר שְׂמָאלָא, הָא פַּגְמִין לִסְטַר דָּא, וּפַגְמִין לְגַרְמַיְיהוּ, וּפַגְמִין לְנַפְשַׁיְיהוּ, פְּגִימִין בְּעָלְמָא דֵּין, וּפְגִימִין, בְּעָלְמָא דְּאָתֵי. כָּל שֶׁכֵּן מַאן דְּאִתְדַּבָּק בִּסְטָר דִּמְסָאֲבָא, דְּכֹלָּא אָחִיד דָּא בְּדָא, וּכְתִיב (דברים י״ד:ב׳) כִּי עַם קָדוֹשׁ אַתָּה לַיְיָ' אֱלֹהֶיךָ וְגוֹ'.</p>\n<p>רִבִּי יוֹסֵי פָּתַח וְאָמַר, (קהלת ו׳:ז׳) כָּל עֲמַל הָאָדָם לְפִיהוּ וְגוֹ'. אִסְתַּכַּלְנָא בְּמִלֵּי דִּשְׁלֹמֹה מַלְכָּא, וְכֻלְּהוּ אֲחִידָן בְּחָכְמָה עִלָּאָה. כָּל עֲמַל הָאָדָם לְפִיהוּ, הַאי קְרָא, בְּשַׁעֲתָא דְּדַיְינִין לֵיהּ <Nonei></i>לְבַּר נָשׁ בְּהַהוּא עָלְמָא כְּתִיב, כָּל הַהוּא דִּינָא, וְכָל מַאי דְּסָבִיל בְּהַהוּא עָלְמָא, וְנָקְמִין מִנֵּיהּ נִקְמָתָא דְּעָלְמָא. לְפִיהוּ: בְּגִין פִּיהוּ, דְּלָא נָטִיר לֵיהּ, וְסָאִיב לֵיהּ לְנַפְשֵׁיהּ, וְלָא אִתְדְּבַק בְּסִטְרָא דְּחַיֵּי, בְּסִטְרָא דִּימִינָא. וְגַם הַנֶפֶשׁ לֹא תִמָלֵא, לָא תִּשְׁתְּלִים דִּינָהָא לְעָלַם וּלְעָלְמֵי עָלְמִין. דָּבָר אַחֵר לֹא תִמָלֵא, לָא תִּשְׁתְּלִים לְסַלְּקָא לְאַתְרָהָא לְעָלְמִין, בְּגִין דְּהָא אִסְתְּאָבַת, וְאִתְדַּבְּקַת בְּסִטְרָא אָחֳרָא.</p>\n<p>רִבִּי יִצְחָק אָמַר, כָּל מַאן דְּאִסְתְּאָב בְּהוּ, כְּאִילּוּ פָּלַח לְעֲבוֹדָה זָרָה, דְּאִיהוּ (דברים יז) תּוֹעֲבַת יְיָ', וּכְתִיב לֹא תֹאכַל כָּל תּוֹעֵבָה. מַאן דְּפָלַח לְעֲבוֹדָה זָרָה, נָפִיק מִסִּטְרָא דְּחַיֵּי, נָפִיק מֵרְשׁוּתָא קַדִּישָׁא, וְעָיִיל בִּרְשׁוּתָא אָחֳרָא. אוּף מַאן דְּאִסְתְּאָב בְּהָנֵי מֵיכְלֵי, נָפִיק מִסִּטְרָא דְּחַיֵּי, וְנָפִיק מֵרְשׁוּ קַדִּישָׁא, וְעָיִיל בִּרְשׁוּתָא אָחֳרָא. וְלֹא עוֹד, אֶלָּא דְּאִסְתְּאָב בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי. וְעַל דָּא וְנִטְמֵתֶם בָּם כְּתִיב בְּלָא א'.</p>\n<p>וּכְתִיב, וְלֹא תְשַׁקְּצוּ אֶת נַפְשׁוֹתֵיכֶם בַּבְּהֵמָה וּבָעוֹף וּבְכָל אֲשֶׁר תִּרְמוֹשׂ הָאֲדָמָה אֲשֶׁר הִבְדַּלְתִּי אֶתְכֶם לְטַמֵּא. מַאי לְטַמֵּא. לְטַמֵּא לְעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, דְּהָא אִינּוּן מִסְאֲבִין, וּמִסִּטְרָא דִּמְסָאֲבָא קָא אַתְיָין. וְכָל חַד אִתְדַּבָּק בְּאַתְרֵיהּ.</p>\n<p>רִבִּי אֶלְעָזָר הֲוָה יָתִיב קָמֵי דְּרִבִּי שִׁמְעוֹן אֲבוֹי, אָמַר לֵיהּ, הָא דְּתָנֵינָן זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְדַכָּאָה לְהוּ לְיִשְׂרָאֵל, בְּמָּה. אָמַר לֵיהּ, בְּמָּה דִּכְתִּיב, (יחזקאל ל״ו:כ״ה) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם וְגוֹ'. כֵּיוָן דְּאִתְדַכְּאָן מִתְקַדְּשָׁן, וְיִשְׂרָאֵל דְּאִתְדַּבְּקָן בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, קֹדֶשׁ אִקְרוּן, דִּכְתִּיב, (ירמיהו ב׳:ג׳) קֹדֶשׁ יִשְׂרָאֵל לַיְיָ' רֵאשִׁית תְּבוּאָתֹה, וּכְתִיב (שמות כ״ב:ל׳) וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא קָאָמַר עָלַיְיהוּ, וִהְיִיתֶם קְדוֹשִׁים כִּי קָדוֹשׁ אָנִי יְיָ', בְּגִין דִּכְתִּיב (דברים י') וּבוֹ תִדְבָּק, וּכְתִיב (תהילים קמ״ז:כ׳) לֹא עָשָׂה כֵן לְכָל גּוֹי וּמִשְׁפָּטִים בַּל יְדָעוּם הַלְלוּיָהּ.</p>"],[9520012051,"<p><Noneb>רעיא מהימנא</b> (נדפס תצא רע\"ח ע\"ב) דָּגִים וַחֲגָבִים, אֵינָן טְעוּנִין שְׁחִיטָה, אֶלָּא אֲסִיפָתָם הִיא הַמַתֶּרֶת אוֹתָם. הָכִי מָארֵי מְתִיבְתָּא, אֵין צְּרִיכִין שְׁחִיטָה, אֶלָּא דְּאִתְּמַר בְּהוֹן, (בראשית מ״ט:ל״ג) וַיִּגְוַע וַיִּאָסֶף אֶל עַמָּיו. מַה נוּנֵי יַמָּא, חִיוּתָן בְּיַמָּא. אַף תַּלְמִידֵי (תיקון נ\"ו) חֲכָמִים, מָארֵי מַתְנִיתִין, חִיּוּתַיְיהוּ בְּאוֹרַיְיתָא, וְאִי אִתְפָּרְשָׁן מִנָּהּ, מִיַּד מֵתִים. (נ\"א תנאין) תָנֵינָן דְּמַתְנִיתִין, דְּבָהּ אִתְרַבּוּ כְּנוּנֵי יַמָּא, וְאִי אִינּוּן דִּבְיַבֶּשְׁתָּא יַעֲלוּן לְמַיָּא, וְלָא יַדְעִין לְשַׁטְטָא, אִינּוּן מַיְיתִין. אֲבָל אָדָם (דאינון מארי קבלה אינון לעילא), דְּאִיהוּ לְעֵילָּא מִכֻּלְּהוּ, אִתְּמַר בֵּיהּ (בראשית א׳:כ״ו) וְיִרְדּוּ בִדְגַּת הַיָּם וּבְעוֹף הַשָּׁמַיִם.</p>\n<p>דְּאִינּוּן מָארֵי מַתְנִיתִין תַּנִינַיָּא, הַתַּנִּין הַגָּדוֹל, (ישעיהו כ״ז:א׳) נָחָשׁ בָּרִיחַ, לָקֳבֵל (שמות כ״ו:כ״ח) וְהַבְּרִיחַ הַתִּיכוֹן בְּתוֹךְ הַקְּרָשִׁים, בְּזִמְנָא דְּתַנִּינָן מָארֵי מִשְׁנָה אִית בְּהוֹן מַחֲלוֹקֶת, וּמַקְשִׁין דָּא לְדָא, בָּלַע לְחַבְרֵיהּ. וְהַאי אִיהוּ תַּלְמִיד זְעֵיר שֶׁלֹּא הִגִּיעַ לְהוֹרָאָה וּמוֹרֶה, חַיָּיב מִיתָה. וְאִי אִינּוּן שָׁוִין דָּא לְדָא, וְאִית בְּהוֹן מַחֲלוֹקֶת, וְקוּשְׁיָא, אִתְּמַר בְּהוֹן (ס\"א לבסוף) (במדבר כ״א:י״ד) אֶת וָהֵב בְּסוּפָה, אוֹקְמוּהָ אַהֲבָה בְּסוּפָה. (ע\"כ רע\"מ).</p>"],[9520012052,"<p>(ויקרא י״ב:ב׳) וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה לֵאמֹר אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר וְגוֹ'. רִבִּי אֶלְעָזָר פָּתַח, (שיר השירים ג׳:א׳) עַל מִשְׁכָּבִי בַּלֵּילוֹת בִּקַּשְׁתִּי וְגוֹ'. עַל מִשְׁכָּבִי, בְּמִשְׁכָּבִי מִבָּעֵי לֵיהּ, מַהוּ עַל מִשְׁכָּבִי. אֶלָּא כְּנֶסֶת יִשְׂרָאֵל אָמְרָה קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וּבָעָאת מִנֵּיהּ עַל גָּלוּתָא, בְּגִין דְּהִיא יָתְבָא בֵּין שְׁאָר עַמִּין עִם בְּנָהָא, וּשְׁכִיבַת לְעַפְרָא, וְעַל דְּהִיא שְׁכִיבַת בְּאַרְעָא אָחֳרָא מִסְאֲבָא, אָמְרָה, עַל מִשְׁכָּבִי בָּעֵינָא, דְּכָאִיבְנָא (נ\"א דשכיבנא) בְּגָלוּתָא, וְעַל דָּא, בִּקַּשְׁתִּי אֵת שֶׁאָהֲבָה נַפְשִׁי וּלְאַפָּקָא לִי מִנֵּיהּ.</p>\n<p>בִּקַּשְׁתִּיו וְלֹא מְצָאתִיו, דְּלָאו אָרְחֵיהּ לְאִזְדַּוְּוגָא <Nonei></i>בִּי אֶלָּא בְּהֵיכָלֵיהּ, קְרָאתִיו וְלֹא עָנָנִי. דְּהָא בֵּינִי עַמִּין אָחֳרָנִין יָתִיבְנָא, וְקָלֵיהּ לָא שַׁמְעִין אֶלָּא בְּנוֹי. דִּכְתִּיב, (דברים ד׳:ל״ג) הֲשָׁמַע עָם קוֹל אֱלֹהִים וְגוֹ'.</p>\n<p>רִבִּי יִצְחָק אָמַר, עַל מִשְׁכָּבִי בַּלֵּילוֹת. אָמְרָה כְנֶסֶת יִשְׂרָאֵל עַל מִשְׁכָּבִי אִתְרָעַמְנָא קַמֵּיהּ, דִּיְהֵא מִזְדְּוַּוג עַמִּי לְמֶחְדֵּי לִי, וּלְבָרְכָא לִי, בְּחֵידוּ שְׁלִים. דְּהָכִי תָּנֵינָן דְּמִזִוּוּגָא דְּמַלְכָּא בִּכְּנֶסֶת יִשְׂרָאֵל, כַּמָּה צַדִּיקִים יַרְתּוּ יְרוּתַת אַחֲסַנְתָּא קַדִּישָׁא, וְכַמָּה בִּרְכָאן מִשְׁתַּכְּחֵי בְּעָלְמָא.</p>"],[9520012053,"<p>רִבִּי אַבָּא הֲוָה אָזִיל לִכְפָר קַנְיָּא, (ס\"א בפרקמטיא) לִמְעַרְתָּא דְלוּד. וַהֲווּ עִמֵּיהּ רִבִּי יוֹסֵי וְרִבִּי חִיָּיא. אָמַר רִבִּי יוֹסֵי, כְּתִיב, (משלי י״ב:ד׳) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ וְגוֹ'. אֵשֶׁת חַיִל, דָּא כְּנֶסֶת יִשְׂרָאֵל. וּכְרָקָב בְּעַצְמוֹתָיו מְבִישָׁה. אִלֵּין (נ\"א דא מהימנותא דשאר) עַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, דְּקוּדְשָׁא בְּרִיךְ הוּא לָא יָכִיל לְמִסְבַּל לוֹן בְּעָלְמָא, כְּמָה דְאַתְּ אָמֵר, (ויקרא כ׳:כ״ג) וָאָקוּץ בָּם. כְּהָנֵי קוֹצִין וְגוּבִין דְּדַחֲקִין לֵיהּ לְבַּר נָשׁ וְלָא יָכִיל לְמִסְבַּל לוֹן. אָמַר רִבִּי אַבָּא, הָכִי הוּא וַדַּאי, אֵשֶׁת חַיִל, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּהִיא גְּבִירְתָּא מִכַּמָּה חַיָּילִין וְכַמָּה מַשִּׁרְיָין דְּמִשְׁתַּכְּחֵי בְּעָלְמָא, עֲטֶרֶת בַּעְלָהּ, כְּמָה דְאַתְּ אָמֵר, עֲטֶרֶת תִּפְאֶרֶת, וְכֹלָּא חַד. (ל\"ג וכו' אשת חיל דא כנסת ישראל דהא בזווגא דמלכא אפיקת כמה חיילין כמה משיריין כמה צדיקים בעלמא וכלהו אקרון בנים לקודשא בריך הוא ולכנסת ישראל כמה דכתיב (דברים י״ד:א׳) בנים אתם ליי' אלהיכם.) עַד דַּהֲווֹ אָזְלֵי, אָמַר רִבִּי אַבָּא כָּל חַד לֵימָא מִלָּה, בִּכְּנֶסֶת יִשְׂרָאֵל.</p>\n<p>רִבִּי אַבָּא פָּתַח וְאָמַר. (משלי ל״א:י׳) אֵשֶׁת חַיִל מִי יִמְצָא, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי אֵשֶׁת חַיִל, כְּמָה דְּאַמָרָן. מִי יִמְצָא, כְּמָה דְאַתְּ אָמֵר, אֲשֶׁר יִמְצָא אֶתְכֶם בְּאַחֲרִית הַיָּמִים. (ל\"ג מי ימצא לאגחא ביה קרבא) מִי יִמְצָא, מַאן יִזְכֶּה לְמֶהֱוִי בֵּהּ בִּשְׁלִימוּ, וּלְאִשְׁתַּכְּחָא עִמָּהּ תָּדִיר.</p>\n<p>וְרָחוֹק מִפְּנִינִים מִכְרָהּ, מִכְרָהּ, מִקְחָהּ מִבָּעֵי לֵיהּ. אֶלָּא, לְכָל אִינּוּן דְּלָא אִתְדַּבְּקָן בָּהּ בִּשְׁלִימוּ, וְלָא שְׁלֵמִין בַּהֲדָהּ, הִיא מָכְרָה לוֹן וְאַסְגְּרָא לוֹן בִּידָא דְּעַמָמִין אָחֳרָנִין. כְּמָה דְאַתְּ אָמֵר, (שמואל א י״ב:ט׳) וַיַּעַזְבוּ בְּנֵי יִשְׂרָאֵל אֶת יְיָ' וַיִמְכּוֹר אוֹתָם בְּיַד סִיסְרָא. וּכְדֵין כֻּלְּהוּ רְחִיקִין מֵאִלֵּין פְּנִינִים עִלָּאִין קַדִּישִׁין, דְּלָא יְהֵא חוּלָקָא בְּהוּ. הֲדָא הוּא דִכְתִיב וְרָחוֹק מִפְּנִינִים מִכְרָהּ.</p>\n<p>רִבִּי חִיָּיא פָּתַח קְרָא אֲבַתְרֵיהּ וְאָמַר, בָּטַח בָּהּ לֵב בַּעְלָהּ וְשָׁלָל לֹא יֶחְסָר. בָּטַח בָּהּ לֵב בַּעְלָהּ, דָּא קוּדְשָׁא בְּרִיךְ הוּא, דִּבְגִינֵי כַּךְ מָנֵי לֵהּ עַל עָלְמָא, לְאִתְדַבְּרָא עָלָהּ, כָּל זִיּוּנִין דִּלֵיהּ אַפְקִיד בִּידָהָא, וְכָל אִינּוּן מַגִּיחֵי קְרָבָא, וְעַל דָּא, וְשָׁלָל לֹא יֶחְסָר.</p>\n<p>רִבִּי יוֹסֵי פָּתַח קְרָא אֲבַתְרֵיהּ, וְאָמַר, גְּמָלַתְהוּ טוֹב וְלֹא רָע כָּל יְמֵי חַיֶּיהָ. גְּמָלַתְהוּ טוֹב, הִיא זְמִינַת טָב לְעָלְמָא, זְמִינַת טָב לְהֵיכָלָא דְּמַלְכָּא וְלִבְנֵי הֵיכָלֵיהּ. וְלֹא רָע. בְּגִין דִּכְתִּיב, (בראשית ב׳:ט׳) וְעֵץ הַדַּעַת טוֹב וָרָע, טּוֹב אֵימָתַי, בְּזִמְנָא דְּאִינּוּן יְמֵי הַשָּׁמַיִם, נָהֲרִין עָלָה, וּמִזְדַּוְּוגַן עִמָּהּ כְּדְקָא יֵאוֹת, דְּאִינּוּן יְמֵי חַיֶּיהָ. בְּגִין דְּעֵץ הַחַיִּים, שָׁדַר לָהּ חַיִּים, וְנָהִיר לָהּ. וּבְהַהוּא זִמְנָא גְּמָלַתְהוּ טוֹב וְלָא רָע. אָמַר רִבִּי אַבָּא שַׁפִּיר הוּא, וְכֻלְּהוּ קְרָאֵי בִּכְנֶסֶת יִשְׂרָאֵל אִתְּמָרוּ.</p>"],[9520012054,"<p>(ויקרא י״ב:ב׳) אִשָּׁה כִּי תַזְרִיעַ. תָּנֵינָן, אִשָּׁה מַזְרַעַת תְּחִלָּה יוֹלֶדֶת זָכָר. רִבִּי אֲחָא אָמַר, הָא תָּנֵינָן, דְּקוּדְשָׁא בְּרִיךְ הוּא גָּזַר עַל הַהִיא טִפָּה, אִי אִיהוּ דְּכַר אִי אִיהִי נוּקְבָּא, וְאַתְּ אַמְרַת אִשָׁה מַזְרַעַת תְּחִלָּה יוֹלֶדֶת זָכָר. אָמַר רִבִּי יוֹסֵי, וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא אַבְחִין בֵּין טִפָּה דִּדְכוּרָא וּבֵין טִפָּה דְּנוּקְבָּא, וּבְגִין דְּאַבְחִין לֵיהּ, גָּזַר עָלֵיהּ, אִי לִהֱוִי דְּכַר אוֹ נוּקְבָּא.</p>\n<p>אָמַר רִבִּי אֲחָא, וְיָלְדָה זָכָר, וְכִי כֵּיוָן דְּמַזְרַעַת יוֹלֶדֶת, דִּכְתִּיב, וְיָלְדָה (אלא), הַאי קְרָא הָכִי מִבָּעֵי לֵיהּ, אִשָׁה כִּי תַּהַר וְיָלְדָה זָכָר. (ס\"א תזריע ויהיה זכר) מַהוּ, כִּי תַזְרִיעַ וְיָלְדָה. אָמַר רִבִּי יוֹסֵי, אִתְּתָא, מִן יוֹמָא דְּאִתְעַבְּרַת עַד יוֹמָא דְּיוֹלִדַת לֵית לָהּ בְּפוּמָא, אֶלָּא יְלִידוּ דִּילָהּ אִי לִהֱוִי דְּכַר, וְעַל דָּא, אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר.</p>\n<p>אִשָּׁה כִּי תַזְרִיעַ. רִבִּי חִזְקִיָּה פָּתַח, (תהילים ק״ד:כ״ד) מַה רַבּוּ מַעֲשֶׂיךָ יְיָ'. כַּמָה סַגִּיאִין עוֹבָדוֹהִי דְּמַלְכָּא קַדִּישָׁא בְּעָלְמָא, מְתַל לְבַּר נָשׁ דְּנָטִיל בִּידוֹהִי כַּמָה <Nonei></i>מַקְטוּרִין כַּחֲדָא, וְזָרַע לוֹן בְּזִמְנָא חֲדָא, וּלְבָתַר נָפִיק כָּל חַד וְחַד בִּלְחוֹדוֹי. כַּךְ קוּדְשָׁא בְּרִיךְ הוּא עֲבִיד עוֹבָדוֹהִי בְּחָכְמָה, וּבְחָכְמָה נָטִיל כֹּלָּא כַּחֲדָא וְזָרַע לוֹן, וּלְבָתַר נָפְקוּ כָּל חַד וְחַד בְּזִמְנֵיהּ, הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ד) כֻּלָּם בְּחָכְמָה עָשִׂיתָ.</p>"],[9520012055,"<p>אָמַר רִבִּי אַבָּא, מָה רַבּוּ מַעֲשֶׂיךָ יְיָ', כַּמָה סַגִּיאִין אִינּוּן עוֹבָדוֹהִי דְּמַלְכָּא קַדִּישָׁא, וְכֻלְּהוּ, סְתִימִין בְּחָכְמָה, הֲדָא הוּא דִכְתִיב כֻּלָּם בְּחָכְמָה עָשִׂיתָ. כֻּלְּהוּ בְּחָכְמָה כְּלִילָן, וְלָא נָפְקֵי לְבַר אֶלָּא בִּשְׁבִילִין יְדִיעָן, לְגַבֵּי בִּינָה. וּמִתַּמָּן, אִתְעָבִידוּ כֹּלָּא וְאִתְתְּקָנוּ, הֲדָא הוּא דִכְתִיב, (משלי כ״ד:ג׳) וּבִתְבוּנָה יִתְכּוֹנָן. וְעַל דָּא כֻּלָּם בְּחָכְמָה עָשִׂיתָ, בְּבִינָה.</p>\n<p>מָלְאָה הָאָרֶץ, הָאָרֶץ: דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּמִתַּמָּן אִתְמַלְּיָא מִכֹּלָּא, כְּמָה דְאַתְּ אָמֵר (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְגוֹ'. קִנְיָנֶיךָ. דְּהִיא אַפִּיקַת לוֹן לְבָתַר, הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. בְּגִינֵי כַּךְ מָלְאָה הָאָרֶץ קִנְיָנֶיךָ.</p>"],[9520012056,"<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּבַר נָשׁ אָתֵי לְאִתְקַדְשָׁא לְאִזְדַוְּוגָא בְּנוּקְבֵיהּ, (בכוונה) בִּרְעוּתָא קַדִּישָׁא דִּילֵיהּ, אִתְּעַר עָלֵיהּ רוּחָא (אחרא) קַדִּישָׁא, כָּלִיל דְּכַר וְנוּקְבָּא. וְרָמִיז קוּדְשָׁא בְּרִיךְ הוּא לְחַד שְׁלוּחָא מְמָנָא עַל עִדּוּיֵיהוֹן דִּבְנֵי נָשָׁא, וּמָנֵי בִּידֵיהּ הַהוּא רוּחָא, וְאוֹדַע לֵיהּ, לְאָן אֲתַר יִפְקוֹד לֵיהּ. הֲדָא הוּא דִּכְתִּיב, (איוב ג׳:ג׳) וְהַלַּיְלָה אָמַר הוֹרָה גָּבֶר. הַלַּיְלָה אָמַר, לְהַהוּא מְמָנָא, הוֹרָה גָּבֶר מִפְּלַנְיָא, וְקוּדְשָׁא בְּרִיךְ הוּא אַפְקִיד לֵיהּ, לְהַהוּא רוּחָא, כָּל מַה דְּאַפְקִיד, וְהָא אוּקְמוּהָ.</p>\n<p>כְּדֵין רוּחָא נַחְתָּא, וְחַד צוּלְמָא עִמֵּיהּ, (ק\"ד ע\"ב) הַהוּא דְּקָאִים בְּדִיוּקְנֵיהּ לְעֵילָּא, בְּהַהוּא צוּלְמָא אִתְבְּרֵי (ס\"א אתרבי), בְּהַהוּא צוּלְמָא אָזִיל בְּהַאי עָלְמָא. הֲדָא הוּא דִּכְתִּיב, (תהילים ל״ט:ז׳) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. בְּעוֹד דְּהַאי צוּלְמָא אִשְׁתְּכַח (ויחי ר\"כ ע\"א) עִמֵּיהּ דְּבַּר נָשׁ, (בצולמא דיליה) קָאִים בְּהַאי עָלְמָא, דְמִתְחֲבְּרָאן כַּחֲדָא (ס\"א אשתכח עמיה בר נש קאים בהאי עלמא ותרין אינון דמתחברן כחדא), וּשְׁלֹמֹה מַלְכָּא אַזְהַר לִבְנֵי נָשָׁא וְאָמַר, (שיר השירים ב׳:י״ז) עַד שֶׁיָּפוּחַ הַיּוֹם וְנָסוּ הַצְּלָלִים, תְּרֵי.</p>\n<p>וּבְסִפְרָא דְּחָרָשִׁין דְּאַשְׁמְדַאי, אַשְׁכַּחְנָא דְּאִינּוּן דְּיַדְעֵי (ס\"א דבעו) לְחַרְשָׁא חָרָשִׁין מִסְטַר שְׂמָאלָא, וּלְאִתְדַּבְּקָא בְּהוּ, יְקוּם לִנְהוֹרָא דִּשְׁרָגָא, אוֹ בַּאֲתַר דְּיִתְחֲזוּן אִינּוּן צוּלְמִין דִּילֵיהּ, וְיֵימָא אִינּוּן מִלִּין דְּמִתַתְּקְנֵי לְאִינּוּן חָרָשִׁין, וְיִקְרֵי לוֹן, לְאִינּוּן סִטְרִין מִסְאֲבִין, בִּשְׁמָהָן מִסְאֲבִין דִּילְהוֹן, וְיַזְמִּין (ויומי) צוּלְמִין דִּילֵיהּ לְאִינּוּן דְּקָארֵי, וְיֵימָא דְּהוּא אִתְתָּקַּן בִּרְעוּתֵיהּ לְהוּ לְפִקּוּדַיְיהוּ, וְהַהוּא בַּר נָשׁ נָפַק מֵרְשׁוּ דְּמָארֵיהּ וּפִקְדוֹנָא דִּילֵיהּ, יָהַב לִסְטַר מִסְאֲבָא.</p>\n<p>וּבְאִינּוּן מִלִּין דְּחָרָשִׁין דְּאִיהוּ יֵימָא, וְיַזְמִין (נ\"א ויומי) לוֹן לְצוּלְמֵי, אִתְחָזוּן תְּרֵין רוּחִין וּמִתְתַּקְּנִין בְּאִינּוּן צוּלְמִין דִּילֵיהּ, בְּחֵיזוּ דִּבְנֵי אֱנָשָׁא, וּמוֹדְעִין לֵיהּ מִלִּין לְאַבְאָשָׁא, וּמִלִּין לְאוֹטָבָא, לְזִמְנִין יְדִיעָן. וְאִלֵּין תְּרֵי רוּחִין, דְּלָא אִתְכְּלִילוּ בִּכְלָלָא דְּגוּפָא, הַשְׁתָּא אִתְכְּלִילָן בְּאִלֵּין צוּלְמִין, וּמִתְתַּקְּנָן בְּהוּ וּמוֹדְעִין לֵיהּ לְבַר נָשׁ מִלִּין לְאַבְאָשָׁא, וְדָא הוּא דְּנָפִיק מֵרְשׁוּתָא דְּמָארֵיהּ, וּפִקְדוֹנָא דִּילֵיהּ, יָהִיב לִסְטַר מִסְאֲבָא.</p>\n<p>תָּא חֲזֵי, אָסִיר לֵיהּ לְבַר נָשׁ לְאַשְׁדָאָה מָאנֵי דְּבֵיתָא, וּלְאַפְקְדָא לֵיהּ לְסִטְרָא אָחֳרָא, דְּלָא אִצְטְרִיךְ, אוֹ מִלָּה אָחֳרָא דִּכְוָותֵיהּ, (ס\"א דביתיה לקבלא ליה) דְּהָא כַּמָה גַּרְדִּינֵי נִימוּסִין זְמִינִין לְהַהוּא מִלָּה לְקַבְּלָא לֵיהּ, וּמֵהַהוּא זִמְנָא, לָא שָׁארוּ עָלֵיהּ בִּרְכָאן, דְּהָא מִסִּטְרָא אָחֳרָא הוּא. כָּל שֶׁכֵּן מַאן דְּאַזְמִין בִּרְעוּתֵיהּ עַל הַהוּא טִיבוּ עִלָּאָה דִּילֵיהּ, לְאָחֳרָא וּלְסִטְרָא אָחֳרָא. דְּהָא, מֵהַהוּא דְּאַזְמִין לֵיהּ הֲוִי.</p>\n<p>וְכַד קְרִיבוּ יוֹמִין דְּבַּר נָשׁ לְנָפְקָא מֵהַאי עָלְמָא, הַהוּא צוּלְמָא עִלָּאָה דְּיָהֲבֵי לֵיהּ, אַתְיָא הַהוּא רוּחָא בִּישָׁא דְּהֲוָה מִתְדָּבַּק בֵּיהּ בְּכָל יוֹמָא, וְנָטִיל לֵיהּ לְהַהוּא צוּלְמָא, וְאִתְתָּקַּן בֵּיהּ וְאָזִיל לֵיהּ, וְלָא אִתְחֲזָר בֵּיהּ בְּבַּר נָשׁ לְעָלְמִין. כְּדֵין יִנְדַּע דְּהָא אִתְדַּחְיָא הוּא מִכֹּלָּא.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּנִשְׁמְתָא נַחְתָּא לְאַעֲלָא לֵיהּ בְּהַאי עָלְמָא, נַחְתָּא בְּגִנְתָּא דְּעֵדֶן דְּאַרְעָא, וְחָמָאת יְקָרָא דְּרוּחֵיהוֹן דְּצַדִּיקַיָּיא קַיְימִין שׁוּרִין שׁוּרִין. לְבָתַר אַזְלַא לַגֵּיהִנָּם, וְחָמָאת לְהוּ לְרַשִׁיעַיָּיא דְּצַוְוחִין וַוי וַוי, וְלָא מֵרַחֲמֵי עָלַיְיהוּ. וּבְכֹלָּא אַסְהִידוּ בָּהּ סַהֲדוּתָא, וְהַהוּא צוּלְמָא קַדִּישָׁא קַיְּימָא עָלֵיהּ, עַד דְּנָפִיק לְעָלְמָא.</p>\n<p><Nonei></i>כַּד נָפִיק לְעָלְמָא, אִזְדְּמַן הַהוּא צוּלְמָא לְגַבֵּיהּ, וְאִשְׁתְּתַף בַּהֲדֵּיהּ, וְאִתְרַבֵּי עִמֵּיהּ. כְּמָה דְּאִתְּמַר, (תהילים ל״ט:ז׳) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. וּבְהַהוּא צֶלֶם אִשְׁתָּתָּפוּ (אשתכחו) יוֹמוֹי דְּבַר נָשׁ, וְתַּלְיָין בֵּיהּ, הֲדָא הוּא דִכְתִיב, (איוב ח׳:ט׳) כִּי תְמוֹל אֲנַחְנוּ וְלֹא נֵדָע כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ. כִּי צֵל יָמֵינוּ וַדַּאי. וּמִן יוֹמָא דְּמִתְעַבְּרָא אִתְּתָא עַד יוֹמָא דְּאוֹלִידַת, לָא יַדְעִין בְּנֵי נָשָׁא עוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, כַּמָּה אִינּוּן רַבְרְבִין, וְכַמָּה אִינּוּן עִלָּאִין. הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ד) מַה רַבּוּ מַעֲשֶׂיךָ יְיָ' וְגוֹ'.</p>\n<p>תָּא חֲזֵי, כָּל רוּחִין דְּעָלְמָא כְּלִילָן דְּכַר וְנוּקְבָּא, וְכַד נָפְקִין, דְּכַר וְנוּקְבָּא נָפְקִין, וּלְבָתַר מִתְפָּרְשָׁן בְּאָרְחַיְיהוּ, אִי זָכֵי בַּר נָשׁ, לְבָתַר מִזְדַּוְּוגֵי כַּחֲדָא. וְהַיְינוּ בַּת זוּגוֹ, וּמִתְחַבְּרָן בְּזִוּוּגָא (ס\"א בגוונא) חַד בְּכֹלָּא, רוּחָא וְגוּפָא. דִּכְתִּיב, (בראשית א׳:כ״ד) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. מַאי לְמִינָהּ. הַהוּא רוּחָא דְּבַּר נָשׁ דְּנָפִיק זוּגֵיהּ דְּדָמֵי לֵיהּ.</p>\n<p>וּמַאי הָאָרֶץ, כְּמָה דְאַתְּ אָמֵר, (תהילים קל״ט:ט״ו) רֻקַּמְתִּי בְּתַחְתִּיּוֹת אָרֶץ. וְהָא אוּקְמוּהָ. תּוֹצֵא הָאָרֶץ וַדַּאי, דְּהָא מִנָּהּ נָפְקִין נֶפֶשׁ חַיָּה, כְּמָה דְּאוֹקִימְנָא, דָּא רוּחֵיהּ דְּאָדָם קַדְמָאָה, הַיְינוּ דִּכְתִּיב, (בראשית ג׳:ג׳) וּמִפְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן. וּמִפְּרִי הָעֵץ, דָּא קוּדְשָׁא בְּרִיךְ הוּא, אֲשֶׁר בְּתוֹךְ הַגָּן, אֲשֶׁר בְּתוֹךְ הָאִשָּׁה, תָּנֵינָן, הַיְינוּ, אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר, כְּתִיב. וְלָא כָּלִיל דְּכַר וְנוּקְבָּא, כְּפוּם אוֹרְחוֹי דְּעָלְמָא, דְּאִינּוּן, גָּרְמוּ לֵיהּ, דְּלָא מִתְחַבְּרָן, כַּמָה דְּנַפְקָן מִלְּעֵילָּא זוּגוֹת.</p>\n<p>בְּגִין דְּאָדָם קַדְמָאָה, וְזִוּוג דִּילֵיהּ, חָבוּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְעַל דָּא מִתְפָּרְשִׁין, כַּד נָפְקִין מִלְּעֵילָּא, עַד דְּהֲוָה רַעֲוָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אִי זָכָה בַּר נָשׁ, יָהֲבִין לֵיהּ זוּגָתוֹ, וְאִי לָא, מַפְרִישִׁין לֵהּ מִנֵּיהּ, וְיָהֲבִין לָהּ לְאָחֳרָא, מוֹלִידִין בְּנִין דְּלָא כְּדְקָא יֵאוֹת. וְעַל דָּא כְּתִיב, (בראשית ו׳:ג׳) לֹא יָדוֹן רוּחִי בָאָדָם. מַאי רוּחִי, רוּחוֹ מִבָּעֵי לֵיהּ, אִינּוּן תְּרֵין רוּחֵי, דְּנַפְקֵי זוּגוֹת, לָא יְדוּנוּן כַּחֲדָא, וְעַל דָּא כְּתִיב, וְיָלְדָה זָכָר, וְלָא כָּלִיל דְּכַר וְנוּקְבָּא, כְּפוּם אוֹרְחוֹי דְּעָלְמָא, דְּאִינּוּן גָּרְמוּ.</p>"],[9520012057,"<p>רִבִּי אֶלְעָזָר אָמַר לָאו הָכִי, דְּהָא כֹּלָּא, דְּכַר וְנוּקְבָּא כְּלִילָן כַּחֲדָא, וּמִתְפָּרְשָׁן לְבָתַר, אֲבָל וְיָלְדָה זָכָר, כְּלִילָן כַּחֲדָא מִסִּטְרָא דִּימִינָא, וְאִם נְקֵבָה תֵלֵד, כְּלִילָן בְּחַד נוּקְבָּא וּדְכַר מִסִּטְרָא שְׂמָאלָא, דְּשַׁלְטָא סְטָר שְׂמָאלָא עַל סְטָר יְמִינָא יַתִּיר, וּדְכוּרָא אִתְכַּפְיָא בִּימִינָא דְּלָא שַׁלְטָא, וּכְדֵין הַהוּא דְּכַר דְּנָפִיק מִגּוֹ נוּקְבָּא, מִסְּטַר שְׂמָאלָא, כָּל אוֹרְחוֹי כְּנוּקְבָּא (ולא אקרי דכר), אֲבָל דְּכַר דְּנָפִיק מִגּוֹ יְמִינָא, הוּא שַׁלְטָא, וְנוּקְבָּא דְּנָפְקָא מִנֵּיהּ אִתְכַּפְיָא, דְּהָא סְטָר שְׂמָאלָא לָא שַׁלְטָא, וְעַל דָּא וְיָלְדָה זָכָר כְּתִיב.</p>"],[9520012058,"<p>וְכַמָּה אֶלֶף וְרִבְבָן נַפְקֵי בְּזִמְנָא חֲדָא לְעָלְמָא. וּמִן יוֹמָא דְּאַפְקַת לוֹן, לָא אִקְרוּן נַפְשָׁן, עַד דְּאִתְיַישְּׁבָן בְּגוּפָא. וְכַמָּה הוּא, ל\"ג יָמִים. הַיְינוּ דִּכְתִּיב, וּשְׁלֹשִׁים יוֹם וּשְׁלֹשֶׁת יָמִים וְגוֹ'. וְטָמְאָה שִׁבְעַת יָמִים, דְּהָא כָּל שִׁבְעַת יָמִים לָא עָאלִין רוּחִין לְגַבָּהּ, לְאִתְקַשְּׁרָא בָּהּ, וְכָל אִלֵּין שִׁבְעַת יָמִים, רוּחָא אָזְלָא בְּגוּפָא, לְאַשְׁכְּחָא אַתְרֵיהּ. וּכְדֵין כְּתִיב, (ויקרא כ״ב:כ״ז) וְהָיָה שִׁבְעַת יָמִים תַּחַת אִמּוֹ.</p>\n<p>וּבְיוֹמָא תְּמִינָאָה, אִתְהֲדָרוּ רוּחָא וְגוּפָא לְאִתְחֲזָאָה קָמֵי מַטְרוֹנִיתָא, וּלְאִתְקַשְּׁרָא בָּהּ, וּבִדְכוּרָא, בְּגוּפָא וּבְרוּחָא. וּשְׁלֹשִׁים יוֹם וּשְׁלֹשֶׁת יָמִים תֵּשֵׁב עַל דְּמֵי טָהֳרָה, לְאִתְיַישְּׁבָא רוּחָא בְּגוּפָא. וְג' יָמִים מַאי עֲבִידְתַּיְיהוּ. אֶלָּא שְׁלֹשֶׁת יָמִים דְּמִילָה, דְּרַבְיָא כָּאִיב, וְרוּחָא לָא שַׁרְיָא מָדוֹרֵיהּ בְּגוּפָא כִּשְׁאָר יוֹמִין, וְעַל דָּא וּשְׁלֹשִׁים יוֹם וּשְׁלֹשֶׁת יָמִים תֵּשֵׁב בִּדְמֵי טָהֳרָה.</p>\n<p>בִּדְמֵי טָהֳרָה בְּקַדְמִיתָא, וּלְבָתַר יְמֵי טָהֳרָה. בִּדְמֵי טָהֳרָה, אִלֵּין, דְּמֵי מִילָה, דָּמָא בָּתַר דָּמָא דְּאָתֵי מֵרַבְיָא, וְקוּדְשָׁא בְּרִיךְ הוּא נָטִיר לְאִינּוּן דְּמֵי כָּל אִלֵּין יוֹמִין, הֲדָא הוּא דִכְתִיב, תֵּשֵׁב בִּדְמֵי טָהֳרָה. טָהֳרָה סְתָם, וְלָא אַדְכִּיר הֵ\"א בַּתְרָאָה, דְּלָא תֵּימָא טָהֳרָה דְּמַטְרוֹנִיתָא, אֶלָּא טָהֳרָה סְתָם, דְּמֵי טָהֳרָה אִקְרוּן אִלֵּין דְּמֵי דַּכְיָא.</p>\n<p>(ויקרא י״ב:ד׳) בְּכָל קֹדֶשׁ לֹא תִגָּע וְאֶל הַמִּקְדָּשׁ וְגוֹ'. תָּא חֲזֵי, בְּכָל יוֹמָא וְיוֹמָא, כְּנֶסֶת יִשְׂרָאֵל, נַטְלָא מִבֵּי מַלְכָּא מְזוֹנָא לְרוּחֵיהוֹן דִּבְנֵי נָשָׁא, וְזָנַת <Nonei></i>לְהוּ בִּקְדוּשָּׁה. בַּר לְהָנֵי, עַד דְּאִתְיַישְּׁבָן בְּגוּפָא אִינּוּן רוּחִין, בָּתַר תְּלָתִין וּתְלַת יוֹמִין, אַשְׁגָחַת עָלַיְיהוּ כָּל יוֹמָא, דְּהָא רוּחִין מִתְקַשְּׁרָן בְּגוּפָא כִּשְׁאָר בְּנֵי עָלְמָא, כְּמָה דְּהִיא לָא שַׁרְיָא אֶלָּא בַּאֲתַר שְׁלִים, כַּךְ כָּל עוֹבָדוֹי כְּהַאי גַּוְונָא, עַד דְּאִשְׁתְּלִימוּ. בְּכָל קֹדֶשׁ לֹא תִגָע, לְאַשְׁגְּחָא עָלַיְיהוּ.</p>"],[9520012059,"<p>וְאִם נְקֵבָה תֵלֵד. כְּמָה דְּאוֹקִימְנָא, דְּשַׁלְטָא סְטָר שְׂמָאלָא יַתִיר וְאִתְכַּפְיָא יְמִינָא, וְעַל דָּא כֹּלָּא עַל חַד תְּרֵין, רְחִיקָא נוּקְבָּא, מִדְּכוּרָא, לְאִתְקַשְּׁרָא רוּחָא בְּגוּפָא, דְּהָא שְׂמָאלָא לָא אִתְיַישְׁבָא הָכִי כִּימִינָא, וְאִשְׁתְּכָחַת בְּתוּקְפָא יַתִיר.</p>"],[9520012060,"<p><Nonei></i><Noneb>רעיא מהימנא</b> (ויקרא י״ב:ג׳) וּבַיּוֹם הַשְּׁמִינִי יִמּוֹל בְּשַׂר עָרְלָתוֹ. פִּקּוּדָא דָּא, לְמִגְזַר לִתְמַנְיָּא יוֹמִין גְּזִירוּ דְּקַּיָּימָא קַדִּישָׁא. רָזָא עִלָּאָה, דִּכְתִּיב, (תהילים כ״ה:י״ד) סוֹד יְיָ' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם. לְמַאן, לְאִינּוּן יְרֵאָיו אִינּוּן דַּחֲלֵי חַטָאָה, דְּהָא רָזָא דְּקַּיָּימָא קַדִּישָׁא לָא אִתְחֲזִי לְגַלָּאָה בַּר לְהוּ. וְרָזָא דְּקַּיָּימָא קַדִּישָׁא, הָא אוּקְמוּהָ וְאִתְּמַר בְּכַמָּה דּוּכְתִּין.</p>\n<p>וְרָזָא דָּא, לַח' יוֹמִין, אִיהוּ חִיוּבָא עַל עָלְמָא, לְכָל עַמָּא קַדִּישָׁא. דִּכְתִּיב, וּבַיּוֹם הַשְּׁמִינִי יִמּוֹל בְּשַׂר עָרְלָתוֹ. יוֹם הַשְּׁמִינִי, דָּא הוּא אָת קַיָּימָא קַדִּישָׁא, וְאִיהוּ תְּמִינָאָה לְכָל דַּרְגִּין. וּגְזִירוּ דְּהַהוּא קַיָּימָא, לְאַעְבְּרָא הַהוּא עָרְלָה. <Nonei></i>מִקַּמֵּי בְּרִית.</p>\n<p>דְּהָא בְּהַהוּא זִמְנָא דְּמִתְכַּנְשֵׁי עַמָּא קַדִּישָׁא לְאַעְבְּרָא הַהוּא עָרְלָה מִקַּמֵּי בְּרִית, קוּדְשָׁא בְּרִיךְ הוּא כָּנִישׁ כָּל פָּמַלְיָא דִּילֵיהּ, וְאִתְגְּלֵי וַדַּאי לְאַעְבְּרָא לְהַהוּא עָרְלָה לְעֵילָּא, מִקַּמֵּי בְּרִית קַיָּימָא קַדִּישָׁא. דְּהָא כָּל עוֹבָדִין דְּיִשְׂרָאֵל עַבְדִּין לְתַתָּא, מִתְעָרֵי עוֹבָדָא לְעֵילָּא. וּבְהַהוּא זִמְנָא אִתְדַּחְיָיא הַהוּא עָרְלָה, מִכָּל עַמָּא קַדִּישָׁא לְעֵילָּא. וּלְהַהוּא עָרְלָה מְתַקְּנֵי מָאנָא חֲדָא בְּעַפְרָא, לְאַשְׁרָאָה הַהוּא עָרְלָה בְּגַוִיהּ. בְּרָזָא דִּכְתִּיב, (ישעיהו ס״ה:כ״ה) וְנָחָשׁ עָפָר לַחְמוֹ. (בראשית ג׳:י״ד) וְעָפָר תֹּאכַל כָּל יְמֵי חַיְּיךָ.</p>\n<p>מִכָּאן, (תיקון ס\"א) דְּלָא אִצְּטְרִיךְ לְאַנְהֲגָא קְלָנָא בְּהַהוּא אֲתַר, אַף עַל גַּב דִּמְעַבְרֵי לֵיהּ מִקַּמֵּי הַאי בְּרִית, וְדוּכְתֵיהּ, כַּד מִתְעַבְּרָא מֵהַאי בְּרִית, עַפְרָא אִיהוּ, (ס\"א דהא) דְּהָרֵי בָּתַר דְּהַהוּא נָחָשׁ אִתְעַבָּר מִקַּמֵּי אָדָם, קוּדְשָׁא בְּרִיךְ הוּא שַׁוִּי לֵיהּ מָדוֹרֵיהּ בֶּעָפָר, דִּכְתִּיב וְעָפָר תֹּאכַל כָּל יְמֵי חַיְּיךָ. וְכֵיוָן דְּקוּדְשָׁא בְּרִיךְ הוּא כַּד אַעְבָּר לֵיהּ מִקַּמֵּי אָדָם שַׁוִּי מָדוֹרֵיהּ בְּעַפְרָא וְאַתְקִין לֵיהּ, כַּךְ בְּהַהוּא גַּוְונָא מַמָּשׁ, אֲנָן צְּרִיכִין כַּד מְעַבְּרִין לַעָרְלָה, לְאִתְתַּקְנָא לֵיהּ עַפְרָא, לְמֶהֱוִי בֵּיהּ מָדוֹרֵיהּ.</p>\n<p>כָּל בַּר נָשׁ אִצְּטְרִיךְ לְקָרְבָא הַהוּא בְּרָא קָרְבְּנָא לְּקוּדְשָׁא בְּרִיךְ הוּא, בְּחֶדְוָה, בִּרְעוּ דְּלִבָּא, לְמֵיעַל לֵיהּ תְּחוֹת גַּדְפּוֹי דִּשְׁכִינְתָּא, וְאִתְחַשָּׁב קָמֵי קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ קָרְבְּנָא, שְׁלִים לְאִתְקַבְּלָא בְּרַעֲוָא.</p>\n<p>וְקָרְבְּנָא דָּא, כְּגַוְונָא דְּקָרְבְּנָא דִּבְעִירָא, דָּא לַח' יוֹמִין, וְדָא לַח' יוֹמִין, דִּכְתִּיב, וּמִיּוֹם הַשְּׁמִינִי וָהָלְאָה יִרָצֶּה, בְּמַאי יִרָצֶּה. בְּמֶעְבַּר עָלֵיהּ חַד שַׁבְּתָא, כֵּיוָן דְּאַעְבָּר עָלֵיהּ חַד שַׁבְּתָא, כְּדֵין יִרָצֶּה דָּא לְקָרְבְּנָא, וְדָא לְקָרְבְּנָא. אֲמַאי. בְּגִין דְּאִתְדְּבַק וְאִזְדְּמַן לְגַבֵּי הַהוּא שַׁבָּת, רָזָא דִּבְרִית קַדִּישָׁא, וְעַל דָּא כֹּלָּא בְּרָזָא עִלָּאָה אִיהוּ. (ע\"כ רעיא מהימנא)</p>"],[9520012061,"<p>(ויקרא י״ב:ב׳) אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר וְגוֹ'. רִבִּי יְהוּדָה פָּתַח, (שמואל א ב׳:ב׳) אֵין קָדוֹשׁ כַּיְיָ' כִּי אֵין בִּלְתֶּךָ וְאֵין צוּר כֵּאלֹהֵינוּ, הַאי קְרָא קַשְׁיָא, אֵין קָדוֹשׁ כַּיְיָ', מַשְׁמַע דְּאִיכָּא קָדוֹשׁ אָחֳרָא, בְּגִין דִּכְתִּיב כַּיְיָ', וְאֵין צוּר כֵּאלֹהֵינוּ, מַשְׁמַע דְּאִיכָּא צוּר אָחֳרָא.</p>\n<p>אֶלָּא וַדַּאי, אֵין קָדוֹשׁ כַּיְיָ', דְּכַמָּה קַדִּישִׁין נִינְהוּ, קַדִישִׁין לְעֵילָּא, דִּכְתִיב, (דניאל ד׳:י״ד) וּמֵאמַר קַדִישִׁין שְׁאֵלְתָּא. יִשְׂרָאֵל קַדִּישִׁין נִינְהוּ, דִּכְתִּיב, (ויקרא יט) קְדוֹשִׁים תִּהְיוּ. וְכֻלְּהוּ קַדִּישִׁין, וְלָאו קַדִּישִׁין כַּיְיָ'. וּמַאי טַעְמָא. בְּגִין דִּכְתִיב, כִּי אֵין בִּלְתֶּךָ. מַאי, כִּי אֵין בִּלְתֶּךָ, אֶלָּא קְדוּשָּׁה דְּקוּדְשָׁא בְּרִיךְ הוּא בִּלְתִּי קְדוּשָּׁא דִּלְהוֹן, דְּהוּא לָא אִצְטְרִיךְ לִקְדוּשָּׁה דִּלְהוֹן. אֲבָל אִינּוּן, לָאו אִינּוּן קַדִּישִׁין בִּלְתֶּךָ, וְדָא הוּא, כִּי אֵין בִּלְתֶּךָ, אֵין קְדוּשָּׁה דִּלְהוֹן, בִּלְתֶּךָ.</p>\n<p>וְאֵין צוּר כֵּאלֹהֵינוּ. כְּמָה דְּאוּקְמוּהָ, דְּקוּדְשָׁא בְּרִיךְ הוּא צָר צוּרָה בְּגוֹ צוּרָה, וְתָקִין לֵיהּ, וְנָפַח רוּחָא דְּחַיֵּי, וְאַפִּיק לֵיהּ לַאֲוִירָא דְּעָלְמָא, דָּבָר אַחֵר, וְאֵין צוּר כֵּאלֹהֵינוּ. אִית צוּר, דְּאִקְרֵי צוּר, (ישעיהו נ״א:א׳) הַבִּיטוּ אֶל צוּר חוּצַּבְתֶּם. (שמות י״ז:ו׳) וְהִכִּיתָ בַצּוּר. הִנְנִי עוֹמֵד לְפָנֶיךָ שָּׁם עַל הַצּוּר בְּחוֹרֵב. וְכֻלְּהוּ אִקְרוּן צוּר, וְאֵין צוּר בְּכֻלְּהוּ כֵּאלֹהֵינוּ, דִּילֵיהּ שׁוּלְטָנוּ וּמַלְכוּתָא עַל כֹּלָּא.</p>"],[9520012062,"<p>רִבִּי חִיָּיא וְרִבִּי אֲחָא הֲווֹ יַתְבֵי לֵילְיָא חַד קַמֵּיהּ דְּרִבִּי אַבָּא. קָמוּ בְּפַלְגוּת לֵילְיָא לְמִלְעֵי בְּאוֹרַיְיתָא. עַד דְּנָפְקוּ לְבַר, חָמוּ חַד כֹּכָבָא דְּהֲוָה בָּטַשׁ ג' זִמְנֵי בְּכֹכָבָא אָחֳרָא וְסָתִים נְהוֹרֵיהּ. אַדְהָכִי שָׁמְעוּ תְּרֵי קָלֵי בִּתְרֵי סִטְרֵי, קָלָא חַד לִסְטַר צָפוֹן לְעֵילָּא, וְקָלָא <Nonei></i>חַד לְתַתָּא. וְהַהוּא קָלָא אַכְרִיז וְאָמַר, עוּלוּ וְאִתְכְּנִישׁוּ לְאַתְרַיְיכוּ, הַשְׁתָּא אִסְתַּמְרוּתָא דְּנוּקְבָּא פְּתִיחָא, קוּדְשָׁא בְּרִיךְ הוּא עָאל לְטַיְילָא בְּגִנְתָא, לְאִשְׁתַּעְשְׁעָא בְּצַדִיקַיָּיא דִּי בְּגִנְתָא, אַעְבָר הַהוּא קָלָא וְשָׁכִיךְ.</p>\n<p>אָהַדְרוּ רִבִּי אֲחָא וְרִבִּי חִיָיא, אָמְרוּ, הָא וַדַאי עִדָּן רְעוּתָא, דְּאִתְעָרוּתָא דְּכְּנֶסֶת יִשְׂרָאֵל (עדן) הוּא לְאִתְחַבְּרָא בְּמַלְכָּא קַדִּישָׁא, אָמַר רִבִּי אֲחָא, וַדַאי, לָא (אתחברת) אֲנְגִידָת לָהּ כְּנֶסֶת יִשְׂרָאֵל בְּקוּדְשָׁא בְּרִיךְ הוּא אֶלָּא מִגּוֹ שִׁירָתָא, מִגּוֹ שְׁבָחָא דִּילָהּ לְגַבֵּיהּ. עַד דְּאָתֵי צַפְרָא, וְאוֹשִׁיט לָהּ מַלְכָּא חוּטָא דְּחֶסֶד, וְרָזָא דְּמִלָּה כְּמָה דְּאַמְרִינָן, (אסתר ה׳:ב׳) וַיּוֹשֶׁט הַמֶּלֶךְ לְאֶסְתֵּר אֶת שַׁרְבִיט הַזָּהָב אֲשֶׁר בְּיָדוֹ וְגוֹ'. וְלָא תֵּימָא דְּלָהּ בִּלְחוֹדָהָא אוֹשִׁיט לָהּ מַלְכָּא דָּא, אֶלָּא לָהּ, וּלְכָל אִינּוּן דְּמִתְחַבְּרָן בָּה. תָּא וְנִתְחַבֵּר כַּחֲדָא. יָתְבוּ.</p>"],[9520012063,"<p>פָּתַח רִבִּי אֲחָא וְאָמַר, (בראשית ב׳:י״ח) וַיֹּאמֶר יְיָ' אֱלֹהִים לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ וְגוֹ'. אֲמַאי פָּתַח קְרָא הָכִי, אֶלָּא הָא אִתְּמַר, דְּעַל דָּא לָא כְּתִיב, כִּי טוֹב בַּשֵּׁנִי, בְּגִין דְּזַמִּין אָדָם לְאִתְפָּרְשָׁא, וּכְתִיב, לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ.</p>\n<p>וְכִי לְבַדּוֹ הֲוָה, וְהָא כְּתִיב, (בראשית ה׳:ב׳) זָכָר וּנְקֵבָה בְּרָאָם. וְתָנֵינָן אָדָם דּוּ פַּרְצוּפִין אִתְבְּרֵי, וְאַתְּ אַמְרַת, לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ. אֶלָּא דְּלָא אִשְׁתְּדַּל בְּנוּקְבֵיהּ, וְלָא הַוַת לֵיהּ, סֶמֶךְ לָקֳבְלֵיהּ, בְּגִין דְּהֲוַת בְּסִטְרוֹי, וַהֲווּ כַּחֲדָא מֵאֲחוֹרָא, וּכְדֵין הֲוָה הָאָדָם לְבַדּוֹ.</p>\n<p>אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ. מַהוּ כְּנֶגְדּוֹ, לָקֳבֵל אַנְפּוֹי, לְאִתְדַּבְּקָא דָּא בְּדָא אַנְפִּין בְּאַנְפִּין, מָה עֲבַד קוּדְשָׁא בְּרִיךְ הוּא, נָסַר לֵיהּ וְנָטִיל נוּקְבָּא מִנֵּיהּ, הֲדָא הוּא דִכְתִיב, (בראשית ב׳:כ״א) וַיִּקַּח אַחַת מִצַּלְעוֹתָיו. מַהוּ אַחַת. דָּא נוּקְבָּא דִּילֵיהּ. כְּמָה דְאַתְּ אָמֵר, (שיר השירים ו׳:ט׳) אַחַת הִיא יוֹנָתִי תַמָּתִי. וַיְבִיאֶהָ אֶל הָאָדָם, אַתְקִין לָהּ כְּכַלָּה וְאַיְיתֵי לָהּ לְמֶהֱוִי לָקֳבֵיל אַנְפּוֹי נְהִירִין אַנְפִּין בְּאַנְפִּין. וּבְעוֹד דְּהֲוָה מִתְדַּבְּקָא נוּקְבָּא בְּסִטְרוֹי, הֲוָה הָאָדָם לְבַדּוֹ. לְבָתַר, סְלִיקוּ תְּרֵין, וְקָמוּ שֶׁבַע כַּחֲדָא.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִתְכְּנָשׁ (ס\"א דאתתקנת) לְגַבֵּי אָדָם, קוּדְשָׁא בְּרִיךְ הוּא בְּרִיךְ לוֹן, הֲדָא הוּא דִכְתִיב, (בראשית א׳:כ״ב) וַיְבָרֶךְ אוֹתָם אֱלֹהִים. כְּחַזָּן דִּמְבָרֵךְ לְכַלָּה בְּשֶׁבַע בְּרָכוֹת. מִכָּאן אוֹלִיפְנָא, חָתָן וְכַלָּה, כֵּיוָן דְּאִתְבָּרְכָן בְּשֶׁבַע בְּרָכוֹת אִתְדַּבְּקָן כַּחֲדָא, כְּדוּגְמָא דִּלְעֵילָּא.</p>\n<p>וְעַל דָּא מַאן דְּאָתֵי לְאִתְחַבְּרָא בְּאִנְתּוּ דְּאָחֳרָא, הָא פָּגִים זִוּוּגָא, (כביכול עביד ב' רשויות לעילא) דְּהָא זִוּוּגָא דְּכְּנֶסֶת יִשְׂרָאֵל, בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, בְּזִמְנָא דְּאִיהוּ בְּרַחֲמֵי, וּבְזִמְנָא דְּאִיהוּ בְּדִינָא. תָּא חֲזֵי, מַאן דְּמִתְחַבָּר בְּאִנְתּוּ דְּאָחֳרָא, כְּאִילּוּ מְשַׁקֵּר בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא וּבִּכְּנֶסֶת יִשְׂרָאֵל, וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא לָא מְכַפֵּר לֵיהּ בִּתְשׁוּבָה, וּתְשׁוּבָה תַּלְיָא עַד דְּיִסְתָּלַק מֵעָלְמָא, הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ב:י״ד) אִם יְכוּפַּר הֶעָוֹן הַזֶּה לָכֶם עַד תְּמוּתוּן. וְאֵימָתַי, בְּשַׁעֲתָא דְּעָאל בִּתְשׁוּבָה לְהַהוּא עָלְמָא, וְאִית לֵיהּ לְקַבְּלָא עוֹנְשָׁא.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, מַאן דִּמְשַׁקֵּר בִּכְּנֶסֶת יִשְׂרָאֵל, לָא יִתְקָבַּל בִּתְשׁוּבָה, עַד דְּיִתְדָּן בְּדִינָא דְּגֵיהִנָּם. כָּל שֶׁכֵּן, מַאן דִּמְשַׁקֵּר בִּכְּנֶסֶת יִשְׂרָאֵל וּבְּקוּדְשָׁא בְּרִיךְ הוּא. וְכָּל שֶׁכֵּן אִי אַטְרַח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד דִּיּוּקְנָא דְּמַמְזֵר בְּאִנְתּוּ דְּאָחֳרָא, וְאַכְחִישׁ פּוּמְבִּי דְּמַלְכָּא.</p>"],[9520012064,"<p>רִבִּי חִיָּיא פָּתַח וְאָמַר, (משלי כ״ח:כ״ד) גּוֹזֵל אָבִיו וְאִמּוֹ וְגוֹ'. אָבִיו, דָּא קוּדְשָׁא בְּרִיךְ הוּא. אִמּוֹ, דָּא כְּנֶסֶת יִשְׂרָאֵל. מַאי גּוֹזֵל. כְּמָה דְאַתְּ אָמֵר, (ישעיהו ג׳:י״ד) גְּזֵלַת הֶעָנִי בְּבָתֵּיכֶם. וּמַאן אִיהוּ, מַאן דְּחָמִיד אִתְּתָא אָחֳרָא דְּלָאו אִיהִי בַּת זוּגֵיהּ.</p>\n<p>תַּמָּן תָּנֵינָן, כָּל הַנֶּהנֶה מִן הָעוֹלָם הַזֶּה בְּלֹא בְּרָכָה, כְּאִלּוּ גּוֹזֵל לְּקוּדְשָׁא בְּרִיךְ הוּא וּכְּנֶסֶת יִשְׂרָאֵל, דִּכְתִיב גּוֹזֵל אָבִיו וְאִמּוֹ וְגוֹ'. כָּל הַנֶּהֱנֶה מִן הָעוֹלָם הַזֶּה, כְּלָל דָּא, אִיהוּ אִינְתּוּ. מַאן דְּאִתְדַּבָּק בְּאִנְתּוּ לְמֵהֱנֵי מִנָּהּ, וְאַף עַל גַּב, דְּאִיהִי פְּנוּיָה, וְאַהֲנֵי מִנָּהּ בְּלָא בְּרָכָה, כְּאִלּוּ גּוֹזֵל קוּדְשָׁא בְּרִיךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל. מַאי טַעְמָא, בְּגִין דְּזִוּוּגָא דִּלְהוֹן, בְּשֶׁבַע בְּרָכוֹת הוּא. וּמַה עַל פְּנוּיָה כַּךְ, מַאן דְּיִתְדְּבַּק בְּאִנְתּוּ דְּאָחֳרָא, דְּקָאִים כְּגַוְונָא דִּלְעֵילָּא, בְּזִוּוּגָא דְּז' בְּרָכוֹת, עַל אַחַת כַּמָה וְכַמָּה.</p>\n<p>(משלי כ״ח:כ״ד) חָבֵר הוּא לְאִישׁ מַשְׁחִית, דָּא יָרָבְעָם, כְּמָה דְּאוּקְמוּהָ, וְאֹמֵר אֵין פָּשַׁע דְּאָמַר הָא פְּנוּיָה הִיא, אֲמַאי אָסוּר. בְּגִין דָּא גּוֹזֵל אָבִיו וְאִמּוֹ הֲוִי. וְלֹא עוֹד אֶלָּא דְּחָבֵר הוּא לְאִישׁ מַשְׁחִית. מַאן הוּא אִישׁ מַשְׁחִית. דְּפָגִים דִּיּוּקְנָא וְתִקּוּנָא דִּלְעֵילָּא. כָּל שֶׁכֵּן מַאן דְּחָמִיד לְאִנְתּוּ דְּחַבְרֵיהּ לְאִתְדַּבְּקָא (ס\"א ואתדבק בה) בָּהּ, <Nonei></i>דְּפָגִים יַתִּיר. וְעַל דָּא אִתְפְּגִים הוּא לְעָלְמִין. אִישׁ מַשְׁחִית, דְּפָגִים לְעֵילָּא, וּפָגִים לְתַתָּא, וּפָגִים לְנַפְשֵׁיהּ, דִּכְתִּיב מַשְׁחִית, וּכְתִיב, (משלי ו׳:ל״ב) מַשְׁחִית נַפְשׁוֹ הוּא יַעֲשֶׂנָּה.</p>"],[9520012065,"<p>רִבִּי אַבָּא פָּתַח וְאָמַר, (בראשית ל״ב:כ״ז) וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר וְגוֹ'. וַיֹּאמֶר שַׁלְּחֵנִי, וְכִי עָקוּד הֲוָה בִּידֵיהּ דְּיַעֲקֹב. אֶלָּא זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּקוּדְשָׁא בְּרִיךְ הוּא חָס עַל יְקָרָא דִּלְהוֹן, וְלָא שָׁבִיק לוֹן לְעָלְמִין. הֲדָא הוּא דִכְתִיב, (תהילים נ״ה:כ״ג) לֹא יִתֵּן לְעוֹלָם מוֹט לַצַּדִיק. וְהָא כְּתִיב, (בראשית ל״ב:כ״ו) וַתֵּקַע כַּף יֶרֶךְ יַעֲקֹב.</p>\n<p>אֶלָּא לְדִידֵיהּ גָּבָה. וְהָא אִתְּמַר, כְּתִיב (בראשית ל״ב:כ״ב) וְהוּא לָן בַּלַּיְלָה הַהוּא בַּמַּחֲנֶה. וּכְתִיב וַיִּקָּחֵם וַיַּעֲבִירֵם אֶת הַנָּחַל מַאי הֲוָה דַּעְתֵּיהּ דְּיַעֲקֹב, לְמַעֲבְּרָא לְהוֹן בְּנַחֲלָא בְּלֵילְיָא. אֶלָּא חָמָא מְקַטְרְגָא אָזִיל בֵּין מַשִּׁרְיָיא דִּילֵיהּ, אָמַר יַעֲקֹב אַעְבָּר לְגִיסָא אָחֳרָא דְּנַהֲרָא, דִּלְמָא לָא יִשְׁתְּכַּח עִרְבּוּבְיָא.</p>\n<p>מַאי קָא חָמָא. חָמָא שַׁלְהוֹבָא דְּאֶשָּׁא מְלָהֲטָא, אַזְלָא וְטָאס בֵּין מַשִׁרְיָיתֵיהּ אָמַר יַעֲקֹב מוּטָב לְנַטְלָא מֵהָכָא, וְנַהֲרָא פָּסִיק בְּגַוָון, וְלָא יִשְׁתְּכַּח עִרְבּוּבְיָא. מִיַּד וַיִּקָּחֵם וַיַּעֲבִירֵם אֶת הַנָּחַל. וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ, מִכָּאן אוֹלִיפְנָא מַאן דְּאִשְׁתְּכַח בִּלְחוֹדוֹי בְּבֵיתָא בְּלֵילְיָא, אוֹ בִּימָמָא בְּבַיִת מְיַחֲדָא, כָּל שֶׁכֵּן בְּלֵילְיָא, מַאי מְיַחֲדָא. מְיַחֲדָא מִשְּׁאָר בֵּיתִין. אוֹ מַאן דְּאָזִיל בִּלְחוֹדוֹי בְּלֵילְיָא יָכִיל לְאִתְזְקָא.</p>\n<p>תָּא חֲזֵי וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ, כְּדֵין וַיֵּאָבֵק אִישׁ עִמּוֹ וְגוֹ'. תָּנֵינָן מִסִּטְרָא דְּדִינָא קָא אָתֵי, וְשׁוּלְטָנֵיהּ בִּסְטָר לֵילְיָא. מַאי בִּסְטָר לֵילְיָא. לְאַעֲלָא גָלוּתָא (נ\"א בגלותא) כֵּיוָן דְּסָלִיק נְהוֹרָא, תָּשַׁשׁ חֵילֵיהּ, וְאִתְגַּבָּר עָלֵיהּ חֵילֵיהּ דְּיַעֲקֹב. (נ\"א הוא) דְּהָא מִסִּטְרָא דְּלֵילְיָא קָא אָתֵי, וּבִזְמְנָא דְּהֲוָה לֵילְיָא לָא הֲוָה יָכִיל בֵּיהּ יַעֲקֹב. כַּד סָלִיק נְהוֹרָא אִתְתְּקַף חֵילָא דְּיַעֲקֹב, וְאָחִיד בֵּיהּ, וְאִתְגַּבָּר עָלֵיהּ. חָמָא לֵיהּ יַעֲקֹב דְּהָא שְׁלִיחָא הוּא.</p>\n<p>אָמַר לֵיהּ שְׁבוֹק לִי דְּלָא יָכִילְנָא לָךְ. מַאי טַעְמָא לָא יָכִיל לֵיהּ. בְּגִין דְּהֲוָה סָלִיק נְהוֹרָא, וְאִתְּבַּר חֵילָא דִּידֵיהּ, דִּכְתִּיב, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. מַאי וַיָּרִיעוּ. דְּאִתְּבָּרוּ כָּל אִינּוּן דְּאַתְיָין מִסִּטְרָא דְּדִינָא. כְּדֵין אִתְתָּקַּף יַעֲקֹב וְאָחִיד בֵּיהּ.</p>\n<p>אָמַר לֵיהּ שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר, מָטָא זִמְנָא לְשַׁבְּחָא שְׁבָחָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְאִתְכַּנְּשָׁא. וַיֹּאמֶר לֹא אֲשַׁלֵּחֲךָ כִּי אִם בֵּרַכְתָּנִי, אִם תְּבָרְכֵנִי מִבָּעֵי לֵיהּ, מַאי אִם בֵּרַכְתָּנִי. אֶלָּא אָמַר לֵיהּ יַעֲקֹב, וַדַּאי אַבָּא בְּרִיךְ לִי אִינּוּן בִּרְכָאן דְּבָעָא לְבָרְכָא לְעֵשָׂו, וּמִסְתָּפֵינָא מִנָךְ, עַל אִינּוּן בִּרְכָאן, אִי אוֹדִית עָלַיְיהוּ, (או) אִי לָאו, אוֹ תִּשְׁתְּכַח עָלַי מְקַטְרְגָא בְּגִינֵיהוֹן.</p>\n<p>מִיַּד אָמַר לֵיהּ, וַיֹּאמֶר לֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךָ. מַאי קָאָמַר לֵיהּ, אֶלָּא הָכִי קָאָמַר לֵיהּ, לָאו בְּחַכִּימוּ, וְלָאו בְּעוּקְבָא (דילך), רַוְוחַת לְאִינּוּן בִּרְכָאן, לָא יֵאָמֵר עוֹד שִׁמְךָ יַעֲקֹב, דְּהָא לָאו בְּעוּקְבָא הֲוָה, כִּי אִם יִשְׂרָאֵל, יִשְׂרָאֵל וַדַּאי אוֹדֵי עֲלָךְ, וּמִנֵּיהּ נָפְקוּ בִּרְכָאן, בְּגִין דְּאַנְתְּ אָחִיד בֵּיהּ, וְעַל דָּא, אֲנָא וְכָל שְׁאָר אוּכְלוּסִין, אוֹדֵינָא עָלַיְיהוּ.</p>\n<p>כִּי שָׂרִיתָ עִם אֱלֹהִים וְעִם אֲנָשִׁים וַתּוּכָל, עִם אֱלֹהִים כָּל אִינּוּן דְּאַתְיָין מִסִּטְרָא דְּדִינָא קַשְׁיָא. וְעִם אֲנָשִׁים, דָּא עֵשָׂו וְאוּכְלוּסִין דִּילֵיהּ. וַתּוּכָל, יָכִילַת לְהוֹן, וְאִינּוּן לָא יַכְלִין לָךְ. וְלָא שָׁבִיק לֵיהּ יַעֲקֹב, עַד דְּאוֹדֵי לֵיהּ עַל אִינּוּן בִּרְכָאן, הֲדָא הוּא דִכְתִיב וַיְבָרֶךְ אוֹתוֹ שָׁם.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּסָלִיק נְהוֹרָא, אִתְכַּפְיָין כָּל אִינּוּן מָארֵי דְּדִינִין, וְלָא מִשְׁתַּכְּחֵי, וּכְּנֶסֶת יִשְׂרָאֵל מִשְׁתָּעֵי בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. וְהַהִיא שַׁעֲתָא עִידָּן דְּרַעֲוָא הוּא לְכֹלָּא, וְאוֹשִׁיט לָהּ מַלְכָּא וּלְכָל אִינּוּן דְּמִשְׁתַּכְּחֵי עִמָּהּ, שַׁרְבִיטָא דְּחוּטָא דְּחֶסֶד, לְאִשְׁתַּכְּחָא בִּשְׁלִימוּ בְּמַלְכָּא קַדִּישָׁא, וְהָא אִתְּמַר.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּכַח בָּהּ בִּכְּנֶסֶת יִשְׂרָאֵל, בְּאִינּוּן זִמְנִין דְּאִשְׁתְּכַח עִמָּהּ, וְהִיא מַתְעָרַת רְעוּתָא לְגַבֵּיהּ בְּקַדְמִיתָא, וּמַשְׁכַאת לֵיהּ לְגַבָּהּ, בִּסְגִיאוּת חִבָּתָא וְתִיאוּבְתָּא, כְּדֵין אִתְמַלְּיָא מִסִּטְרָא דִּימִינָא, וְכַמָּה אוּכְלוּסִין מִשְׁתַּכְּחֵי בְּסִטְרָא דִּימִינָא, בְּכֻלְּהוּ עָלְמִין. וְכַד קוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר חֲבִיבוּתָא וּרְעוּתָא בְּקַדְמִיתָא, וְהִיא <Nonei></i>אִתְּעָרַת לְבָתַר, וְלָאו בְּזִמְנָא דְּאִיהוּ אִתְּעַר, כְּדֵין כֹּלָּא בְּסִטְרָא דְּנוּקְבָּא אִשְׁתְּכַח, וּשְׂמָאלָא אִתְּעַר, וְכַמָּה אוּכְלוּסִין קַיְימֵי וּמִתְעָרֵי בְּסִטְרָא דִּשְׂמָאלָא בְּכֻלְּהוּ עָלְמִין. כְּהַאי גַּוְונָא כְּתִיב, (נ\"א הדא הוא דכתיב) אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר וְגוֹ'. מַאי טַעְמָא. תָּנֵינָן, עָלְמָא תַּתָּאָה כְּגַוְונָא דְּעָלְמָא עִלָּאָה אִשְׁתְּכַח, וְדָא כְּדוּגְמָא דְּדָא.</p>\n<p>וְעַל דָּא, קוּדְשָׁא בְּרִיךְ הוּא גָּזַר דְּכַר אוֹ נוּקְבָּא, לְאִשְׁתַּכְּחָא רְעוּתָא בְּעָלְמָא. וּבְכֹלָּא בָּעֵי בַּר נָשׁ לְאִתְדַּבְּקָא רְעוּתָא לְעֵילָּא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, לְאִשְׁתַּכְּחָא רַעֲוָון בְּעָלְמָא. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, דְּאִינּוּן יַדְעִין לְאַדְבְּקָא רְעוּתְהוֹן לְגַבֵּי מַלְכָּא קַדִּישָׁא, עָלַיְיהוּ כְּתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>"],[9520012066,"<p>(ויקרא י״ג:ב׳) אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ שְׂאֵת אוֹ סַפַּחַת אוֹ בַהֶרֶת וְגוֹ'. רִבִּי יְהוּדָה פָּתַח וְאָמַר, (שיר השירים א׳:ו׳) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ, הַאי קְרָא אִתְּמַר, אֲבָל בְּשַׁעֲתָא דְּסִיהֲרָא אִתְכַּסְּיָא בְּגָלוּתָא, הִיא אָמְרָה, אַל תִּרְאוּנִי. לָאו דְּאִיהִי פְּקִידַת דְּלָא לְמֵחמֵי לָהּ, אֶלָּא בְּגִין דְּאִיהִי חָמָת תִּיאוּבְתָּא דְּיִשְׂרָאֵל לְגַבָּהּ, לְמֵחֱמֵי נְהוֹרָהָא, הִיא אַמְרַת אַל תִּרְאוּנִי, לָא תֵּיכְלוּן לְמֵחֱמֵי לִי. אַל תִּרְאוּנִי וַדַּאי. מַאי טַעְמָא. בְּגִין שֶׁאֲנִי שְׁחַרְחוֹרֶת, בְּגִין דַּאֲנָא בְּקַדְרוּתָא.</p>\n<p>מַאי שְׁחַרְחוֹרֶת, שְׁחוֹרָה מִבָּעֵי לֵיהּ. אֶלָּא, תְּרֵין קַדְרוּתֵי, חַד שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ, דְּאִסְתַּלָּק מִנִּי שִׁמְשָׁא, לְאַנְהֲרָא לִי, וּלְאִסְתַּכְּלָא בִּי. וְחַד דִּבְנֵי אִמִּי נִחֲרוּ בִי.</p>\n<p>שֶׁשְּׁזָפַתְנִי, שְׁזָפַתְנִי מִבָּעֵי לֵיהּ. אֶלָּא רְמָז הוּא דְּקָא רָמִיז, בְּשֵׁשׁ. דְּכַד נַהֲרָא שִׁמְשָׁא בְּשֵׁשׁ נְהוֹרִין נָהִיר, וְכַד אִסְתַּלָּק, כָּל אִינּוּן שִׁית נְהוֹרִין אִסְתְּלָקוּ. בְּנֵי אִמִּי, אִלֵּין אִינּוּן דְּאַתְיָין מִסִּטְרָא דְּדִינָא קַשְׁיָא. נִחֲרוּ בִי, כְּמָה דְאַתְּ אָמֵר (תהילים ס״ט:ד׳) נִחַר גְּרוֹנִי, הֲדָא הוּא דִכְתִיב, (איכה ה׳:ה׳) עַל צַוָּארֵנוּ נִרְדָּפְנוּ דְּכַד הֲווֹ עַיְילִין יִשְׂרָאֵל בְּגָלוּתָא, הֲווֹ אָזְלֵי יְדַיְיהוּ מְהַדְּקָן לַאֲחוֹרָא, וְרֵיחַיִין עַל צַוָארֵיהוֹן, וְלָא יָכִילוּ לְאַפְתְּחָא פּוּמָא.</p>\n<p>שָׂמוּנִי נוֹטֵרָה אֶת הַכְּרָמִים, לְמֵהַךְ בְּגָלוּתָא, לְנַטְרָא לִשְׁאַר עַמִּין בְּגִינֵהוֹן דְּיִשְׂרָאֵל. כַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי, דְּהָא לָא יָכִילְנָא לְנַטְרָא לְהוֹן כַּד בְּקַדְמִיתָא. בְּקַדְמִיתָא נְטִירְנָא כַּרְמִי שֶׁלִּי, וּמִנֵּיהּ אִתְנְטָרוּ שְׁאָר כַּרְמִין. הַשְׁתָּא נְטִירְנָא שְׁאָר כַּרְמִין בְּגִין כַּרְמִי שֶׁלִּי דְּלִהֱוִי נָטִיר בֵּינַיְיהוּ.</p>"],[9520012067,"<p>רִבִּי חִיָּיא וְרִבִּי יוֹסֵי הֲווֹ אָזְלֵי בְּאוֹרְחָא, כַּד מָטוּ חַד בֵּי חֲקַל, חָמוּ חַד דַּפְטִירָא דְּקִיטְפָא בֵּין אָרְחָא לִסְטַר יְמִינָא. אָמַר רִבִּי יוֹסֵי, עֲטִיפָא דְּקוּטְרָא בְּעַיְינִין שְׁכִיחַ, לֵית לָן רְשׁוּ לְמֵחמֵי בְּחֶדְוָותָא, מִיּוֹמָא דְּאִתְחֲרִיב בֵּי מַקְדְּשָׁא.</p>\n<p>פָּתַח וְאָמַר, (תהילים כ״ד:א׳) לַיְיָ' הָאָרֶץ וּמְלוֹאָהּ תֵּבֵל וְיוֹשְׁבֵי בָהּ, כֵּיוָן דְּאָמַר לַיְיָ' הָאָרֶץ וּמְלוֹאָהּ, אֲמַאי תֵּבֵל וְיוֹשְׁבֵי בָה, וְכִי תֵּבֵל לָאו מִן אַרְעָא הוּא. אֶלָּא הָכִי קָאָמַר, לַיְיָ' הָאָרֶץ וּמְלוֹאָהּ, דָּא אַרְעָא קַדִּישָׁא, דְּאִקְרֵי אֶרֶץ הַחַיִּים. תֵּבֵל וְיוֹשְׁבֵי בָהּ, דָּא שְׁאָר אַרְעָאן, כְּמָה דְאַתְּ אָמֵר (תהילים ט׳:ט׳) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק, דְּתֵבֵל בְּצֶדֶק תַּלְיָא, וְכֹלָּא חַד מִלָּה.</p>\n<p>רִבִּי חִיָּיא אָמַר, לַיְיָ' הָאָרֶץ וּמְלוֹאָהּ. הָאָרֶץ תִּינַח, וּמְלוֹאָהּ מַאי הִיא. אֶלָּא אִלֵּין נִשְׁמָתִין דְּצַדִּיקַיָּיא. תֵּבֵל וְיוֹשְׁבֵי בָהּ, תֵּבֵל: דָּא אַרְעָא דִּלְתַתָּא. וְיוֹשְׁבֵי בָהּ: אִלֵּין אִינּוּן בְּנֵי נָשָׁא. אָמַר רִבִּי יוֹסֵי, אִי הָכִי בְּמַאי אוֹקִימְנָא כִּי הוּא עַל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ. אָמַר לֵיהּ וַדַּאי הָכִי הוּא, דְּהַהִיא אֶרֶץ הַחַיִּים עַל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ, דְּכֻלְּהוּ נַפְקֵי מֵהַהוּא נָהָר עִלָּאָה דְּנָגִיד וְנָפִיק מֵעֵדֶן, וּבְהוּ אִתְתְּקָנַת לְאִתְעַטְּרָא בְּמַלְכָּא קַדִּישָׁא, וּלְמֵיזָן עָלְמִין. (ובגין כך)</p>\n<p>מִי יַעֲלֶה בְהַר יְיָ' וְגוֹ', נְקִי כַפַּיִם וּבַר לֵבָב אֲשֶׁר לֹא נָשָׂא לַשָּׁוְא נַפְשִׁי וְגוֹ'. נַפְשׁוֹ כְּתִיב, מַהוּ נַפְשִׁי וְנַפְשׁוֹ. אֶלָּא כֹּלָּא חַד מִלָּה, כְּמָה דְּאַתְּ אָמַר (עמוס ו) נִשְׁבַּע יְיָ' בְּנַפְשׁוֹ (שמואל א ב׳:ל״ה) כַּאֲשֶׁר בִּלְבָבִי וּבְנַפְשִׁי יַעֲשֶׂה. וְדָוִד מַלְכָּא אִתְאֲחִיד בְּהַהוּא לֵב וּבְהַהוּא נֶפֶשׁ, וְעַל דָּא לֹא נָשָׂא לַשָּׁוְא נַפְשׁוֹ.</p>"],[9520012068,"<p>עַד דַּהֲווֹ אָזְלֵי, אִעֲרָעוּ בְּחַד בַּר נָשׁ, וְאַנְפּוֹי מַלְיָין מַכְתְּשִׁין, וַהֲוָה קָם מִתְּחוֹת אִילָנָא חַד, אִסְתְּכָּלוּ בֵּיהּ, וְחָמוּ <Nonei></i>אַנְפּוֹי סוּמָקִין בְּאִינּוּן מַכְתְּשִׁין. אָמַר רִבִּי חִיָּיא מַאן אַנְתְּ. אָמַר לֵיהּ יוּדָאי אֲנָא. אָמַר רִבִּי יוֹסֵי חַטָּאָה הוּא, דְּאִי לָאו הָכִי, לָא אִתְרְשִׁימוּ אַנְפּוֹי בְּאִלֵּין מַרְעִין בִּישִׁין, וְאִלֵּין לָא אִקְרוּן יִסּוּרִין דְּאַהֲבָה. אָמַר רִבִּי חִיָּיא הָכִי הוּא וַדַּאי, דְּיִסוּרִין דְּאַהֲבָה מִתְחַפְּיָין אִינּוּן מִבְּנֵי נָשָׁא.</p>\n<p>תָּא חֲזֵי, דִּכְתִּיב אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ שְׂאֵת אוֹ סַפַּחַת אוֹ בַהֶרֶת. הָא ג' זִינִין הָכָא, וְכֻלְּהוּ אִקְרוּן נֶגַע צָרַעַת, הֲדָא הוּא דִכְתִיב וְהָיָה בְעוֹר בְּשָׂרוֹ לְנֶגַע צָרָעַת. מַאי נֶגַע צָרָעַת. סְגִירוּ. סְגִירוּ בְּכֹלָּא, וּכְתִיב וְהוּבָא אֶל אַהֲרֹן הַכֹּהֵן וְגוֹ'. אֲבָל אִינּוּן דְּיִתְחֲזוּן לְבַר כְּתִיב, וְרָאָהוּ הַכֹּהֵן וְטִמֵּא אוֹתוֹ. דְּהָא וַדַּאי אִינּוּן דְּיִתְחֲזוּן לְבַר בִּבְנֵי נָשָׁא, מִסִּטְרָא דִּמְסָאֲבָא קָא אַתְיָין, וְלָאו יִסּוּרִין דְּאַהֲבָה נִינְהוּ.</p>\n<p>אָמַר רִבִּי יוֹסֵי, מְנָא לָן. אָמַר רִבִּי חִיָּיא, דִּכְתִּיב, (משלי כ״ז:ה׳) טוֹבָה תּוֹכַחַת מְגוּלָה מֵאַהֲבָה מְסוּתָּרֶת. אֵי הַהִיא תּוֹכַחַת מֵאַהֲבָה (ס\"א אינהו תוכחת מאהבה כד איהי), מְסוּתָּרֶת מִבְּנֵי נָשָׁא. כְּגַוְונָא דָּא מַאן דְּאוֹכַח לְחַבְרֵיהּ בִּרְחִימוּתָא, בָּעֵי לְאַסְתְּרָא מִלּוֹי מִבְּנֵי נָשָׁא, דְּלָא יִכְסוֹף מִנַּיְיהוּ חַבְרֵיהּ, וְאִי מִלּוֹי אִינּוּן בְּאִתְגַּלְיָיא קָמֵי בְּנֵי נָשָׁא, לָאו אִינּוּן בִּרְחִימוּתָא.</p>\n<p>כַּךְ קוּדְשָׁא בְּרִיךְ הוּא כַּד אוֹכַח לְבַּר נָשׁ, בְּכֹלָּא אוֹכַח בִּרְחִימוּתָא, בְּקַדְמִיתָא מָחֵי לֵיהּ בְּגַרְמֵיהּ דִּלְגוֹ. אִי הָדָר בֵּיהּ, מוּטָב. וְאִי לָאו מָחֵי לֵיהּ תְּחוֹת תּוֹתְבֵיהּ, וְאִלֵּין (בעורו) אִקְרוּן יִסּוּרִין דְּאַהֲבָה, אִי הָדָר בֵּיהּ מוּטָב, וְאִי לָאו מָחֵי לֵיהּ בְּאִתְגַּלְיָיא בְּאַנְפּוֹי, קָמֵי כֹּלָּא, בְּגִין דְּיִסְתַּכְּלוּן בֵּיהּ, וְיִנְדְּעוּן דְּהָא חַטָּאָה אִיהוּ, וְלָאו רְחִימָא דְּמָארֵיהּ הוּא.</p>\n<p>אָמַר לוֹן הַהוּא בַּר נָשׁ, בְּקִיטְרָא דְּעֵיטָא חַד אֲתִיתוּן גַּבָּאי, וַדַּאי לָאו אַתּוּן אֶלָּא מֵאִינּוּן דְּדִיּוּרֵיהוֹן בְּבֵי רִבִּי שִׁמְעוֹן בֶּן יוֹחָאי דְּלָא דַּחֲלִין מִכֹּלָּא. אִי בָּנַי דְּאַתְיָין אֲבַתְרָאי יְקַטְרְגוּ בְּכוּ, אֵיךְ מִלַּיְיכוּ בְּאִתְגַּלְיָיא. אָמַר לֵיהּ אוֹרַיְיתָא הָכִי הוּא, דִּכְתִּיב, (משלי א׳:כ״א) בְּרֹאשׁ הוֹמִיּוֹת תִּקְרָא בְּפִתְחֵי שְׁעָרִים בָּעִיר אֲמָרֶיהָ תֹאמֵר. וּמַה אִי בְּמִלֵּי דְּאוֹרַיְיתָא אֲנָן דַּחֲלֵי מִקָּמָּךְ, הָא נִשְׁתְּכַח בְּכִסּוּפָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. וְלֹא עוֹד, אֶלָּא דְּאוֹרַיְיתָא בָּעֵי צָחוּתָא. פָּתַח הַהוּא גַּבְרָא וְאָמַר (מיכה ז׳:י״ח) מִי אֵל כָּמוֹךָ נוֹשֵׂא עָוֹן וְגוֹ'. אָרִים יְדוֹי וּבָכָה. אַדְּהָכִי מָטוּן בְּנוֹי. אָמַר בְּרֵיהּ זְעֵירָא סִיַּיעְתָּא דִּשְׁמַיָּיא הָכָא.</p>"],[9520012069,"<p>פָּתַח וְאָמַר (קהלת ז׳:ט״ו) אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי יֵשׁ צַדִּיק אוֹבֵד בְּצִדְקוֹ וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ. הַאי קְרָא אוֹלִיפְנָא בֵּי רִבִּי דּוֹסְתָּאי סָבָא, דְּהֲוָה אָמַר מִשְּׁמֵיהּ דְּרִבִּי יֵיסָא סָבָא. אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי, וְכִי שְׁלֹמֹה מַלְכָּא דְּהֲוָה חַכִּים עַל כֹּלָּא, אֵיךְ אָמַר הָכִי דְּאִיהוּ חָמָא כֹּלָּא בְּזִמְנָא דְּאִיהוּ אָזִיל בַּחֲשׁוֹכֵי עָלְמָא דְּהָא כָּל מַאן דְּאִשְׁתְּדַל בַּחֲשׁוֹכֵי עָלְמָא, לָא חָמֵי מִדִי, וְלָא יָדַע מִדִי.</p>\n<p>אֶלָּא הָכִי אִתְּמַר, בְּיוֹמוֹי דִּשְׁלֹמֹה מַלְכָּא, קַיְּימָא סִיהֲרָא בְּאַשְׁלְמוּתָא, וְאִתְחַכָּם שְׁלֹמֹה עַל כָּל בְּנֵי עָלְמָא, וּכְדֵין חָמָא כֹּלָּא, וְיָדַע כֹּלָּא. וּמַאי חָמָא. חָמָא כֹּ\"ל, דְּלָא אַעְדֵּי מִן סִיהֲרָא. וַהֲוָה נָהִיר לָהּ שִׁמְשָׁא (ס\"א ליה כשמשא). הֲדָא הוּא דִכְתִיב אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי. מַאן הֶבְלִי. דָּא סִיהֲרָא דְּאִתְכְּלִילַת מִן כֹּלָּא, מִן מַיָּא וְאֶשָּׁא וְרוּחָא כַּחֲדָא. כְּהֶבֶל דְּנָפִיק מִן פּוּמָא, דְּכָלִיל מִכֹּלָּא.</p>\n<p>וְהוּא חָמָא כֹּ\"ל, בְּהַהוּא הֶבֶל דִּילֵיהּ, דְּאָחִיד בֵּיהּ. יֵשׁ צַדִּיק אוֹבֵד בְּצִדְקוֹ, תָּא חֲזֵי, בְּזִמְנָא דְּאַסְגִּיאוּ זַכָּאִין בְּעָלְמָא, הַאי כֹּ\"ל לָא אַעְדֵּי מִן סִיהֲרָא לְעָלְמִין, וְהַאי כֹּ\"ל נָטַל כָּל מְשַׁח וּרְבוּ וְחֵדוּ דִּלְעֵילָּא, וְאִתְמְלֵּי (ס\"א ידוי ורוי) וְחַדֵּי וְרַבֵּי, בְּגִין לְאִזְדַּוְּוגָא בְּסִיהֲרָא, וְהוּא רָוַוח בְּגִינָהּ.</p>\n<p>וּבְזִמְנָא דְּאַסְגִּיאוּ חַיָּיבִין בְּעָלְמָא, וְסִיהֲרָא אִתְחַשְּׁכַת, כְּדֵין צַדִּיק אוֹבֵד בְּצִדְקוֹ, צַדִיק נֶאֱבַד לָא כְּתִיב, אֶלָּא צַדִּיק אוֹבֵד, דְּהָא לָא אִתְחֲזֵי (נ\"א אתחבר) בְּסִיהֲרָא, וְלָא נָטִיל מְשַׁח וּרְבוּ וְחֵדוּ לְמַלְיָּא לָהּ, וּלְאִזְדַּוְּוגָא עִמָּהּ. וְעַל דָּא צַדִיק אוֹבֵד, בְּצִדְקוֹ, דָּא סִיהֲרָא, דִּבְגִין סִיהֲרָא דְּלָא אִשְׁתְּכַחַת לְאִזְדַּוְּוגָא עִמֵּיהּ, הוּא אָבִיד, דְּלָא שָׁאִיב מֵחֵידוּ כְּמָה דְּהֲוָה עָבִיד. וּכְדֵין כָּל סְטָר שְׂמָאלָא אִתְּעַר, וְחַיָּיבִין מַאֲרִיכִין בְּשַׁלְוָה <Nonei></i>בְּעָלְמָא, הֲדָא הוּא דִּכְתִּיב, וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ. מַאי בְּרָעָתוֹ בְּהַהוּא סְטָר (נ\"א בההיא רעה) דְּאִתְדְּבַק בֵּיהּ.</p>\n<p>תּוּ יֵשׁ צַדִּיק אוֹבֵד בְּצִדְקוֹ, דְּכַד חַיָּיבִין סְגִיאוּ בְּעָלְמָא, וְדִינָא תַּלְיָא (בחובייהו) צַדִּיק אוֹבֵד בְּצִדְקוֹ, אִיהוּ אִתְּפַס בְּחוֹבַיְיהוּ, כְּגוֹן אַבָּא דְּאִתְפַּס בְּחוֹבַיְיהוּ דִּבְנֵי מָאתֵיהּ, דַּהֲווֹ כֻּלְּהוּ חֲצִיפִין (לגביה), וְהוּא לָא אַסְהִיד בְּהוּ וְלָא אַכְסִיף לְהוּ לְעָלְמִין, וּמָחֵי בִּידָן, דְּלָא נִתְגְּרֵי בְּהוּ בְּרַשִׁיעַיָּא (נ\"א ולא מחי בידיהון דלא מתגרו בהו). וַהֲוָה אָמַר לָן, (תהילים ל״ז:א׳) לְדָוִד אַל תִּתְחַר בַּמְּרֵעִים אַל תְּקַנֵּא בְּעוֹשֵׂי עַוְלָה. אָמַר אֲבוּי, וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא אַעְנִישׁ לִי בְּדָא, דְּהָא הֲוָה רְשׁוּ בִּידִי לִמְחֳאָה בִּידַיְיהוּ, וְלָא עֲבָדִית, וְלָא אַכְסִיפְנָא (נ\"א אוכיחנא) לְהוּ, לָא בִּטְמִירוּ, וְלָא בְּאִתְגַּלְיָא.</p>\n<p>תּוּ פָּתַח בְּרֵיהּ אָחֳרָא וְאָמַר, (בראשית ב׳:ז׳) וַיִּיצֶר יְיָ' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה וְגוֹ'. וַיִּיצֶר יְיָ' אֱלֹהִים, בִּתְרֵי יוֹדִין, בִּתְרֵין יִצְרִין, יֵצֶר טוֹב וְיֵצֶר רָע, חַד לָקֳבֵל מַיָּא, וְחַד לָקֳבֵל אֶשָּׁא. יְיָ' אֱלֹהִים, שֵׁם מָלֵא. אֶת הָאָדָם, כָּלִיל דְּכַר וְנוּקְבָּא. עָפָר מִן הָאֲדָמָה, דָּא עַפְרָא דְּאַרְעָא קַדִּישָׁא, דְּמִתַּמָּן אִתְבְּרֵי, וְהוּא אֲתַר דְּבֵי מַקְדְּשָׁא.</p>"],[9520012070,"<p>וַיִפַּח בְּאַפָּיו נִשְׁמַת חַיִּים, דָּא נִשְׁמְתָא קַדִּישָׁא, דְּאִתְמַשְּׁכָא מֵאִינּוּן חַיִּים דִּלְעֵילָּא. וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה, אָדָם אִתְכְּלִיל בְּנַפְשָׁא קַדִּישָׁא, מֵחַיָּה עִלָּאָה. דְּאַפִּיקַת אַרְעָא דִּכְתִּיב, (בראשית א׳:כ״ד) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, נֶפֶשׁ דְּהַהִיא חַיָּה עִלָּאָה.</p>\n<p>תָּא חֲזֵי, בְּכָל זִמְנָא דְּהַאי נִשְׁמְתָא קַדִּישָׁא, אִתְדַּבְּקַת בֵּיהּ בְּבַר נָשׁ. רְחִימָא הוּא דְּמָארֵיהּ. כַּמָה נְטוּרִין נַטְרִין לֵיהּ מִכָּל סִטְרִין, רְשִׁימָא הוּא לְטָב לְעֵילָּא וְתַתָּא, וּשְׁכִינְתָּא קַדִּישָׁא שַׁרְיָא עֲלוֹי.</p>\n<p>וּבְזִמְנָא דְּאִיהוּ אַסְטֵי אָרְחוֹי, שְׁכִינְתָּא אִסְתְּלָקַת מִנֵּיהּ, וְנִשְׁמְתָא קַדִּישָׁא לָא אִתְדְּבָקַת בֵּיהּ. וּמִסִּטְרָא דְּחִוְיָא בִּישָׁא תַּקִּיפָא, אִתְּעַר רוּחָא חַד, דְּשָׁט וְאָזִיל בְּעָלְמָא, דְּלָא שַׁרְיָא אֶלָּא בַּאֲתַר דִּקְדוּשָּׁה עִלָּאָה אִסְתְּלַּק מִתַּמָּן. וּכְדֵין אִסְתְּאַב בַּר נָשׁ, וְאִתְפְּגִים בִּבְשָׂרֵיהּ, בְּחֵיזוּ דְּאַנְפּוֹי בְּכֹלָּא.</p>\n<p>וְתָּא חֲזֵי, בְּגִין דְּהַאי נֶפֶשׁ חַיָּה אִיהִי קַדִּישָׁא עִלָּאָה, כַּד אַרְעָא קַדִּישָׁא מַשְׁכָא לָהּ, וְאִתְכְּלִילַת בְּגַוָּוה, כְּדֵין קָרֵינָן לָהּ נְשָׁמָה. וְדָא הִיא דְּסַלְּקָא לְעֵילָּא, וּמְמַלְּלָא קָמֵי מַלְכָּא קַדִּישָׁא, וְעַיְילָא בְּכָל תַּרְעִין, וְלֵית דְּיִמְחֵי בִּידָהָא. וְעַל דָּא אִתְקְרֵי רוּחָא מְמַלְּלָא, דְּהָא כָּל שְׁאָר נַפְשָׁתָא לֵית לוֹן רְשׁוּ לְמַלְּלָא קָמֵי מַלְכָּא, בַּר הַאי.</p>\n<p>וְעַל דָּא אוֹרַיְיתָא אַכְרִיזַת וְאַמְרַת, (תהילים ל״ד:י״ד) נְצוֹר לְשׁוֹנְךָ מֵרָע וְגוֹ', וּכְתִיב (משלי כ״א:כ״ג) שׁוֹמֵר פִּיו וּלְשׁוֹנוֹ וְגוֹ', בְּגִין דְּאִי שִׁפְוָותֵיהּ וְלִישָׁנֵיהּ מְמַלְּלָן מִלִּין בִּישִׁין, אִינּוּן מִלִּין סַלְּקִין לְעֵילָּא, וּבְשַׁעֲתָא דְּסַלְּקִין, כֹּלָּא מַכְרִיזִין וְאָמְרִין אִסְתֵּלָקוּ מִסּוֹחֲרָנֵיהּ דְּמִלָּה בִּישָׁא דִּפְלַנְיָא, פְּנוּן אֲתַר לְאָרְחֵיהּ דְּחִוְיָא תַּקִּיפָא. כְּדֵין נִשְׁמְתָא קַדִּישָׁא אִתְעַבְּרָא מִנֵּיהּ וְאִסְתְּלָּקַת, וְלָא יַכְלָא לְמַלְּלָא, כְּמָה דְאַתְּ אָמֵר (תהילים ל״ט:ג׳) נֶאֱלַמְתִּי דּוּמִיָּה הֶחֱשֵׁיתִי מִטּוֹב.</p>\n<p>וְהַהִיא נִשְׁמְתָא סַלְּקָא בְּכִסּוּפָא, בְּעָאקוּ דְּכֹלָּא, וְלָא יָהֲבִין לָהּ אֲתַר כְּמִלְּקַדְּמִין. וְעַל דָּא כְּתִיב, שׁוֹמֵר פִּיו וּלְשׁוֹנוֹ שׁוֹמֵר מִצָּרוֹת נַפְשׁוֹ. נַפְשׁוֹ וַדַּאי הַהִיא דַּהֲוַת מְמַלְּלָא, אִתְעָבִידַת מַשְׁתּוּקָא, בְּגִין מִלּוּלָא בִּישָׁא. וּכְדֵּין חִוְיָא אִזְדְּמַן, דְּכֹלָּא לְאַתְרֵיהּ אִתְהַדָּר, וְכַד הַהִיא מִלָּה בִּישָׁא סַלְּקָא בְּאוֹרְחִין יְדִיעָן, וְשָׁארִי קַמֵּיהּ דְּחִוְיָא תַּקִּיפָא, כַּמָה רוּחִין מִתְעָרִין בְּעָלְמָא, וְרוּחָא נַחְתָּא מֵהַהוּא סִטְרָא, וְאַשְׁכַּח דְּהַהוּא בַּר נָשׁ אִתְּעַר לֵיהּ בְּמִלָּה בִּישָׁא, וְהָא רוּחָא מְמַלְּלָא קַדִּישָׁא אִתְעַבְּרָא מִנֵּיהּ, כְּדֵין שַׁרְיָא עֲלוֹי וְסָאִיב לֵיהּ, וּכְדֵין הוּא סָגִיר.</p>"],[9520012071,"<p>כְּמָה דְּעוֹנְשָׁא דְּהַאי בַּר נָשׁ בְּגִין מִלָּה בִּישָׁא. כַּךְ עוֹנְשֵׁיהּ בְּגִין מִלָּה טָבָא, דְּקָאתֵי לִידֵיהּ, וְיָכִיל לְמַלְּלָא, וְלָא מַלִּיל. בְּגִין דְּפָגִים לְהַהוּא רוּחָא מְמַלְּלָא, דְּהִיא אִתְתְּקָנַת לְמַלְּלָא לְעֵילָּא, וּלְמַלְּלָא לְתַתָּא, וְכֹלָּא בִּקְדוּשָּׁה. כָּל שֶׁכֵּן אִי עַמָּא אַזְלִין בְּאוֹרְחָא עֲקִימָא, וְהוּא יָכִיל לְמַלְּלָא לְהוּ וּלְאוֹכָחָא לְהוּ, וְשָׁתִיק וְלָא מַלִּיל, כַּמָה דַּאֲמֵינָא דִּכְתִּיב, נֶאֱלַמְתִּי דוּמִיָּה הֶחֱשֵׁיתִי מִטּוֹב וּכְאֵבִי נֶעְכָּר. נֶעְכָּר בְּמַכְתְּשִׁין דִּמְסָאֲבוּתָא, וְדָא הוּא דְּאָמַר דָּוִד <Nonei></i>מַלְכָּא אַלְקֵי בְּהַאי, וְאִתְפְּנֵי מִנֵּיהּ, דִּכְתִּיב, (תהילים כ״ה:ט״ז) פְּנֵה אֵלַי וְחָנֵּנִי. מַהוּ פְּנֵה אֵלַי. כְּמָה דְאַתְּ אָמֵר (במדבר י״ב:י׳) וַיִּפֶן אַהֲרֹן. נַחְתּוּ רִבִּי חִיָּיא וְרִבִּי יוֹסֵי, וּנְשָּׁקוּהוּ. אִזְדָּוָּוגוּ כַּחֲדָא כָּל הַהוּא אוֹרְחָא, קָרָא רִבִּי חִיָּיא עָלַיְיהוּ, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם.</p>\n<p>(ויקרא י״ג:ט׳) נֶגַע צָרָעַת כִּי תִהְיֶה בְּאָדָם וְהוּבָא אֶל הַכֹּהֵן. אָמַר רִבִּי יוֹסֵי, הַאי נֶגַע, כָּל גַּוְונִין דִּילֵיהּ אִתְּעֲרוּ בְּהוּ חַבְרַיָּיא, וְכַהֲנָא הֲוָה יָדַע בְּהוּ לְדַכְיָא וּלְמְסָאֲבָא, הֲוָה יָדַע, אִינּוּן דַּהֲווֹ יִסּוּרִין דִּרְחִימוּתָא, אוֹ אִינּוּן דְּאִשְׁתְּכָחוּ בְּמַאן דְּמָאִיס בֵּיהּ מָארֵיהּ וְרָחִיק בֵּיהּ, דְּהָא לְפוּם אָרְחוֹי דְּבַּר נָשׁ גָּרִים נֶגַע בְּעָלְמָא.</p>\n<p>כְּתִיב (תהילים קמ״א:ד׳) אַל תַּט לִבִּי לְדָבָר רָע לְהִתְעוֹלֵל עֲלִילוֹת בְּרֶשַׁע, מִכָּאן תָּנֵינָן בְּאָרְחָא דְּבַּר נָשׁ בָּעֵי לְמֵיהַךְ בָּהּ מַדְבְּרִין לֵיהּ. אָמַר רִבִּי יִצְחָק, הַאי קְרָא קַשְׁיָא, וְכִי קוּדְשָׁא בְּרִיךְ הוּא אַסְטֵי לֵיהּ לְבַר נָשׁ לְמֵהַךְ בְּאֹרַח חַטָּאָה, וּלְמֶעְבַּד עוֹבָדִין בִּישִׁין, אִי הָכִי לֵית דִּינָא בְּעָלְמָא דָּא, וְלָא בְּעָלְמָא דְּאָתֵי, וְאוֹרַיְיתָא לָא אִתְתְּקָנַת, דִּכְתִּיב בָּהּ אִם תִּשְׁמַע וְאִם לֹא תִּשְׁמַע.</p>\n<p>אֶלָּא דָּוִד אַזְהַר לְלִבֵּיהּ, לְדַבְּרָא לֵיהּ בְּאוֹרַח קְשׁוֹט, כְּמָה דְאַתְּ אָמֵר (דברים ד׳:ל״ט) וַהֲשֵׁבוֹתָ אֶל לְבָבֶךָ. מַאי וַהֲשֵׁבוֹתָ. אֶלָּא זִמְנָא חַד, וּתְרֵין, וּתְלַת, לְאַהְדָרָא לָקֳבְלֵיהּ, וּלְדַבְּרָא, וּלְאַזְהָרָא לֵיהּ. וְהָכִי קָאָמַר לֵיהּ, אַל תַּט לִבִּי לְדָבָר רָע, לְלִבֵּיהּ קָאָמַר דָּוִד (כלומר) אַל תַּט לְפוּם אוֹרְחוֹי דְּבַּר נָשׁ (נ\"א והכי קאמר ליה, לבי, אל תט לדבר רע) דְּהָא דָּבָר רָע גָּרִים נֶגַע בְּעָלְמָא, וְדִינָא שַׁרְיָא בְּעָלְמָא, וְהַיְינוּ נֶגַע צָרַעַת.</p>\n<p>נֶגַע צָרַעַת, הָא אִתְּעֲרוּ חַבְרַיָּיא, אֲבָל צָרַעַת כְּתַרְגּוּמוֹ, אָמַר רִבִּי יְהוּדָה, מַאי כְּתַרְגּוּמוֹ. סְגִירוּ, דְּסָגִיר וְלָא פָּתַח, וְכַד סָגִיר הוּא וְלָא פָּתַח, נֶגַע הוּא דְּאִקְּרֵי. רִבִּי יוֹסֵי אָמַר, דְּלָא מִסְתַּפְּקִין אֲבָהָן, כָּל שֶׁכֵּן בְּנִין. וְהַיְינוּ דִּכְתִּיב נֶגַע צָרַעַת כִּי תִהְיֶה בְּאָדָם, בָּאָדָם מַמָּשׁ, וּמִכָּאן נָחִית לְמַאן דְּנָחִית, אִשְׁתְּכַח נֶגַע לְכֹלָּא, מֵהַהוּא סְגִירוּ.</p>\n<p>אָמַר רִבִּי יִצְחָק, וַדַּאי דָּא הוּא רָזָא דְּמִלָּה, דִּכְתִּיב, (איכה ב׳:ז׳) נִאֵר מִקְדָּשׁוֹ. מַאי טַעְמָא. מִשּׁוּם דִּבְנֵי עָלְמָא גָּרְמוּ הַאי, דִּכְתִּיב, (במדבר י״ט:כ׳) אֶת מִקְדַּשׁ יְיָ' טִמֵּא, טִמֵּא מַמָּשׁ. אָמַר רִבִּי אֶלְעָזָר, טִמֵּא, מִשּׁוּם דְּאִסְתַּלְקַת (שכינתא מניה) מַאן דְּאִסְתַּלָּק, וְחִוְיָא תַּקִּיפָא שַׁרְיָא, וְאָטִיל זוּהֲמָא, וְסָאִיב לְמַאן דְּסָאִיב, וְכֻלְּהוּ בְּגִין חוֹבֵי עָלְמָא.</p>"],[9520012072,"<p>תָּאנֵי, כַּד שָׁאֲרִי חִוְיָא (תקיפא) לְאִתְגַּלָּאָה, מִסְתַּלְּקִין סַמְכִין וּבִנְיָינִין וּמִתְעַבְּרִין, וְאָתֵי חִוְיָא תַּקִּיפָא וְאָטִיל זוּהֲמָא, וּכְדֵין אִשְׁתְּכַח מַקְדְּשָׁא מִסְאָב, מַאן מַקְדְּשָׁא. כְּמָה דְּאִתְּמַר (ויקרא י״ד:ל״ד) וְנָתַתִּי נֶגַע צָרַעַת בְּבֵית אֶרֶץ אֲחוּזָּתְכֶם. וּכְתִיב (בראשית ג׳:א׳) וְהַנָּחָשׁ הָיָה עָרוּם מִכֹּל חַיַּת הַשָּׂדֶה אֲשֶׁר עָשָׂה יְיָ' אֱלֹהִים וַיֹּאמֶר אֶל הָאִשָּׁה. אֶל הָאִשָּׁה מַמָּשׁ, דְּאֲתַר מַקְדְּשָׁא אִתְאֲחִיד בְּגַוָּוהּ, וְהַיְינוּ אֶת מִקְדַּשׁ יְיָ' טִמֵּא בְּגִין חוֹבוֹי, מִשּׁוּם דְּאִתְגַּלְיָא חִוְיָא תַּקִּיפָא.</p>\n<p>מַאן חוֹבוֹי. דָּא לִישָׁנָא בִּישָׁא, דִּבְגִין לִישָׁנָא בִּישָׁא, חִוְיָא אִזְדָּמַן, בֵּין לְעֵילָּא בֵּין לְתַתָּא, דִּכְתִּיב, (במדבר כ״א:ו׳) וַיְשַׁלַּח יְיָ' בָּעָם אֵת הַנְּחָשִׁים הַשְּׂרָפִים. הַשׂוֹרְפִים אוֹ הַשְׂרוּפִים לָא כְּתִיב, אֶלָּא הַשְּׂרָפִים, מַאן שְׂרָפִים. דִּכְתִּיב (תהילים ע״ד:י״ג) רָאשֵׁי תַנִּינִים (תרי, חד אתאחיד לעילא, וחד לתתא) (ס\"א תרי, חד אתחזרו לזמנין) וּכְתִיב (ישעיהו ו׳:ב׳) שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ, מִמַּעַל לוֹ וַדַּאי, כְּמָה דְאַתְּ אָמֵר (איוב א) לְהִתְיַצֵּב עַל יְיָ', וּכְדֵין סְגִירוּ בְּכֹלָּא, וְלֵית מַאן דְּפָתַח, וְעַל דָּא כְּתִיב (משלי ל׳:כ׳) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת אָכְלָה וּמָחֲתָה פִיהָ וְגוֹ', מַאי מְנָאָפֶת. מְנָאָפֶת מַמָּשׁ וַדַּאי, אָכְלָה וּמָחֲתָה פִיהָ וְאָמְרָה לֹא פָעַלְתִּי אָוְן.</p>\n<p>אָמַר רִבִּי חִיָּיא אָמַר רִבִּי יִצְחָק, בִּרְעוּתָא דְּכֹלָּא לָא אִשְׁתְּכַח לְתַתָּא, אֶלָּא בְּגִין דְּאִשְׁתְּכַח לְעֵילָּא. וּלְעֵילָּא לָא אִשְׁתְּכַח, אֶלָּא כַּד אִשְׁתְּכַח לְתַתָּא בְּחוֹבֵי עָלְמָא, דְּיַלְפֵינָן דְּכֹלָּא תַּלְיָיא הַאי בְּהַאי, וְהַאי בְּהַאי.</p>"],[9520012073,"<p>(ויקרא י״ג:מ׳) וְאִישׁ כִּי יִמָּרֵט רֹאשׁוֹ וְגוֹ'. רִבִּי חִיָּיא פָּתַח וְאָמַר (קהלת ב׳:י״ג) וְרָאִיתִי אָנִי שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה מִן הַסִּכְלוּת וְגוֹ', בְּכַמָּה אֲתַר אִסְתַּכַּלְנָא בְּמִלּוֹי דִּשְׁלֹמֹה מַלְכָּא, וְאָשְׁגַּחְנָא בְּחָכְמְתָא <Nonei></i>סַגִּיאָה דִּילֵיהּ, וְאַסְתִּים מִלּוֹי בְּגוֹ, לְגוֹ הֵיכָלָא קַדִּישָׁא. הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, אֲמַאי אָמַר וְרָאִיתִי אָנִי, וְכִי שְׁאָר בְּנֵי עָלְמָא לָא יַדְעֵי וְלָא חָמָאן דָּא. אֲפִילּוּ מַאן דְּלָא יָדַע חָכְמְתָא מִן יוֹמוֹי, וְלָא אַשְׁגַּח בָּהּ, יָדַע הַאי שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה מִן הַסִּכְלוּת כִּיתְרוֹן הָאוֹר מִן הַחֹשֶׁךְ. וְהוּא שָׁבַּח גַּרְמֵיהּ וְאָמַר רָאִיתִי אָנִי.</p>\n<p>אֶלָּא הָכִי תָּאנָא, מַאן חַכִּים כִּשְׁלֹמֹה דִּבְשִׁבְעָה דַּרְגִּין דְּחָכְמָה אִתְקְרֵי כְּגַוְונָא דִּלְעֵילָּא. שִׁיתָא יוֹמִין לְעֵילָּא, שְׁבִיעָאָה עִלָּאָה עָלַיְיהוּ. שִׁיתָא יוֹמִין לְתַתָּא, שְׁבִיעָאָה עָלַיְיהוּ. שִׁיתָא דַּרְגִּין לְכוּרְסְיָיא, הוּא עַל כּוּרְסְיָיא, דִּכְתִּיב, (דברי הימים א כ״ט:כ״ג) וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא יְיָ' לְמֶלֶךְ. שִׁבְעָה כִּתְרִין דְּיוֹמִין לְעֵילָּא, וּכְדֵין לָקֳבְלֵיהוֹן שִׁבְעָה שְׁמָהָן לִשְׁלֹמֹה. לְאִתְחֲזָאָה בֵּיהּ חָכְמְתָא קַדִּישָׁא. וּבְגִין כָּךְ אִתְקְרֵי שֶׁבַע שְׁמָהָן: שְׁלֹמֹה. יְדִידְיָה. אָגוּר. בֶּן יָקֶה. לְמוּאֵל, אִיתִיאֵל, קֹהֶלֶת.</p>\n<p>וְאָמַר שִׁבְעָה הֲבָלִים. וּמַה דְּאִיהוּ חָמָא לָא חָמָא בַּר נָשׁ אָחֳרָא, וְכַד כָּנַשׁ חָכְמְתָא וְאִסְתַּלָּק בְּדַרְגִּין דְּחָכְמְתָא, אִקְרֵי קֹהֶלֶת. וְשִׁבְעָה הֲבָלִין אָמַר, לָקֳבֵיל ז' כִּתְרִין דִּלְעֵילָּא, וְכָל הֶבֶל קָלָא אִתְעָבִיד מִנֵּיהּ, וְעָלְמָא לָא מִתְקַיְּימָא אֶלָּא בַּהֶבֶל.</p>\n<p>וְתָאנָא מִשְּׁמֵיהּ דְּרַבִּי שִׁמְעוֹן, הֶבֶל אַפִּיק קָלָא בְּרוּחָא וּמַיָא דְּבֵיהּ, וְלֵית קָלָא אֶלָּא בַּהֶבֶל. וְתָאנָא בְּשִׁבְעָה הֲבָלִין אִתְקַיְּימִין עִלָּאִין וְתַתָּאִין. וְתָאנֵי רִבִּי יִצְחָק, תָּא חֲזֵי, דְּעַל הֶבֶל מִתְקַיֵּים עָלְמָא, דְּאִלְמָלֵא לָא הֲוָה הֲבָל דְּנָפִיק מִפּוּמָא, לָא אִתְקַיָּים בַּר נָשׁ אֲפִילּוּ שַׁעֲתָא חֲדָא.</p>\n<p>כְּגַוְונָא דָּא אָמַר שְׁלֹמֹה מִלּוֹי, דְּעָלְמָא מִתְקַיְּימָא בְּהוּ, דְּהַאי הֶבֶל דְּמִתְקַיֵים בֵּיהּ עָלְמָא. וְהַאי הֶבֶל דְּמִתְקַיֵים בֵּיהּ עָלְמָא, מֵהֲבָלִים דִּלְעֵילָּא קָאֲתֵי, הֲדָא הוּא דִכְתִיב הֲבֵל הֲבָלִים, הֲבֵל מֵהֲבָלִים דִּלְעֵילָּא. וְכָל מִלּוֹי הָכִי הֲווֹ. וּבַהֲבָלִים דִּלְעֵילָּא כְּתִיב, (דברים ח׳:ג׳) כִּי עַל כָּל מוֹצָא פִי יְיָ' יִחְיֶה הָאָדָם. מַאי מוֹצָא פִי יְיָ'. דָּא הֲבָלִים דִּלְעֵילָּא.</p>\n<p>וְתַנְיָא, וְרָאִיתִי אָנִי שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה מִן הַסִּכְלוּת. מִן הַסִּכְלוּת מַמָּשׁ, אָתֵי תּוֹעַלְתָּא לְחָכְמְתָא, דְּאִלְמָלֵא לָא אִשְׁתְּכַח שְׁטוּתָא בְּעָלְמָא, לָא אִשְׁתְּמוֹדְעָא חָכְמְתָא וּמִלּוֹי. (תיקון קכ\"ג ע\"א) וְתָאנָא חִיּוּבָא הוּא עַל בַּר נָשׁ דְּאוֹלִיף חָכְמְתָא, לְמֵילַף זְעֵיר מִן שְׁטוּתָא, וּלְמִנְדַּע לָהּ. בְּגִין דְּאָתֵי תּוֹעַלְתָּא לְחָכְמְתָא בְּגִינֵיהּ. כְּמָה דְּאַתְיָא תּוֹעַלְתָּא לִנְהוֹרָא מֵחֲשׁוֹכָא, דְּאִלְמָלֵא חֲשׁוֹכָא לָא אִשְׁתְּמוֹדַע נְהוֹרָא. וְלָא אַתְיָיא (נ\"א אתחזיא) תּוֹעַלְתָּא לְעָלְמָא מִנֵּיהּ.</p>\n<p>תָּנָא שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה, לַחָכְמָה סְתָם. דְּאָמַר רִבִּי שִׁמְעוֹן לְרִבִּי אַבָּא, תָּא חֲזֵי רָזָא דְּמִלָּה, לָא נָהִיר חָכְמְתָא דִּלְעֵילָּא, וְלָא אִתְנְהִיר, אֶלָּא בְּגִין שְׁטוּתָא דְּאִתְּעַר מֵאֲתַר אָחֳרָא, וְאִלְמָלֵא הַאי, נְהִירוּ וּרְבוּ סַגִיא וְיַתִּיר לָא הֲוָה (להוי), וְלָא אִתְחַזְיָא תּוֹעַלְתָּא דְּחָכְמְתָא. וּבְגִין שְׁטוּתָא אִתְנְהִיר יַתִּיר, וּנְהִירִין לֵיהּ יַתִּיר, הֲדָא הוּא דִכְתִיב שֶׁיֵּשׁ יִתְרוֹן לַחָכְמָה, לַחָכְמָה סְתָם, מִן הַסִּכְלוּת סְתָם. וְכַךְ לְתַתָּא, אִלְמָלֵא לָא הֲוָה שְׁטוּתָא שְׁכִיחַ בְּעָלְמָא, לָא הֲוִי חָכְמְתָא שְׁכִיחַ בְּעָלְמָא.</p>\n<p>וְהַיְינוּ דְּרַב הַמְנוּנָא סָבָא, כַּד הֲווֹ יַלְפִין מִנֵּיהּ חַבְרַיָּיא רָזֵי דְּחָכְמְתָא, הֲוָה מְסַדֵּר קָמַיְיהוּ פִּרְקָא דְּמִלֵּי דִּשְׁטוּתָא, בְּגִין דְּיֵיתֵי תּוֹעַלְתָּא לְחָכְמְתָא בְּגִינֵיהּ. הֲדָא הוּא דִכְתִיב (קהלת י׳:א׳) יָקָר מֵחָכְמָה וּמִכָּבוֹד סִכְלוּת מְעַט, מִשּׁוּם דְּהִיא תִּקּוּנָא דְּחָכְמְתָא, וִיקָרָא דְּחָכְמְתָא. וְעַל דָּא כְּתִיב, וְלִבִּי נוֹהֵג בַּחָכְמָה וְלֶאֱחוֹז בְּסִכְלוּת.</p>\n<p>רִבִּי יוֹסֵי אָמַר יָקָר מֵחָכְמָה וּמִכָּבוֹד, כְּלוֹמַר יְקָרָא דְּחָכְמְתָא וְנוֹי דִּילָהּ, וִיקָרָא דְּכָבוֹד דִּלְעֵילָּא, מַאי הִיא. סִכְלוּת מְעַט. זְעֵיר דִּשְׁטוּתָא אַחְזֵי וְגַלֵּי יְקָרָא דְּחָכְמְתָא וְכָבוֹד דִּלְעֵילָּא, יַתִּיר מִכָּל אָרְחִין דְּעָלְמָא.</p>\n<p>כְּיִתְרוֹן הָאוֹר מִן הַחֹשֶׁךְ, תּוֹעַלְתָּא דִּנְהוֹרָא לָא אַתְיָיא (נ\"א אתחזיא) אֶלָּא מִן חֲשׁוֹכָא. (ולעולם) תִּקּוּנָא דְּחִוָּורָא מַאי הִיא. אוּכָמָא, אִלְמָלֵא אוּכָמָא לָא אִשְׁתְּמוֹדַע חִוָּורָא, וּבְגִין אוּכָמָא, אִסְתָּלִיק חִוָּורָא וְאִתְיָקָר. אָמַר רִבִּי יִצְחָק, מָשָׁל לְמָתוֹק בְּמַר, דְּלָא יָדַע אֱינָשׁ טַעֲמָא דִּמְתִיקָא, עַד דְּטָעִים מְרִירָא, מַאן עָבִיד לְהַאי מְתִיקָא. הֶוִי אוֹמֵר הַאי מְרִירָא. וְהַיְינוּ דִּכְתִּיב, (קהלת ז׳:י״ד) גַּם אֶת זֶה לְעוּמַּת זֶה עָשָׂה הָאֱלֹהִים. וּכְתִיב <Nonei></i>(קהלת ז׳:י״ח) טוֹב אֲשֶׁר תֶּאֱחוֹז בָּזֶה וְגַם מִזֶּה אַל תָּנַּח יָדֶךָ.</p>"],[9520012074,"<p>תָּאנָא בְּכַמָּה דַּרְגִּין אִתְקְרֵי בַּר נָשׁ: אָדָם, גֶּבֶר, אֱנוֹשׁ, אִישׁ. גָּדוֹל שֶׁבְּכֻלָּם אָדָם. (משום) דִּכְתִּיב, (בראשית א׳:כ״ז) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ. וּכְתִיב (בראשית ט׳:ו׳) כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. וְלָא כְּתִיב, גֶּבֶר, אֱנוֹשׁ, אִישׁ. אָמַר רִבִּי יְהוּדָה, אִי הָכִי, וְהָא כְּתִיב (ויקרא א׳:ב׳) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַיְיָ'. (ולא גבר, אנוש, איש) מַאן בָּעֵי לְמִקְרַב קָרְבְּנָא. מַאן דְּאִיהוּ חַטָּאָה וּכְתִיב אָדָם.</p>\n<p>אָמַר רִבִּי יִצְחָק תָּא חֲזֵי, קִיּוּמָא דְּעָלְמָא דְּעִלָּאִין וְתַתָּאִין, הוּא קָרְבְּנָא. נַיְיחָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וּמַאן אִתְחֲזֵי לְמִקְרַב קַמֵּיהּ הַאי נַיְיחָא, הֶוִי אוֹמֵר הַאי אָדָם, דְּיַקִּירָא מִכֹּלָּא. אָמַר לֵיהּ אִי הָכִי, הָא כְּתִיב, אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ וְגוֹ', וְהָיָה בְעוֹר בְּשָׂרוֹ לְנֶגַע צָרָעַת. אָמַר לֵיהּ, לְהַאי בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְדַכָּאָה יַתִּיר מִכֹּלָּא, דְּמַאן דְּאִיהוּ בְּדַרְגָּא עִלָּאָה דְּכֻלְּהוּ, לָא לִיתִיב הָכֵי.</p>\n<p>וּבְגִין כַּךְ כְּתִיב בָּאָדָם, וְהוּבָא אֶל הַכֹּהֵן. וּבָא לָא כְּתִיב, אֶלָּא וְהוּבָא, דְּכָל מַאן דְּחָמֵי לֵיהּ, אִתְחַיָּיב בֵּיהּ לְאַקְרוֹבֵי קָמֵי כַּהֲנָא, דְּדִיּוּקְנָא קַדִּישָׁא לָא לֵיתִיב הָכִי. וּכְתִיב אִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בוֹ נָגַע וְגוֹ', וְאִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בְּעוֹר בְּשָׂרָם בֶּהָרוֹת וְגוֹ', וְלָא כְּתִיב בְּהוּ וְהוּבָא.</p>\n<p>אָמַר לֵיהּ, וְהָא כְּתִיב (במדבר י״ב:ג׳) וְהָאִישׁ מֹשֶׁה, (שמות ל״ב:א׳) כִּי זֶה מֹשֶׁה הָאִישׁ, אֲמַאי לָא אִקְרֵי אָדָם. אָמַר לֵיהּ מִשּׁוּם דְּאִקְרֵי עֶבֶד לְמַלְכָּא, דִּכְתִּיב, (במדבר י״ב:ז׳) לֹא כֵן עַבְדִּי מֹשֶׁה. (יהושע א׳:ב׳) מֹשֶׁה עַבְדִּי. וְאוֹף הָכִי אִקְרֵי אִישׁ לְגַבֵּי אָדָם דִּלְעֵילָּא. אָמַר לֵיהּ אִי הָכִי, וְהָא כְּתִיב (שמות ט״ו:ג׳) יְיָ' אִישׁ מִלְחָמָה, וְלָא כְּתִיב אָדָם. אָמַר לֵיהּ (תהלים כה) סוֹד יְיָ' לִירֵאָיו. אָמַר לֵיהּ אִי הָכִי אֲנָא בֵּינַיְיהוּ (ס\"א יתיב) אָתִיבוּ בְּכֹלָּא, וּבַאֲתַר דָּא לָא זָכִינָא.</p>\n<p>אָמַר לֵיהּ זִיל לְרִבִּי אַבָּא, דַּאֲנָא אוֹלִיפְנָא מִנֵּיהּ עַל מְנָת דְּלָא לְגַלָּאָה. אָזַל לְגַבֵּי דְּרִבִּי אַבָּא, אַשְׁכָּחֵיהּ דְּהֲוָה דָּרִישׁ וְאָמַר, אֵימָתַי אִתְקְרֵי שְׁלֵימוּתָא דִּלְעֵילָּא (נ\"א דכלא), כַּד יָתִיב קוּדְשָׁא בְּרִיךְ הוּא בְּכוּרְסְיָּיא. וְעַד דְּלָא יָתִיב בְּכוּרְסְיָּיא, לָא אִשְׁתְּכַח שְׁלֵימוּתָא. דִּכְתִּיב, (יחזקאל א׳:כ״ו) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה, מַשְׁמַע דִּכְתִּיב אָדָם, דְּהוּא כְּלָלָא, וּשְׁלֵימוּתָא דְּכֹלָּא. אָמַר רִבִּי יְהוּדָה, בְּרִיךְ רַחֲמָנָא דְּאַשְׁכָּחִית לָךְ בְּהַאי. אָמַר לֵיהּ אִי הָכִי הָא כְּתִיב (שמות ט״ו:ג׳) יְיָ' אִישׁ מִלְחָמָה, וְלָא כְּתִיב אָדָם. אָמַר לֵיהּ יָאוּת שָׁאַלְתָּ.</p>\n<p>תָּא חֲזֵי, הָתָם לָא אִשְׁתְּכַח שְׁלֵימוּתָא דְּכֹלָּא, וּבְגִּינֵי כַּךְ אִקְרֵי אִישׁ. אֲבָל הָכָא, שְׁלֵימוּתָא דְּכֹלָּא, וּכְלָלָא דְּכֹלָּא, בְּגִין כַּךְ אִקְרֵי אָדָם. קָארֵי עָלֵיהּ (תהילים קי״ט:ע״ב) טוֹב לִי תוֹרַת פִּיךָ מֵאַלְפֵי זָהָב וָכָסֶף.</p>\n<p>תּוּ אָמַר לֵיהּ, כְּתִיב (תהלים לו) אָדָם וּבְהֵמָה, וְלָא כְּתִיב אִישׁ וּבְהֵמָה. אָמַר לֵיהּ וְלָא. וְהָכְּתִיב (שמות י״א:ז׳) לְמֵאִישׁ וְעַד בְּהֵמָה. אֲבָל מַה דִּכְתִּיב אָדָם וּבְהֵמָה, כְּמָה דִּכְתִּיב, (מלכים א ה׳:י״ג) מִן הָאֶרֶז אֲשֶׁר בַּלְּבָנוֹן עַד הָאֵזוֹב אֲשֶׁר יוֹצֵא בַּקִּיר. אוֹרְחֵיהּ דִּקְרָא הוּא, דְּנָקִיט עִלָּאָה מְכֻּלְּהוּ, וְנָמִיךְ מְכֻּלְּהוּ. אוּף הָכָא עִלָּאָה דְּכֹלָּא, אָדָם, וְנָמִיךְ מִכֹּלָּא בְּהֵמָה.</p>\n<p>אָמַר לֵיהּ וְהָא כְּתִיב (בראשית ב׳:ה׳) וְאָדָם אַיִן לַעֲבוֹד אֶת הָאֲדָמָה. אָמַר לֵיהּ, תָּא חֲזֵי, דְּכָל מַה דִּי בְּעָלְמָא לָא הֲוִי אֶלָּא בְּגִינֵיהּ דְּאָדָם, וְכֻלְּהוּ בְּגִינֵיהּ מִתְקַיְּימֵי, וְלָא אִתְחֲזִיאוּ בְּעָלְמָא, וְכֻלְּהוּ אִתְעַכְּבוּ עַד דְּיֵיתֵי הַהוּא דְּאִקְרֵי אָדָם. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ה׳) וְכֹל שִׁיחַ הַשָּׂדֶה טֶרֶם יִהְיֶה בָאָרֶץ וְגוֹ'. טֶרֶם: עַד לָא, כְּתַרְגּוּמוֹ. מִשּׁוּם דְּדִיּוּקְנָא עִלָּאָה לָא אִתְחֲזֵי, הֲדָא הוּא דִכְתִיב וְאָדָם אַיִן, כְּלוֹמַר, כֻּלְּהוּ אִתְעַכְּבוּ בְּגִינֵיהּ דְּהַאי דִּיּוּקְנָא, עַד דְּאִתְחֲזֵי. וּבְגִין כָּךְ לָא אִתְחֲזֵי (נ\"א אתברי) הַאי דִּיּוּקְנָא, אֶלָּא בְּדִיּוּקְנָא דְּאִתְחֲזֵי לֵיהּ, הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ז׳) וַיִּיצֵר יְיָ' אֱלֹהִים אֶת הָאָדָם, בְּשֵׁם מָלֵּא. כְּמָה דְּאוֹקִימְנָא, דְּאִיהוּ שְׁלֵימוּתָא דְּכֹלָּא, וּכְלָלָא דְּכֹלָּא.</p>\n<p>תָּאנָא, בַּשִּׁשִּׁי נִבְרָא אָדָם, בְּשָׁעָה שֶׁנִּשְׁלַם הַכִּסֵא. וְנִקְרָא כִּסֵּא, דִּכְתִּיב, (מלכים א י׳:י״ט) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. וּלְפִיכָךְ נִבְרָא הָאָדָם בַּשִּׁשִּׁי, שֶׁהוּא רָאוּי לֵישֵׁב עַל הַכִּסֵּא. וְתָאנָא כֵּיוָן דְּנִבְרָא אָדָם אִתְתָּקַּן כֹּלָּא, וְכָל מַה דִּלְעֵילָּא וְתַתָּא, וְכֹלָּא אִתְכְּלִיל בָּאָדָם.</p>\n<p>תַּנְיָא אָמַר רִבִּי יוֹסֵי, כְּתִיב (יחזקאל א׳:י׳) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, כְּלָלָא דְּכֹלָּא, וְכֹלָּא כְּלִילָן בְּהַאי דִּיּוּקְנָא. אָמַר רִבִּי יְהוּדָה וְהָא כְּתִיב (יחזקאל א׳:י׳) וּפְנֵי אַרְיֵה אֶל הַיָמִין לְאַרְבַּעְתָּם, וּפְנֵי שׁוֹר <Nonei></i>מֵהַשְּׂמֹאל לְאַרְבַּעְתָּן, אָמַר לֵיהּ כֹּלָּא אַפֵּי אָדָם הֲווֹ, וּבְהַהוּא דִּיּוּקְנָא דְּאָדָם, אִתְחַזְיָין כָּל גַּוְונִין וְכָל דִּיוּקְנִין. כְּמָה דְּתָנֵינָן אַנְפּוֹי אַנְפֵּי נִשְׁרָא, לָא דְּהוּא נִשְׁרָא, אֶלָּא דְּאִתְחֲזֵי בְּדִיּוּקְנָא דְּאָדָם, מִשּׁוּם דְּכָּלִיל כָּל גַּוְונִין וְכָל דִּיוּקְנִין.</p>\n<p>אָמַר רִבִּי יִצְחָק, תָּא חֲזֵי, כָּל מַאן דְּאִיהוּ תְּחוֹת שׁוּלְטָנֵי דְּאָדָם, אִתְקְרֵי אִישׁ. מִשּׁוּם דְּאִתְתָּקַן בְּגַוְונָא דְּאָדָם, מִדַּרְגָּא אָחֳרָא דְּהֲוָה בֵּיהּ בְּקַדְמִיתָא. דְּתַנְיָא בְּרָזָא עִלָּאָה (תרומה קע\"ח ע\"ב, מ\"ו ע\"ב) בְּסִפְרָא דִּצְנִיעוּתָא, כַּד אִתְבְּרֵי אָדָם, נָחַת בְּדִיּוּקְנָא קַדִּישָׁא עִלָּאָה, וְנַחְתּוּ עִמֵּיהּ תְּרֵין רוּחִין, מִתְּרֵין סִטְרִין, מִימִינָא וּמִשְּׂמָאלָא, כְּלָלָא דְּאָדָם. וְרוּחָא דִּימִינָא, אִתְקְרֵי נִשְׁמְתָא קַדִּישָׁא, דִּכְתִּיב, (בראשית ב׳:ז׳) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. וְרוּחָא דִּשְׂמָאלָא, אִתְקְרֵי נֶפֶשׁ חַיָּה, וַהֲוָה אָזִיל וְנָחִית מֵעֵילָּא לְתַתָּא, וְלָא אִתְיַישְׁבָא בַּהֲדֵי אָחֳרָא.</p>\n<p>כַּד הֲוָה עַיִּיל שַׁבְּתָא, וַהֲוָה חָב אָדָם, אִתְעָבִידוּ (נ\"א אתנגידו) מֵהַהוּא רוּחָא שְׂמָאלָא, בִּרְיָין מִתְפַּשְּׁטָן בְּעָלְמָא, וְלָא אִסְתְּיָימוּ גּוּפָא דִּלְהוֹן. וְאִתְחַבָּרוּ בְּהַאי גּוּפָא דְּאָדָם, בִּדְכוּרָא וְנוּקְבָּא, וְאִתְיְלִידוּ בְּעָלְמָא. וְאִלֵּין אִקְרוּן נִגְעֵי בְּנֵי אָדָם. (כ\"ה ע\"א) תָּנָא, עִלָּאִין מִנַּיְיהוּ דְּלָא אִתְדְּבָקוּ לְתַתָּא, וְתַּלְיָין בַּאֲוִירָא, וְשַׁמְעִין מַה דְּשַׁמְעִין מִלְּעֵילָּא. וּמִנַּיְיהוּ יַדְעִין אִינּוּן אָחֳרָנִין לְתַתָּא.</p>\n<p>תָּנָא, מִן בּוּצִינָא דְּקַרְדִּינוּתָא, נָפְקִין תְּלַת מְאָה וְעֶשְׂרִים וְחָמֵשׁ נִיצוֹצֵי, מִתְגַּלְּפִין וּמִתְאַחֲדָן כַּחֲדָא מִסִּטְרָא דִּגְבוּרָה, דְּאִקְרוּן גְּבוּרוֹת, (ס\"א ומתלכדן) כַּחֲדָא, וְאִתְעָבִידוּ חַד. (גופא) וְכַד עַיְילִין אִלֵּין בְּגוּפָא, אִקְרֵי אִישׁ. (ס\"א ולא איש דא) דָּא דְּתָנֵינָן אִישׁ תָּם וְיָשָׁר אִישׁ צַדִּיק, וְאִישׁ דְּהָכָא, אִישׁ מִלְחָמָה כְּתִיב, דְּכֹלָּא סָלִיק דִּינָא, וְכֹלָּא חֲדָא. אָמַר רִבִּי יְהוּדָה אֲמַאי. לָא הֲוָה בִּידֵיהּ (דרבי יצחק). אָתוּ שָׁאִילוּ קָמֵיהּ דְּרַבִּי שִׁמְעוֹן, אָמַר לוֹן, תּוּ קַשְׁיָא, דְּהָא תָּנֵינָן כְּתִיב (בראשית ב׳:כ״ג) לְזֹאת יִקָּרֵא אִשָּׁה כִּי מֵאִישׁ לֻקֳחָה זֹּאת, וְתָנֵינָן מַאן אִישׁ דָּא חֶסֶד, וְהָכָא אַמְרִיתּוּ דְּהוּא דִּינָא.</p>"],[9520012075,"<p>אֶלָּא הָכִי תָּאנָא, כֹּלָּא הוּא בְּחַד מַתְקְלָא סַלְּקָא, וְכֹלָּא חַד. וּמִשּׁוּם דְּדִינֵי תַּתָּאֵי מִתְאַחֲדָן (נ\"א ומתלכדן) וּמִתְחַבְּרָן בְּשַׂעֲרוֹי דְּהַאי. אִקְרֵי הוּא דִּינָא קַשְׁיָא, וְכַד אִתְעַבָּר מִנֵּיהּ שַׂעֲרָא דְּרֵישָׁא, אִתְבְּסָם, וְדִינִין דִּלְתַתָּא לָא אִזְדְּמָנוּ. וּבְגִין כָּךְ אִקְרֵי טָהוֹר. דְּלָא אִקְרֵי טָהוֹר, אֶלָּא כַּד נָפִיק מִסִּטְרָא דִּמְסָאֲבָא, וְכַד נָפִיק מִן מִסְאֲבָא, אִקְרֵי טָהוֹר. דִּכְתִּיב, (איוב י״ד:ד׳) מִי יִתֵּן טָהוֹר מִטָּמֵא. מִטָּמֵא וַדַּאי, וְהָכָא כְּתִיב, וְאִישׁ כִּי יִמָּרֵט רֹאשׁוֹ קֵרֵחַ הוּא טָהוֹר הוּא.</p>\n<p>וְתָּא חֲזֵי, בְּרֵישָׁא דְּהַאי אִישׁ, בּוּצִינָא דְּקַרְדִּינוּתָא. וּבְגִין כָּךְ גּוּלְגַלְתָּא דְּרֵישָׁא דְּהַאי, סוּמָקָא כֹּלָּא כְּוַורְדָּא, וְשַׂעְרֵי סוּמָקֵי בְּגוֹ סוּמָקֵי, וְתַּלְיָין מִנֵּיהּ כִּתְרִין תַּתָּאִין דִּלְתַתָּא, דְּמִתְעֲרִין דִּינִין בְּעָלְמָא. וְכַד אִתְעַבָּר מִנֵּיהּ שַׂעֲרָא וְאִתְגְלִישׁ, מֵחֶסֶד עִלָּאָה אִתְבְּסָם כֹּלָּא, וְאִתְקְרֵי טָהוֹר עַל שְׁמֵיהּ.</p>\n<p>אָמַר רִבִּי יְהוּדָה, אִי אִתְקְרֵי עַל שְׁמֵיהּ, קָדוֹשׁ אִתְקְרֵי, וְלָא טָהוֹר. אָמַר לֵיהּ לָאו הָכֵי, דְּקָדוֹשׁ לָא אִתְקְרֵי אֶלָּא כַּד תָּלֵי שַׂעֲרָא. דִּקְדוּשָּׁה בְּשַׂעְרָא תָּלֵי, דִּכְתִּיב, (במדבר ו׳:ה׳) קָדוֹשׁ יִהְיֶה גַּדֵל פֶּרַע שְׂעַר רֹאשׁוֹ. וְהַאי אִקְרֵי טָהוֹר, מִסִּטְרָא דְּתַּלְיָין לְתַתָּא מִנֵיהּ, וּבְגִּינֵי כַּךְ אִתְעַבָּר מִנֵּיהּ שַׂעֲרָא, וְאִתְדַּכְיָא.</p>\n<p>וְתָא חֲזֵי כָּל מַאן דְּאִיהוּ מִסִּטְרָא דְּדִינָא, וְדִינִין מִתְאַחֲדִין בֵּיהּ, לָא אִתְדָּכֵי, עַד דְּאִתְעֲבָר מִנֵּיהּ שַׂעֲרָא, וּמִדְאִתְעֲבָר מִנֵּיהּ שַׂעֲרָא אִתְדָּכֵי. וְאִי תֵּימָא אָדָם. לָאו הָכִי, דְּהָא הוּא שְׁלֵימוּתָא דְּכֹלָּא, וְרַחֲמֵי אִשְׁתְּכָחוּ בֵּיהּ. בְּגִין כַּךְ לָאו הָכִי דְּכֻלְּהוּ קְדוּשָׁאן וְקַדִּישִׁין אִתְיָיחֲדוּ בֵּיהּ. אֲבָל הַאי, הוּא דִּינָא, וְדִינֵי אִתְאַחֲדָן בֵּיהּ, לָא אִתְבְּסָם עַד דְּאִתְעֲבָר מִנֵּיהּ שַׂעֲרָא.</p>\n<p>תָּא חֲזֵי, דְּהָא לֵיוָאֵי דְּאָתוּ מֵהַאי סִטְרָא דְּדִינָא, לָא מִתְדַּכְּאָן עַד דְּאִתְעֲבָרוּ מִנְּהוֹן שַׂעֲרָא, דִּכְתִּיב, (במדבר ח׳:ז׳) וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם הַזֵּה עֲלֵיהֶם מֵי חַטָּאת וְהֶעֱבִירוּ תַעַר עַל כָּל בְּשָׂרָם וְגוֹ'. וּבְגִין דְּיִתְבַּסְּמוּן יַתִּיר, בָּעֵי כַּהֲנָא דְּאָתָא מִסִּטְרָא דְּחֶסֶד עִלָּאָה, לְאָרָמָא לוֹן, דִּכְתִּיב, (במדבר ח׳:י״א) וְהֵנִיף אַהֲרֹן אֶת הַלְוִיִּם תְּנוּפָה לִפְנֵי יְיָ'. כְּמָה דְּאִיהוּ לְהַאי אִישׁ דִּלְעֵילָּא, דְּכַד בָּעֵי לְאִתְבַּסְּמָא <Nonei></i>יַתִּיר, אִתְגַּלְיָיא בֵּיהּ חֶסֶד עִלָּאָה, וְאִתְבְּסָם. וּמְבָסֵּם הוּא, לְתַתָּא.</p>\n<p>וְהַאי אִישׁ בִּכְלָלָא דְּאָדָם הוּא. וְכַד בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְאַגָּחָא קְרָבָא, בְּהַאי אִישׁ אֲגַח בְּהוּ קְרָבָא, דִּכְתִּיב (שמות ט״ו:ג׳) יְיָ' אִישׁ מִלְחָמָה, בְּהַאי אִישׁ מַמָּשׁ. וְלָא אֲגַח בְּהוּ קְרָבָא, עַד דְּאַעְבָּר לֵיהּ שַׂעֲרָא דְּרֵישָׁא, בְּגִין דְּיִשְׁתַּלְשְׁלוּן מִשִּׁלְשׁוּלֵיהוֹן, וְיִתָּבְּרוּן כָּל אִינּוּן כִּתְרִין דְּמִתְאַחֲדָן בְּשַׂעֲרֵי. הֲדָא הוּא דִכְתִיב, (ישעיהו ז׳:כ׳) בַּיוֹם הַהוּא יְגַלַּח יְיָ' וְגוֹ'. בְּעֶבְרֵי נָהָר בְּמֶלֶךְ אַשּׁוּר אֶת הָרֹאשׁ וְשַׂעַר הָרַגְלָיִם וְגַם אֶת הַזָּקָן תִּסְפֶּה.</p>\n<p>תָּאנָא, וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם. מַאי וְכֹה. כְּגַוְונָא דִּלְעֵילָּא, הַזֵּה עֲלֵיהֶם מֵי חַטָּאת, שִׁיּוּרֵי טַלָּא דִּבְדוֹלְחָא הָכָא מֵי חַטָּאת, דְּאִינּוּן שִׁיּוּרֵי טַלָּא. לְזִמְנָא דְּאָתֵי כְּתִיב, (יחזקאל ל״ו:כ״ה) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים. וְכִבְּסוּ בִגְדֵיהֶם, כְּגַוְונָא דִּלְעֵילָּא, דְּתִקוּנוֹי דְּהַאי אִישׁ אִתְסָחָן בְּחֶסֶד עִלָּאָה וְאִתְדַכֵּי מִכֹּלָּא.</p>\n<p>וְתָנֵינָן, אֲמַאי כְּתִיב בְּתַעַר וְלֹא בְּמִסְפְּרַיִם. אֶלָּא מִשּׁוּם דְּיִתְעַבָר שַׂעֲרָא בְּשָׁרְשׁוֹי, וְיִתְעֲבְּרוּן מִנֵיהּ דִּינִין תַּתָּאִין מִשּׁוּלְשׁוּלֵיהוֹן. וּלְזִמְנָא דְּיִתְכַּשְׁרוּן עוֹבָדִין לְתַתָּא, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא שַׂעֲרָא דָּא לְאַעְבְּרָא לֵיהּ, וּלְמִגְלְשֵׁיהּ בְּגִין דְּלָא יִצְמַח וְיִרְבֶּה, דִּכְתִּיב כִּי יִמָּרֵט רֹאשׁוֹ.</p>\n<p>אָמַר רִבִּי יִצְחָק, רַב מִכָּל לֵיוָאֵי, קֹרַח הֲוָא, דְּעַבְדֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְתַתָּא, כְּגַוְונָא דִּלְעֵילָּא, וְקַרְיֵיהּ קֹרַח. אֵימָתַי. בְּשַׁעֲתָא דְּגָלִישׁ בְּגִינֵיהּ לְהַאי אִישׁ, דִּכְתִּיב קֵרֵחַ הוּא.</p>\n<p>וְכַד חָמָא קֹרַח רֵישֵׁיהּ בְּלָא שַׂעֲרָא, וְחָמָא לְאַהֲרֹן מִתְקַשֵּׁט בְּקִשׁוּטֵי מַלְכִין, אִתְזַלְזָל בְּעֵינֵיהּ וְקִנֵּא לְאַהֲרֹן. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אֲנָא עֲבָדִית לָךְ כְּגַוְונָא דִּלְעֵילָּא, לָא בָּעָאת לְאַעְלָאָה בְּעִלָּאִין, חוּת לְתַתָּא וַהֲוִי בְּתַתָּאִין. דִּכְתִּיב, (במדבר ט״ז:ל׳) וְיָרְדוּ חַיִּים שְׁאוֹלָה. מַאי אִיהוּ שְׁאוֹל. גֵּיהִנָּם. דְּתַמָּן צַוְוחִין חַיָּיבִין, וְלֵית מַאן דִּמְרַחֲמֵי עָלַיְיהוּ. וּזְמִינִין אִינּוּן לְאַחֲיָיא וּלְאַעֲלָא, כַּד יִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא לְעַמֵּיהּ, וּלְאַחֲיָיא לְהוּ. דִּכְתִּיב, (שמואל א ב׳:ו׳) יְיָ' מֵמִית וּמְחַיֶּה מוֹרִיד שְׁאוֹל וַיָּעַל.</p>\n<p>(ויקרא י״ג:מ״א) וְאִם מִפְּאַת פָּנָיו יִמָּרֵט רֹאשׁוֹ. תָּאנָא, אִית פָּנִים וְאִית פָּנִים, וּמַאן פָּנִים הַלָּלוּ. אִלֵּין אִינּוּן דְּאִקְרוּן פָּנִים שֶׁל זַעַם. וְכָל אִלֵּין דְּתַּלְיָין מֵאִינּוּן פָּנִים חֲצִיפִין, כֻּלְּהוּ תַּקִּיפִין. כֻּלְּהוּ דְּלָא מֵרַחֲמֵי, וְכַד אִתְעַבָּר שַׂעֲרָא מִסִּטְרָא דְּאִינּוּן פָּנִים, מִתְעַבְּרָן כֻּלְּהוּ וְאִתְּבָּרוּ.</p>\n<p>דְּתַנְיָא, (קל\"א ע\"ב, קמ\"א) כָּל אִינּוּן דְּתַּלְיָין מִשַּׂעֲרָא דְּרֵישָׁא, אִינּוּן עִלָּאִין עַל אָחֳרָנִין, וְלָא חֲצִיפִין כְּוָותַיְיהוּ. וְכָל אִינּוּן דְּתַּלְיָין מִסִּטְרָא דְּשַׂעֲרָא דְּאִינּוּן פָּנִים, כֻּלְּהוּ חֲצִיפִין וְתַקִיפִין, וּבְגִין כָּךְ אַנְפּוֹי מִתְלַהֲטָן כְּאֶשָּׁא, מִשּׁוּם נִיצוֹצָא דְּבוּצִינָא דְּקַרְדִּינוּתָא. וּבְהַאי כְּתִיב, (איכה ד) פְּנֵי יְיָ' חִלְּקָם. (תהילים ל״ד:י״ז) פְּנֵי יְיָ' בְּעוֹשֵׂי רָע.</p>"],[9520012076,"<p>אָמַר רִבִּי יִצְחָק מַהוּ נֶגַע לָבָן אֲדַמְדָּם. נֶגַע מַמָּשׁ הוּא, אִי חִוָּורָא אִתְחֲזֵי, וְסוּמָקָא לָא אִתְעַבָּר. מַשְׁמַע דִּכְתִּיב לָבָן אֲדַמְדָּם. אָמַר רִבִּי יוֹסֵי, דְּחִוָּורָא לָא אִתְחֲזֵי אֶלָּא בְּסוּמָקָא, כְּגַוְונָא חִוָּורָא וְסוּמָקָא. רִבִּי יִצְחָק אָמַר, אַף עַל גַּב דְּחִוָּורָא אִתְחֲזֵי, אִי סוּמָקָא לָא אָזִיל, נֶגַע הוּא. דִּכְתִּיב, (ישעיהו א׳:י״ח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וְכַד אִתְחֲוָּור, כֹּלָּא רַחֲמֵי אִשְׁתְּכָחוּ, וְדִינִין לָא אִשְׁתְּכָחוּ. (ס\"א דהא אתעקרו)</p>\n<p>תָּאנֵי רִבִּי אַבָּא, כְּתִיב נֶגַע הוּא, וּכְתִיב נֶגַע הִיא. חַד דְּכַר וְחַד נוּקְבָּא. אֶלָּא כַּד נוּקְבָּא, אִסְתְּאָבַת בְּגִין חוֹבֵי תַּתָּאֵי, כְּתִיב נֶגַע הִיא. וְכַד דְּכַר לָא אִתְדָּכֵי בְּגִין חוֹבֵי תַּתָּאֵי, כְּתִיב נֶגַע הוּא.</p>\n<p>וְאִשְׁתְּמוֹדְעָן מִלִּין אִלֵּין לְגַבֵּי כַּהֲנָא, דִּינִין דְּאָתוּ מֵהַאי, וְדִינִין דְּאָתוּ מֵהַאי. וְאִשְׁתְּמוֹדְעָן קָרְבָּנֵי דְּבַעְיָין לְקָרְבָא, דִּכְתִּיב זָכָר תָּמִים. וּכְתִיב נְקֵבָה תְּמִימָה יְבִיאֶנָּה, דְּהָא אִשְׁתְּמוֹדְעָן מִלֵי, מֵאָן אָתוּ דִּינִין, וּמֵאָן אִינּוּן חוֹבֵי. דְּאִתְאַחֲדָן בְּהַאי אוֹ בְּהַאי. וְעַל דָּא כְּתִיב, (תהילים נ״א:י״ט) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה. לְאַפָּקָא שְׁאָר קָרְבְּנִין דְּלָא כְּתִיב רוּחַ נִשְׁבָּרָה, דְּאִינּוּן שְׁלָמָא לְעָלְמָא, וְחֶדְוָה דְּעִלָּאִין וְתַתָּאִין.</p>\n<p>(ויקרא י״ג:כ״א) וְאִם יִרְאֶנָּה הַכֹּהֵן. תָּאנֵי רִבִּי יוֹסֵי, כְּתִיב <Nonei></i>(תהילים ס״ה:ג׳) שׁוֹמֵעַ תְּפִלָּה עָדֶיךָ וְגוֹ'. שׁוֹמֵעַ תְּפִלָּה, דָּא קוּדְשָׁא בְּרִיךְ הוּא. רִבִּי חִזְקִיָּה אָמַר, שׁוֹמֵעַ תְּפִלָּה, שׁוֹמֵעַ תְּפִלּוֹת מִבָּעֵי לֵיהּ, מַהוּ שׁוֹמֵעַ תְּפִלָּה. אֶלָּא תְּפִלָּה, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי תְּפִלָּה, דִּכְתִּיב, (תהילים ק״ט:ד׳) ואֲנִי תְפִלָּה (ס\"א (תהילים ס״ט:י״ד) ואני תפלתי) וְדָוִד בְּגִין כְנֶסֶת יִשְׂרָאֵל קָאָמַר לָהּ. וּמַה דְּאָמַר וַאֲנִי תְפִלָּה, כֹּלָּא חַד, וְעַל דָּא שׁוֹמֵעַ תְּפִלָּה, וְדָא תְּפִלָּה שֶׁל יַד, דִּכְתִּיב, (שמות יג) עַל יָדְכָה בְּהֵ\"א.</p>\n<p>עָדֶיךָ כָּל בָּשָׂר יָבוֹאוּ. בְּשַׁעֲתָא דְּגוּפָא שַׁרְיָא בְּצַעֲרָא, בְּמַרְעִין בְּמַכְתְּשִׁין. כְּמָה דְאַתְּ אָמֵר וּבָשָׂר כִּי יִהְיֶה בְעוֹרוֹ. אֶת הַנֶּגַע בְּעוֹר הַבָּשָׂר. הַבָּשָׂר הַחַי. וּבְגִין כָּךְ לָא כְּתִיב, כָּל רוּחַ יָבֹאוּ, אֶלָּא כָּל בָּשָׂר יָבֹאוּ. מַהוּ עָדֶיךָ. אֶלָּא כְּמָה דְּאִתְּמַר, וְהוּבָא אֶל הַכֹּהֵן, דָּא הוּא קוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, וְאִם יִרְאֶנָּה הַכֹּהֵן. תָּא חֲזֵי, בַּאֲתַר חַד אַהֲרֹן הַכֹּהֵן, וּבְאַתְרָא אָחֳרָא הַכֹּהֵן סְתָם, וְדָא קוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9520012077,"<p>אָמַר רִבִּי יִצְחָק, וְהָא כְּתִיב נֶגַע צָרַעַת כִּי תִהְיֶה בְּאָדָם וְהוּבָא אֶל הַכֹּהֵן, אִי הָכִי דָּא קוּדְשָׁא בְּרִיךְ הוּא. אָמַר לֵיהּ אִין. בְּגִין דְּבֵיהּ תַּלְיָא כָּל דַּכְיוּתָא וְכָל קְדוּשָּׁה. אָמַר לֵיהּ, אִי הָכִי, אֲמַאי וְהוּבָא, וְהוּעֲלָה מִבָּעֵי לֵיהּ. אָמַר לֵיהּ, כְּמָה דְאַתְּ אָמֵר (שמות כ״ז:ז׳) וְהוּבָא אֶת בַּדָּיו בַּטַּבָּעוֹת, דְּעָיִיל דָּא בְּגוֹ דָּא. אוּף הָכָא וְהוּבָא, דְּיִכָּנְסוּן לֵיהּ לְכַהֲנָא, לְדַכְּאָה לֵיהּ (כד אהדר ביה) וְיֵעָלוּן מִלָּה קַמֵּיהּ.</p>\n<p>אָמַר רִבִּי יִצְחָק, הָכִי תָּנֵינָן, נֶגַע צָרַעַת. נֶגַע הוּא דִּינָא תַּקִּיפָא שַׁרְיָא בְּעָלְמָא. צָרַעַת: סְגִירוּ. כְּמָה דְאַתְּ אָמֵר, סְגִירוּ דִּנְהוֹרָא עִלָּאָה. סְגִירוּ דְּטִיבוּ עִלָּאָה, דְּלָא נָחִית לְעָלְמָא. כִּי תִהְיֶה בְּאָדָם, בְּאָדָם סְתָם. וְהוּבָא אֶל הַכֹּהֵן. דָּא כֹּהֵן דִּלְתַתָּא, דְּהוּא אִתְתְּקַּן לְמִפְתַּח הַהוּא סְגִירוּ, וּלְאֲדְלָקָא בּוּצִינִיָא דְּיִשְׁתְּכָחוּ עַל יְדוֹי בִּרְכָן לְעֵילָּא וּלְתַתָּא. וְיִתְעֲבָר וְיִסְתָּלַק הַהוּא נֶגַע, וְיִשְׁרֵי נְהִירוּ דְּרַחֲמֵי עַל כֹּלָּא, וּבְגִין כָּךְ וְהוּבָא אֶל הַכֹּהֵן.</p>"],[9520012078,"<p>אָמַר רִבִּי אַבָּא, חֲמֵינָא לְאִינְהוּ בְּנֵי עָלְמָא, דְּלָא מַשְׁגְּחָן, וְלָא יַדְעִין בִּיקָרָא דְּמָארֵיהוֹן, כְּתִיב בְּהוּ בְּיִשְׂרָאֵל, (ויקרא כ׳:כ״ד) אֲשֶׁר הִבְדַּלְתִּי אֶתְכֶם מִן הָעַמִּים לִהְיוֹת לִי. וּכְתִיב, (ויקרא כ׳:כ״ד) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים כִּי קָדוֹשׁ אָנִי יְיָ'. אִי אִינּוּן מִתְרַחֲקָן, אָן הוּא קְדוּשָּׁה דִּלְהוֹן, הָא רְעוּתָא דִּלְהוֹן אִתְרַחֲקַת מִנֵּיהּ. וּקְרָא אַכְרִיז וְאָמַר, (תהילים ל״ב:ט׳) אַל תִּהְיוּ כְּסוּס כְּפֶרֶד אֵין הָבִין, בְּמָה אִתְפָּרְשָׁן בְּנֵי נָשָׁא מִסּוּס וָפֶרֶד, בִּקְדוּשָּׁה דְּגַרְמַיְיהוּ, לְאִשְׁתַּכְּחָא שְׁלֵימִין וּרְשִׁימִין מִכֹּלָּא.</p>\n<p>וְעַל דָּא זִוּוּגָא דִּבְנֵי נָשָׁא הוּא בְּזִמְנִין יְדִיעָן, לְכַוְּונָא רְעוּתָא לְאִתְדַּבְּקָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. וְהָא אִתְּעֲרוּ, בְּפַלְגוּת לֵילְיָא קוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִנְתָּא דְּעֵדֶן, לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא, וּכְּנֶסֶת יִשְׂרָאֵל מְשַׁבַּחַת לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְהִיא שַׁעֲתָא דִּרְעוּתָא לְאִתְדַּבְּקָא בְּהוּ.</p>\n<p>וְחַבְרַיָּיא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, מִשְׁתַּתְּפֵי בָּהּ בִּכְּנֶסֶת יִשְׂרָאֵל, לְשַׁבְּחָא לְמַלְכָּא קַדִּישָׁא, וְאִתְעַסְּקָן בְּאוֹרַיְיתָא, שְׁאָר בְּנֵי נָשָׁא כְּדֵין עִידָּן רְעוּתָא לְאִתְקַדְּשָׁא בִּקְדוּשָּׁה דְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְכַוְּונָא רְעוּתָא לְאִתְדַּבְּקָא בֵּיהּ. וְאִינּוּן חַבְרַיָּיא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא זִוּוּגָא דִּלְהוֹן בְּשַׁעֲתָא דְּזִוּוּגָא אָחֳרָא אִשְׁתְּכַח, וְהַאי מִשַּׁבָּת לְשַׁבָּת לְכַוְּונָא רְעוּתָא לְאִתְדַּבְּקָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא וּבִכְנֶסֶת יִשְׂרָאֵל, דְּהוּא עִידָּן רְעוּתָא דְּמִתְבָּרְכָן כֹּלָּא עִלָּאֵי וְתַתָּאֵי.</p>\n<p>אִי בְּנֵי נָשָׁא אִתְרַחֲקוּ מִנֵּיהּ, וְעַבְדָּן כִּבְעִירֵי, אָן הוּא קְדוּשָּׁה דִּלְהוֹן, לְאִשְׁתַּכְּחָא קַדִּישִׁין. אָן אִינּוּן נַפְשָׁאָן קַדִּישִׁין דְּמָשְׁכָן מֵעֵילָּא. וּשְׁלֹמֹה מַלְכָּא צָוַוח וְאָמַר, (משלי י״ט:ב׳) גַּם בְּלֹא דַּעַת נֶפֶשׁ לֹא טוֹב. גַּם בְּלֹא דַּעַת, מַאן הוּא דַּעַת. דָּא קוּדְשָׁא בְּרִיךְ הוּא. נֶפֶשׁ לֹא טוֹב, דָּא הוּא נֶפֶשׁ, דְּאִינּוּן מַשְׁכִין בְּעוֹבָדַיְיהוּ, לֹא טוֹב, דְּהָא מִסִּטְרָא אָחֳרָא אִתְמַשְּׁכָאן עָלַיְיהוּ נַפְשָׁתָא דְּלָאו אִיהוּ טוֹב, בְּגִין דְּלָא מְכַוְּונֵי לִבַּיְיהוּ לְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>מַאן דְּאִתְלְהִיט בְּיֵצֶר הָרָע, בְּלָא רְעוּתָא וְכַוָּונָה דְּלִבָּא לְּקוּדְשָׁא בְּרִיךְ הוּא. מִסִּטְרָא דְּיֵצֶר הָרָע אִתְמְשַׁךְ עָלֵיהּ נַפְשָׁא, דְּלָאו אִיהִי טוֹב, הֲדָא הוּא דִכְתִיב גַּם בְּלֹא דַּעַת נֶפֶשׁ לֹא טוֹב וְאָץ בְּרַגְלַיִם חוֹטֵא. מַאן דְּאִיהוּ אָץ בְּרַגְלַיִם וְדָחֵי שַׁעֲתָא בְּלָא רְעוּתָא קַדִּישָׁא, חוֹטֵא. חוֹטֵא וַדַּאי, בְּכֹלָּא.</p>\n<p>וְעַל דָּא שַׁרְיָין מַכְתְּשִׁין בִּישִׁין בִּבְנֵי נָשָׁא, וְאַסְהִידוּ בְּאַנְפַּיְיהוּ בַּחֲצִיפוּתָא דִּלְהוֹן, לְאַחֲזָאָה דְּהָא קוּדְשָׁא בְּרִיךְ הוּא מָאִיס בְּהוּ, וְלָאו דַּעְתֵּיהּ בְּהוֹן, עַד דְּאִינּוּן זַכָּאן <Nonei></i>וּמַכְשְׁרָאן עוֹבָדַיְיהוּ כְּמִלְּקַדְּמִין, וּמִתְבָּרְכָן (ס\"א ומתדכאן). וְעַל דָּא אִשְׁתְּמוֹדְעָן מַכְתְּשִׁין לְגַבֵּי כַּהֲנָא, אִינּוּן דְּאַתְיָין מִסִּטְרָא דִּמְסָאֲבָא, וְאִינּוּן דְּאַתְיָין מִסִּטְרָא אָחֳרָא.</p>"],[9520012079,"<p>כְּגַוְונָא דָּא כְּתִיב, כִּי תָבֹאוּ אֶל אֶרֶץ כְּנַעַן וְגוֹ', וְנָתַתִּי נֶגַע צָרַעַת בְּבֵית אֶרֶץ אֲחוּזַּתְכֶם. וְכִי אֲגָר טַב הוּא, דְּיִשְׁתְּכַח בְּאִינּוּן דְּזַכָּאן לְמֵיעָל בְּאַרְעָא. אֶלָּא הָא אוּקְמוּהָ לְאַשְׁכְּחָא מַטְמוֹנִין דְּאַטְמְרָן בְּבֵיתַיְיהוּ, וּלְאַהֲנָאָה לוֹן לְיִשְׂרָאֵל.</p>\n<p>אֲבָל תָּא חֲזֵי, זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּאִינּוּן מִתְדַּבְּקָן בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְקוּדְשָׁא בְּרִיךְ הוּא רָחִים לְהוּ, דִּכְתִּיב, (מלאכי א׳:ב׳) אָהַבְתִּי אֶתְכֶם אָמַר יְיָ'. וּמִגּוֹ רְחִימוּתָא דִּילֵיהּ, אָעִיל לְהוּ לְאַרְעָא קַדִּישָׁא, לְאַשְׁרָאָה שְׁכִינְתֵּיהּ בֵּינַיְיהוּ, וּלְמֶהֱוִי דִּיּוּרֵיהּ עִמְּהוֹן, וְיִשְׂרָאֵל דְּיִשְׁתַּכְּחוּן קַדִּישִׁין עַל כָּל בְּנֵי עָלְמָא.</p>\n<p>תָּא חֲזֵי, כְּתִיב (שמות ל״ה:כ״ו) וְכָל הַנָּשִׁים אֲשֶׁר נָשָׂא לִבָּן וְגוֹ'. בְּשַׁעֲתָא דַּהֲווֹ עַבְדִּין עֲבִידְתָּא, הֲווֹ אַמְרֵי, דָּא לְמַקְדְּשָׁא. דָּא לְמַשְׁכְּנָא. דָּא לְפָרוֹכְתָּא. וְכֵן כָּל אִינּוּן אוּמְנִין בְּגִין דְּיִשְׁרֵי קְדוּשָּׁה עַל יְדַיְיהוּ, וְאִתְקַדַּשׁ הַהוּא עֲבִידְתָּא. וְכַד סָלִיק לְאַתְרֵיהּ, בִּקְדוּשָּׁה סָלִיק.</p>\n<p>כְּגַוְונָא דָּא מַאן דְּעָבִיד עֲבִידְתָּא לְעֲבוֹדָה זָרָה, אוֹ לְסִטְרָא אָחֳרָא, דְּלָא קַדִּישָׁא. כֵּיוָן דְּאִדְכַּר לֵיהּ עַל הַהוּא עֲבִידְתָּא, הָא רוּחַ מִסְאֲבָא שַׁרְיָא עֲלוֹי, וְכַד סָלִיק עֲבִידְתָּא, בִּמְסָאֲבָא סָלִיק. כְּנַעֲנִיִם פַּלְחֵי לְעֲבוֹדָה זָרָה אִינְהוּ, וּמִתְדַּבְּקָן כֻּלְּהוּ כַּחֲדָא בְּרוּחַ מִסְאֲבָא בְּעֲבוֹדָה זָרָה, וַהֲווּ בִּנְיָין בָּנִין לְפַרְצוּפַיְיהוּ (ס\"א לטנופייהו) וּלְגִעוּלַיְיהוּ לִסְטַר מִסְאֲבָא לְעֲבוֹדָה זָרָה, וְכַד שָׁרָאן לְמִבְנֵי, הֲווֹ אַמְרֵי מִלָּה, וְכֵיוָן דְּאִתְדְּכָר בְּפוּמַיְיהוּ, סָלִיק עָלֵיהּ רוּחַ מִסְאֲבָא. כַּד אִסְתָּלִיק עֲבִידְתָּא, בְּרוּחַ מִסְאֲבָא אִסְתָּלִיק.</p>\n<p>כֵּיוָן דְּעָאלוּ יִשְׂרָאֵל לְאַרְעָא, בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְדַכְּאָה לוֹן, וּלְקַדְּשָׁא לוֹן אַרְעָא, וּלְאַפְנָאָה אֲתַר לִשְׁכִינְתָּא דְּלָא תִּשְׁרֵי שְׁכִינְתָּא גּוֹ מִסְאֲבָא. וְעַל דָּא בְּהַהוּא נֶגַע צָרַעַת, הֲווֹ סָתְרִין בִּנְיָינִין דְּאָעִין וַאֲבָנִין דְּאִתְעָבֵידוּ בִּמְסָאֲבוּ.</p>"],[9520012080,"<p>תָּא חֲזֵי, אִי עוֹבָדָא דָּא הֲוָה לְאַשְׁכְּחָא מַטְמוֹנִין בִּלְחוֹדוֹי, יְהַדְרוּן אֲבָנִין לְבָתַר כְּמָה דְּאִינּוּן לְאַתְרַיְיהוּ, וְעַפְרָא לְאַתְרֵיהּ. אֲבָל קְרָא כְּתִיב, וְחִלְּצוּ אֶת הָאֲבָנִים. וּכְתִיב וְעָפָר אַחֵר יִקַּח. בְּגִין דְּיִתְעַבָּר רוּחַ מִסְאֲבָא, וְיִתְפְּנֵי וְיִתְקַדַּשׁ הַשְׁתָּא כְּמִלְּקַדְּמִין, וְיִשְׁתְּכָחוּ יִשְׂרָאֵל בִּקְדוּשָּׁה, וּבְדִיּוּרָא קַדִּישָׁא, לְמִשְׁרֵי בֵּינַיְיהוּ שְׁכִינְתָּא.</p>\n<p>וְעַל דָּא מַאן דְּבָנֵי בִּנְיָן כַּד שָׁארֵי לְמִבְנֵי, בָּעֵי לְאַדְכְּרָא בְּפוּמֵיהּ, דְּהָא לְפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא הוּא בָּנֵי. בְּגִין דִּכְתִּיב, (ירמיהו כ״ב:י״ג) הוֹי בּוֹנֶה בֵיתוֹ בְּלֹא צֶדֶק וְגוֹ', וּכְדֵין סִיַּיעְתָּא דִּשְׁמַיָּא שָׁארֵי עֲלוֹי, וְקוּדְשָׁא בְּרִיךְ הוּא זַמִּין עָלֵיהּ קְדוּשָׁתָא, וְקָארִי עָלֵיהּ שָׁלוֹם, הֲדָא הוּא דִכְתִיב, (איוב ה׳:כ״ד) וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךָ וְגוֹ'. מַהוּ (איוב ה׳:כ״ד) וּפָקַדְתָּ נָוְךָ, הָא אוּקְמוּהָ, אֲבָל וּפָקַדְתָּ, לְאַפְקְדָא מִלָּה בְּפוּמָא כַּד אִיהוּ בָּנֵי. וּכְדֵין וְלֹא תֶחֱטָא כְּתִיב. וְאִי לָאו הָא זַמִּין לְבֵיתֵיהּ סִטְרָא אָחֳרָא.</p>\n<p>כָּל שֶׁכֵּן, מַאן דְּבָנֵי וּרְעוּתֵיהּ בְּגַוְונָא אָחֳרָא, בְּגִין דִּמְיַחֵד בֵּיתָא לְסִטְרָא אָחֳרָא, לְאִסְתַּאֲבָא בֵּיהּ. הָא וַדַּאי שַׁרְיָא בֵּיהּ רוּחַ מִסְאֲבָא, וְלָא נָפִיק הַהוּא בַּר נָשׁ מֵעָלְמָא, עַד דְּאִתְעֲנָשׁ בְּהַהוּא בֵּיתָא, וּמַאן דְּדָיִיר בֵּיהּ, יָכִיל לְאַתְזְקָא, דְּהָא הַהוּא דִּירָה רוּחַ מִסְאֲבָא שַׁרְיָא בֵּיהּ, וְאָזִיק מַאן דְּאִשְׁתְּכַח בֵּיהּ.</p>"],[9520012081,"<p>וְאִי תֵּימָא בְּמַה יְדִיעַ. כְּגוֹן דְּאִתְּזַק בְּהַהוּא בֵּיתָא, הַהוּא דְּבָנֵי לָהּ, אוֹ אַנְשֵׁי בֵּיתֵיהּ, אוֹ בְּנִזְקֵי דְּגוּפָא, אוֹ בְּנִזְקֵי מָמוֹנָא, הוּא וּתְרֵין אָחֳרָנִין אֲבַתְרֵיהּ. הָא וַדַּאי יַעֲרוֹק בַּר נָשׁ לְטוּרָא, וְלָא יָדוּר בֵּיהּ. יָדוּר בְּטִיחֲלָא דְּעַפְרָא, וְלָא יָדוּר בֵּיהּ.</p>\n<p>וּבְגִין כַּךְ, קוּדְשָׁא בְּרִיךְ הוּא חָס עָלַיְיהוּ דְּיִשְׂרָאֵל, דְּאִינּוּן לָא יַדְעִין מִלָּה בְּכָל אִינּוּן בָּתֵי. וְהוּא אָמַר, אַתּוּן לָא יַדְעִין, אֲנָא יְדַעְנָא, וְאַרְשִׁימְנָא לוֹן בְּנֶגַע. נֶגַע דָּיִיר בְּבֵיתָא, הָא נֶגַע אָחֳרָא תַּקִּיפָא, דְּיָפִּיק לֵיהּ, וְיַּעֲבַּר לֵיהּ מִן עָלְמָא. וּכְדֵין וְנָתַץ אֶת הַבַּיִת אֶת אֲבָנָיו וְאֶת עֵצָיו. כֵּיוָן דְּאָזִיל לֵיהּ, מַאי טַעֲמָא וְנָתַץ אֶת הַבַּיִת. אֶלָּא בְּכָל זִמְנָא דְּהַהוּא בִּנְיָן לִהֱוִי קַיָּים, <Nonei></i>דִּילֵיהּ הוּא, וְיָכִיל לְאָהַדְּרָא.</p>\n<p>הַאי בְּאַרְעָא קַדִּישָׁא, כָּל שֶׁכֵּן בְּאַרְעָא אָחֳרָא, דִּזְמִינָא רוּחַ מִסְאֲבָא יַתִּיר, וְיָכִיל בַּר נָשׁ לְאִתְזְקָא. אָמַר רִבִּי אֶלְעָזָר, וְכָּל שֶׁכֵּן דְּאִקְרֵי בִּקְלִפּוֹי דְּחַבְרוֹי אָחֳרָנִין, לְאִשְׁתַּכְּחָא תַּמָּן, וַאֲפִילּוּ טוּרְפֵי דְּקַסְפְּתָא לָא מַעְבְּרָן לֵיהּ מֵהַהוּא בֵּיתָא, וּבְגִין כָּךְ הַאי קְרָא אַכְרִיז וְאָמַר, הוֹי בּוֹנֶה בֵיתוֹ בְּלֹא צֶדֶק. הוֹי וַדַּאי קָאַמְרֵי כָּל יוֹמָא בְּהַהוּא בֵּיתָא.</p>\n<p>רִבִּי יוֹסֵי עָאל חַד יוֹמָא בְּחַד בֵּיתָא, מָטָא בַּסִּפְתָא (ס\"א אטרח בטיפסא), עָאל לְגוֹ. שָׁמַע חַד קָלָא דְּאָמַר, אִתְכְּנָשׁוּ עוּלוּ, הָא חַד פְּלוּגְתָּא דִּילָן. סִיפְתוּ וְנָנְזִיק לֵיהּ עַד לָא יִנְפּוֹק, אָמְרוּ, לָא נֵיכוּל אֶלָּא אִי דִּיּוּרֵיהּ הָכָא. נָפַק רִבִּי יוֹסֵי וְדָחִיל. אָמַר, ודַּאי מַאן דְּאַעְבָּר עַל מִלּוֹי דְּחַבְרַיָּיא, אִתְחַיָּיב בְּנַפְשֵׁיהּ.</p>\n<p>אָמַר לֵיהּ רִבִּי חִיָיא, וְהָא גּוֹיִם וּשְׁאָר בְּנֵי נָשָׁא דַּיְּירֵי בְּגַוִּיהּ, וְאִשְׁתְּלִימוּ. אָמַר לֵיהּ, אִינּוּן מִסִּטְרַיְיהוּ קָא אַתְיָין, אֲבָל מַאן דְּדָחִיל חַטָּאָה, יָכִיל לְאַתְזְקָא. וַאֲפִילּוּ אִינּוּן, אִי יְעַכְּבוּ דִּיּוּרֵיהוֹן בֵּיהּ, לָא יִפְקוּן בִּשְׁלָם. אָמַר לֵיהּ, וְהָא כְּתִיב (איוב כ״א:ט׳) בָּתֵּיהֶם שָׁלוֹם מִפָּחַד. אָמַר לֵיהּ כְּגוֹן דְּהֲוָה מֵאָחֳרָא, וְאִתְבְּנֵי מִצֶּדֶק. וְקְרָא הָכִי הוּא, בָּתֵּיהֶם שָׁלוֹם מִפָּחַד, כְּשֶׁבָּתֵּיהֶם שָׁלוֹם מִפָּחַד שֵׁבֶט אֱלוֹהַּ לָא שַׁרְיָא עֲלֵיהֶם.</p>"],[9520012082,"<p>(ויקרא י״ד:ל״ה) וּבָא אֲשֶׁר לוֹ הַבַּיִת וְהִגִּיד וְגוֹ'. וְהִגִּיד, וַיֹּאמֶר מִבָּעֵי לֵיהּ, אוֹ וַיְדַבֵּר, מַהוּ וְהִגִּיד. אֶלָּא בְּכָל אֲתַר מִלָּה דְּחָכְמְתָא הוּא, וְהָא אוּקְמוּהָ. כְּנֶגַע נִרְאָה לִי בַּבַּיִת, כְּנֶגַע, נֶגַע מִבָּעֵי לֵיהּ. נִרְאָה לִי, יֵשׁ לִי מִבָּעֵי לֵיהּ. דְּהָא כְּתִיב, וְנָתַתִּי נֶגַע צָרַעַת בְּבֵית אֶרֶץ אֲחֻזַתְכֶם, דְּיִתְחֲזֵי לְכֹלָּא. אֲמַאי כְּנֶגַע נִרְאָה לִי.</p>\n<p>אֶלָּא בְּשַׁעֲתָא דְּהַאי עַיִּיל, אָחֳרָא אִתְגַּלְיָא. וּמְקַטְרְגָא דָּא בְּדָא. וְעַל דָּא נִרְאָה לִי, הַהוּא דְּאִתְכַּסֵּי אִתְגַּלְיָא, וּדְאִתְגַּלְיָא אִתְכַּסֵּי, וּלְבָתַר מִתְחֲזֵי לֵיהּ בְּדִיּוּקְנָא דְּהַהוּא נֶגַע דְּבֵיתָא, וְאִתְכַּסְּיָא אָחֳרָא. וְעַל דָּא וְהִגִּיד לַכֹּהֵן, דְּמִלָּה דְּחָכְמְתָא הִיא.</p>\n<p>וּכְדֵין אָתֵי כַּהֲנָא, וְיִרְמוּן בֵּיתָא, וְיִנְתְּצוּן לֵיהּ אֲבָנִין וְאָעִין וְכֹלָּא. כֵּיוָן דְּאִנְתְּצָן וְאִתְדָּכָן כֹּלָּא, מִתְבָּרְכָאן, כְּדֵין כְּתִיב, (דברים ח׳:י״ב) וּבָתִּים טוֹבִים תִּבְנֶה וְיָשָׁבְתָּ. אִלֵּין אִקְרוּן טוֹבִים, דְּהָא קַדְמָאֵי לָאו אִינּוּן טוֹבִים, וְלָאו בִּכְלָלָא דִּקְדוּשָּׁה וְדַכְיוּ נִינְהוּ.</p>\n<p>אָמַר רִבִּי יְהוּדָה, אִי הָכִי בְּמַאי מוּקְמֵינָן קְרָא דִּכְתִּיב, (דברים ו׳:י״א) וּבָתִּים מְלֵאִים כָּל טוּב אֲשֶׁר לֹא מִלֵּאתָ. אִי רוּחַ מִסְאֲבָא שַׁרְיָא בְּגַוַויְיהוּ הֵיךְ מְלֵאִים כָּל טוּב. אָמַר רִבִּי אֶלְעָזָר, מְלֵאִים כָּל טוּב: בְּמָמוֹנָא, בְּכַסְפָּא, וּבְדַהֲבָא, וּבְכֹלָּא. כְּמָה דְאַתְּ אָמֵר (בראשית מ״ה:ח׳) כִּי טוּב כָּל אֶרֶץ מִצְרַיִם. וְאָמַר רִבִּי יְהוּדָה, וְהָא כָּל בָּתֵּי דְּמִצְרָאֵי, מַלְּיָין חַרְשִׁין וְטַעֲוָון הֲווֹ. אֶלָּא בְּגִין עוּתְרָא דְּאַרְעָא אִתְּמַר. אוּף הָכָא בְּגִין עוּתְרָא וּמָמוֹנָא הוּא.</p>\n<p>תְּרֵין עוּתְרִין נַטְלוּ יִשְׂרָאֵל, חַד כַּד נָפְקוּ מִגָּלוּתָא דְּמִצְרַיִם. וְחַד כַּד עָאלוּ לְאַרְעָא. רִבִּי שִׁמְעוֹן אָמַר, כָּל דָּא וַדַּאי הֲוָה לְאִתְקַדְשָׁא אַרְעָא, וּלְאַעְבְּרָא רוּחַ מִסְאֲבָא מֵאַרְעָא, וּמִגּוֹ יִשְׂרָאֵל. וְכַד בֵּיתָא הֲוָה נָתִיץ, הֲוָה אִשְׁתְּכַח בָּהּ מָמוֹנָא, לְמִבְנֵי לֵיהּ, וּלְמַלְיָא בֵּיתֵיהּ, בְּגִין דְּלָא יִצְטָעֵר עַל בֵּיתָא, וְיִשְׁרוּן בְּדִיּוּרָא דִּקְדוּשָּׁה.</p>\n<p>(ויקרא י״ג:ל״ח) וְאִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בְעוֹר בְּשָׂרָם בֶּהָרוֹת וְגוֹ'. רִבִּי יוֹסֵי אָמַר, כְּסִילְתָּא דְּמוֹקְפֵי בְּבַהֶרֶת עַזָּה, חֵיזוֹ תָּנֵינָא, וּבְחֵיזוֹ אִתְּדָּן, בְּאִינּוּן גַּוְונִין. אָמַר רִבִּי יִצְחָק ש' טַעְמֵי אִית מַאן דְּגָרִיס בְּבַהֶרֶת עַזָּה. וְכֻלְּהוּ אוֹלִיפְנָא מֵאַבָּא, בַּר חֵיזוּר (חיור) חַד סָאִיב, סָהֲדָא חַד. תְּרֵין, תְּרֵי סַהֲדֵי, וְדָכֵי. מִכָּאן וּלְהָלְאָה, אֲפִילּוּ מֵאָה כִּתְרֵי, וּתְרֵי כְּמֵאָה. וְדָא אוֹלִיפְנָא לְבָתַר דִּכְתִּיב, (דברים י״ט:ט״ו) לֹא יָקוּם עֵד אֶחָד בְּאִישׁ וְגוֹ', עַל פִּי שְׁנַיִם עֵדִים וְגוֹ'.</p>"],[9520012083,"<p>רִבִּי חִזְקִיָּה הֲוָה יָתִיב קַמֵּיהּ דְּרִבִּי שִׁמְעוֹן, אָמַר, כְּתִיב נֶגַע לָבָן אֲדַמְדָּם, כְּדֵין הוּא נֶגַע, דְּהָא חִוָּורָא לָא קָאִים בְּעֵינֵיהּ. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, כְּתִיב (ישעיהו א׳:י״ח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים וְגוֹ', זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְדַכְּאָה לוֹן בְּכֹלָּא, בְּגִין דְּלָא יִשְׁתַּכְּחוּן בְּדִינָא קַמֵּיהּ. וּמָארֵיהוֹן דְּדִינָא לָא יִשְׁלְטוּן בְּהוֹן, דְּהָא כֹּלָּא אָזִיל בָּתַר זִינֵיהּ. סוּמָקָא לְסוּמָקָא, וְחִוָּורָא לְחִוָּורָא. יְמִינָא לִימִינָא, וּשְׂמָאלָא לִשְׂמָאלָא.</p>\n<p>בְּעֵשָׂו כְּתִיב, (בראשית כ״ה:כ״ה) וַיֵצֵא הָרִאשׁוֹן אַדְמוֹנִי, וְעַל דָּא שַׁרְיָא בֵּיהּ זִינֵיהּ. <Nonei></i>וְאִי תֵּימָא אַדְמוֹנִי כְּתִיב בְּעֵשָׂו. וּכְתִיב בֵּיהּ בְּדָוִד, (שמואל א ט״ז:י״ב) וַיְבִיאֵהוּ וְהוּא אַדְמוֹנִי. אֶלָּא דָּא מִזּוֹהֲמָא דְּדַהֲבָא אִתְעַבִיד, וְדָא בְּזוֹהֲרָא דְּדַהֲבָא אִתְדְּבַק, בְּעֵשָׂו כְּתִיב בֵּיהּ, אַדְמוֹנִי כֻּלּוֹ כְּאַדֶּרֶת שֵׂעָר, (מ\"ח ע\"ב) בְּזוּהֲמָא דְּהִתוּכָא נָפַק. בֵּיהּ כְּתִיב בְּדָוִד, עִם יְפֵה עֵינַיִם וְטוֹב רֹאִי.</p>\n<p>תָּא חֲזֵי, מַאי טַעְמָא. גַּוְונָא חִוָּורָא אִשְׁתְּמוֹדַע, וְגַוְונָא סוּמָקָא אִשְׁתְּמוֹדַע, סוּמָקָא בְּקַדְמִיתָא, וְהָא אִתְחֲזֵי בֵּיהּ חִוָּורָא, הָא דַּכְיוּתָא אִתְיְילִיד בֵּיהּ, וְשָׁארִי לְאִתְדַכְּאָה. חִוָּורָא בְּקַדְמִיתָא, וְאִתְחַזֵּי בֵּיהּ סוּמָקָא, הָא שָׁארֵי לְאִסְתַּאֲבָא, וּכְתִיב וְטִמְּאוֹ הַכֹּהֵן, דְּהָא אִתְיְילִיד בֵּיהּ סוּמָקָא, לְאִסְתַּאֲבָא. וְכַהֲנָא הֲוָה יָדַע בְּכָל אִינּוּן גַּוְונִין. וּלְזִמְנִין דְּאִתְחֲזֵי בֵּיהּ גַּוְונָא דְּדַכְיוּתָא, וְיַסְגִר לֵיהּ לְמֵחֱמֵי אִי אִתְיְילִיד בֵּיהּ גַּוְונָא אָחֳרָא. וְאִי לָא, מַדְכֵּי לֵיהּ, הֲדָא הוּא דִכְתִיב וְטִהֲרוֹ הַכֹּהֵן וְגוֹ'.</p>\n<p>רִבִּי יִצְחָק וְרִבִּי יְהוּדָה הֲווֹ אָזְלֵי בְּאָרְחָא, אָמַר רִבִּי יְהוּדָה, כְּתִיב (מלכים ב ה׳:כ״ז) וְצָרַעַת נַעֲמָן תִּדְבַּק בְּךָ וּבְזַרְעֲךָ לְעוֹלָם וְגוֹ', אִי הוּא חָטָא בְּנוֹי אֲמַאי יִלְקוּן. אָמַר לֵיהּ, אֱלִישָׁע יַתִּיר מִשְּׁאַר נְבִיאֵי חָמָא. חָמָא דְּלָא נָפִיק מִגֵחֲזִי בְּרָא דִּמְעַלְיָא, וְעַל דָּא לָיִיט לְכֻלְּהוּ.</p>\n<p>וְלֹא עוֹד, אֶלָּא אָמַר לֵיהּ, אֲנָא פּוּלְחָנָא בְּשִׁמוּשָׁא עִלָּאָה לְגַבֵּי אֵלִיָּהוּ, וְזָכֵינָא בִּתְרֵין חוּלָקִין, דְּהָא פְּלַחְנָא לֵיהּ בִּקְשׁוֹט, וְאַנְתְּ רָשָׁע פְּגִימַת לִי, אוּמֵית לְשִׁקְרָא, וַחֲמִידַת, הָא עָבַרְתָּ עַל אוֹרַיְיתָא כֹּלָּא, וּמַאן דְּאַעְבָּר עַל דָּא, מִית הוּא לְעָלְמָא דְּאָתֵי. אֲבָל בְּגִין דְּפַלְחַת לִי, שִׁמּוּשָׁא דִּילָךְ לָא לִהֱוִי לְמַגָּנָא, תֶּהֱוִי מִיתָה דִּילָךְ בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי לָא. וּבְגִין כַּךְ, וְצָרַעַת נַעֲמָן תִּדְבַּק בְּךָ וּבְזַרְעֲךָ. (גוונא דחיוורא אשתמודע, וגוונא דסומקא אשתמודע)</p>"],[9520012084,"<p>אָמַר רִבִּי יוֹסֵי, בֶּגֶד הַצֶּמֶר אוֹ הַפִּשְׁתִּים אֲמַאי. אָמַר רִבִּי יִצְחָק, בְּכֹלָּא שַׁרְיָא, וּבְכֹלָּא שַׁלְטָא. וְאִית כְּגַוְונָא דָּא דִּכְתִּיב, (משלי ל״א:י״ג) דָּרְשָׁה צֶמֶר וּפִשְׁתִּים. וּבְגִּינֵי כַּךְ, שׁוּלְטָנֵיהּ דְּהַהוּא נֶגַע דְּנָפִיק מֵאֲתַר עִלָּאָה, דָּא שַׁלְטָא בְּכֹלָּא, בִּתְרֵי גַּוְונֵי, בְּצֶמֶר וּבְפִשְׁתִּים. וּבְגִין כַּךְ, זֹאת תּוֹרַת נֶגַע הַצָּרַעַת בֶּגֶד הַצֶּמֶר אוֹ הַפִּשְׁתִּים.</p>"]]});
